#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define SAMPLE_RATE_MS 500
#define SAMPLE_SIZE 16
#define SAMPLE_COUNT (SAMPLE_RATE_MS / 100) // 100 samples per second

// Define ADS1115 registers
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONVERSION_START 0x01

// Define GPIO pins
#define SDA_PIN 2
#define SCL_PIN 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int16_t *raw_data);
int convert_to_amperes(int16_t raw_data);
void log_current(int16_t raw_data);
void cleanup();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int adc_address;
    int sample_rate_ms;
    int sample_size;
    int sample_count;
} config_t;

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115
int configure_ads1115() {
    // Configure for single-shot mode
    if (i2cWriteByteData(i2c_handle, ADS1115_CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Configure for single-ended input on AIN0
    if (i2cWriteByteData(i2c_handle, ADS1115_CONVERSION_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to conversion register\n");
        return -1;
    }

    // Configure for 128 SPS
    if (i2cWriteByteData(i2c_handle, ADS1115_CONVERSION_REG, 0x80) < 0) {
        fprintf(stderr, "Error writing to conversion register\n");
        return -1;
    }

    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *raw_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_CONVERSION_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw data to amperes
int convert_to_amperes(int16_t raw_data) {
    // Assuming a gain of 4.096V/LSB and a resolution of 16 bits
    return (int16_t)((float)raw_data / (4.096 / 2.0));
}

// Log current value to console
void log_current(int16_t raw_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Current: %d\n", timestamp, raw_data);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SDA_PIN, PI_OUTPUT);
    gpioSetMode(SCL_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int16_t raw_data[SAMPLE_SIZE];
    int16_t current_value;
    int16_t adc_value;
    int i;

    // Main loop
    while (!terminate) {
        // Read data from ADS1115
        if (read_ads1115(raw_data) == 0) {
            // Convert raw data to amperes
            current_value = convert_to_amperes(raw_data[0]);

            // Log current value
            log_current(current_value);

            // Store current value for next iteration
            for (i = 0; i < SAMPLE_SIZE; i++) {
                raw_data[i] = current_value;
            }
        } else {
            fprintf(stderr, "Failed to read ADS1115 data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_RATE_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

