#define MICS_4514_ADDR 0x60
#define CO_THRESHOLD 25.0
#define ALERT_LOG_FILE "co_log.txt"
#define CO_LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"

// Global variables
int i2c_handle;
FILE *co_log_file;
FILE *alert_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mics_sensor(int i2c_handle, int *co_adc, int *red_adc);
float convert_co_adc_to_ppm(int co_adc);
int check_co_threshold(float co_ppm, float co_threshold);
int check_alert_threshold(float co_ppm, float co_threshold);
int log_co_data(FILE *co_log_file, float co_ppm);
int log_alert_data(FILE *alert_log_file, float co_ppm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read data from the MICS-4514 sensor
int read_mics_sensor(int i2c_handle, int *co_adc, int *red_adc) {
    char buf[4];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *co_adc = (buf[0] << 8) | buf[1];
    *red_adc = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to convert CO ADC reading to ppm
float convert_co_adc_to_ppm(int co_adc) {
