#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RANGE_MSP 0.5 // Milli-second range for ADC conversion
#define ADC_CHANNEL 0 // MCP3008 channel for microphone 0
#define ADC_CHANNEL 1 // MCP3008 channel for microphone 1
#define ADC_RESOLUTION 10 // 10-bit resolution for MCP3008
#define ADC_MAX_VALUE 1023 // Maximum ADC value for 10-bit resolution
#define SAMPLE_RATE 1000 // Samples per second
#define WINDOW_SIZE 100 // Window size in samples
#define HIGH_THRESHOLD 500 // High RMS threshold
#define LOW_THRESHOLD 100  // Low RMS threshold
#define NUM_SAMPLES (WINDOW_SIZE * SAMPLE_RATE)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold ADC data
typedef struct {
    int16_t adc_value;
    float rms;
} ADCData;

// Function prototypes
int spi_init();
ADCData read_adc(int channel);
float calculate_rms(ADCData data);
void log_event(float mic1_rms, float mic2_rms);
void control_led(float mic1_rms, float mic2_rms);
void signal_handler(int signal);

// SPI initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Open SPI channel 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC data from MCP3008
ADCData read_adc(int channel) {
    ADCData data = {0, 0.0};
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        data.adc_value = -1; // Indicate error
        return data;
    }

    // Extract ADC value (10 bits)
    data.adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return data;
}

// Function to calculate RMS value
float calculate_rms(ADCData data) {
    float sum = 0.0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        sum += data.adc_value;
    }
    return sqrt(sum / NUM_SAMPLES);
}

// Function to log events to file
void log_event(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED based on RMS values
void control_led(float mic1_rms, float mic2_rms) {
    if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC data from both microphones
        ADCData adc1_data = read_adc(ADC_CHANNEL);
        ADCData adc2_data = read_adc(ADC_CHANNEL);

        // Calculate RMS values
        float mic1_rms = calculate_rms(adc1_data);
        float mic2_rms = calculate_rms(adc2_data);

        // Log events
        log_event(mic1_rms, mic2_rms);

        // Control LED
        control_led(mic1_rms, mic2_rms);

        // Wait for 1 ms
        gpioDelay(1000000); // 1 ms = 1000000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

