#define ADS1115_ADDRESS 0x48
#define SAMPLE_RATE_HZ 10
#define WARNING_LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD_CURRENT 50.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_ads1115(int i2c_handle, int channel);
float convert_to_current(int raw_value);
void add_to_buffer(CircularBuffer *buffer, float current);
float calculate_average_current(CircularBuffer *buffer);
void control_warning_led(int gpio_pin, int state);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADS1115 channel A0
int read_ads1115(int i2c_handle, int channel) {
    char buf[2];
    int16_t raw_value;

    // Read the channel register (0x00)
    buf[0] = 0x00;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Read the channel data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Convert raw value to current
float convert_to_current(int raw_value) {
    // Assuming a linear relationship between raw value and current
    // and a sensitivity of 100 mV/LSB
    return (float)raw_value * 0.1; // Example conversion factor
}

// Add current to circular buffer
void add_to_buffer(CircularBuffer *buffer, float current) {
    buffer->buffer[buffer->head] = current;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate average current in the circular buffer
float calculate_average_current(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

