#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define PRESSURE_CHANNEL_REG 0x01
#define TEMPERATURE_CHANNEL_REG 0x02
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *pressure, int16_t *temperature);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void print_data(float pressure, float temperature);
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure and temperature from ADS1115
int read_ads1115(int16_t *pressure, int16_t *temperature) {
    char buf[2];
    int16_t raw_pressure, raw_temperature;

    // Read pressure channel
    if (i2cWriteByte(i2c_handle, PRESSURE_CHANNEL_REG) < 0) {
        fprintf(stderr, "Error writing to pressure channel\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from pressure channel\n");
        return -1;
    }
    raw_pressure = (buf[0] << 8) | buf[1];

    // Read temperature channel
    if (i2cWriteByte(i2c_handle, TEMPERATURE_CHANNEL_REG) < 0) {
        fprintf(stderr, "Error writing to temperature channel\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from temperature channel\n");
        return -1;
    }
    raw_temperature = (buf[0] << 8) | buf[1];

    *pressure = convert_pressure(raw_pressure);
    *temperature = convert_temperature(raw_temperature);

    return 0;
}

// Convert raw pressure data to kPa
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature data to °C
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 1024.0 * 165.0 - 40.0;
}

// Print data to console
void print_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
}

// Control the LED
void control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    int16_t raw_pressure, raw_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_ads1115(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            pressure = convert_pressure(raw_pressure);
            temperature = convert_temperature(raw_temperature);

            // Print data
            print_data(pressure, temperature);

            // Control LED
            if (pressure > PRESSURE_THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

