#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MCP3008_VOLTAGE_REF 3.3
#define ADC_MAX_VALUE 1023.0
#define ADC_MIN_VALUE 0.0
#define OVERCURRENT_THRESHOLD 10.0
#define GPIO_MOTOR_PIN 27
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_data(float voltage, float current);
void shutdown_motor();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * MCP3008_VOLTAGE_REF / ADC_MAX_VALUE;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return voltage / MCP3008_VOLTAGE_REF * ADC_MAX_VALUE;
}

// Function to log data to file
void log_data(float voltage, float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Voltage: %.2f V, Current: %.2f A\n", timestamp, voltage, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to shut down the motor
void shutdown_motor() {
    gpioWrite(GPIO_MOTOR_PIN, 0); // Set GPIO27 to LOW
    printf("Motor shutdown initiated.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_MOTOR_PIN, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_PIN, 1); // Initially turn motor off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log data
        log_data(voltage, current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            break; // Exit loop after shutdown
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(GPIO_MOTOR_PIN, 0); // Set GPIO27 to LOW
    gpioTerminate();

    return 0;
}

