#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define LOG_FILE "methane_log.txt"
#define ALARM_FILE "/var/log/leak_alarm.log"
#define ALARM_THRESHOLD 1000
#define ALARM_DURATION 5 // seconds
#define SENSOR_READ_INTERVAL 1 // seconds
#define SENSOR_READ_DELAY 1 // seconds
#define SENSOR_READ_MAX_RETRIES 3
#define SENSOR_READ_RETRY_DELAY 1 // seconds

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
FILE *alarm_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int log_data(int sensor_value, const char *timestamp);
int check_alarm(int sensor_value, const char *timestamp);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to file
int log_data(int sensor_value, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, sensor_value) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Function to check for leak alarm
int check_alarm(int sensor_value, const char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[80];

    time(&rawtime);
    timeinfo = localtime_r(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (sensor_value > ALARM_THRESHOLD) {
        fprintf(stderr, "%s: ALARM: Methane concentration exceeds threshold (%d ppm)\n", timestamp_str, ALARM_THRESHOLD);
        if (alarm_file != NULL) {
            fprintf(alarm_file, "%s: ALARM: Methane concentration exceeds threshold (%d ppm)\n", timestamp_str, ALARM_THRESHOLD);
            fflush(alarm_file);
        }
        return 1;
    } else {
        return 0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    if (wiringPiSPISetup(spi_fd, SPI_MODE, SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup function to close SPI and file handles
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (alarm_file != NULL) {
        fclose(alarm_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Open alarm log file
    alarm_file = fopen(ALARM_FILE, "a");
    if (alarm_file == NULL) {
        perror("Failed to open alarm log file");
        cleanup();
        return 1;
    }

    printf("Methane monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_mcp3008(ADC_CHANNEL);
        if (sensor_value == -1) {
            fprintf(stderr, "Failed to read sensor value. Retrying...\n");
            delay(SENSOR_READ_DELAY * 1000); // Wait before retrying
            continue;
        }

        char timestamp[20];
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime_r( &rawtime );
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (log_data(sensor_value, timestamp) == -1) {
            fprintf(stderr, "Failed to log data.\n");
        }

        if (check_alarm(sensor_value, timestamp)) {
            fprintf(stderr, "ALARM: Methane concentration exceeded threshold (%d ppm)\n", ALARM_THRESHOLD);
            if (alarm_file != NULL) {
                fprintf(alarm_file, "%s: ALARM: Methane concentration exceeded threshold (%d ppm)\n", timestamp, ALARM_THRESHOLD);
                fflush(alarm_file);
            }
        }

        delay(SENSOR_READ_INTERVAL * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

