#define ADS1115_ADDR 0x48
#define SAMPLE_RATE_HZ 1
#define SAMPLE_DELAY_MS 100
#define SAMPLE_COUNT_MAX 100
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int initialize_ads1115();
int read_ads1115(int16_t *adc_value);
float convert_adc_to_pressure(int16_t adc_value);
int validate_pressure(float pressure);
int log_pressure_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initializes the ADS1115 ADC
int initialize_ads1115() {
    // Configure ADS1115 for single-ended channel AIN0, gain of 128, and continuous conversion mode
    char config_buffer[2];
    config_buffer[0] = 0x80; // Configure register address
    config_buffer[1] = 0x00; // Configure value

    if (i2cWriteDevice(i2c_handle, config_buffer, 2) != 0) {
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Reads the ADS1115 ADC value
int read_ads1115(int16_t *adc_value) {
    char buffer[2];
