#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3208_CS_PIN 8
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int cs_pin, int channel);
float convert_to_humidity(int adc_value);
float convert_to_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Function to read data from MCP3208 ADC
int read_mcp3208(int cs_pin, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3208 command: Start bit (1), Single-ended mode (1), Channel (3 bits), Dummy bit (1 bit)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode + channel
    tx_buffer[2] = 0x00; // Dummy bit

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to humidity percentage
float convert_to_humidity(int adc_value) {
    // Assuming a linear relationship between ADC value and humidity percentage
    // This is a simplified example; adjust based on the HIH-4602-A datasheet
    // and your specific application.
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to convert ADC value to temperature in Celsius
float convert_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // This is a simplified example; adjust based on the HIH-4602-A datasheet
    // and your specific application.
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to a file
int log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to send email alert using ssmtp
int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity: %.2f%%\nTemperature: %.2f C\" | ssmtp -t %s", humidity, temperature, EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to send email alert\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure MCP3208 CS pin as output
    gpioSetMode(MCP3208_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3208_CS_PIN, 1); // Ensure CS is initially high

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1 MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_value = read_mcp3208(MCP3208_CS_PIN, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to humidity and temperature
        float humidity = convert_to_humidity(adc_value);
        float temperature = convert_to_temperature(adc_value);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold
        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Sending email alert.\n");
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Error: Failed to send email alert\n");
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

