#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3208_CHANNEL 0
#define MCP3208_CS 8
#define MCP3208_VREF 3.3
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_RESOLUTION 10 // 12-bit resolution
#define ADC_SCALE (ADC_MAX - ADC_MIN)
#define TEMPERATURE_SCALE (ADC_SCALE / 100.0) // Celsius per ADC unit
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 125.0
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3208(int channel);
float adc_to_temperature(int adc_value);
void log_temperature(float temperature);
void signal_handler(int signal);

// Function to read data from MCP3208 channel
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3208 datasheet)
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3208_CS, 0); // Select MCP3208
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3208_CS, 1); // Deselect MCP3208

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to temperature in Celsius
float adc_to_temperature(int adc_value) {
    float temperature = (float)adc_value * TEMPERATURE_SCALE / ADC_MAX;
    if (temperature < TEMPERATURE_MIN) {
        temperature = TEMPERATURE_MIN;
    } else if (temperature > TEMPERATURE_MAX) {
        temperature = TEMPERATURE_MAX;
    }
    return temperature;
}

// Function to log temperature data to CSV file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(MCP3208_CS, PI_OUTPUT);
    gpioWrite(MCP3208_CS, 1); // Deselect MCP3208 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float temperature = adc_to_temperature(adc_value);

        log_temperature(temperature);

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

