    tx_buffer[1] = ADXL335_XOUT_H | (channel << 4);
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error reading from SPI channel\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    int adc_value = ((int16_t)rx_buffer[1] << 8) | rx_buffer[0];

