    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle the impact threshold
void handle_impact_threshold(int adc_value) {
    if (adc_value > IMPACT_THRESHOLD) {
        printf("IMPACT DETECTED! ADC Value: %d\n", adc_value);
        log_data(adc_value, 0, 0); // Log the impact event
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .spi_mode = SPI_MODE,
        .ce_pin = CE_PIN,
        .impact_threshold = IMPACT_THRESHOLD,
        .sample_rate = SAMPLE_RATE,
        .log_file = LOG_FILE
    };

