    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CE pin as output
    gpioSetMode(config.ce_pin, PI_OUTPUT);
    gpioWrite(config.ce_pin, 1); // Initially set to high

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Impact detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int x = read_adxl335(0);
        int y = read_adxl335(1);
        int z = read_adxl335(2);

        if (x >= 0 && y >= 0 && z >= 0) {
            if (validate_adc_value(x) && validate_adc_value(y) && validate_adc_value(z)) {
                log_data(x, y, z);
                handle_impact_threshold(x);
            }
        } else {
            fprintf(stderr, "Error reading ADC values\n");
        }

        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

