#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0
#define FLOW_RATE_STEP 0.1
#define LOG_FILE "flow_log.csv"
#define ERROR_LOG_FILE "error_log.txt"
#define SENSOR_PRESENT_THRESHOLD 0.0
#define SENSOR_ABSENT_THRESHOLD 0.0
#define SENSOR_ABSENT_ERROR_THRESHOLD 0.0
#define SENSOR_READ_DELAY_MS 100
#define SENSOR_READ_MAX_RETRIES 3

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float convert_adc_to_flow_rate(int adc_value);
int validate_flow_rate(float flow_rate);
int log_flow_rate(float flow_rate);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Transfer data
    if (write(spi_fd, tx_buf, 3) != 3) {
        perror("Error writing to SPI device");
        return -1;
    }

    // Read data
    if (read(spi_fd, rx_buf, 3) != 3) {
        perror("Error reading from SPI device");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float convert_adc_to_flow_rate(int adc_value) {
    // Assuming a linear relationship between ADC value and flow rate
    // This is a placeholder; you'll need to calibrate your sensor
    // and determine the correct conversion factor.
    // This is a simplified example; a more accurate model would be needed
    // for a real-world application.
    return (float)adc_value * 0.1; // Example conversion factor
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        return 0; // Invalid flow rate
    }
    return 1; // Valid flow rate
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        return -1;
    }
}

// Log error to file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s,ERROR: %s\n", timestamp, message);
        fflush(error_log_file);
        return 0;
    } else {
        return -1;
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flow measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            log_error("Error reading ADC value");
            continue; // Skip to the next iteration
        }

        float flow_rate = convert_adc_to_flow_rate(adc_value);
        if (validate_flow_rate(flow_rate)) {
            if (log_flow_rate(flow_rate) != 0) {
                log_error("Error logging flow rate");
            }
        } else {
            log_error("Invalid flow rate");
        }

        gpioDelay(SENSOR_READ_DELAY_MS * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

