    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s,ERROR: %s\n", timestamp, message);
        fflush(error_log_file);
        return 0;
    } else {
        return -1;
    }
}

// Cleanup resources
