    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flow measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value == -1) {
            log_error("Error reading ADC value");
            continue; // Skip to the next iteration
        }

        float flow_rate = convert_adc_to_flow_rate(adc_value);
        if (validate_flow_rate(flow_rate)) {
            if (log_flow_rate(flow_rate) != 0) {
                log_error("Error logging flow rate");
            }
        } else {
            log_error("Invalid flow rate");
        }

        gpioDelay(SENSOR_READ_DELAY_MS * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
