#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to the first microphone
#define SAMPLE_RATE 16000 // 16 kHz
#define NUM_SAMPLES (SAMPLE_RATE * 1000) // Number of samples per second
#define NUM_CHANNELS 2
#define NUM_SENSORS 3
#define NUM_SAMPLE_PER_SENSOR (NUM_SAMPLES / NUM_CHANNELS)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int channel;
    int sample_rate;
    int num_samples;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int apply_noise_cancellation(int raw_audio, int gain);
void print_csv(int sensor_id, int raw_audio, int gain, int noise_cancelled_audio);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads the ADC value from the specified MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Applies noise cancellation to the raw audio
int apply_noise_cancellation(int raw_audio, int gain) {
    // Simple noise cancellation algorithm (e.g., simple subtraction)
    // This is a placeholder; a more sophisticated algorithm is needed for
    // effective noise reduction.
    // For example, you could use a filter to remove high-frequency noise.

    // Simplified example: subtract the previous sample from the current one
    int subtracted_sample = raw_audio - (NUM_SAMPLE_PER_SENSOR * gain);
    return subtracted_sample;
}

// Prints the CSV data to the console
void print_csv(int sensor_id, int raw_audio, int gain, int noise_cancelled_audio) {
    printf("Sensor %d, Raw Audio: %d, Gain: %d, Noise Cancelled Audio: %d\n",
           sensor_id, raw_audio, gain, noise_cancelled_audio);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--gain") == 0) {
            if (i + 1 < argc) {
                gain = atoi(argv[i + 1]);
                i++;
            } else {
                fprintf(stderr, "Error: Gain value missing.\n");
                return 1;
            }
        } else if (strcmp(argv[i], "--sensor") == 0) {
            if (i + 1 < argc) {
                sensor_id = atoi(argv[i + 1]);
                i++;
            } else {
                fprintf(stderr, "Error: Sensor ID missing.\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: Invalid argument: %s\n", argv[i]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio from each sensor
        int raw_audio_left = 0;
        int raw_audio_right = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            int channel = MCP3008_CHANNEL;
            if (i == 0) {
                channel = 0; // Left channel
            } else if (i == 1) {
                channel = 1; // Right channel
            } else {
                fprintf(stderr, "Error: Invalid sensor ID: %d\n", i);
                return 1;
            }

            raw_audio_left += read_mcp3008(channel);
            raw_audio_right += read_mcp3008(channel);
        }

        // Apply noise cancellation
        int noise_cancelled_audio = apply_noise_cancellation(raw_audio_left, gain);
        int noise_cancelled_audio_right = apply_noise_cancellation(raw_audio_right, gain);

        // Print CSV data
        print_csv(sensor_id, raw_audio_left, gain, noise_cancelled_audio);

        // Delay for a short period
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

