FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_temperature(float voltage);
int log_data(float raw_adc, float voltage, float temperature, int flame_detected);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to temperature (Celsius)
float voltage_to_temperature(float voltage) {
    // Assuming a linear relationship between voltage and temperature
    // This is a simplified example; a more accurate model would be needed for accurate temperature readings.
    // For example, using a lookup table or a more complex formula.
    return (voltage - 0.5) * 0.1; // Example: 0.5V = 50°C
}

// Function to log data to file
int log_data(float raw_adc, float voltage, float temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, raw_adc, voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

