        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    // Register signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off buzzer
    gpioWrite(BUZZER_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to temperature
        float temperature = voltage_to_temperature(voltage);

        // Log data
        if (log_data(adc_value, voltage, temperature, 0) != 0) {
            fprintf(stderr, "Error logging data. Retrying...\n");
        }

        // Check for flame detection
        int flame_detected = gpioRead(BUZZER_GPIO);
        if (flame_detected == 1) {
            printf("Flame detected!\n");
            gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            log_data(adc_value, voltage, temperature, 1); // Log data with flame_detected
        } else {
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

