#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define ADC_CHANNEL 0
#define MIN_CALIBRATION_VALUE 0.0
#define MAX_CALIBRATION_VALUE 1.0
#define MIN_THRESHOLD 30.0
#define MAX_THRESHOLD 100.0
#define LOG_INTERVAL 60
#define MAIL_RECIPIENT "recipient@example.com"
#define MAIL_CONFIG_FILE "mail.config"

// Global variables
int spi_handle;
FILE *log_file;
int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
int validate_threshold(float moisture_percentage);
int send_email(const char *recipient, const char *subject, const char *body);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    // Assuming a linear relationship between ADC value and moisture percentage
    // This is a simplified example; calibration is required for accurate results
    // For a more accurate model, you would need to measure the actual moisture content
    // and create a lookup table or a more complex function.
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to validate the moisture threshold
int validate_threshold(float moisture_percentage) {
    if (moisture_percentage < MIN_THRESHOLD || moisture_percentage > MAX_THRESHOLD) {
        fprintf(stderr, "Error: Moisture percentage out of range: %.2f%%\n", moisture_percentage);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Function to send an email using msmtp
int send_email(const char *recipient, const char *subject, const char *body) {
    FILE *pipe;
    char command[256];
    int status;

    // Construct the email command
    snprintf(command, sizeof(command), "echo \"%s\" | msmtp -t %s", body, recipient);

    // Open the pipe for communication
    pipe = popen(command, "r");
    if (pipe == NULL) {
        fprintf(stderr, "Error: Failed to open pipe for sending email\n");
        return -1;
    }

    // Read the email body from the pipe
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
        // Process the email body (e.g., remove newline characters)
        buffer[strcspn(buffer, "\n")] = 0; // Remove newline character
    }

    // Close the pipe
    pclose(pipe);

    // Check the exit status of msmtp
    status = WEXITSTATUS(status);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp returned non-zero exit status: %d\n", status);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:d:m:t:i:l:e:g:h")) != -1) {
        switch (opt) {
            case 'c':
                spi_channel = atoi(optarg);
                break;
            case 'd':
                spi_channel = atoi(optarg);
                break;
            case 'm':
                adc_channel = atoi(optarg);
                break;
            case 't':
                min_threshold = atof(optarg);
                break;
            case 'i':
                max_threshold = atof(optarg);
                break;
            case 'l':
                log_interval = atoi(optarg);
                break;
            case 'e':
                mail_recipient = optarg;
                break;
            case 'g':
                mail_config_file = optarg;
                break;
            case 'h':
                printf("Usage: %s [-c spi_channel] [-d adc_channel] [-m min_threshold] [-t max_threshold] [-i min_threshold] [-l max_threshold] [-e mail_recipient] [-g mail_config_file]\n", argv[0]);
                return 1;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-d adc_channel] [-m min_threshold] [-t max_threshold] [-i min_threshold] [-l max_threshold] [-e mail_recipient] [-g mail_config_file]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(spi_channel, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to moisture percentage
        float moisture_percentage = adc_to_moisture(adc_value);

        // Validate moisture percentage
        if (validate_threshold(moisture_percentage)) {
            // Send email if threshold is exceeded
            if (send_email(mail_recipient, "Moisture Monitoring", "Moisture level below threshold!") != 0) {
                fprintf(stderr, "Error: Failed to send email\n");
            }
        }

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %.2f%%\n", timestamp, moisture_percentage);
        fflush(log_file); // Ensure data is written to file immediately

        // Wait for the specified interval
        sleep(log_interval);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

