int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:d:m:t:i:l:e:g:h")) != -1) {
        switch (opt) {
            case 'c':
                spi_channel = atoi(optarg);
                break;
            case 'd':
                spi_channel = atoi(optarg);
                break;
            case 'm':
                adc_channel = atoi(optarg);
                break;
            case 't':
                min_threshold = atof(optarg);
                break;
            case 'i':
                max_threshold = atof(optarg);
