                printf("Usage: %s [-c spi_channel] [-d adc_channel] [-m min_threshold] [-t max_threshold] [-i min_threshold] [-l max_threshold] [-e mail_recipient] [-g mail_config_file]\n", argv[0]);
                return 1;
