    printf("Cleaning up...\n");
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        SAMPLE_INTERVAL_US = atoi(argv[1]);
        if (SAMPLE_INTERVAL_US > MAX_SAMPLE_INTERVAL_US) {
            SAMPLE_INTERVAL_US = MAX_SAMPLE_INTERVAL_US;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage\n");
            continue; // Skip to the next iteration
        }

        log_data(moisture_percentage);

        // Check if enough time has passed
        if (gpioTime(PI_TIME_RELATIVE, SAMPLE_INTERVAL_US) >= SAMPLE_INTERVAL_US) {
            printf("Sample taken at %s\n", asctime(localtime(&(time(NULL)))));
            SAMPLE_INTERVAL_US = 0; // Reset sample interval
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

