// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Check if the ADC value is within the valid range
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value * 3.3 / 1023.0;

    // Calculate the moisture percentage
    float moisture_percentage = 100.0 - ((voltage - 0.0) / (3.3 - 0.0));

    return moisture_percentage;
}

// Function to log moisture percentage to the console
