    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log moisture percentage
        log_moisture_percentage(moisture_percentage);

        // Wait for the specified interval
        sleep(LOG_INTERVAL);
    }

    // Close SPI device
    spiClose(spi_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

