#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "moisture_log.txt"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 Register Map
#define MOISTURE_CHANNEL 0
#define MOISTURE_READ_CMD 0x01
#define MOISTURE_READ_RESPONSE 0x04

// Global Variables
int spi_fd = -1;
int pump_state = 0;
int log_fd = -1;
FILE *log_file = NULL;
int server_socket = -1;

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    int pump_state;
    int moisture_level;
    char log_message[256];
} MoistureData;

MoistureData moisture_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function Prototypes
int initialize_spi();
int initialize_gpio();
int initialize_socket();
int initialize_logging();
int read_mcp3008(int channel);
int log_data(int moisture_level, int pump_state);
int send_data_to_server(int moisture_level, int pump_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", SPI_DEVICE);
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially
    return 0;
}

// Function to initialize socket
int initialize_socket() {
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    // Set socket options
    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        syslog(LOG_ERR, "Failed to set socket options: %s", strerror(errno));
        close(server_socket);
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to bind socket: %s", strerror(errno));
        close(server_socket);
        return -1;
    }

    if (listen(server_socket, 3) < 0) {
        syslog(LOG_ERR, "Failed to listen on socket: %s", strerror(errno));
        close(server_socket);
        return -1;
    }

    return 0;
}

// Function to initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
