#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x60
#define PULSES_PER_SECOND 1
#define SAMPLE_INTERVAL_MS 1000
#define MAX_SAMPLE_COUNT 1000
#define MAX_SAMPLE_SIZE (MAX30102_ADDR + 1)
#define MAX_I2C_RETRIES 3
#define MAX_I2C_RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t sp02;
    uint16_t hr;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int verify_sensor_id(uint8_t *part_id);
int read_max30102_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[MAX_SAMPLE_SIZE];
    int retries = 0;
    int result;

    while (retries < MAX_I2C_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, MAX_SAMPLE_SIZE);
        if (result == MAX_I2C_RETRIES) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            return -1; // I2C read failed
        } else if (result < 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            return -1; // I2C read failed
        } else {
            break; // Success
        }

        retries++;
        gpioDelay(MAX_I2C_RETRY_DELAY_MS); // Delay before retrying
    }

    if (retries == MAX_I2C_RETRIES) {
        fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        return -1; // I2C read failed after retries
    }

    // Extract SpO2 and HR values from the buffer
    data->sp02 = (buf[0] << 8) | buf[1];
    data->hr = (buf[2] << 8) | buf[3];

    return 0; // Success
}

// Function to verify sensor ID
int verify_sensor_id(uint8_t *part_id) {
    uint8_t id = part_id[0];
    if (id != 0x01) {
        fprintf(stderr, "Sensor ID mismatch: Expected 0x01, got 0x%02X\n", id);
        return -1;
    }
    return 0;
}

// Function to read MAX30102 data
int read_max30102_data(sensor_data_t *data) {
    char buf[MAX_SAMPLE_SIZE];
    int retries = 0;
    int result;

    while (retries < MAX_I2C_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, MAX_SAMPLE_SIZE);
        if (result == MAX_I2C_RETRIES) {
