                } else {
                    fprintf(stderr, "Failed to read MAX30102 data\n");
                }
            } else {
                fprintf(stderr, "Sensor ID verification failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

