        } else if (result < 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            return -1; // I2C read failed
        } else {
            break; // Success
        }

        retries++;
        gpioDelay(MAX_I2C_RETRY_DELAY_MS);
    }

    if (retries == MAX_I2C_RETRIES) {
        fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        return -1; // I2C read failed after retries
    }

    // Extract SpO2 and HR values from the buffer
    data->sp02 = (buf[0] << 8) | buf[1];
    data->hr = (buf[2] << 8) | buf[3];

    return 0; // Success
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s.%06ld, SpO2: %d%% - Heart Rate: %d bpm\n",
            timestamp, data.sp02, data.hr);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    uint8_t part_id;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(&part_id) != 0) {
        fprintf(stderr, "Sensor ID verification failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Verify sensor ID
            if (verify_sensor_id(&part_id) == 0) {
                // Read MAX30102 data
                if (read_max30102_data(&sensor_data) == 0) {
                    // Log data
                    log_data(sensor_data);
                } else {
                    fprintf(stderr, "Failed to read MAX30102 data\n");
                }
            } else {
                fprintf(stderr, "Sensor ID verification failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

