    if (csv_file == NULL) {
        fprintf(stderr, "Error: CSV file is not open.\n");
        return -1;
    }

    fprintf(csv_file, "%s,%d,%d\n", timestamp, channel, voltage);
    fflush(csv_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

