int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Could not open CSV file for writing\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                int voltage = (adc_value * 3.3) / 1024.0; // Assuming 3.3V reference
                if (log_data(i, voltage) != 0) {
                    fprintf(stderr, "Error: Failed to log data for channel %d\n", i);
                }
            } else {
                fprintf(stderr, "Error: Failed to read channel %d\n", i);
            }
        }
        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

