// Define GPIO pins
#define MQ2_SENSOR_PIN 4
#define BUZZER_PIN 24

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADC channel
#define ADC_CHANNEL 0

// Define threshold value
#define THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int read_mq2_sensor();
void control_buzzer(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d, result %d)\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read MQ-2 sensor
int read_mq2_sensor() {
    int adc_value = read_mcp3008(ADC_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error: Failed to read MQ-2 sensor\n");
        return -1;
    }
    return adc_value;
}

// Function to control buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Signal handler for Ctrl-C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MQ2_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mq2_sensor();
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MQ-2 sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (adc_value < THRESHOLD) {
            control_buzzer(1); // Turn buzzer on
        } else {
            control_buzzer(0); // Turn buzzer off
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

