#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define ADC channel
#define ADC_CHANNEL 0

// Define SPI mode
#define SPI_MODE 0

// Define SPI flags
#define SPI_FLAGS 0

// Define CSV file name
#define CSV_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
int log_data(int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int initialize_gpio();
int initialize_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CS0_PIN, PI_OUTPUT);
    gpioSetMode(CS1_PIN, PI_OUTPUT);
    gpioSetMode(CS2_PIN, PI_OUTPUT);

    gpioWrite(CS0_PIN, 1);
    gpioWrite(CS1_PIN, 1);
    gpioWrite(CS2_PIN, 1);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Log data to CSV file
int log_data(int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return 1;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fclose(csv_file);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int sensor1_value = read_adc(ADC_CHANNEL);
        int sensor2_value = read_adc(ADC_CHANNEL + 1);
        int sensor3_value = read_adc(ADC_CHANNEL + 2);

        // Check for errors during ADC reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Log data
        if (log_data(sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data. Retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

