#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Define the ADC channel
#define ADC_CHANNEL 0

// Function to read from the PCF8591 ADC
int read_pcf8591(int i2c_fd) {
    char buf[1];
    int result;

    // Write to the PCF8591 to trigger a conversion
    buf[0] = 0x00; // Dummy write
    result = i2cWriteDevice(i2c_fd, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to PCF8591: %d\n", result);
        return -1;
    }

    // Read the 8-bit conversion value
    result = i2cReadDevice(i2c_fd, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from PCF8591: %d\n", result);
        return -1;
    }

    return buf[0];
}

// Function to handle signals (e.g., Ctrl-C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd;
    int adc_value;
    int result;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        adc_value = read_pcf8591(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Print the ADC value to stdout
        printf("ADC Value: %d\n", adc_value);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

