#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define SENSOR_CHANNEL AIN0
#define SAMPLE_RATE 1 // Hz
#define THRESHOLD 500.0 // Gauss
#define GPIO_PIN 27
#define BUFFER_SIZE 100
#define SAMPLE_DELAY_US 1000000 // 1 second

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer sensor_buffer;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *adc_value);
float convert_to_gauss(int16_t adc_value);
void add_to_buffer(float value);
float get_rolling_average();
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Error opening I2C: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Read from ADS1115
int read_ads1115(int16_t *adc_value) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Error reading from ADS1115: %d", result);
        return -1;
    }

    *adc_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Convert ADC value to Gauss
float convert_to_gauss(int16_t adc_value) {
    // Scale the ADC value to the range 0-3.3V
    float voltage = (float)adc_value / 4096.0 * 3.3;

    // Convert voltage to Gauss (assuming a linear relationship)
    float gauss = voltage * 500.0;

    return gauss;
}

// Add value to circular buffer
void add_to_buffer(float value) {
    sensor_buffer.buffer[sensor_buffer.head] = value;
    sensor_buffer.head = (sensor_buffer.head + 1) % BUFFER_SIZE;
    if (sensor_buffer.count < BUFFER_SIZE) {
        sensor_buffer.count++;
    }
}

// Get rolling average of the buffer
float get_rolling_average() {
    if (sensor_buffer.count == 0) {
        return 0.0;
    }
    return (sensor_buffer.buffer[sensor_buffer.head] + sensor_buffer.buffer[sensor_buffer.head - 1]) / 2.0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO to LOW
    gpioTerminate();
    closelog();
}

