    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is initially LOW

    // Initialize I2C
    if (initialize_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Magnetic field monitor started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&adc_value) == 0) {
            // Convert to Gauss
            gauss_value = convert_to_gauss(adc_value);

            // Add to circular buffer
            add_to_buffer(gauss_value);

            // Get rolling average
            rolling_average = get_rolling_average();

            // Check if threshold is exceeded
            if (rolling_average > THRESHOLD) {
                syslog(LOG_INFO, "Threshold exceeded! Gauss: %.2f", rolling_average);
                gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
                sleep(1); // Keep HIGH for 1 second
                gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        // Wait for 1 second
        gpioDelay(SAMPLE_DELAY_US);
    }

    // Cleanup and exit
    cleanup();
    syslog(LOG_INFO, "Magnetic field monitor stopped");
    return 0;
}

