#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VDD 3.3
#define ADC_MAX 1023.0
#define ADC_MIN 0.0
#define RAIN_THRESHOLD 0.5
#define LOG_FILE "rainfall.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_rainfall(float voltage);
void log_data(float voltage, float rainfall);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * VDD / ADC_MAX;
}

// Function to convert voltage to rainfall intensity
float voltage_to_rainfall(float voltage) {
    return RAIN_THRESHOLD + (voltage - ADC_MIN) * (RAIN_THRESHOLD - ADC_MIN) / (ADC_MAX - ADC_MIN);
}

// Function to log data to file
void log_data(float voltage, float rainfall) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, voltage, rainfall);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Rainfall monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to rainfall intensity
        float rainfall = voltage_to_rainfall(voltage);

        // Log data
        log_data(voltage, rainfall);

        // Print data to console
        printf("Voltage: %.2f V, Rainfall: %.2f mm/hr\n", voltage, rainfall);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close SPI channel and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    printf("Rainfall monitoring stopped.\n");

    return 0;
}

