#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define PGA_GAIN 4.096
#define LED_GPIO 17
#define THRESHOLD 100.0
#define SAMPLE_RATE 100 // Samples per second
#define SAMPLE_DELAY_US 10000 // 10ms delay

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int configure_ads1115(int i2c_handle);
int read_ads1115(int i2c_handle, int channel);
float convert_to_gauss(int adc_value);
void control_led(int gpio_pin, int on_duration_ms, int off_duration_ms);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int threshold;
} Config;

Config config = {THRESHOLD};

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        config.threshold = atoi(argv[1]);
        printf("Using threshold: %f Gauss\n", config.threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_ads1115(i2c_handle, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to Gauss
        float gauss = convert_to_gauss(adc_value);

        // Print Gauss value
        printf("Gauss: %.2f\n", gauss);

        // Check if threshold is exceeded
        if (gauss > config.threshold) {
            control_led(LED_GPIO, 500, 500); // Turn LED on
            control_led(LED_GPIO, 500, 500); // Keep LED on for 1 second
            control_led(LED_GPIO, 0, 0);    // Turn LED off
            printf("Threshold exceeded! Blinking LED.\n");
        }

        // Delay
        gpioDelay(SAMPLE_DELAY_US);
    }

    // Cleanup
    control_led(LED_GPIO, 0, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115
int configure_ads1115(int i2c_handle) {
    // Configure PGA gain
    if (i2cWriteByteData(i2c_handle, 0x00, PGA_GAIN) < 0) {
        fprintf(stderr, "Error configuring PGA gain\n");
        return -1;
    }

    // Configure conversion mode (single-ended, channel 0)
    if (i2cWriteByteData(i2c_handle, 0x01, 0x01) < 0) { // 0x01 = single-ended, 0x00 = continuous conversion
        fprintf(stderr, "Error configuring conversion mode\n");
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_ads1115(int i2c_handle, int channel) {
    char buf[2];
    int16_t adc_value;

    // Read two bytes from the specified channel
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    adc_value = (buf[0] << 8) | buf[1];

    return adc_value;
}

// Convert ADC value to Gauss
float convert_to_gauss(int adc_value) {
    // Assuming a linear relationship between ADC value and Gauss (adjust as needed)
    // This is a placeholder; a proper calibration is required for accurate conversion
    // For example, using a lookup table or a more complex formula.
    // This is a simplified example and may not provide accurate results.
    return (float)adc_value / 32768.0 * 100.0; // Example conversion
}

// Control LED
void control_led(int gpio_pin, int on_duration_ms, int off_duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(on_duration_ms);
    gpioWrite(gpio_pin, 0); // Turn LED off
    gpioDelay(off_duration_ms);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

