#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <math.h>

// Define SPI device file path
#define SPI_DEVICE "/dev/spidev0.0"

// Define SPI mode
#define SPI_MODE 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define ADC reference voltage
#define ADC_REF 3.3

// Define ADC resolution
#define ADC_RESOLUTION 1024

// Define ADC offset
#define ADC_OFFSET 0

// Define ADC gain
#define ADC_GAIN 1.0

// Define ADC reference voltage
#define ADC_REF_VOLTAGE 3.3

// Define ADC reference current
#define ADC_REF_CURRENT 0.1

// Define ADC reference capacitance
#define ADC_REF_CAPACITANCE 100.0

// Define ADC conversion time
#define ADC_CONVERSION_TIME_US (10.0 / (ADC_RESOLUTION * ADC_REF_VOLTAGE / ADC_REF_CURRENT))

// Global variables
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_open(const char *device, int mode);
int spi_read(int fd, unsigned char *data, int len);
int spi_write(int fd, unsigned char *data, int len);
int spi_close(int fd);
int read_mcp3008(int fd, int channel);
float adc_to_voltage(int adc_value, float voltage);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device, int mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &8) < 0) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error setting max speed Hz");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Error getting max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read function
int spi_read(int fd, unsigned char *data, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error performing SPI transfer");
        return -1;
    }

