#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define CS_PIN 8
#define CSV_FILE "sensor_data.csv"
#define BUFFER_SIZE 256

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
void append_to_csv(float voltage1, float voltage2, float voltage3);
void signal_handler(int signal);
int initialize_spi();
int initialize_gpio();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * (3.3 / 1024.0);
}

// Function to append data to CSV file
void append_to_csv(float voltage1, float voltage2, float voltage3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, voltage1, voltage2, voltage3);
    fflush(csv_file); // Ensure data is written to disk immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Voltage1,Voltage2,Voltage3\n");
    }

    // Main loop
    while (!terminate) {
        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);
        int adc_value3 = read_mcp3008(2);

        if (adc_value1 >= 0 && adc_value2 >= 0 && adc_value3 >= 0) {
            float voltage1 = adc_to_voltage(adc_value1);
            float voltage2 = adc_to_voltage(adc_value2);
            float voltage3 = adc_to_voltage(adc_value3);

            append_to_csv(voltage1, voltage2, voltage3);
        } else {
            fprintf(stderr, "Error reading ADC values. Skipping.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

