#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VIBRATION_THRESHOLD 500
#define PWM_FREQUENCY 100
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 255
#define PWM_GPIO 17
#define PWM_CHANNEL 0
#define VIBRATION_LOG_FILE "vibration_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int adc_read(int channel);
float calculate_noise_level(int adc_value);
void pwm_set_duty_cycle(int gpio, int channel, int duty_cycle);
void log_event(const char *message);
void signal_handler(int signal);

// SPI Initialization
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// ADC Read Function
int adc_read(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Noise Level Calculation
float calculate_noise_level(int adc_value) {
    // Assuming a linear relationship between ADC value and noise level
    // This is a simplified example; adjust based on your sensor and application
    return (float)adc_value / 1023.0 * 100.0; // Example: 0-1023 ADC value maps to 0-100% noise level
}

// PWM Control
void pwm_set_duty_cycle(int gpio, int channel, int duty_cycle) {
    if (gpioPWM(gpio, channel, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
    }
}

// Logging Function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal Handler
