    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(VIBRATION_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = adc_read(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate noise level
        float noise_level = calculate_noise_level(adc_value);

        // Control PWM
        pwm_set_duty_cycle(PWM_GPIO, PWM_CHANNEL, (int)(noise_level * PWM_DUTY_CYCLE_MAX));

        // Log event
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Noise level: %.2f, Vibration: %d", noise_level, adc_value);
        log_event(log_message);

        // Delay
        gpioDelay(10); // 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

