    }
    return 0;
}

// ADC Read Function
int adc_read(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Noise Level Calculation
float calculate_noise_level(int adc_value) {
    // Assuming a linear relationship between ADC value and noise level
    // This is a simplified example; adjust based on your sensor and application
    return (float)adc_value / 1023.0 * 100.0; // Example: 0-1023 ADC value maps to 0-100% noise level
}

// PWM Control
void pwm_set_duty_cycle(int gpio, int channel, int duty_cycle) {
    if (gpioPWM(gpio, channel, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
    }
}

// Logging Function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(VIBRATION_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = adc_read(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate noise level
        float noise_level = calculate_noise_level(adc_value);

        // Control PWM
        pwm_set_duty_cycle(PWM_GPIO, PWM_CHANNEL, (int)(noise_level * PWM_DUTY_CYCLE_MAX));

        // Log event
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Noise level: %.2f, Vibration: %d", noise_level, adc_value);
        log_event(log_message);

        // Delay
        gpioDelay(10); // 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

