    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (validate_mcp3008_data(adc_value) == 0) {
            log_data(adc_value);
            if (adc_value < MOISTURE_THRESHOLD) {
                control_pump(1); // Turn pump on
            } else {
                control_pump(0); // Turn pump off
            }
        } else {
            fprintf(stderr, "Error: Invalid ADC value. Skipping logging.\n");
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

