#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VALVE_GPIO 17
#define VALVE_PWM_FREQUENCY 100 // Hz
#define VALVE_PWM_RANGE 100
#define NUM_SENSORS 3
#define NUM_READS 3
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float average_adc_values(int *adc_values, int num_values);
int set_valve_position(int duty_cycle);
int log_data(int adc_values[NUM_SENSORS], float average, int duty_cycle);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to compute average ADC value
float average_adc_values(int *adc_values, int num_values) {
    float sum = 0.0;
    for (int i = 0; i < num_values; i++) {
        sum += adc_values[i];
    }
    return sum / num_values;
}

// Function to set valve position using PWM
int set_valve_position(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > VALVE_PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    gpioPWM(VALVE_GPIO, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(int adc_values[NUM_SENSORS], float average, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, adc_values[0], adc_values[1], adc_values[2], average);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

