        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int adc_values[NUM_SENSORS];
    float average_adc;
    int duty_cycle;
    int i;

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC values
        for (i = 0; i < NUM_SENSORS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read ADC value from sensor %d\n", i);
                adc_values[i] = 0; // Set to 0 to avoid incorrect averaging
            }
        }

        // Compute average ADC value
        average_adc = average_adc_values(adc_values, NUM_SENSORS);

        // Set valve position
        duty_cycle = (int)(average_adc * VALVE_PWM_RANGE / 100.0); // Scale to 0-100 range
        if (set_valve_position(duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set valve position\n");
        }

        // Log data
        log_data(adc_values, average_adc, duty_cycle);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds = 5000000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

