#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PWM_GPIO 18
#define PWM_CHANNEL 0
#define PWM_FREQUENCY 500
#define SENSOR_THRESHOLD 100 // cm
#define SENSOR_TIMEOUT 5      // seconds
#define CALIBRATION_FILE "theremin_config.txt"

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;
float distance_threshold = SENSOR_THRESHOLD;

// Structure for calibration data
typedef struct {
    float offset;
    float scale;
} CalibrationData;

CalibrationData calibration_data = {0.0, 1.0};

// Function Prototypes
int read_mcp3008(int channel);
float calculate_distance(int echo_duration);
float map_distance_to_frequency(float distance);
float map_distance_to_volume(float distance);
void set_pwm_frequency(int frequency);
void set_pwm_dutycycle(int dutycycle);
void signal_handler(int signal);
int load_calibration_data(const char *filename);
int save_calibration_data(const char *filename);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate distance in centimeters
float calculate_distance(int echo_duration) {
    return (float)echo_duration / 10.0; // cm
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    return 440.0 * (1.0 + (distance / distance_threshold) * (1.0 - 0.5)); // Theremin-like
}

// Function to map distance to volume
float map_distance_to_volume(float distance) {
    return distance * (1.0 - (distance / distance_threshold) * (1.0 - 0.5)); // Theremin-like
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    gpioPWM(PWM_GPIO, frequency);
}

// Function to set PWM duty cycle
void set_pwm_dutycycle(int dutycycle) {
    gpioPWM(PWM_GPIO, dutycycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to load calibration data from file
int load_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s\n", filename);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *token = strtok(line, "=");
        if (token != NULL) {
            char *value_str = strtok(NULL, "=");
            if (value_str != NULL) {
                float offset = atof(token);
                float scale = atof(value_str);
                calibration_data.offset = offset;
                calibration_data.scale = scale;
                break;
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to save calibration data to file
int save_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing\n", filename);
        return -1;
    }

    char line[256];
    fprintf(fp, "%f,%f\n", calibration_data.offset, calibration_data.scale);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    if (load_calibration_data(CALIBRATION_FILE) != 0) {
        fprintf(stderr, "Error: Calibration data not loaded.  Using default values.\n");
    }

    // Set PWM frequency
    set_pwm_frequency(PWM_FREQUENCY);

    // Set PWM duty cycle
    set_pwm_dutycycle(0); // Initially off

    // Main loop
    while (!terminate) {
        // Read sensor data
        int echo_duration = read_mcp3008(MCP3008_CHANNEL);
        if (echo_duration < 0) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        float distance = calculate_distance(echo_duration);

        // Map distance to frequency
        float frequency = map_distance_to_frequency(distance);

        // Map distance to volume
        float volume = map_distance_to_volume(distance);

        // Set PWM frequency
        set_pwm_frequency(frequency);

        // Set PWM duty cycle
        set_pwm_dutycycle(volume);

        // Delay
        gpioDelay(10); // 10ms
    }

    // Cleanup
    set_pwm_dutycycle(0); // Turn off PWM
    spiClose(spi_handle);
    gpioTerminate();

    // Save calibration data
    save_calibration_data(CALIBRATION_FILE);

    return 0;
}

