#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define NUM_CHANNELS 8
#define READ_INTERVAL_SEC 60

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int process_sensor_data(int raw_value);
int control_pump(int state);
int log_data(int raw_value, int pump_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to process raw sensor data
int process_sensor_data(int raw_value) {
    // Simple linear mapping (adjust as needed)
    return (int)((float)raw_value / 1023.0 * 10.0); // Example: 10-bit ADC -> 10-bit output
}

// Function to control the water pump
int control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    return 0; // Return 0 for success, -1 for failure
}

// Function to log data to file
int log_data(int raw_value, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Raw Value: %d, Pump State: %s\n", timestamp, raw_value, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PUMP_GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Sensor Monitoring\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        int raw_value = read_mcp3008(0);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
            continue; // Skip to the next iteration
        }

        // Process sensor data
        int processed_value = process_sensor_data(raw_value);

        // Control pump
        if (processed_value < MOISTURE_THRESHOLD) {
            if (control_pump(1) != 0) {
                fprintf(stderr, "Error: Failed to control pump\n");
            }
        } else {
            if (control_pump(0) != 0) {
                fprintf(stderr, "Error: Failed to control pump\n");
            }
        }

        // Log data
        if (log_data(processed_value, gpioRead(PUMP_GPIO)) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait for the next reading
        gpioDelay(READ_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    gpioTerminate();

    return 0;
}

