#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

#define LED_GPIO 17

// Define constants
#define SAMPLE_RATE_HZ 100
#define SAMPLE_DELAY_MS 10
#define CALIBRATION_WINDOW_MS 5000
#define THRESHOLD_DEBOUNCE_MS 10
#define NUM_CHANNELS 1

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold calibration data
typedef struct {
    int16_t baseline;
    int16_t min_level;
    int16_t max_level;
} CalibrationData;

CalibrationData calibration_data = {0, 0, 1023};

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_ambient_noise();
int compare_sound_level(int16_t current_level, int16_t baseline);
void control_led(int state);
void signal_handler(int signal);

// Function to initialize the SPI bus
int initialize_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(SPI_CS, 0); // Select the MCP3008
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(SPI_CS, 1); // Deselect the MCP3008

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate ambient noise level
int calibrate_ambient_noise() {
    printf("Calibrating ambient noise level...\n");
    for (int i = 0; i < CALIBRATION_WINDOW_MS; i++) {
        int16_t raw_level = read_mcp3008(0);
        if (raw_level < calibration_data.min_level) {
            calibration_data.min_level = raw_level;
        }
        if (raw_level > calibration_data.max_level) {
            calibration_data.max_level = raw_level;
        }
        gpioDelay(1); // Small delay between samples
    }
    printf("Ambient noise level calibrated: %d\n", calibration_data.baseline);
    return 0;
}

// Function to compare sound level to a baseline
int compare_sound_level(int16_t current_level, int16_t baseline) {
    if (current_level > baseline + calibration_data.threshold) {
        return 1; // Sound level exceeds threshold
    } else if (current_level < baseline - calibration_data.threshold) {
        return 0; // Sound level below threshold
    } else {
        return 0; // Sound level within threshold
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        return 1;
    }

    // Calibrate ambient noise level
    calibrate_ambient_noise();

    // Main loop
    while (program_running) {
        // Read sound level from channel 0
        int16_t current_level = read_mcp3008(0);

        // Calibrate the current level
        calibrate_ambient_noise();

        // Compare the current level to the baseline
        int compare_result = compare_sound_level(current_level, calibration_data.baseline);

        // Control the LED based on the comparison result
        if (compare_result) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        // Delay for the specified sample rate
        gpioDelay(SAMPLE_DELAY_MS * 1000); // pigpioDelay takes microseconds
    }

    return 0;
}

