#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the magnetic field range
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl-C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a GPIO pin
int read_gpio(int gpio) {
    return gpioRead(gpio);
}

// Function to convert a GPIO pin state to a magnetic field strength
float gpio_to_magnetic_field(int gpio_state) {
    if (gpio_state == 1) {
        return 3.3 * (1.0 - (float)gpio_state / 2.0); // Assuming HIGH is 3.3V
    } else {
        return 0.0; // Assuming LOW is 0V
    }
}

// Function to log the magnetic field values to a file
void log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening magnetic_log.txt for writing!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set up signal handling for Ctrl-C
    signal(SIGINT, signal_handler);

    printf("Hall-Effect sensor data logging started. Press Ctrl-C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the state of the GPIO pins
        int sensor1_state = read_gpio(SENSOR1_GPIO);
        int sensor2_state = read_gpio(SENSOR2_GPIO);
        int sensor3_state = read_gpio(SENSOR3_GPIO);

        // Check for errors during GPIO read
        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading GPIO pin. Skipping logging.\n");
            gpioTerminate();
            return 1;
        }

        // Convert GPIO states to magnetic field strengths
        float sensor1_mT = gpio_to_magnetic_field(sensor1_state);
        float sensor2_mT = gpio_to_magnetic_field(sensor2_state);
        float sensor3_mT = gpio_to_magnetic_field(sensor3_state);

        // Log the magnetic field values
        log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    printf("Hall-Effect sensor data logging stopped.\n");

    return 0;
}

