#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdbool.h>

// Configuration
#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define GPIO_PIN 17
#define LED_STATE_ON 1
#define LED_STATE_OFF 0
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_ATTEMPTS 5

// MQTT Callbacks
static void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strncmp(payload, "{\"led_state\":", 13) == 0) {
            int led_state = atoi(payload + 13);
            if (led_state == LED_STATE_ON) {
                gpioWrite(GPIO_PIN, LED_STATE_ON);
                printf("LED turned ON\n");
            } else if (led_state == LED_STATE_OFF) {
                gpioWrite(GPIO_PIN, LED_STATE_OFF);
                printf("LED turned OFF\n");
            }
        }
    }
}

// Error Handling
static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// MQTT Client
static struct mosquitto *mqtt_client = NULL;

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("MQTT disconnection error: %s", mosquitto_strerror(rc));
    } else {
        printf("Disconnected from MQTT broker\n");
    }
}

static void on_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strncmp(payload, "{\"led_state\":", 13) == 0) {
            int led_state = atoi(payload + 13);
            if (led_state == LED_STATE_ON) {
                gpioWrite(GPIO_PIN, LED_STATE_ON);
                printf("LED turned ON\n");
            } else if (led_state == LED_STATE_OFF) {
                gpioWrite(GPIO_PIN, LED_STATE_OFF);
                printf("LED turned OFF\n");
            }
        }
    }
}

// GPIO Driver
static void gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        log_error("pigpio initialisation failed");
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, LED_STATE_OFF);
}

static void gpio_cleanup() {
    gpioWrite(GPIO_PIN, LED_STATE_OFF);
    gpioTerminate();
}

// Signal Handling
static void signal_handler(int signum) {
    printf("Signal received (%d). Cleaning up and exiting...\n", signum);
    gpio_cleanup();
    exit(signum);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "h")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [-h]\n", argv[0]);
                return 0;
            default:
                fprintf(stderr, "Usage: %s [-h]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    gpio_init();

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        log_error("Failed to create MQTT client");
        gpio_cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, on_connect);
    mosquitto_message_callback_set(mqtt_client, on_message_callback);

    mosquitto_loop_start(mqtt_client);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        mosquitto_loop_forever(mqtt_client, -1, 1);
    }

    return 0;
}

