    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_level();
        if (sound_level == 1) {
            printf("Sound detected!\n");
            control_alarm(1); // Turn alarm on
            gpioDelay(1000);   // Wait for 1 second
            control_alarm(0); // Turn alarm off
            printf("Alarm turned off.\n");
        } else {
            printf("No sound detected.\n");
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Program terminated.\n");
    return 0;
}

