    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(SOUND_SENSOR_DO, PI_INPUT);

    // Set GPIO18 as output
    gpioSetMode(ALARM_LED, PI_OUTPUT);

    return 0;
}

