    gpioWrite(ALARM_LED, 0); // Turn off alarm
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Exiting gracefully.\n", signal);
    program_running = 0;
}

