#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define VIBRATION_SENSOR_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define SHUTDOWN_COMMAND "sudo shutdown -h now"

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd;

// Function prototypes
int read_gpio(int gpio_pin);
int read_vibration_sensor(int gpio_pin);
int read_spi_data(int spi_fd, unsigned char *data, int data_len);
int log_event(const char *message);
int send_shutdown_command();
void signal_handler(int signal);

// Function to read GPIO value
int read_gpio(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to read vibration sensor
int read_vibration_sensor(int gpio_pin) {
    return read_gpio(gpio_pin);
}

// Function to read SPI data
int read_spi_data(int spi_fd, unsigned char *data, int data_len) {
    struct spi_ioc_transfer transfer[1];
    struct spi_info info;

    memset(&info, 0, sizeof(info));
    info.mode = 0;
    info.bits_per_word = 8;
    info.bits_per_word_shift = 0;
    info.max_speed_hz = SPI_SPEED;
    info.delay_usecs = 0;
    info.bits_per_word = 8;
    info.bits_per_word_shift = 0;
    info.max_speed_hz = SPI_SPEED;
    info.delay_usecs = 0;

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)data;
    transfer[0].rx_buf = NULL;
    transfer[0].len = data_len;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].bits_per_word_shift = 0;
    transfer[0].max_speed_hz = SPI_SPEED;
    transfer[0].delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI I/O error");
        return -1;
    }

    return 0;
}

// Function to log events
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to send shutdown command
int send_shutdown_command() {
    int status = system(SHUTDOWN_COMMAND);
    if (status == -1) {
        perror("Error executing shutdown command");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(VIBRATION_SENSOR_GPIO, PI_INPUT);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpioTerminate();
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI mode configuration failed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int vibration_detected = read_vibration_sensor(VIBRATION_SENSOR_GPIO);
        if (vibration_detected == 0) {
            printf("Vibration detected!\n");
            if (read_spi_data(spi_fd, (unsigned char *)&vibration_detected, 1) == 0) {
                if (log_event("Vibration detected") == 0) {
                    send_shutdown_command();
                } else {
                    fprintf(stderr, "Error logging event.\n");
                }
            } else {
                fprintf(stderr, "Error reading SPI data.\n");
            }
        } else {
            printf("No vibration detected.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    close(spi_fd);
    gpioTerminate();

    return 0;
}

