    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int32_t raw_temperature, raw_pressure;
    double altitude;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_bmp280_data(i2c_handle, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            double t_fine = compensate_temperature(raw_temperature, dig_T1, dig_T2, dig_T3);
            double pressure = compensate_pressure(raw_pressure, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9, t_fine);

            // Calculate altitude
            altitude = calculate_altitude(pressure, t_fine);

            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, altitude) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            free(timestamp); // Free the allocated memory

            printf("Temperature: %.2f °C, Pressure: %.2f hPa, Altitude: %.2f m\n", altitude, pressure, altitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

