#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 10.0
#define TEMP_LOG_FILE "temp_log.dat"
#define BUFFER_SIZE 120

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature readings
typedef struct {
    float temperatures[BUFFER_SIZE];
    int head;
    int count;
} TemperatureBuffer;

// Function prototypes
int initialize_spi();
float read_adc(int channel);
float convert_to_celsius(int adc_value);
void add_to_buffer(TemperatureBuffer *buffer, float temperature);
float get_temperature_from_buffer(TemperatureBuffer *buffer);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from the MCP3008 ADC
float read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1.0;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1.0;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return (adc_value * ADC_RESOLUTION) / 1023.0;
}

// Function to add a temperature reading to the circular buffer
void add_to_buffer(TemperatureBuffer *buffer, float temperature) {
    buffer->temperatures[buffer->head] = temperature;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to retrieve the temperature from the circular buffer
float get_temperature_from_buffer(TemperatureBuffer *buffer) {
    if (buffer->count == 0) {
        return -1.0; // Return -1.0 if the buffer is empty
    }
    return buffer->temperatures[buffer->head];
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close the SPI interface and terminate pigpio
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create circular buffer
    TemperatureBuffer buffer;
    buffer.head = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 5 seconds.\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Add to buffer
        add_to_buffer(&buffer, temperature);

        // Print temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

