#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

// Structure to hold GPIO configuration
typedef struct {
    int gpio_pin;
    int pull_up_resistor;
    int mode;
} gpio_config_t;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(gpio_config_t *config);
int read_flame_sensor(int gpio_pin);
int log_event(int pin, int state);
void cleanup_gpio(gpio_config_t *config);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->gpio_pin, PI_INPUT);
    gpioSetPullUpDown(config->gpio_pin, PI_PUD_DOWN);

    return 0;
}

// Read the flame sensor value
int read_flame_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Log the event to the CSV file
int log_event(int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, pin, state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(gpio_config_t *config) {
    gpioTerminate();
}

int main() {
    gpio_config_t flame_config = {FLAME_SENSOR_GPIO, 1, PI_INPUT};
    int state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&flame_config) != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        state = read_flame_sensor(flame_config.gpio_pin);

        if (state == 1) {
            printf("Flame detected!\n");
            if (log_event(flame_config.gpio_pin, 1) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        } else {
            printf("No flame detected.\n");
            if (log_event(flame_config.gpio_pin, 0) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup GPIO resources
    cleanup_gpio(&flame_config);

    return 0;
}

