#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP4725_ADDR 0x60
#define TMP36_CHANNEL 0
#define I2C_BUS 1
#define I2C_DEVICE 0x48
#define ADC_CHANNEL 0
#define ADC_SCALE 0.0078125 // 0.0078125 V/ADC_SCALE
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int write_mcp4725(int adc_value);
int read_mcp4725(int channel);
int log_data(int raw_count, float temperature, int adc_value, int dac_voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, tx_buf, 3) < 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    // TMP36 calibration curve (example, adjust based on your sensor)
    // This is a simple linear approximation.  A more accurate model would be needed for a real sensor.
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float temperature = (voltage - 0.5) * 100.0; // Example linear conversion
    return temperature;
}

// Function to write to MCP4725 DAC
int write_mcp4725(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    // Construct SPI message
    unsigned char tx_buf[2];
    tx_buf[0] = 0x40; // Single-ended mode, channel select
    tx_buf[1] = (adc_value << 4) | 0x00; // 10-bit value

    if (wiringPiSPIDataRW(SPI_CHANNEL, tx_buf, 2) < 0) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read from MCP4725 DAC
int read_mcp4725(int channel) {
    if (channel < 0 || channel > 1023) {
        fprintf(stderr, "Invalid channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char tx_buf[2];
    tx_buf[0] = 0x40; // Single-ended mode, channel select
    tx_buf[1] = (0x08 | channel) << 4; // 10-bit value

    if (wiringPiSPIDataRW(SPI_CHANNEL, tx_buf, 2) < 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    return ((tx_buf[1] & 0x03) << 8) + tx_buf[2];
}

// Function to log data to file
int log_data(int raw_count, float temperature, int adc_value, int dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %d, %.2f\n", timestamp, raw_count, temperature, adc_value, dac_voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_count = 0;
        float temperature = 0.0;
        int adc_value = 0;
        int dac_voltage = 0;

        // Read ADC value
        adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to temperature
        temperature = adc_to_temperature(adc_value);

        // Write DAC value
        if (write_mcp4725(adc_value) == -1) {
            fprintf(stderr, "Failed to write to DAC, retrying...\n");
            sleep(1);
            continue;
        }

        // Log data
        if (log_data(raw_count, temperature, adc_value, dac_voltage) != 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
        }

        // Delay
        sleep(SAMPLE_INTERVAL_MS);

        // Increment raw count
        raw_count++;
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

