// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
void activateRelay(int pin);
void deactivateRelay(int pin);
void sequenceRelays(int pin1, int pin2, int pin3, int pin4);
void cleanup();

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
    cleanup();
    exit(0);
}

// Function to activate a relay
void activateRelay(int pin) {
    gpioWrite(pin, 1); // Set the pin HIGH to activate the relay
    printf("Relay %d activated\n", pin);
}

// Function to deactivate a relay
void deactivateRelay(int pin) {
    gpioWrite(pin, 0); // Set the pin LOW to deactivate the relay
    printf("Relay %d deactivated\n", pin);
}

// Function to sequence the relays
void sequenceRelays(int pin1, int pin2, int pin3, int pin4) {
    activateRelay(pin1);
    gpioDelay(1000); // Wait for 1 second
    deactivateRelay(pin2);
    gpioDelay(1000); // Wait for 1 second
    activateRelay(pin3);
    gpioDelay(1000); // Wait for 1 second
    deactivateRelay(pin4);
    gpioDelay(1000); // Wait for 1 second
}

// Cleanup function to release GPIO lines
void cleanup() {
    printf("Cleaning up and exiting...\n");
    gpioTerminate(); // Terminate the pigpio library
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sequenceRelays(RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN);
        gpioDelay(500); // Wait for 0.5 seconds
    }

    cleanup(); // Clean up GPIO before exiting
    return 0;
}

