        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        int rain_level = calculate_rain_level(adc_value);

        if (rain_level > RAIN_THRESHOLD) {
            printf("Rain level: %d\n", rain_level);
            control_motor(1, 3000); // Forward for 3 seconds
            log_data(rain_level);
        } else {
            control_motor(0, 3000); // Reverse for 3 seconds
            log_data(rain_level);
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

