    if (adc_initialized) {
        // Debounce
        gpioDelay(DEBOUNCE_TIME_MS * 1000); // Convert ms to microseconds
        if (gpioRead(ADC_PIN) == 0) {
            adc_value = 0; // Reset if no signal detected
        }
    }
    return adc_value;
