float convert_to_magnetic_field(int adc_value) {
    // Assuming a linear relationship between ADC value and magnetic field strength
    // and a calibration factor of 0.1 mT/ADC_VALUE
    return (float)adc_value * 0.1;
}

// Function to log data to file
int log_data(FILE *log_file, float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f mT\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to control LED
void control_led(int led_pin, int state) {
    gpioWrite(led_pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close SPI and LED
void cleanup() {
    printf("Cleaning up...\n");
    control_led(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .adc_channel = ADC_CHANNEL,
        .adc_resolution = ADC_RESOLUTION,
        .led_pin = LED_PIN,
        .log_file = LOG_FILE,
        .threshold = THRESHOLD,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config.spi_channel, config.spi_speed) != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(spi_handle, config.adc_channel);
        if (adc_value >= 0) {
            float magnetic_field = convert_to_magnetic_field(adc_value);
            if (magnetic_field > config.threshold) {
                control_led(config.led_pin, 1); // Turn on LED
            } else {
                control_led(config.led_pin, 0); // Turn off LED
            }
            log_data(log_file, magnetic_field);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(config.sample_interval_ms * 1000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

