        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Current sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float current_A = convert_to_amperes(adc_value);
            if (log_data(current_A) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the specified interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

