#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define VDD 5.0
#define ADC_RESOLUTION 1024
#define ADC_MAX_VALUE (VREF / VDD) - 1
#define ADC_MIN_VALUE 0
#define ADC_MAX_VALUE (ADC_MAX_VALUE * VREF)
#define ADC_SCALE (ADC_MAX_VALUE - ADC_MIN_VALUE)
#define ADC_OFFSET ADC_MIN_VALUE
#define ADC_THRESHOLD (ADC_MIN_VALUE + ADC_SCALE / 2)
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define SAMPLE_DELAY_US (SAMPLE_INTERVAL_MS * 1000)
#define SAMPLE_COUNT 100000

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int spi_open(const char *device, int mode);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int adc_read(int channel);
float adc_to_current(int adc_value);
int log_data(float current);
void signal_handler(int sig);
int initialize_spi(int fd);

// SPI Open Function
int spi_open(const char *device, int mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &8) == -1) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Error setting max speed Hz");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Error getting max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer Function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
