#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 2

// Global variable to track the last sensor reading
int last_sensor_value = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Function to read the sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor reading
int debounce_sensor(int gpio, int delay_ms) {
    int current_value = read_sensor(gpio);
    if (current_value == -1) {
        return -1; // Indicate an error
    }

    gpioDelay(delay_ms * 1000); // Delay in microseconds

    int new_value = read_sensor(gpio);
    if (new_value == -1) {
        return -1; // Indicate an error
    }

    return new_value;
}

// Function to log the sensor state
void log_sensor_state(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d: %s\n", timestamp, sensor_value, (sensor_value == 0) ? "Object Present" : "No Object");
}

// Function to check for object presence
int check_object_presence(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to check for both sensors detecting object
int check_both_sensors_detected(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up/down resistors (optional, but recommended)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = debounce_sensor(SENSOR1_GPIO, DEBOUNCE_DELAY_MS);
        int sensor2_value = debounce_sensor(SENSOR2_GPIO, DEBOUNCE_DELAY_MS);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Check for object presence
        int object_present = check_object_presence(sensor1_value, sensor2_value);

        // Check for both sensors detecting object
        int both_sensors_detected = check_both_sensors_detected(sensor1_value, sensor2_value);

        // Log sensor states
        log_sensor_state(sensor1_value);
        log_sensor_state(sensor2_value);
        log_sensor_state(object_present);
        log_sensor_state(both_sensors_detected);

        // Check for both sensors detecting object simultaneously
        if (both_sensors_detected) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // The program should never reach here due to the infinite loop, but included for completeness
    gpioTerminate();
    return 0;
}

