#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 17
#define CAMERA_GPIO 18

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 200

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int debounce_motion(int *pir_state);
int capture_camera_snapshot(const char *filename);
void log_event(const char *event);
void cleanup();
void signal_handler(int signal);

// Global variables
int pigpio_initialized = 0;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    cleanup();
    exit(0);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;
    return 0;
}

// Function to read the PIR sensor state
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to debounce the PIR sensor
int debounce_motion(int *pir_state) {
    int current_state = *pir_state;
    int delay_ms = DEBOUNCE_DELAY;
    int delay_us = (delay_ms * 1000) * 1000; // Convert ms to us

    gpioDelay(delay_us);

    if (current_state != *pir_state) {
        *pir_state = current_state;
        return 1; // Motion detected
    } else {
        return 0; // No motion
    }
}

// Function to capture a camera snapshot
int capture_camera_snapshot(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

    int status = system(command);
    if (status == -1) {
        syslog(LOG_ERR, "Failed to execute libcamera-still command");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char message[256];
    snprintf(message, sizeof(message), "%s - %s", timestamp, event);
    syslog(LOG_INFO, "%s", message);
}

// Function to perform cleanup and exit
void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
    }
    syslog(LOG_INFO, "pigpio terminated");
}

int main() {
    // Open syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        int pir_state = read_pir_sensor();
        int debounced_motion = debounce_motion(&pir_state);

        if (debounced_motion) {
            log_event("Motion Detected");
            if (capture_camera_snapshot("motion_snapshot.jpg") != 0) {
                log_event("Camera capture failed");
            }
        }

        gpioDelay(50000); // Check every 50ms
    }

    return 0;
}

