#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_LEFT_BUTTON_PIN 6
#define PAN_RIGHT_BUTTON_PIN 7
#define TILT_UP_BUTTON_PIN 8
#define TILT_DOWN_BUTTON_PIN 9

// Define servo positions
#define PAN_POS_MIN 75
#define PAN_POS_MAX 125
#define PAN_POS_STEP 25

#define TILT_POS_MIN 75
#define TILT_POS_MAX 125
#define TILT_POS_STEP 25

// Define PWM period (20 ms)
#define PWM_PERIOD 20000

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_position(int gpio, int pos);
int read_button_state(int gpio);
void control_pan_tilt(int pan_pos, int tilt_pos);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(PAN_SERVO_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_SERVO_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Set servo position
int set_servo_position(int gpio, int pos) {
    if (gpioServo(gpio, pos) != 0) {
        fprintf(stderr, "Error setting servo position on GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Read button state
int read_button_state(int gpio) {
    return gpioRead(gpio);
}

// Control pan-tilt servo
void control_pan_tilt(int pan_pos, int tilt_pos) {
    // Map pan position to PWM duty cycle
    int pan_duty = (pan_pos - PAN_POS_MIN) / (PAN_POS_STEP) * (PWM_PERIOD / 1000.0);
    int tilt_duty = (tilt_pos - TILT_POS_MIN) / (TILT_POS_STEP) * (PWM_PERIOD / 1000.0);

    // Set servo positions
    if (set_servo_position(PAN_SERVO_PIN, pan_duty) != 0) {
        fprintf(stderr, "Error setting pan servo position\n");
        return;
    }
    if (set_servo_position(TILT_SERVO_PIN, tilt_duty) != 0) {
        fprintf(stderr, "Error setting tilt servo position\n");
        return;
    }

    // Update pan and tilt positions
    pan_pos += PAN_POS_STEP;
    tilt_pos += TILT_POS_STEP;

    // Clamp pan and tilt positions
    if (pan_pos < PAN_POS_MIN) {
        pan_pos = PAN_POS_MIN;
    } else if (pan_pos > PAN_POS_MAX) {
        pan_pos = PAN_POS_MAX;
    }
    if (tilt_pos < TILT_POS_MIN) {
        tilt_pos = TILT_POS_MIN;
    } else if (tilt_pos > TILT_POS_MAX) {
        tilt_pos = TILT_POS_MAX;
    }

    // Update servo positions
    if (set_servo_position(PAN_SERVO_PIN, pan_pos) != 0) {
        fprintf(stderr, "Error setting pan servo position\n");
        return;
    }
    if (set_servo_position(TILT_SERVO_PIN, tilt_pos) != 0) {
        fprintf(stderr, "Error setting tilt servo position\n");
        return;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Camera control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int pan_left_pressed = read_button_state(PAN_LEFT_BUTTON_PIN);
        int pan_right_pressed = read_button_state(PAN_RIGHT_BUTTON_PIN);
        int tilt_up_pressed = read_button_state(TILT_UP_BUTTON_PIN);
        int tilt_down_pressed = read_button_state(TILT_DOWN_BUTTON_PIN);

        // Control pan-tilt
        control_pan_tilt(pan_left_pressed ? PAN_POS_MIN : PAN_POS_MAX, tilt_up_pressed ? TILT_POS_MIN : TILT_POS_MAX);

        // Delay
        gpioDelay(50);
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

