#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width range (1000-2000 µs)
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define center pulse width (1500 µs)
#define CENTER_PULSE_WIDTH 1500

// Define button debounce time (50 ms)
#define DEBOUNCE_TIME 50

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
