#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <stdint.h>

// Define GPIO pin and SPI parameters
#define GPIO_PIN 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE_BITS_PER_WORD 8

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int spi_open(const char *device);
int spi_read(int fd, char *buffer, int len);
int spi_write(int fd, char *buffer, int len);
int spi_close(int fd);
int spi_transfer(int fd, char *tx_buf, char *rx_buf, int len);
int capture_image(const char *filename);
int log_motion_event(const char *filename);
void signal_handler(int sig);

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/export: %s", strerror(errno));
        return -1;
    }
    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        syslog(LOG_ERR, "Failed to export GPIO %d: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/unexport: %s", strerror(errno));
        return -1;
    }
    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        syslog(LOG_ERR, "Failed to unexport GPIO %d: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO direction file: %s", strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        syslog(LOG_ERR, "Failed to set GPIO direction: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO value file: %s", strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        syslog(LOG_ERR, "Failed to read GPIO value: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO value file: %s", strerror(errno));
        return -1;
    }
    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        syslog(LOG_ERR, "Failed to write GPIO value: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to open the SPI device
int spi_open(const char *device) {
    int fd;
    struct spi_ioc_transfer tr;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = NULL;
    tr.rx_buf = NULL;
    tr.len = 0;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_WR_TRANSFER, &tr) < 0) {
        syslog(LOG_ERR, "Failed to configure SPI device: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the SPI device
int spi_read(int fd, char *buffer, int len) {
    if (ioctl(fd, SPI_IOC_RD_TRANSFER, &buffer) < 0) {
        syslog(LOG_ERR, "Failed to read from SPI device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write to the SPI device
int spi_write(int fd, char *buffer, int len) {
    if (ioctl(fd, SPI_IOC_WR_TRANSFER, &buffer) < 0) {
        syslog(LOG_ERR, "Failed to write to SPI device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to close the SPI device
int spi_close(int fd) {
    if (close(fd) < 0) {
        syslog(LOG_ERR, "Failed to close SPI device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to transfer data to the SPI device
int spi_transfer(int fd, char *tx_buf, char *rx_buf, int len) {
    if (ioctl(fd, SPI_IOC_MESSAGE(1), (char *)tx_buf) < 0) {
        syslog(LOG_ERR, "Failed to transfer data to SPI device: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_MESSAGE(1), (char *)rx_buf) < 0) {
        syslog(LOG_ERR, "Failed to transfer data to SPI device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to capture an image using the camera
int capture_image(const char *filename) {
    char command[256];
    int fd;
    int width, height, mib[3];
    struct spi_ioc_transfer tr;

    // Construct the camera capture command
    snprintf(command, sizeof(command), "raspistill -o %s --width 640 --height 480 --quiet", filename);

    // Open the SPI device
    fd = spi_open(SPI_DEVICE);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device for camera capture: %s", strerror(errno));
        return -1;
    }

    // Configure the camera parameters
    mib[0] = 0; // SPI device number
    mib[1] = 0; // SPI mode
    mib[2] = 0; // SPI bits per word

    tr.tx_buf = NULL;
    tr.rx_buf = NULL;
    tr.len = 0;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_WR_TRANSFER, &tr) < 0) {
        syslog(LOG_ERR, "Failed to configure camera parameters: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Capture the image
    snprintf(command, sizeof(command), "raspistill -o %s --width 640 --height 480 --quiet", filename);
    if (system(command) != 0) {
        syslog(LOG_ERR, "Failed to capture image: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Close the SPI device
    close(fd);

    // Log the image filename
    log_motion_event(filename);

    return 0;
}

// Function to log a motion event to a file
int log_motion_event(const char *filename) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Open the log file
    fp = fopen(filename, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return -1;
    }

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Log the event
    fprintf(fp, "%s - Motion detected\n", timestamp);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    // Open syslog
    openlog("motion_capture", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        syslog(LOG_ERR, "Failed to export GPIO pin %d", GPIO_PIN);
        goto cleanup;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        syslog(LOG_ERR, "Failed to set GPIO direction for pin %d", GPIO_PIN);
        goto cleanup;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        goto cleanup;
    }

    // Main loop
    while (program_running) {
        // Read GPIO value
        int value = gpio_read(GPIO_PIN);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO value: %s", strerror(errno));
            goto cleanup;
        }

        // Check for falling edge
        if (value == 0) {
            // Debounce delay
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = 50 * 1000000; // 50ms
            nanosleep(&delay, NULL);

            // Capture image
            if (capture_image("motion_capture.jpg") < 0) {
                syslog(LOG_ERR, "Failed to capture image");
                goto cleanup;
            }

            // Log motion event
            if (log_motion_event("motion_capture.jpg") < 0) {
                syslog(LOG_ERR, "Failed to log motion event");
                goto cleanup;
            }
        }

        // Delay to avoid excessive CPU usage
        nanosleep(&delay, NULL);
    }

cleanup:
    // Close SPI device
    spi_close(spi_fd);

    // Unexport GPIO pin
    gpio_unexport(GPIO_PIN);

    // Close syslog
    closelog();

    return 0;
}

