#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define angle limits
#define ANGLE_LIMIT_MIN 0
#define ANGLE_LIMIT_MAX 180

// Define servo movement parameters
#define SERVO_MIN_PWM 1000
#define SERVO_MAX_PWM 2000
#define SERVO_STEP 100

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
}

// Function to set servo angle
void set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range: %d\n", angle);
        return;
    }

    // Map angle to PWM range
    int pwm_value = (int)((angle / 180.0) * (SERVO_MAX_PWM - SERVO_MIN_PWM + 1));

    // Set servo position
    gpioServo(gpio, pwm_value);
}

// Function to move servo
void move_servo(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range: %d\n", angle);
        return;
    }

    // Map angle to PWM range
    int pwm_value = (int)((angle / 180.0) * (SERVO_MAX_PWM - SERVO_MIN_PWM + 1));

    // Set servo position
    gpioServo(gpio, pwm_value);
}

// Function to read arrow key
int read_arrow_key() {
    int key = getchar();
    if (key == 'q') {
        return 0; // 'q'
    }
    return key;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, 50);
    gpioSetPWMfrequency(TILT_SERVO_PIN, 50);

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, SERVO_MAX_PWM - SERVO_MIN_PWM + 1);
    gpioSetPWMrange(TILT_SERVO_PIN, SERVO_MAX_PWM - SERVO_MIN_PWM + 1);

    // Set servo initial positions
