    int i;

    // Wait for the sensor to go high
    int timeout = 0;
    while (gpioRead(SENSOR_PIN) == 0 && timeout < 1000) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: Sensor timeout waiting for high signal.\n");
        return -1; // Indicate error
    }

    // Read the pulse count
    for (i = 0; i < 10; i++) {
        gpioDelay(1); // Small delay
        pulse_count++;
    }

    return pulse_count;
}

// Function to calculate flow rate
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / 10.0; // Flow rate in pulses per second
}

// Function to accumulate volume
float accumulate_volume(float flow_rate) {
    return flow_rate * 10.0; // Volume in liters
}

// Function to display data on LCD
void display_lcd(float flow_rate, float volume) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/s, Volume: %.2f L", flow_rate, volume);
    lcd_write_string(buffer);
}

// Function to write to LCD
void lcd_write_string(const char *string) {
    char *c = string;
    while (*c) {
        char ch = *c;
        if (ch >= 'A' && ch <= 'Z') {
            ch += 32; // Convert to ASCII
        }
        i2cWriteByteData(i2c_handle, LCD_RS_PIN, 0); // Select
        i2cWriteByteData(i2c_handle, LCD_EN_PIN, 1); // Enable
        i2cWriteByteData(i2c_handle, LCD_D4_PIN, ch & 0x07); // Data bits
        i2cWriteByteData(i2c_handle, LCD_D5_PIN, (ch >> 2) & 0x07); // D7
        i2cWriteByteData(i2c_handle, LCD_D6_PIN, (ch >> 4) & 0x07); // D6
        i2cWriteByteData(i2c_handle, LCD_D7_PIN, (ch >> 6) & 0x07); // D5
        gpioDelay(1); // Small delay
        i2cWriteByteData(i2c_handle, LCD_RS_PIN, 1); // Deselect
        i2cWriteByteData(i2c_handle, LCD_EN_PIN, 0); // Disable
        i2cWriteByteData(i2c_handle, LCD_D4_PIN, 0); // D4
        i2cWriteByteData(i2c_handle, LCD_D5_PIN, 0); // D5
        i2cWriteByteData(i2c_handle, LCD_D6_PIN, 0); // D6
        i2cWriteByteData(i2c_handle, LCD_D7_PIN, 0); // D7
        i2cWriteByteData(i2c_handle, LCD_RS_PIN, 1); // Select
        i2cWriteByteData(i2c_handle, LCD_EN_PIN, 0); // Enable
        i2cWriteByteData(i2c_handle, LCD_D4_PIN, 0); // D4
        i2cWriteByteData(i2c_handle, LCD_D5_PIN, 0); // D5
        i2cWriteByteData(i2c_handle, LCD_D6_PIN, 0); // D6
        i2cWriteByteData(i2c_handle, LCD_D7_PIN, 0); // D7
        gpioDelay(1); // Small delay
    }
}

