// Function to read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to calculate wind speed from pulse count
float calculate_wind_speed(int pulse_count) {
    if (pulse_count == 0) return 0.0; // Avoid division by zero
    return (float)pulse_count / (float)SAMPLE_WIND_WIND_WIND_SPEED_THRESHOLD * (float)ADC_RESOLUTION;
}

// Function to read LCD data
int read_lcd(int row, int col) {
    int data = 0;
    int i;

    for (i = 0; i < LCD_COMMAND_COUNT; i++) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, &data, 1) == -1) {
            fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
            return -1;
        }
        delay(1); // Small delay between commands
    }

    if (wiringPiSPIDataRW(SPI_CHANNEL, &data, 1) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    return data;
}

