#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Configuration
#define SENSOR_PIN 17
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define FLOW_THRESHOLD 1.0 // Liters per minute
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_DELAY_MS 100

// Global variables
static volatile int pulse_count = 0;
static volatile int pulse_last_time = 0;
static volatile int running = 1;
static int lcd_fd;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_sensor(void);
float calculate_flow_rate(int pulse_count, float pulse_duration);
void display_lcd(float flow_rate);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    running = 0;
    if (lcd_fd >= 0) {
        lcd_fd = -1; // Close the LCD file descriptor
    }
    wiringPiSetup(); // Reset wiringPi
    exit(0);
}

// Initialize GPIO pin
int init_gpio(void) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(SENSOR_PIN, INPUT);
    pullUpDnControl(SENSOR_PIN, PUD_UP); // Enable pull-up resistor
    return 0;
}

// Initialize I2C
int init_i2c(void) {
    lcd_fd = wiringPiI2CSetup(LCD_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor(void) {
    int pulse_count = 0;
    int pulse_duration = 0;

    while (pulse_count < SAMPLE_DELAY_MS && pulse_duration < SAMPLE_INTERVAL_MS) {
        int level = digitalRead(SENSOR_PIN);
        if (level == HIGH) {
            pulse_count++;
            pulse_duration += 1000; // Convert pulse duration to microseconds
        }
        delay(1); // Small delay to avoid busy-waiting
    }

    if (pulse_count == 0) {
        fprintf(stderr, "Sensor empty, no pulse detected.\n");
        return -1; // Indicate sensor is empty
    }

    pulse_last_time = millis();
    return pulse_count;
}

// Calculate flow rate
float calculate_flow_rate(int pulse_count, float pulse_duration) {
    if (pulse_count == 0) {
        return 0.0; // Avoid division by zero
    }
    return (float)pulse_count / (float)pulse_duration;
}

// Display flow rate on LCD
void display_lcd(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Flow Rate: %.2f L/min\n", timestamp, flow_rate);
}

int main(void) {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() == -1) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    printf("Water Flow Sensor Monitoring\n");

    while (running) {
        int pulse_count = read_sensor();
        if (pulse_count == -1) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        float flow_rate = calculate_flow_rate(pulse_count, pulse_count);
        display_lcd(flow_rate);

        delay(SAMPLE_INTERVAL_MS);
    }

    return 0;
}

