#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the LED matrix
#define ROW_ANODES {2, 3, 4, 17, 27, 22, 10, 9}
#define COLUMN_CATHODES {14, 15, 18, 23, 24, 25, 8, 7}

// Function prototypes
void set_row_anode(int row, int on);
void set_column_cathode(int column, int on);
void clear_matrix();
void scan_columns(int row, int column);
void display_animation(int row, int column);
void cleanup();

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a row anode
void set_row_anode(int row, int on) {
    gpioWrite(ROW_ANODES[row], on);
}

// Function to set the state of a column cathode
void set_column_cathode(int column, int on) {
    gpioWrite(COLUMN_CATHODES[column], on);
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            set_row_anode(i, 0);
            set_column_cathode(j, 0);
        }
    }
}

// Function to scan the columns and light the LEDs
void scan_columns(int row, int column) {
    if (row == 0) {
        set_row_anode(row, 1);
        set_column_cathode(column, 1);
        display_animation(row, column);
    } else {
        set_row_anode(row, 0);
        set_column_cathode(column, 0);
    }
}

// Function to display the animation
void display_animation(int row, int column) {
    if (row == 0) {
        set_row_anode(row, 1);
        set_column_cathode(column, 1);
    } else {
        set_row_anode(row, 0);
        set_column_cathode(column, 0);
    }
}

// Function to clean up GPIO lines
void cleanup() {
    gpioTerminate();
    printf("GPIO lines released.\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO pins as outputs
    for (int i = 0; i < 8; i++) {
        gpioSetMode(ROW_ANODES[i], PI_OUTPUT);
        gpioSetMode(COLUMN_CATHODES[i], PI_OUTPUT);
