#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x60
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the MLX75031 sensor
int initialize_sensor() {
    // Check if the sensor is already initialized
    int status = i2cReadByteData(i2c_handle, 0x00); // Check if the sensor is ready
    if (status < 0) {
        fprintf(stderr, "Error: Could not read initialization status from sensor.\n");
        return -1;
    }

    if (status != 0) {
        fprintf(stderr, "Error: Sensor initialization failed (status: %d).\n", status);
        return -1;
    }

    // Configure the sensor (example configuration, adjust as needed)
    // This is a placeholder, replace with actual configuration commands
    // based on the MLX75031 datasheet.
    // For example, you might need to set the measurement mode, gain, etc.

    // Example: Set measurement mode to continuous mode
    char config_data[2] = {0x01, 0x00}; // Example config data
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, config_data, 2) < 0) {
        fprintf(stderr, "Error: Could not write configuration data to sensor.\n");
        return -1;
    }

    return 0;
}

// Reads the distance from the sensor
int read_distance(int *distance) {
    char buffer[2];
    int status;

    // Read two bytes from the sensor
    status = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Could not read distance data from sensor.\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Logs the distance data to the CSV file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance;

        // Read the distance from the sensor
        if (read_distance(&distance) == 0) {
            // Log the distance data
            log_data(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

