#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define MEASURE_CMD 0x21
#define MEASURE_DURATION_US 50000 // 50ms
#define LOG_FILE "biometric_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
int verify_sensor_id(uint16_t sensor_id);
void log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(MEASURE_DURATION_US); // Wait for measurement

    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *proximity = (buf[0] << 8) | buf[1];
    *ambient_light = (buf[2] << 8) | buf[3];

    return 0;
}

// Verify sensor ID
int verify_sensor_id(uint16_t sensor_id) {
    uint8_t part_id;

    part_id = i2cReadByte(i2c_handle);
    if (part_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", part_id);
        return -1;
    }

    if (part_id != 0x00) {
        fprintf(stderr, "Sensor ID mismatch: Expected 0x00, got 0x%02X\n", part_id);
        return -1;
    }

    return 0;
}

// Log data to file
void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %u, %u\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint16_t proximity, ambient_light;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            if (verify_sensor_id(proximity) == 0) {
                log_data(proximity, ambient_light);
            } else {
                fprintf(stderr, "Sensor ID verification failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

