#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MAX_DISTANCE 400      // Maximum distance in cm
#define MIN_DISTANCE 2        // Minimum distance in cm
#define TIMEOUT_ERROR -1       // Timeout error code

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int trigger_sensor();
int read_echo_pulse();
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Read the echo pulse width
int read_echo_pulse() {
    int pulse_width = gpioRead(ECHO_PIN);
    if (pulse_width < 0) {
        fprintf(stderr, "Error reading echo pulse width\n");
        return -1;
    }
    return pulse_width;
}

// Calculate distance from pulse width
double calculate_distance(int pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 to get distance in cm
}

// Log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < 0) {
        fprintf(log_file, "%s: Error: Distance out of range (%.2f cm)\n", timestamp, distance);
    } else {
        fprintf(log_file, "%s: Distance: %.2f cm\n", timestamp, distance);
    }
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error triggering sensor!\n");
            continue; // Skip to the next iteration
        }

        // Read the echo pulse width
        int pulse_width = read_echo_pulse();
        if (pulse_width < 0) {
            fprintf(stderr, "Error reading echo pulse width!\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Check for timeout
        if (distance < 0) {
            fprintf(stderr, "Timeout reading distance!\n");
            continue; // Skip to the next iteration
        }

        // Check for sensor absence
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Sensor absent or out of range!\n");
            continue; // Skip to the next iteration
        }

        // Log the distance
        log_distance(distance);

        // Check for watering plant condition
        if (distance < 15.0) {
            fprintf(stderr, "Time to water the plant!\n");
        }

        // Delay for 60 seconds
        gpioDelay(60000); // 60 seconds = 60000 microseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

