#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define HEART_RATE_REG 0x24
#define PROXIMITY_REG 0x26
#define CSV_FILENAME "heartrate.csv"
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Structure to hold sensor data
typedef struct {
    int proximity;
    int heart_rate;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_proximity();
int read_heart_rate();
float convert_to_bpm(int proximity);
int write_to_csv(float bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read proximity data from the sensor
int read_proximity() {
    int result = i2cReadByteData(i2c_handle, PROXIMITY_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    return result;
}

// Read heart rate data from the sensor
int read_heart_rate() {
    int result = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", result);
        return -1;
    }
    return result;
}

// Convert proximity data to beats per minute
float convert_to_bpm(int proximity) {
    // Assuming proximity ranges from 0 to 255 (0-100% proximity)
    // and heart rate ranges from 0 to 200 (0-200 beats per minute)
    // This is a simplified conversion.  A more accurate model would
    // take into account the sensor's calibration curve.
    return (float)proximity / 100.0 * 200.0;
}

// Write data to the CSV file
int write_to_csv(float bpm) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILENAME);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int proximity = read_proximity();
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity, skipping...\n");
            continue; // Skip to the next iteration
        }

        int heart_rate = read_heart_rate();
        if (heart_rate < 0) {
            fprintf(stderr, "Error reading heart rate, skipping...\n");
            continue; // Skip to the next iteration
        }

        float bpm = convert_to_bpm(proximity);
        if (write_to_csv(bpm) != 0) {
            fprintf(stderr, "Error writing to CSV, skipping...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

