#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.txt"

// VL53L0X Registers
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x14
#define VL53L0X_REG_RESULT_INTERRUPT_CLEAR 0x16
#define VL53L0X_REG_RESULT_INTERRUPT_ENABLE 0x18
#define VL53L0X_REG_RESULT_INTERRUPT_DISABLE 0x1A
#define VL53L0X_REG_RESULT_INTERRUPT_CLEAR_VALUE 0x16
#define VL53L0X_REG_RESULT_INTERRUPT_CLEAR_MODE 0x17
#define VL53L0X_REG_RESULT_INTERRUPT_CLEAR_VALUE_1 0x16
#define VL53L0X_REG_RESULT_INTERRUPT_CLEAR_MODE_1 0x17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int read_register(int reg);
int write_register(int reg, int value);
int read_distance();
int log_distance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        return -1;
    }
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor
    return 0;
}

// Read a register from the VL53L0X
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Write a register to the VL53L0X
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the VL53L0X
int read_distance() {
    int distance = read_register(VL53L0X_REG_RESULT_INTERRUPT_STATUS);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance register\n");
        return -1;
    }
    return distance;
}

// Log distance to file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("VL53L0X Distance Sensor Program\n");

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            if (distance > 0) {
                printf("Distance: %d mm\n", distance);
                if (log_distance(distance) != 0) {
                    fprintf(stderr, "Error logging distance\n");
                }
            } else {
                fprintf(stderr, "Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the specified interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

