    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 0); // Ensure it's initially low

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance_mm;

        if (trigger_sensor() == 0) {
            if (read_sensor_data(&distance_mm) == 0) {
                log_data(distance_mm);
                printf("Distance: %d mm\n", distance_mm);
            } else {
                fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Error triggering sensor, skipping logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for SAMPLE_INTERVAL_MS milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

