    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Log the sensor readings
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break; // Exit the loop if there's an error
        }

