#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x50
#define MEASUREMENT_COMMAND_LENGTH 4
#define MEASUREMENT_RESPONSE_LENGTH 15
#define AVERAGE_DISTANCE_THRESHOLD 1000
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t distance;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(SensorData *data);
int write_command(uint8_t command);
int read_response(uint8_t *response, int len);
int verify_header(const uint8_t *response);
int process_sensor_data(const uint8_t *response, int len);
int log_data(const SensorData *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the Omron B5L-LD50-07050
int read_sensor_data(SensorData *data) {
    char buffer[MEASUREMENT_RESPONSE_LENGTH];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, MEASUREMENT_RESPONSE_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Verify header
    if (!verify_header(buffer)) {
        fprintf(stderr, "Error: Invalid header in sensor data\n");
        return -1;
    }

    // Extract distance
    data->distance = (buffer[11] << 8) | buffer[12];

    return 0;
}

// Write the measurement command to the sensor
int write_command(uint8_t command) {
    char buffer[MEASUREMENT_COMMAND_LENGTH];
    buffer[0] = command;
    int result = i2cWriteI2CBlockData(i2c_handle, 0x00, buffer, MEASUREMENT_COMMAND_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the measurement response from the sensor
int read_response(uint8_t *response, int len) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, response, len);
    if (result < 0) {
        fprintf(stderr, "Error reading response: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the header of the sensor response
int verify_header(const uint8_t *response) {
    if (response[0] != 0x01) {
        fprintf(stderr, "Error: Invalid header in sensor response\n");
        return -1;
    }
    return 0;
}

// Process the sensor data and calculate the average distance
int process_sensor_data(const uint8_t *response, int len) {
    SensorData data;
    if (read_sensor_data(&data) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    int sum = 0;
    for (int i = 0; i < len; i++) {
        sum += data.distance;
    }
    return (int)((double)sum / len);
}

// Log the intrusion event to a file
int log_data(const SensorData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, data->distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        SensorData sensor_data;
        int retries = 0;
        int result;

        while (retries < RETRY_COUNT) {
            result = write_command(0x01); // Trigger measurement command
            if (result != 0) {
                fprintf(stderr, "Error writing command, retrying...\n");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }
            gpioDelay(10); // Wait for measurement to complete

            result = read_response(sensor_data.response, MEASUREMENT_RESPONSE_LENGTH);
            if (result != 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            if (verify_header(sensor_data.response) != 0) {
                fprintf(stderr, "Error: Invalid header in sensor response\n");
                result = -1; // Indicate failure
            } else {
                if (process_sensor_data(sensor_data.response, MEASUREMENT_RESPONSE_LENGTH) != 0) {
                    fprintf(stderr, "Error processing sensor data\n");
                    result = -1; // Indicate failure
                }
            }

            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
            }
        }

        if (result != 0) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries\n", RETRY_COUNT);
            log_data(&sensor_data); // Log the error
        } else {
            log_data(&sensor_data); // Log the successful read
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

