    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        SensorData sensor_data;
        int retries = 0;
        int result;

        while (retries < RETRY_COUNT) {
            result = write_command(0x01); // Trigger measurement command
            if (result != 0) {
                fprintf(stderr, "Error writing command, retrying...\n");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }
            gpioDelay(10); // Wait for measurement to complete

            result = read_response(sensor_data.response, MEASUREMENT_RESPONSE_LENGTH);
            if (result != 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            if (verify_header(sensor_data.response) != 0) {
                fprintf(stderr, "Error: Invalid header in sensor response\n");
                result = -1; // Indicate failure
            } else {
                if (process_sensor_data(sensor_data.response, MEASUREMENT_RESPONSE_LENGTH) != 0) {
                    fprintf(stderr, "Error processing sensor data\n");
                    result = -1; // Indicate failure
                }
            }

            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
            }
        }

        if (result != 0) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries\n", RETRY_COUNT);
            log_data(&sensor_data); // Log the error
        } else {
            log_data(&sensor_data); // Log the successful read
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

