#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define the I2C address of the OPT3101 sensor
#define OPT3101_ADDR 0x39

// Define the register addresses for channel 0
#define OPT3101_REG_DATA_LOW 0x00
#define OPT3101_REG_DATA_HIGH 0x01
#define OPT3101_REG_CONTROL 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single byte from the OPT3101 sensor
int read_opt3101(int i2c_handle, int channel) {
    int data = i2cReadByteData(i2c_handle, OPT3101_REG_DATA_LOW + channel);
    if (data < 0) {
        fprintf(stderr, "Error reading data from channel %d: %d\n", channel, data);
        return -1; // Indicate an error
    }
    return data;
}

// Function to read the distance measurement from the OPT3101 sensor
int read_distance(int i2c_handle) {
    int low_byte, high_byte;

    // Read the low byte
    low_byte = i2cReadByteData(i2c_handle, OPT3101_REG_DATA_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte from sensor\n");
        return -1;
    }

    // Read the high byte
    high_byte = i2cReadByteData(i2c_handle, OPT3101_REG_DATA_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte from sensor\n");
        return -1;
    }

    // Combine the bytes to form the distance value
    return (high_byte << 8) | low_byte;
}

// Function to read the ambient light value from the OPT3101 sensor
int read_ambient_light(int i2c_handle) {
    int low_byte, high_byte;

    // Read the low byte
    low_byte = i2cReadByteData(i2c_handle, OPT3101_REG_DATA_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte from sensor\n");
        return -1;
    }

    // Read the high byte
    high_byte = i2cReadByteData(i2c_handle, OPT3101_REG_DATA_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte from sensor\n");
        return -1;
    }

    // Combine the bytes to form the ambient light value
    return (high_byte << 8) | low_byte;
}

// Function to log the distance, ambient light, and error flags to the console
void log_data(int distance, int ambient_light, int error_flag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %d, Ambient Light: %d, Error Flag: %d\n", timestamp, distance, ambient_light, error_flag);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the distance from channel 0
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, skipping logging.\n");
        } else {
            // Read the ambient light value
            int ambient_light = read_ambient_light(i2c_handle);
            if (ambient_light < 0) {
                fprintf(stderr, "Error reading ambient light, skipping logging.\n");
            } else {
                // Log the data
                log_data(distance, ambient_light, 0); // Error flag is 0
            }
        }

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

