#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 200000 // 200ms timeout
#define MAX_PULSE_DURATION 38000 // 38ms maximum pulse duration

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to trigger the HC-SR04 sensor
int trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Function to measure the echo pulse duration
int measure_pulse_duration() {
    int start_tick = gpioTick();
    int end_tick = start_tick;

    // Wait for the echo to start
    while (gpioRead(ECHO_PIN) == 0 && end_tick - start_tick > TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (end_tick - start_tick > TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Timeout
    }

    // Wait for the echo to end
    while (gpioRead(ECHO_PIN) == 1 && end_tick - start_tick > TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (end_tick - start_tick > TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1; // Timeout
    }

    // Calculate pulse duration in microseconds
    int pulse_duration = end_tick - start_tick;

    return pulse_duration;
}

// Function to log the measurement with timestamp
void log_measurement(int pulse_duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %d us\n", timestamp, pulse_duration);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO modes
    if (set_gpio_mode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_gpio_mode(ECHO_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error triggering sensor\n");
        }

        // Measure the pulse duration
        int pulse_duration = measure_pulse_duration();

        if (pulse_duration < 0) {
            fprintf(stderr, "Error measuring pulse duration\n");
        } else {
            // Log the measurement
            log_measurement(pulse_duration);
        }

        // Wait for 1 second
        gpioDelay(1000); // 1 second = 1000 milliseconds
    }

    // Cleanup
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

