#include <string.h>

// Define GPIO pins
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 22
#define BUZZER_GPIO 18

// Define obstacle detection threshold
#define OBSTACLE_THRESHOLD 500

// Define buzzer duration
#define BUZZER_DURATION 500 // milliseconds

// Global variables
volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile int buzzer_state = 0;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_state(int sensor_number, int state);
void control_buzzer(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log state transition
void log_state(int sensor_number, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_number, state ? "Obstacle Detected" : "No Obstacle Detected");
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to control buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("obstacle_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for obstacle detection
        if (sensor1_value == OBSTACLE_THRESHOLD || sensor2_value == OBSTACLE_THRESHOLD) {
            printf("Obstacle detected!\n");
            control_buzzer(1); // Activate buzzer
            gpioDelay(BUZZER_DURATION);
            control_buzzer(0); // Deactivate buzzer
            gpioDelay(100); // Debounce delay
        }

        // Log state transitions
        log_state(1, sensor1_value);
        log_state(2, sensor2_value);

        gpioDelay(100); // Delay to avoid overwhelming the system
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    gpioTerminate();
    fclose(log_file);
    return 0;
}

