#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define DISTANCE_REG 0x00
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define MAX_DISTANCE 100.0 // Maximum distance in cm
#define MIN_DISTANCE 0.0   // Minimum distance in cm
#define ALERT_DURATION_MS 500
#define ALERT_TIMEOUT_MS 5000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float distance;
    time_t timestamp;
} SensorData;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
void log_data(float distance);
void check_alert();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_PIN, 0); // Set GPIO pin to LOW
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;

    // Read two bytes from the distance register
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the distance in cm
    *distance = (float)((buf[0] << 8) | buf[1]) / 10.0;

    return 0;
}

// Log data to file
void log_data(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for alert and activate GPIO pin
void check_alert() {
