int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance();
void log_data(int distance, int led_state);
void blink_led(int led_state);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

