void blink_led(int led_state) {
    gpioWrite(LED_GPIO, led_state);
    gpioDelay(LED_ON_DURATION_MS);
    gpioWrite(LED_GPIO, !led_state);
    gpioDelay(LED_OFF_DURATION_MS);
}

