            gpioDelay(SAMPLE_INTERVAL_MS); // Wait for sample interval
            log_data(distance, 0); // Log distance and LED state
            blink_led(0); // Turn off LED
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait for sample interval
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

