// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x60
#define MEASUREMENT_COMMAND 0x00
#define DELAY_MS 100
#define LOG_FILE "distance_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_distance();
int write_measurement_command();
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance() {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASUREMENT_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Delay for measurement (adjust as needed)
    gpioDelay(10); // 10 ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine bytes into a single integer
    int distance = (buf[0] << 8) | buf[1];

    return distance;
}

// Write measurement command to the sensor
int write_measurement_command() {
    char buf[1];
    buf[0] = MEASUREMENT_COMMAND;
    int result = i2cWriteI2CBlockData(i2c_handle, 0, buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

