#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
int debounce_sensor(int gpio_pin);
int log_event(int sensor_id, int event_type);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the sensor reading
int debounce_sensor(int gpio_pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    return gpioRead(gpio_pin);
}

// Function to log the event to the log file
int log_event(int sensor_id, int event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = debounce_sensor(SENSOR1_GPIO);
        int sensor2_value = debounce_sensor(SENSOR2_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100 * 1000); // Wait 100ms before retrying
            continue;
        }

        // Determine the event type based on sensor values
        int event_type = (sensor1_value == 1) ? 'DETECTED' : 'CLEARED';

        // Log the event
        if (log_event(1, event_type) != 0) {
            fprintf(stderr, "Error logging event.\n");
        }

        // Print the event to the console
        printf("Sensor 1: %s, Sensor 2: %s, Event: %s\n",
               sensor1_value == 1 ? "DETECTED" : "CLEARED",
               sensor2_value == 1 ? "DETECTED" : "CLEARED",
               event_type);

        // Wait for 10ms
        gpioDelay(10000); // 10ms
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

