#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29
#define ZONE_GRID_SIZE 64
#define ZONE_DISTANCE_REG 0x0A // Example register for zone distance
#define CONFIG_REG 0x00        // Example configuration register
#define CONFIG_VALUE 0x01      // Example configuration value

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int grid_size;
    int grid_offset;
} sensor_config_t;

// Function prototypes
int init_i2c();
int init_sensor(sensor_config_t config);
int read_zone_distance(int handle, int *distance);
void log_zone_distances(int *distances, int num_zones);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L5CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the VL53L5CX sensor
int init_sensor(sensor_config_t config) {
    // Example initialization sequence (replace with actual register writes)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, config.grid_offset) < 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_REG + 1, config.grid_size) < 0) {
        fprintf(stderr, "Error writing to grid size register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read the distance from a specific zone
int read_zone_distance(int handle, int *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, ZONE_DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Log the zone distances to the console
void log_zone_distances(int *distances, int num_zones) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Zone Distances: ", timestamp);
    for (int i = 0; i < num_zones; i++) {
        printf("%d ", distances[i]);
    }
    printf("\n");
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor({64, 0}) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int zone_distances[ZONE_GRID_SIZE];
        int num_zones = 0;

        // Read zone distances
        for (int i = 0; i < ZONE_GRID_SIZE; i++) {
            if (read_zone_distance(i2c_handle, &zone_distances[i]) == 0) {
                num_zones++;
            } else {
                fprintf(stderr, "Failed to read zone distance %d\n", i);
            }
        }

        // Log zone distances
        log_zone_distances(zone_distances, num_zones);

        // Delay for 500ms
        gpioDelay(500000); // 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

