#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_THRESHOLD 50  // ms
#define SERVO_RANGE 180.0    // degrees
#define SERVO_MIN -90.0      // degrees
#define SERVO_MAX +90.0      // degrees

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioSetServoRange(SERVO_PIN, SERVO_RANGE);
    gpioSetServoPulseWidth(SERVO_PIN, 0); // Ensure servo is initially at 0 degrees

    return 0;
}

// Read sensor data
int read_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    long start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_THRESHOLD) {
            fprintf(stderr, "Timeout waiting for echo\n");
            return -1; // Timeout
        }
    }

    long end_tick = gpioTick();
    long pulse_width = end_tick - start_tick;

    return pulse_width;
}

// Map distance to servo angle
float map_distance_to_angle(float distance) {
    if (distance < 0) {
        return -90.0; // Error value
    }
    return (float)distance / 400.0 * SERVO_RANGE;
}

// Set servo angle
void set_servo_angle(float angle) {
    if (angle < SERVO_MIN || angle > SERVO_MAX) {
        fprintf(stderr, "Invalid servo angle: %f\n", angle);
        return;
    }

    gpioServo(SERVO_PIN, (int)(angle * 1000.0 / SERVO_RANGE)); // Convert angle to pulse width (0-1000)
}

// Log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking-assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int distance = read_sensor();
        if (distance >= 0) {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }

        gpioDelay(200); // Wait 200ms
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
    fclose(log_file);

    return 0;
}

