#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <sys/time.h>
#include <sys/select.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/tmp/distance_queue"
#define BUZZER_DURATION_MS 500

// Global variables
int i2c_handle;
int message_queue_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_message_queue();
int init_gpio();
int read_distance();
int log_distance(int distance);
int activate_buzzer(int duration_ms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize message queue
int init_message_queue() {
    message_queue_fd = mkfifo(MESSAGE_QUEUE_NAME, 0666);
    if (message_queue_fd == -1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char buf[2];
    int distance;

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Log distance to message queue
int log_distance(int distance) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[20];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03d", (int)(tv.tv_usec / 1000));

    if (write(message_queue_fd, timestamp, strlen(timestamp)) < 0) {
        fprintf(stderr, "Error writing to message queue: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize message queue
    if (init_message_queue() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        close(message_queue_fd);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Distance logger started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            if (distance < DISTANCE_THRESHOLD) {
                printf("Distance below threshold: %d mm\n", distance);
                activate_buzzer(BUZZER_DURATION_MS);
            } else {
                log_distance(distance);
            }
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }

        gpioDelay(50); // Wait 50ms
    }

    // Cleanup
