#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define BUZZER_DURATION_MS 500  // 500ms buzzer duration

// Global variables
volatile int echo_start_time = 0;
volatile int echo_end_time = 0;
volatile int echo_duration = 0;
volatile int buzzer_active = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
void cleanup();
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo line
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
    } else if (level == 0) {
        echo_end_time = tick;
        echo_duration = tick - echo_start_time;
        if (echo_duration > TIMEOUT_US) {
            echo_duration = TIMEOUT_US; // Reset timeout if it exceeds
        }
    }
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(ECHO_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting.\n", signal);
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-up/down resistor on ECHO_PIN (optional, but recommended)
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    // Register interrupt handler for ECHO_PIN
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_sensor();
        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

