#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define ELE0_GPIO 2
#define ELE1_GPIO 3
#define ELE2_GPIO 4
#define ELE3_GPIO 5
#define ELE4_GPIO 6
#define ELE5_GPIO 7
#define ELE6_GPIO 8
#define ELE7_GPIO 9
#define ELE8_GPIO 10
#define ELE9_GPIO 11
#define ELE10_GPIO 12
#define ELE11_GPIO 13
#define LED_GPIO 17
#define LED_GPIO_HIGH 17
#define LED_GPIO_LOW 18
#define LED_GPIO_PWM 27
#define LED_GPIO_PWM_HIGH 27
#define LED_GPIO_PWM_LOW 27
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A

// Define MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_ELECTRODE_CONFIG_BIT 0x01
#define MPR121_ELECTRODE_CONFIG_VALUE 0x0F

// Define LED patterns
#define LED_PATTERN_0 0x0F
#define LED_PATTERN_1 0x0A
#define LED_PATTERN_2 0x05
#define LED_PATTERN_3 0x02
#define LED_PATTERN_4 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mpr121_register(int handle, int reg);
int write_mpr121_register(int handle, int reg, int value);
int read_mpr121_touch_status(int handle);
void set_led_pattern(int gpio, int pattern);
void log_proximity_event(int electrode);
void signal_handler(int signal);

// Function to read a single byte from an I2C register
int read_i2c_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_i2c_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the touch status from the MPR121
int read_mpr121_touch_status(int handle) {
    int touch_status = read_i2c_register(handle, MPR121_TOUCHSTATUS_L);
    if (touch_status < 0) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    return touch_status;
}

// Function to set the LED pattern
void set_led_pattern(int gpio, int pattern) {
    gpioWrite(gpio, pattern);
}

// Function to log proximity events
void log_proximity_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Proximity detected on electrode %d\n", timestamp, electrode);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(ELE0_GPIO, PI_INPUT);
    gpioSetMode(ELE1_GPIO, PI_INPUT);
    gpioSetMode(ELE2_GPIO, PI_INPUT);
    gpioSetMode(ELE3_GPIO, PI_INPUT);
    gpioSetMode(ELE4_GPIO, PI_INPUT);
    gpioSetMode(ELE5_GPIO, PI_INPUT);
    gpioSetMode(ELE6_GPIO, PI_INPUT);
    gpioSetMode(ELE7_GPIO, PI_INPUT);
    gpioSetMode(ELE8_GPIO, PI_INPUT);
    gpioSetMode(ELE9_GPIO, PI_INPUT);
    gpioSetMode(ELE10_GPIO, PI_INPUT);
    gpioSetMode(ELE11_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GPIO_HIGH, PI_OUTPUT);
    gpioSetMode(LED_GPIO_LOW, PI_OUTPUT);
    gpioSetMode(LED_GPIO_PWM, PI_OUTPUT);
    gpioSetMode(LED_GPIO_PWM_HIGH, PI_OUTPUT);
    gpioSetMode(LED_GPIO_PWM_LOW, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Soft reset the MPR121
    if (write_mpr121_register(i2c_handle, MPR121_ELECTRODE_CONFIG, MPR121_ELECTRODE_CONFIG_BIT | MPR121_ELECTRODE_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error soft resetting MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(100); // Wait for the soft reset to complete

    // Set LED patterns
    set_led_pattern(LED_GPIO, LED_PATTERN_0);
    set_led_pattern(LED_GPIO_HIGH, LED_PATTERN_0);
    set_led_pattern(LED_GPIO_LOW, LED_PATTERN_0);
    set_led_pattern(LED_GPIO_PWM, LED_PATTERN_0);
    set_led_pattern(LED_GPIO_PWM_HIGH, LED_PATTERN_0);
    set_led_pattern(LED_GPIO_PWM_LOW, LED_PATTERN_0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int touch_status = read_mpr121_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for proximity on all electrodes
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                log_proximity_event(i);
                set_led_pattern(LED_GPIO, LED_PATTERN_0);
                gpioDelay(100); // Debounce delay
                set_led_pattern(LED_GPIO, LED_PATTERN_1);
                gpioDelay(100); // Debounce delay
                set_led_pattern(LED_GPIO, LED_PATTERN_2);
                gpioDelay(100); // Debounce delay
                set_led_pattern(LED_GPIO, LED_PATTERN_3);
                gpioDelay(100); // Debounce delay
                set_led_pattern(LED_GPIO, LED_PATTERN_4);
                gpioDelay(100); // Debounce delay
            }
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

