#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SAMPLE_RATE_HZ 100
#define TIMEOUT_US 30000 // 30ms timeout
#define SERVO_ANGLE_MIN 90
#define SERVO_ANGLE_MAX 180
#define SERVO_PULSE_WIDTH_MAX 2000
#define SERVO_PULSE_WIDTH_MIN 1000
#define SERVO_PULSE_WIDTH_STEP 100
#define NUM_SAMPLES 5
#define FILTER_WINDOW_SIZE 5

// Define data structures
typedef struct {
    time_t timestamp;
    float distance;
    int angle;
} DataPoint;

typedef struct {
    volatile int pulse_width;
    volatile int new_pulse;
} PulseWidthData;

// Global variables
volatile int pulse_width_flag = 0;
volatile int new_pulse_flag = 0;
volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
void set_servo_angle(int angle);
void log_data(float distance, int angle);
void signal_handler(int signal);
int init_gpio();
int init_pigpio();
int init_pwm();
int init_csv();
void cleanup();

// Function to trigger the HC-SR04 sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt callback function
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    PulseWidthData *data = (PulseWidthData *)user;
    if (level == 1) {
        pulse_width_flag = 1;
        new_pulse_flag = 1;
    } else if (level == 0) {
        pulse_width_flag = 0;
        new_pulse_flag = 0;
    }
}

// Function to set the servo motor angle
void set_servo_angle(int angle) {
    if (angle < SERVO_ANGLE_MIN || angle > SERVO_ANGLE_MAX) {
        fprintf(stderr, "Error: Angle out of range (%.2f degrees)\n", angle);
        return;
    }

    int pulse_width = SERVO_PULSE_WIDTH_MIN + (int)((float)(angle - SERVO_ANGLE_MIN) / (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN) * (SERVO_PULSE_WIDTH_MAX - SERVO_PULSE_WIDTH_MIN));
    if (pulse_width < SERVO_PULSE_WIDTH_MIN || pulse_width > SERVO_PULSE_WIDTH_MAX) {
        fprintf(stderr, "Error: Pulse width out of range (%.2f)\n", pulse_width);
        return;
    }

    gpioServo(18, pulse_width);
}

// Function to log data to a CSV file
void log_data(float distance, int angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    running = 0;
}

// Function to initialize GPIO and pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize pigpio and PWM
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 1000); // 1kHz PWM frequency
    gpioSetPWMrange(SERVO_PIN, SERVO_PULSE_WIDTH_MAX); // PWM range

    return 0;
}

// Function to initialize PWM
int init_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetPWMfrequency(SERVO_PIN, 1000); // 1kHz PWM frequency
    gpioSetPWMrange(SERVO_PIN, SERVO_PULSE_WIDTH_MAX); // PWM range

    return 0;
}

// Function to initialize CSV file
int init_csv() {
    FILE *fp = fopen("distance_log.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv for writing\n");
        return -1;
    }

    fprintf(fp, "Timestamp,Distance(cm),Angle(degrees)\n");
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO and pigpio
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger pin is low
    gpioSetPWMfrequency(SERVO_PIN, 0); // Stop PWM
    gpioSetPWMrange(SERVO_PIN, 0);
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO and pigpio
    if (init_gpio() != 0) {
        return 1;
    }
    if (init_pigpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_pwm() != 0) {
        cleanup();
        return 1;
    }
    if (init_csv() != 0) {
        cleanup();
        return 1;
    }

    // Set up interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for the echo to be ready
        int timeout = 0;
        while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
        }
        if (timeout >= TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin not ready after %d us\n", TIMEOUT_US);
            break;
        }

        // Measure the echo pulse width
        gpioDelay(30); // Wait for 30ms
        int pulse_width = gpioRead(ECHO_PIN);
        if (pulse_width < 0) {
            fprintf(stderr, "Error: ECHOPIN read error\n");
            break;
        }

        // Calculate distance
        float distance = (float)pulse_width / 2.0; // Divide by 2 for accurate distance calculation

        // Log the data
        log_data(distance, 0);

        // Set servo angle
        set_servo_angle(0); // Set servo to 90 degrees

        // Wait for the servo to reach the desired angle
        int timeout = 0;
        while (gpioRead(SERVO_PIN) == 0 && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
        }
        if (timeout >= TIMEOUT_US) {
            fprintf(stderr, "Error: Servo pin not ready after %d us\n", TIMEOUT_US);
            break;
        }

        // Set servo angle
        set_servo_angle(90); // Set servo to 90 degrees

        // Wait for the servo to reach the desired angle
        timeout = 0;
        while (gpioRead(SERVO_PIN) == 1 && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
        }
        if (timeout >= TIMEOUT_US) {
            fprintf(stderr, "Error: Servo pin not ready after %d us\n", TIMEOUT_US);
            break;
        }

        // Check for invalid distance reading
        if (distance < 0 || distance > 400) {
            fprintf(stderr, "Error: Invalid distance reading: %.2f cm\n", distance);
            log_data(-1.0, 0); // Log -1.0 to indicate invalid reading
        }

        // Set servo angle to 90 degrees
        set_servo_angle(90);

        // Wait for the servo to reach the desired angle
        timeout = 0;
        while (gpioRead(SERVO_PIN) == 1 && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
        }
        if (timeout >= TIMEOUT_US) {
            fprintf(stderr, "Error: Servo pin not ready after %d us\n", TIMEOUT_US);
            break;
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

