#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define WARNING_LED_GPIO 17
#define WARNING_THRESHOLD 200
#define BUFFER_SIZE 10
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure for circular buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_distance(int *distance);
void add_to_buffer(CircularBuffer *buffer, int distance);
int is_below_threshold(int distance);
void control_warning_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from VL53L1X sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Read two bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to add distance reading to circular buffer
void add_to_buffer(CircularBuffer *buffer, int distance) {
    buffer->buffer[buffer->head] = distance;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to check if distance is below threshold
int is_below_threshold(int distance) {
    return distance < WARNING_THRESHOLD;
}

// Function to control the warning LED
void control_warning_led(int state) {
    gpioWrite(WARNING_LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

