    CircularBuffer distance_buffer;
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("VL53L1X distance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Add distance to circular buffer
            add_to_buffer(&distance_buffer, distance);

            // Check if distance is below threshold
            if (is_below_threshold(distance)) {
                control_warning_led(1); // Turn on LED
            } else {
                control_warning_led(0); // Turn off LED
            }

            // Print distance reading
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
