#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define GPIO_PIN 27
#define THRESHOLD 1000
#define LOG_FILE "proximity.log"
#define INTERRUPT_FLAGS 0x0 // No flags
#define INTERRUPT_MODE 0x0 // Interrupt on rising edge

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int pin);
int read_proximity(int i2c_handle);
int process_proximity(int raw_value);
int set_interrupt_flag(int i2c_handle, int flag);
int set_interrupt_mode(int i2c_handle, int mode);
int log_proximity(int raw_value, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Function to initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", pin);
        return -1;
    }
    return 0;
}

// Function to read proximity value from Si1102
int read_proximity(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to process proximity value
int process_proximity(int raw_value) {
    return (raw_value > THRESHOLD) ? "SAFE" : "ALERT";
}

// Function to set interrupt flag
int set_interrupt_flag(int i2c_handle, int flag) {
    char buf[2];
    buf[0] = INTERRUPT_FLAGS;
    buf[1] = flag;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing interrupt flag: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to set interrupt mode
int set_interrupt_mode(int i2c_handle, int mode) {
    char buf[2];
    buf[0] = INTERRUPT_MODE;
    buf[1] = mode;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing interrupt mode: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to log proximity data
int log_proximity(int raw_value, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%s\n", timestamp, raw_value, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int raw_value = read_proximity(i2c_handle);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading proximity value in interrupt handler\n");
        return;
    }

    int status = process_proximity(raw_value);
    log_proximity(raw_value, status);

    set_interrupt_flag(i2c_handle, INTERRUPT_FLAGS);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        int i2c_address = strtol(argv[1], NULL, 0);
        if (i2c_address == 0) {
            fprintf(stderr, "Invalid I2C address. Using default address 0x60.\n");
            i2c_address = SI1102_ADDR;
        }
        printf("Using I2C address: 0x%02X\n", i2c_address);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set interrupt flag
    if (set_interrupt_flag(i2c_handle, INTERRUPT_FLAGS) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set interrupt mode
    if (set_interrupt_mode(i2c_handle, INTERRUPT_MODE) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, INTERRUPT_MODE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    set_interrupt_flag(i2c_handle, INTERRUPT_FLAGS);
    set_interrupt_mode(i2c_handle, INTERRUPT_MODE);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

