#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define TRIGGER_DELAY_US 10000  // 10 ms
#define ECHO_TIMEOUT_US 100000  // 100 ms
#define BUZZER_FREQUENCY_HZ 200
#define BUZZER_DUTY_CYCLE_MAX 500
#define BUZZER_DUTY_CYCLE_MIN 50
#define BUZZER_PWM_RANGE 1000

// Global variables
volatile int echo_start_time = 0;
volatile int echo_end_time = 0;
volatile int echo_timeout_count = 0;

// Function prototypes
int initialize_gpio();
int read_distance();
float map_distance_to_frequency(float distance);
void generate_tone(float frequency);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioSetPWMrange(BUZZER_PIN, BUZZER_PWM_RANGE);
    gpioSetPWMrange(BUZZER_PIN, BUZZER_PWM_RANGE);
    gpioSetPWMrange(BUZZER_PIN, BUZZER_PWM_RANGE);

    return 0;
}

// Read distance from HC-SR04 sensor
int read_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    echo_start_time = 0;
    echo_end_time = 0;
    echo_timeout_count = 0;

    // Wait for echo to start
    while (gpioRead(ECHO_PIN) == 0 && echo_start_time == 0) {
        echo_start_time = time_time();
    }

    if (echo_start_time == 0) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1; // Indicate error
    }

    // Wait for echo to end
    while (gpioRead(ECHO_PIN) == 1 && echo_end_time == 0) {
        echo_end_time = time_time();
    }

    if (echo_end_time == 0) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1; // Indicate error
    }

    // Calculate echo pulse width in microseconds
    int pulse_width = echo_end_time - echo_start_time;

    // Validate pulse width
    if (pulse_width < 0 || pulse_width > 2000000) {
        fprintf(stderr, "Error: Invalid pulse width: %d us\n", pulse_width);
        return -1; // Indicate error
    }

    return pulse_width;
}

// Map distance to frequency using a linear function
float map_distance_to_frequency(float distance) {
    if (distance < 5.0) {
        return (float)distance * (BUZZER_FREQUENCY_HZ / 5.0);
    } else if (distance > 50.0) {
        return (float)(50.0 - distance) * (BUZZER_FREQUENCY_HZ / 50.0);
    } else {
        return BUZZER_FREQUENCY_HZ;
    }
}

// Generate a continuous tone on the buzzer
void generate_tone(float frequency) {
    if (frequency > 0) {
        int duty_cycle = (int)((frequency / BUZZER_FREQUENCY_HZ) * BUZZER_DUTY_CYCLE_MAX);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > BUZZER_DUTY_CYCLE_MAX) duty_cycle = BUZZER_DUTY_CYCLE_MAX;

        gpioPWM(BUZZER_PIN, duty_cycle);
    } else {
