    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to read the echo pulse duration
long readEcho() {
    long start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start_tick) < TIMEOUT_US) {
        // Wait for echo to go high
    }
    if (gpioRead(ECHO_PIN) == 0) {
        return -1; // Timeout
    }
    long end_tick = gpioTick();
    return end_tick - start_tick;
}

// Function to convert pulse duration to distance
double pulseToDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 to get distance in cm
}

// Function to validate distance reading
int validateDistance(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0; // Invalid reading
    }
    return 1; // Valid reading
}

// Function to print the distance reading
void printDistance(double distance) {
    if (distance < 0) {
        printf("Invalid reading: %.2f cm\n", distance);
    } else if (distance < 10.0) {
        printf("Too close!\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

