    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulse_duration = readEcho();

        if (pulse_duration > 0) {
            double distance = pulseToDistance(pulse_duration);

            if (validateDistance(distance)) {
                printDistance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout reading\n");
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

