// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define MAX_DISTANCE 5000
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float distance;
    time_t timestamp;
} SensorData;

// Function prototypes
int spi_read_data(int channel, unsigned char *data, int len);
int init_spi(int channel);
int init_gpio(int pin);
int init_log_file(const char *filename);
int log_data(FILE *fp, float distance, time_t timestamp);
void signal_handler(int signal);
void cleanup();

// SPI read function
int spi_read_data(int channel, unsigned char *data, int len) {
    int result = spiRead(spi_handle, data, len);
    if (result != len) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }
    return 0;
}

// SPI initialization function
int init_spi(int channel) {
    spi_handle = spiOpen(channel, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// GPIO initialization function
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, float distance, time_t timestamp) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f\n", timestamp_str, distance);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi(SPI_CHANNEL) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(CS_PIN) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        unsigned char data[4];
        int retries = 0;
        time_t start_time = time(NULL);

        while (retries < MAX_RETRIES) {
            if (spi_read_data(SPI_CHANNEL, data, 4) == 0) {
                // Check for valid data (example: checksum is 0x55)
                if (data[0] == 0x55) {
                    // Extract distance (2 bytes)
                    int distance = (data[1] << 8) | data[2];

                    // Get current timestamp
                    time_t current_time = time(NULL);

                    // Validate timestamp
                    if (current_time - start_time > 0) {
                        // Log data
                        if (log_data(log_file, distance, current_time) != 0) {
                            fprintf(stderr, "Failed to log data\n");
                        }
                        break; // Exit loop on success
                    } else {
                        fprintf(stderr, "Invalid timestamp\n");
                    }
                } else {
                    fprintf(stderr, "Invalid data checksum\n");
                }
            } else {
                fprintf(stderr, "SPI read failed, retrying...\n");
                gpioDelay(10); // Small delay before retrying
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
            cleanup();
            return 1;
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

