#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x60
#define LOG_FILE "proximity_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure for sensor data
typedef struct {
    uint16_t als_visible;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_als_value();
int write_command(uint8_t command);
int read_data(uint8_t *data, int len);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Writes a command to the Si1175
int write_command(uint8_t command) {
    int result = i2cWriteByteData(i2c_handle, 0x00, command);
    if (result < 0) {
        fprintf(stderr, "Error writing command 0x%02X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Reads data from the Si1175
int read_data(uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads the ambient light value from the Si1175
int read_als_value() {
    uint8_t als_visible_data[2];
    if (read_data(als_visible_data, 2) != 0) {
        return -1;
    }

    return (als_visible_data[0] << 8) | als_visible_data[1];
}

// Logs the sensor data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, data.als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
