#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_ALS_REG 0x00
#define SI1120_PROX_REG 0x02
#define SI1120_RESET_REG 0x03
#define SI1120_PART_ID_REG 0x04
#define SI1120_COMMAND 0x08
#define SI1120_DATA_LEN 2
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define LOG_FILE "si1120_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_si1120_data(uint16_t *als_data, uint16_t *proximity_data);
int verify_si1120_data(uint16_t als_data, uint16_t proximity_data);
int log_data(uint16_t als_data, uint16_t proximity_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from Si1120 sensor
int read_si1120_data(uint16_t *als_data, uint16_t *proximity_data) {
    char buf[SI1120_DATA_LEN];
    int result;

    // Reset the sensor
    result = i2cWriteByteData(i2c_handle, SI1120_RESET_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error resetting sensor: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, SI1120_ALS_REG, buf, SI1120_DATA_LEN);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    // Read Proximity data
    result = i2cReadI2CBlockData(i2c_handle, SI1120_PROX_REG, buf, SI1120_DATA_LEN);
    if (result < 0) {
        fprintf(stderr, "Error reading Proximity data: %d\n", result);
        return -1;
    }

    *als_data = (uint16_t)((buf[0] << 8) | buf[1]);
    *proximity_data = (uint16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Verify Si1120 data
int verify_si1120_data(uint16_t als_data, uint16_t proximity_data) {
    if (als_data != proximity_data) {
        fprintf(stderr, "Error: ALS and Proximity data mismatch\n");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(uint16_t als_data, uint16_t proximity_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, als_data, proximity_data);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t als_data, proximity_data;
    int retries = 0;

    // Main loop
    while (!terminate) {
        // Read data
        if (read_si1120_data(&als_data, &proximity_data) == 0) {
            // Verify data
            if (verify_si1120_data(als_data, proximity_data) == 0) {
                // Log data
                if (log_data(als_data, proximity_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error: Si1120 data verification failed\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read Si1120 data\n");
        }

        // Delay
        gpioDelay(500); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

