#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_THRESHOLD 20.0 // cm
#define TIMEOUT_US 50000        // 50ms timeout

// Global variables
volatile unsigned int trigger_start_time = 0;
volatile unsigned int echo_start_time = 0;
volatile unsigned int echo_end_time = 0;
volatile unsigned int echo_width = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *user);
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
    int buzzer_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);
    gpioSetMode(config->buzzer_pin, PI_OUTPUT);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(config->trigger_pin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(config->trigger_pin, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick, void *user) {
    if (level == 1) {
        echo_start_time = tick;
    } else if (level == 0) {
        echo_end_time = tick;
    }
}

// Function to measure the echo pulse width
unsigned int measure_echo_width() {
    if (echo_start_time == 0 || echo_end_time == 0) {
        return 0; // Timeout
    }

    unsigned int start_time = echo_start_time;
    unsigned int end_time = echo_end_time;

    if (echo_start_time == 0) {
        echo_start_time = tick;
    } else {
        echo_end_time = tick;
    }

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 to get distance in cm
}

// Function to check if the distance is below the threshold
int is_distance_below_threshold(float distance) {
    return distance < DISTANCE_THRESHOLD;
}

// Function to set the buzzer pin high or low
void set_buzzer_pin(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to clean up GPIO resources
void cleanup() {
    gpioWrite(config->buzzer_pin, 0); // Ensure buzzer is off
    gpioTerminate();
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

int main() {
    gpio_config_t config = {
        .trigger_pin = TRIGGER_PIN,
        .echo_pin = ECHO_PIN,
        .buzzer_pin = BUZZER_PIN
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&config) != 0) {
        return 1;
    }

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(config.echo_pin, RISING_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for echo pin\n");
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(config.trigger_pin, FALLING_EDGE, 0, trigger_pulse, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for trigger pin\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Measure echo pulse width
        unsigned int pulse_width = measure_echo_width();

        if (pulse_width > 0) {
            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Check if distance is below threshold
            if (is_distance_below_threshold(distance)) {
                // Set buzzer pin high
                set_buzzer_pin(config.buzzer_pin, 1);
                printf("Distance below threshold! Distance: %.2f cm\n", distance);
            } else {
                // Set buzzer pin low
                set_buzzer_pin(config.buzzer_pin, 0);
            }
        } else {
            // Timeout occurred
            printf("Timeout occurred\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

