#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0     // cm
#define MIN_DISTANCE 0.0       // cm
#define MIN_SERVO_ANGLE 0.0    // degrees
#define MAX_SERVO_ANGLE 180.0   // degrees

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float getDistance();
void setServoAngle(int angle);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to get distance in centimeters
float getDistance() {
    long long start_tick, end_tick, diff;
    float distance;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 1000000) { // Timeout after 1 second
            fprintf(stderr, "Error: Echo timeout on trigger pin\n");
            return -1.0; // Indicate error
        }
    }
    start_tick = gpioTick();

    // Measure the echo pulse
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > 1000000) { // Timeout after 1 second
            fprintf(stderr, "Error: Echo timeout on echo pin\n");
            return -1.0; // Indicate error
        }
    }
    end_tick = gpioTick();

    diff = end_tick - start_tick;
    distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Distance in cm

    return distance;
}

// Function to set servo angle
void setServoAngle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Map angle to pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2500);

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking-assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = getDistance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);

            // Map distance to servo angle
            int angle = (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * 180.0);
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;

            setServoAngle(angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

