#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI7005_ADDR 0x40

// Define the register addresses
#define CONFIG_REG 0x01
#define MEASURE_REG 0x02
#define TEMP_REG 0x04
#define HUMID_REG 0x06

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the Si7005 sensor
int init_si7005() {
    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor() {
    int raw_temp, raw_humidity;

    // Read temperature
    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data.\n");
        return -1;
    }

    // Read humidity
    raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data.\n");
        return -1;
    }

    // Convert raw data to Celsius and percentage
    float temperature = (175.72 * raw_temp) / 65536.0 - 46.85;
    float humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

// Function to log the sensor data to the console
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si7005() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor() < 0) {
            fprintf(stderr, "Error reading sensor data.\n");
        } else {
            // Log the data
            log_data(temperature, humidity);
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

