#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the MPU-6050
int16_t read_register(int handle, uint8_t reg) {
    int16_t value = i2cReadWordData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return 0; // Return 0 on error
    }
    return value;
}

// Function to read accelerometer data
int16_t read_accel_data(int handle) {
    int16_t accel_x = read_register(handle, ACCEL_XOUT_H);
    int16_t accel_y = read_register(handle, ACCEL_XOUT_H + 2);
    int16_t accel_z = read_register(handle, ACCEL_XOUT_H + 4);
    return (int16_t)((accel_x << 8) | accel_y);
}

// Function to read gyroscope data
int16_t read_gyro_data(int handle) {
    int16_t gyro_x = read_register(handle, GYRO_XOUT_H);
    int16_t gyro_y = read_register(handle, GYRO_XOUT_H + 2);
    int16_t gyro_z = read_register(handle, GYRO_XOUT_H + 4);
    return (int16_t)((gyro_x << 8) | gyro_y);
}

// Function to read temperature data
int16_t read_temperature_data(int handle) {
    int16_t temp_x = read_register(handle, GYRO_XOUT_H + 6);
    int16_t temp_y = read_register(handle, GYRO_XOUT_H + 8);
    int16_t temp_z = read_register(handle, GYRO_XOUT_H + 10);
    return (int16_t)((temp_x << 8) | temp_y);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_handle, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Sensor not found: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWR_MGMT_1 to 0 to enable the accelerometer and gyroscope
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (i2cSetSlaveAddress(i2c_handle, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer and gyroscope data
        int16_t accel_x = read_accel_data(i2c_handle);
        int16_t accel_y = read_accel_data(i2c_handle);
        int16_t accel_z = read_accel_data(i2c_handle);
        int16_t gyro_x = read_gyro_data(i2c_handle);
        int16_t gyro_y = read_gyro_data(i2c_handle);
        int16_t gyro_z = read_gyro_data(i2c_handle);

        // Read temperature data
        int16_t temp_x = read_temperature_data(i2c_handle);
        int16_t temp_y = read_temperature_data(i2c_handle);
        int16_t temp_z = read_temperature_data(i2c_handle);

        // Print the data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d, Temp X: %d, Temp Y: %d, Temp Z: %d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, temp_x, temp_y, temp_z);

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

