#define ERROR_LOG_FILE "error_log.txt"

int i2c_handle;
FILE *log_file;
FILE *error_log_file;

// Structure to hold sensor data
typedef struct {
    float temperature;
    int status;
} SensorData;

// Function prototypes
int initialize_i2c();
SensorData read_temperature();
void log_data(SensorData data);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
SensorData read_temperature() {
    SensorData data;
    char buf[2];
    int bytes_read;

    // Read 2 bytes from the sensor
    bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        log_error("Failed to read temperature data.");
        data.temperature = -999.0; // Indicate error
        data.status = -1;
        return data;
    }

    // Convert the raw data to temperature (Celsius)
    int raw_temperature = (buf[0] << 8) | buf[1];
    data.temperature = (float)raw_temperature / 60.0;

    // Verify the sensor's status
    int sensor_status = (buf[0] >> 4) & 0x03;
    if (sensor_status != 0) {
        log_error("Sensor not present or not ready.");
        data.temperature = -999.0; // Indicate error
        data.status = -1;
        return data;
    }

    return data;
}

// Log data to a file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s,ERROR: %s\n", timestamp, message);
    fflush(error_log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        SensorData data = read_temperature();
        if (data.temperature != -999.0) {
            log_data(data);
        } else {
            log_error("Failed to read temperature. Check sensor or I2C connection.");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

