#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0x2C06 // High repeatability measurement command
#define LOG_FILE "sht40_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sht40(int fd, float *temperature, float *humidity);
int validate_crc(uint8_t crc, uint8_t data);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c(int bus, int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from SHT40 sensor
int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (write(fd, cmd, 2) != 2) {
            perror("Error writing measurement command");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10ms)

        if (read(fd, data, 6) != 6) {
            perror("Error reading data from SHT40");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Validate CRC
        if (!validate_crc(data[0], data[1])) {
            fprintf(stderr, "CRC validation failed for data 0x%02X 0x%02X\n", data[0], data[1]);
            return -1;
        }

        // Convert data to temperature and humidity
        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t hum_raw = (data[3] << 8) | data[4];

        *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
        *humidity = 100.0 * (float)hum_raw / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Validate CRC-8 algorithm
int validate_crc(uint8_t crc, uint8_t data) {
    uint8_t polynomial = 0x31; // CRC-8 polynomial
    uint8_t data_with_crc = data ^ 0xFF; // Data with CRC bit set

    for (int i = 0; i < 8; i++) {
        data_with_crc = (data_with_crc << 1) ^ polynomial;
        if (data_with_crc & 0x80) {
            data_with_crc = ~(data_with_crc);
        } else {
            data_with_crc = ~data_with_crc;
        }
        polynomial = (polynomial << 1) ^ 0x31; // XOR with 0x31
    }

    return (data_with_crc == crc);
}

// Log data to file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = initialize_i2c(I2C_BUS, SHT40_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            // Validate CRC
            if (validate_crc(temperature, humidity)) {
                // Log data
                if (log_data(log_file, temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }

                // Print data to console
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "CRC validation failed.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

