#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define MEASURE_CMD 0x3600 // Continuous measurement command
#define MEASURE_DURATION_MS 100
#define LOG_FILE "airflow.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sdp31(int i2c_handle, float *pressure, float *temperature);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP31 sensor
int read_sdp31(int i2c_handle, float *pressure, float *temperature) {
    char buf[6];
    int bytes_read;
    int16_t pressure_raw, temperature_raw;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 6);
        if (bytes_read == 6) {
            // Convert raw data to pressure and temperature
            pressure_raw = (int16_t)((buf[0] << 8) | buf[1]);
            temperature_raw = (int16_t)((buf[3] << 8) | buf[4]);

            // Validate CRC
            if (pressure_raw == (int16_t)((buf[0] & 0xFF) | (buf[1] << 8))) {
                if (temperature_raw == (int16_t)((buf[3] & 0xFF) | (buf[4] << 8))) {
                    // Convert raw data to pressure and temperature
                    *pressure = (float)pressure_raw / 60.0; // Scaling factor from datasheet
                    *temperature = (float)temperature_raw / 200.0; // Scaling factor from datasheet
                    return 0; // Success
                } else {
                    fprintf(stderr, "Temperature CRC check failed!\n");
                    retries++;
                    gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
                }
            } else {
                fprintf(stderr, "Pressure CRC check failed!\n");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
            }
        } else {
            fprintf(stderr, "I2C read failed: %d\n", bytes_read);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retry
        }
    }

    fprintf(stderr, "Failed to read SDP31 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    float pressure, temperature;
    SensorData sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

