        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (read_sdp31(i2c_handle, &pressure, &temperature) == 0) {
            // Convert data to sensor_data
            sensor_data.pressure = pressure;
            sensor_data.temperature = temperature;

