#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define MEASURE_CMD 0x00
#define LOG_FILE "sensor_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int write_command(int handle, uint8_t command);
int read_data(int handle, uint8_t *data, int len);
SensorData read_sensor_data(int handle);
void log_data(SensorData data);
void signal_handler(int signal);
int initialize_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Write a command to the Si7015 sensor
int write_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Error writing command 0x%02X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the Si7015 sensor
int read_data(int handle, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature and humidity from the Si7015 sensor
SensorData read_sensor_data(int handle) {
    SensorData data;
    uint8_t buffer[6];
    int result;

    // Write command to trigger measurement
    result = write_command(handle, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Error writing measurement command: %s\n", strerror(errno));
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10);

    // Read 6 bytes of data
    result = read_data(handle, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert raw data to temperature and humidity
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    int16_t raw_humidity = (buffer[3] << 8) | buffer[4];

    data.temperature = (float)raw_temperature / 100.0;
    data.humidity = (float)raw_humidity / 100.0;

    return data;
}

// Log sensor data to file
void log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        i2cClose(i2c_handle);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        SensorData sensor_data = read_sensor_data(i2c_handle);

        // Log data
        log_data(sensor_data);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

