#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x70
#define MEASURE_CMD 0x362F // Single shot, high repeatability
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_MS 5000
#define CRC_POLYNOMIAL 0x31 // CRC-8 polynomial
#define CRC_INITIAL_VALUE 0x00

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    int crc_check;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sts30(sensor_data_t *data);
int validate_crc(uint8_t crc, uint8_t data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from STS30 sensor
int read_sts30(sensor_data_t *data) {
    char buf[6];
    int bytes_read;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD) < 0) {
        fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    bytes_read = i2cReadDevice(i2c_handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    // CRC check
    if (validate_crc(buf[2], buf[0]) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Extract temperature data
    data->temperature = (float)((buf[0] << 8) | buf[1]) / 10.0;
    data->crc_check = validate_crc(buf[3], buf[4]);

    return 0;
}

// Function to validate CRC checksum
int validate_crc(uint8_t crc, uint8_t data) {
    uint8_t polynomial = CRC_POLYNOMIAL;
    uint8_t initial_value = CRC_INITIAL_VALUE;
    uint8_t xor_result = 0;

    for (int i = 0; i < 8; i++) {
        xor_result ^= data & 0x01;
        data >>= 1;
        if (xor_result & 0x80) {
            xor_result ^= polynomial;
        }
    }

    return (crc == xor_result);
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.temperature, data.crc_check, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting temperature measurement...\n");

    while (!terminate) {
        ret = read_sts30(&sensor_data);
        if (ret == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    cleanup();
    return 0;
}

