// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0x2C06 // High repeatability measurement command
#define LOG_FILE "sht40_log.txt"
#define READ_DELAY_MS 8500
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sht40(sensor_data_t *data);
int validate_crc(unsigned char crc, unsigned char data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result < 0) {
            fprintf(stderr, "Error writing measurement command: %d\n", result);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(200); // Wait for measurement (at least 180ms)

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result < 0) {
            fprintf(stderr, "Error reading data: %d\n", result);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(buf[0], buf[1])) {
            fprintf(stderr, "CRC validation failed for temperature data\n");
            return -1;
        }
        if (!validate_crc(buf[2], buf[3])) {
            fprintf(stderr, "CRC validation failed for humidity data\n");
            return -1;
        }

        // Convert data
        data->temperature = -45.0 + 175.0 * (float)((buf[0] << 8) | buf[1]) / 65535.0;
        data->humidity = 100.0 * (float)((buf[2] << 8) | buf[3]) / 65535.0;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 data after %d retries\n", RETRY_COUNT);
    return -1;
}

// Validate CRC-8 algorithm
int validate_crc(unsigned char crc, unsigned char data) {
    unsigned char polynomial = 0x31;
    unsigned char result = 0;

    for (int i = 0; i < 8; i++) {
        result = (result << 1) ^ (crc & 0x1);
        crc = (crc >> 1) & 0xFE;
        if (i < 7) {
            result = (result << 1) ^ polynomial;
        }
    }

    return (result == data);
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        if (read_sht40(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

