#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMPERATURE_THRESHOLD 28.0
#define FAN_OFF_THRESHOLD 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
} sensor_data_t;

sensor_data_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_si7021(int i2c_handle, float *temperature);
void add_to_buffer(float temperature);
void print_buffer();
void control_fan(float temperature);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from Si7021
int read_si7021(int i2c_handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    *temperature = (175.72 * (buf[0] >> 8)) / 100.0 - 46.85;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(float temperature) {
    sensor_data_t new_data;
    new_data.timestamp = time(NULL);
    new_data.temperature = temperature;

    sensor_buffer[buffer_index] = new_data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        printf("Buffer is full!\n");
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Temperature Data:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %ld, Temperature: %.2f\n", sensor_buffer[i].timestamp, sensor_buffer[i].temperature);
    }
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMPERATURE_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON\n");
    } else if (temperature < FAN_OFF_THRESHOLD) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_si7021(i2c_handle, &temperature) == 0) {
            add_to_buffer(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

