#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x33
#define CO2_THRESHOLD 1000.0
#define LED_GPIO 17
#define BUFFER_SIZE 20

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float co2[BUFFER_SIZE];
    time_t timestamp[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer co2_buffer;

// Function prototypes
int initialize_i2c();
int read_scd40(float *co2, float *temperature, float *humidity);
int validate_checksum(uint16_t data);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SCD40 sensor
int read_scd40(float *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x24, 0x00}; // Trigger measurement command
    uint8_t data[6];
    int result;

    // Send trigger measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (datasheet specifies >1ms)
    gpioDelay(2000); // 2ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate checksum
    if (!validate_checksum(data[0])) {
        fprintf(stderr, "Checksum validation failed\n");
        return -1;
    }

    // Convert data to CO2, temperature, and humidity
    *co2 = (float)data[0] * 0.01; // CO2
    *temperature = -45 + 175 * (float)data[1] / 65535.0; // Temperature
    *humidity = 100 * (float)data[2] / 65535.0;      // Humidity

    return 0;
}

// Function to validate checksum
int validate_checksum(uint16_t data) {
    uint8_t crc = 0;
    uint8_t data_with_crc[2];

    data_with_crc[0] = (uint8_t)(data >> 8);
    data_with_crc[1] = (uint8_t)data;

    crc = (uint8_t)data_with_crc[0];

    for (int i = 0; i < 2; i++) {
        crc ^= data_with_crc[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == data[1]);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and GPIO
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

