    float co2, temperature, humidity;
    time_t current_time;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    co2_buffer.head = 0;
    co2_buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd40(&co2, &temperature, &humidity) == 0) {
            // Store data in circular buffer
            current_time = time(NULL);
            co2_buffer.co2[co2_buffer.head] = co2;
            co2_buffer.timestamp[co2_buffer.head] = current_time;
            co2_buffer.head = (co2_buffer.head + 1) % BUFFER_SIZE;
            if (co2_buffer.count < BUFFER_SIZE) {
                co2_buffer.count++;
            }

            // Validate checksum
            if (validate_checksum(co2_buffer.co2[co2_buffer.head])) {
                printf("CO2: %.2f ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);
            } else {
                fprintf(stderr, "CO2 checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

