#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50000
#define MAX_FAILURES 3

// Structure to hold sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} SensorData;

// Global variables
int gpio_initialized = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor_data(float *temperature);
float calculate_temperature(int high_pulse_width, int total_cycle_width);
void log_data(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initializes the pigpio library and sets the GPIO pin as an input
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    gpio_initialized = 1;
    return 0;
}

// Reads the raw PWM data from the GPIO pin
int read_sensor_data(float *temperature) {
    int high_pulse_width = 0;
    int total_cycle_width = 0;

    // Read the high pulse width
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Ensure pull-up is enabled
    int high_pulse_width_raw = gpioRead(GPIO_PIN);

    // Read the total cycle width
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Ensure pull-up is enabled
    int total_cycle_width_raw = gpioRead(GPIO_PIN);

    if (high_pulse_width_raw < 0 || total_cycle_width_raw < 0) {
        fprintf(stderr, "Error reading GPIO pin\n");
        return -1;
    }

    // Calculate the high pulse width in microseconds
    high_pulse_width = (int)((float)high_pulse_width_raw * 1000.0 / (1 << 30));

    // Calculate the total cycle width in microseconds
    total_cycle_width = (int)((float)total_cycle_width_raw * 1000.0 / (1 << 30));

    // Validate the data
    if (high_pulse_width < 0 || high_pulse_width > 1000000 || total_cycle_width < 0 || total_cycle_width > 1000000) {
        fprintf(stderr, "Invalid sensor data: high_pulse_width=%d, total_cycle_width=%d\n", high_pulse_width, total_cycle_width);
        return -1;
    }

    // Calculate the temperature
    *temperature = calculate_temperature(high_pulse_width, total_cycle_width);

    return 0;
}

// Calculates the temperature from the high pulse width and total cycle width
float calculate_temperature(int high_pulse_width, int total_cycle_width) {
    if (total_cycle_width == 0) {
        return -273.15; // Dummy value for division by zero
    }
    return (float)high_pulse_width / (float)total_cycle_width * 100.0;
}

