#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400 // High repeatability, clock stretching disabled
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sht35(int i2c_handle, float *temperature, float *humidity);
int validate_crc(uint16_t temperature_raw, uint16_t humidity_raw);
SensorData process_data(float temperature, float humidity);
void log_data(SensorData data);
void signal_handler(int signal);

// CRC calculation function
uint16_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature and humidity from SHT35
int read_sht35(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (datasheet specifies at least 10ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // CRC check
    if (validate_crc(data[0], data[1]) != 0 || validate_crc(data[2], data[3]) != 0 ||
        validate_crc(data[4], data[5]) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[2] << 8) | data[3];

    *temperature = -45.0 + (175.0 * temperature_raw / 65535.0);
    *humidity = -6.0 + (125.0 * humidity_raw / 65535.0);

    return 0;
}

// Validate CRC
int validate_crc(uint16_t temperature_raw, uint16_t humidity_raw) {
    uint16_t crc = crc8(temperature_raw, 1);
    uint16_t expected_crc = crc8(humidity_raw, 1);

    if (crc != expected_crc) {
        fprintf(stderr, "CRC check failed for temperature: 0x%04X, expected 0x%04X\n", temperature_raw, expected_crc);
        return -1;
    }

    if (crc != 0xFFFF) {
        fprintf(stderr, "CRC check failed for humidity: 0x%04X, expected 0x%04X\n", humidity_raw, expected_crc);
        return -1;
    }

    return 0;
}

// Process data
SensorData process_data(float temperature, float humidity) {
    SensorData data;
    data.temperature = temperature;
    data.humidity = humidity;
    return data;
}

// Log data to file
void log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    float temperature, humidity;
    SensorData data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            // Process data
            data = process_data(temperature, humidity);

            // Log data
            log_data(data);

            // Calculate sinusoidal offset
            data.temperature += 2.0;
            data.humidity += 5.0;

            // Print data
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 5 seconds
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

