#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_I2C_ADDR 0x25
#define MEASURE_CMD_HIGH 0x36
#define MEASURE_CMD_LOW 0x37
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define CRC8_BIT_SHIFT 0
#define CRC8_BIT_MASK 0xFE
#define CRC8_RESULT_BIT 0
#define CRC8_RESULT_BYTE (CRC8_RESULT_BIT >> CRC8_BIT_SHIFT)
#define CRC8_RESULT_BITS (CRC8_RESULT_BIT & CRC8_BIT_MASK)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measure_command(int handle, unsigned char command);
int read_sensor_data(int handle, unsigned char *data);
int validate_crc8(unsigned char data[], unsigned char crc);
sensor_data_t process_sensor_data(unsigned char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send the measurement command
int send_measure_command(int handle, unsigned char command) {
    char buf[2];
    buf[0] = command;
    buf[1] = 0x00; // Dummy byte for command
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, unsigned char *data) {
    int result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC8 checksum
int validate_crc8(unsigned char data[], unsigned char crc) {
    unsigned char crc_byte = data[0];
    unsigned char crc_bit = data[1];
    unsigned char crc_bit_shift = CRC8_BIT_SHIFT;
    unsigned char crc_bit_mask = CRC8_BIT_MASK;

    crc_byte = crc_byte ^ CRC8_INITIAL_VALUE;
    for (int i = 0; i < 8; i++) {
        crc_byte = (crc_byte << 1) ^ CRC8_POLYNOMIAL;
        if (crc_byte & CRC8_BIT_MASK) {
            crc_byte = (crc_byte >> 1) ^ CRC8_BIT_BIT_SHIFT;
        } else {
            crc_byte = (crc_byte >> 1);
        }
    }

    crc_byte = crc_byte ^ CRC8_INITIAL_VALUE;
    for (int i = 0; i < 8; i++) {
        crc_bit = (crc_bit << 1) ^ CRC8_POLYNOMIAL;
        if (crc_bit & CRC8_BIT_MASK) {
            crc_bit = (crc_bit >> 1) ^ CRC8_BIT_BIT_SHIFT;
        } else {
            crc_bit = (crc_bit >> 1);
        }
    }

    return (crc_byte == crc) ? 0 : -1;
}

// Process sensor data
sensor_data_t process_sensor_data(unsigned char *data) {
    sensor_data_t sensor_data;
    sensor_data.pressure = (float)((data[0] << 8) | data[1]) / 10.0;
    sensor_data.temperature = (float)((data[2] << 8) | data[3]) / 10.0;
    return sensor_data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char data[9];
    unsigned char crc;
    float pressure, temperature;

    // Main loop
    while (program_running) {
        // Send measurement command
        if (send_measure_command(i2c_handle, MEASURE_CMD_HIGH) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            continue; // Continue to the next iteration
        }

        // Wait for measurement (approximately 45 ms)
        gpioDelay(50000); // 50 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC8 checksum
        crc = validate_crc8(data, CRC8_RESULT_BYTE);
        if (crc != 0) {
            fprintf(stderr, "CRC8 checksum error\n");
            continue; // Continue to the next iteration
        }

        // Process sensor data
        sensor_data_t sensor_data = process_sensor_data(data);

        // Convert data to physical units
        pressure = sensor_data.pressure;
        temperature = sensor_data.temperature;

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

