    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char data[9];
    unsigned char crc;
    float pressure, temperature;

    // Main loop
    while (program_running) {
        // Send measurement command
        if (send_measure_command(i2c_handle, MEASURE_CMD_HIGH) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            continue; // Continue to the next iteration
        }

        // Wait for measurement (approximately 45 ms)
        gpioDelay(50000); // 50 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC8 checksum
        crc = validate_crc8(data, CRC8_RESULT_BYTE);
        if (crc != 0) {
            fprintf(stderr, "CRC8 checksum error\n");
            continue; // Continue to the next iteration
        }

        // Process sensor data
        sensor_data_t sensor_data = process_sensor_data(data);

        // Convert data to physical units
        pressure = sensor_data.pressure;
        temperature = sensor_data.temperature;

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

