#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_I2C_ADDR 0x25
#define MEASURE_CMD 0x36 // Continuous measurement command
#define MEASURE_DURATION_US 50000 // 50ms
#define SAMPLE_INTERVAL_US 1000000 // 1 second
#define CRC_8_POLYNOMIAL 0x31
#define SAMPLE_SIZE 9
#define ERROR_CODE -1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int initialize_sensor();
int read_sensor_data(SensorData *data);
int validate_crc8(uint8_t *data, int data_len);
float convert_raw_data(uint16_t pressure, uint16_t temperature);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the SDP810 sensor
int initialize_sensor() {
    // Send the continuous measurement command
    char cmd[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }

    // Wait for the measurement to complete (at least 5ms)
    gpioDelay(5000000); // 5ms

    return 0;
}

// Read sensor data
int read_sensor_data(SensorData *data) {
    char buffer[SAMPLE_SIZE];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, SAMPLE_SIZE);

    if (bytes_read != SAMPLE_SIZE) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return ERROR_CODE;
    }

    // Validate CRC8
    if (!validate_crc8(buffer, SAMPLE_SIZE)) {
        fprintf(stderr, "CRC8 validation failed\n");
        return ERROR_CODE;
    }

    // Convert raw data
    uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
    uint16_t temperature_raw = (buffer[3] << 8) | buffer[4];

    data->pressure = convert_raw_data(pressure_raw, temperature_raw);
    data->temperature = (float)temperature_raw / 100.0; // Scale factor is 100 for SDP810

    return 0;
}

// Validate CRC8
int validate_crc8(uint8_t *data, int data_len) {
    uint8_t crc = 0;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[data_len - 1]);
}

// Convert raw data to floating-point values
float convert_raw_data(uint16_t pressure, uint16_t temperature) {
    return (float)pressure / 100.0; // Scale factor is 100 for SDP810
}

// Log data to file
void log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("airflow.dat", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    SensorData sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

