#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define LED_GPIO 17
#define AVG_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *buffer, float temperature);
float calculate_average(CircularBuffer *buffer);
void control_led(float average_temperature);
void cleanup();
void signal_handler(int signal);

// Circular buffer initialization
CircularBuffer temperature_buffer = {0};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -273.15) { // Check for invalid temperature
            add_to_buffer(&temperature_buffer, temperature);
            float average_temperature = calculate_average(&temperature_buffer);
            control_led(average_temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from STLM75
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temperature = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    float temperature = (float)raw_temperature / 16384.0 * 165.0 - 40.0;

    return temperature;
}

// Add temperature to circular buffer
void add_to_buffer(CircularBuffer *buffer, float temperature) {
    buffer->buffer[buffer->head] = temperature;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate average temperature
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
