#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define SCD30_ADDR 0x33
#define LOG_FILE "air_quality.log"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100
#define VENTILATION_THRESHOLD 800.0
#define VENTILATION_LOW_THRESHOLD 1200.0
#define VENTILATION_HIGH_THRESHOLD 1200.0
#define VENTILATION_DURATION_SEC 5
#define VENTILATION_INTERVAL_SEC 60
#define VENTILATION_STATE_OFF 0
#define VENTILATION_STATE_LOW 1
#define VENTILATION_STATE_HIGH 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_scd30_data(sensor_data_t *data);
float convert_co2_ppm(int raw_co2);
float convert_temperature_celsius(int raw_temperature);
float convert_humidity_percent(int raw_humidity);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float co2, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from SCD30 sensor
int read_scd30_data(sensor_data_t *data) {
    char buf[6];
    int retries = I2C_RETRY_COUNT;
    int i;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 6) == 6) {
            // Read 6 bytes of data (CO2, Temp, Humidity)
            for (i = 0; i < 6; i++) {
                buf[i] = i2cReadByteData(i2c_handle, 0); // Read from register 0
            }

            // CRC check (replace with actual CRC calculation if needed)
            if (buf[0] == 0x36 && buf[1] == 0x36 && buf[2] == 0x36 && buf[3] == 0x36 && buf[4] == 0x36 && buf[5] == 0x36) {
                // Data read successfully
                data->co2 = convert_co2_ppm(buf[2]);
                data->temperature = convert_temperature_celsius(buf[3]);
                data->humidity = convert_humidity_percent(buf[4]);
                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed for sensor data.\n");
                retries--;
                gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        } else {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            retries--;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Convert CO2 ppm to float
float convert_co2_ppm(int raw_co2) {
    return (float)raw_co2 / 100.0;
}

// Convert temperature Celsius to float
float convert_temperature_celsius(int raw_temperature) {
    return (float)raw_temperature / 100.0;
}

// Convert humidity %RH to float
float convert_humidity_percent(int raw_humidity) {
    return (float)raw_humidity / 100.0;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(const char *timestamp, float co2, float temperature, float humidity) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    sensor_data_t sensor_data;
    char *timestamp;
    int retries;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        retries = 0;
        while (retries < I2C_RETRY_COUNT) {
            if (read_scd30_data(&sensor_data) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retrying I2C read...\n");
                retries++;
                gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == I2C_RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
            log_data(get_iso8601_timestamp(), NAN, NAN, NAN); // Log error
            continue; // Skip to the next iteration
        }

        // Convert data
        sensor_data.co2 = convert_co2_ppm(sensor_data.raw_co2);
        sensor_data.temperature = convert_temperature_celsius(sensor_data.raw_temperature);
        sensor_data.humidity = convert_humidity_percent(sensor_data.raw_humidity);

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, sensor_data.co2, sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Control ventilation
        if (sensor_data.co2 < VENTILATION_THRESHOLD && program_running) {
            if (program_data.co2 < VENTILATION_LOW_THRESHOLD) {
                program_data.co2 = VENTILATION_LOW_THRESHOLD;
                printf("CO2 level below threshold, turning ventilation ON.\n");
            } else {
                program_data.co2 = VENTILATION_LOW_THRESHOLD;
                printf("CO2 level above threshold, turning ventilation OFF.\n");
            }
        } else if (sensor_data.co2 > VENTILATION_HIGH_THRESHOLD && program_running) {
            if (program_data.co2 > VENTILATION_HIGH_THRESHOLD) {
                program_data.co2 = VENTILATION_HIGH_THRESHOLD;
                printf("CO2 level above threshold, turning ventilation ON.\n");
            } else {
                program_data.co2 = VENTILATION_HIGH_THRESHOLD;
                printf("CO2 level below threshold, turning ventilation OFF.\n");
            }
        }

        // Flush log file
        fflush(log_file);

        // Sleep for 5 seconds
        gpioDelay(5 * 1000); // Delay in microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

