#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDR 0x25
#define GPIO_SDP8_PRESSURE_DATA_PIN 2
#define GPIO_SDP8_TEMPERATURE_DATA_PIN 3
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_COUNT_PER_READ 5
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFFFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[3], uint8_t crc);
void log_data(sensor_data_t data);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int bytes_read;
    int retry_count = 0;

    while (retry_count < I2C_RETRY_COUNT) {
        bytes_read = i2cReadDevice(i2c_handle, buffer, 9);
        if (bytes_read == 9) {
            break;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retry_count + 1, bytes_read);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retry_count++;
        }
    }

    if (bytes_read != 9) {
        fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRY_COUNT);
        return -1;
    }

    // Validate CRC
    if (validate_crc(buffer, buffer[0]) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Extract sensor data
    data->pressure = (float)((buffer[0] << 8) | buffer[1]) / 10.0;
    data->temperature = (float)((buffer[2] << 8) | buffer[3]) / 10.0;
    data->crc = buffer[4];

    return 0;
}

// Validate CRC
