#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define DRDY_REG 0x03
#define TEMP_SCALE 0.0625
#define HUMID_SCALE 0.0078125
#define DELAY_MS 200
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_hdc1000(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1000
int read_hdc1000(float *temperature, float *humidity) {
    uint8_t data[2];
    int result;

    // Read temperature
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Read humidity
    result = i2cReadI2CBlockData(i2c_handle, HUMID_REG, (char *)data + 1, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    int16_t raw_temp = (data[0] << 8) | data[1];
    int16_t raw_humidity = (data[2] << 8) | data[3];

    *temperature = (float)raw_temp * TEMP_SCALE;
    *humidity = (float)raw_humidity * HUMID_SCALE;

    return 0;
}

// Log data to console
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("HDC1000 sensor data logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc1000(&temperature, &humidity) == 0) {
            // Wait for DRDYn to go low
            int retry = 0;
            while (gpioRead(DRDY_REG) == 1 && retry < RETRY_COUNT) {
                gpioDelay(10); // Wait 10ms
                retry++;
            }
            if (retry >= RETRY_COUNT) {
                fprintf(stderr, "DRDYn not set after multiple retries.\n");
                continue; // Skip logging if retry fails
            }

            // Wait for DRDYn to go high
            retry = 0;
            while (gpioRead(DRDY_REG) == 0 && retry < RETRY_COUNT) {
                gpioDelay(10); // Wait 10ms
                retry++;
            }
            if (retry >= RETRY_COUNT) {
                fprintf(stderr, "DRDYn not set after multiple retries.\n");
                continue; // Skip logging if retry fails
            }

            // Wait for conversion to complete (at least 14 bits)
            gpioDelay(10); // Wait 10ms

            // Read temperature and humidity
            if (read_hdc1000(&temperature, &humidity) == 0) {
                // Log data
                log_data(temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read temperature and humidity.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

