int read_pressure(float *pressure) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert raw pressure to Pascals (assuming 0.1 Pa/LSB)
    *pressure = (float)raw_pressure * 0.1;

    return 0;
}

