#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_COMMAND 0x36
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00
#define SAMPLE_INTERVAL_MS 45000
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *pressure, uint16_t *temperature);
int validate_data(uint16_t pressure, uint16_t temperature, uint8_t crc);
int log_data(float differential_pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *pressure, uint16_t *temperature) {
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (datasheet specifies >10ms)
    gpioDelay(20); // 20ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC
    if (!validate_data(buf[0], buf[1], buf[2])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *pressure = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *temperature = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);

    return 0;
}

// Function to validate CRC
int validate_data(uint16_t pressure, uint16_t temperature, uint8_t crc) {
    uint8_t crc_value = (crc >> 8) | (crc & 0x00); // Extract high byte
    uint8_t data_value = (pressure >> 8) | (pressure & 0x00); // Extract high byte
    uint8_t data_value_with_crc = (data_value << 8) | crc_value; // Combine data and CRC

    if (crc_value != data_value_with_crc) {
        fprintf(stderr, "CRC validation failed for pressure: %d, temperature: %d, crc: %d\n", pressure, temperature, crc);
        return 0; // Indicate failure
    }

    return 1; // Indicate success
}

// Function to log data to file
int log_data(float differential_pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, differential_pressure, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
