int initialize_i2c();
int trigger_measurement();
int read_response(uint8_t *data, int len);
sensor_data_t parse_response(uint8_t *data, int len);
int verify_crc8(const uint8_t *data, int len);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Triggers a measurement on the SDP800-500Pa sensor
int trigger_measurement() {
    char buf[2];
    buf[0] = TRIGGER_MEASUREMENT;
    buf[1] = 0x00; // Dummy byte
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads a response from the SDP800-500Pa sensor
int read_response(uint8_t *data, int len) {
    int result = i2cReadDevice(i2c_handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading response: %d\n", result);
        return -1;
    }
    return 0;
}

// Parses the response data into a sensor_data_t structure
sensor_data_t parse_response(uint8_t *data, int len) {
    sensor_data_t result;
    result.pressure = (float)((data[0] << 8) | data[1]) / 10.0; // Convert bytes to float
    result.crc_ok = verify_crc8(data + 2, len - 2);
