            result = read_response(data, 3);
            if (result == 0) {
                // Parse the response
                sensor_data_t sensor_data = parse_response(data, 3);

                // Verify CRC-8
                if (verify_crc8(data, 3) == sensor_data.crc_ok) {
                    // Log the data
                    if (log_data(sensor_data.pressure) != 0) {
                        fprintf(stderr, "Error logging data.\n");
                    }
                } else {
                    fprintf(stderr, "CRC-8 check failed for sensor.\n");
                }
            } else {
                fprintf(stderr, "Error reading response from sensor.\n");
            }
        } else {
            fprintf(stderr, "Error triggering measurement.\n");
        }

        // Wait before next measurement
        gpioDelay(50000); // 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

