#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x24
#define MEASUREMENT_COMMAND 0x3600 // High precision measurement command
#define TRIGGER_COMMAND 0x3600 // Trigger measurement command
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1000000 // 1 MB
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_hih6130(int i2c_handle, float *temperature, float *humidity);
int validate_sensor_data(int status, float temperature, float humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads temperature and humidity from the HIH6130 sensor
int read_hih6130(int i2c_handle, float *temperature, float *humidity) {
    char buf[6];
    int result;

    // Trigger a measurement
    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete (datasheet specifies 10ms)

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate the data
    if (validate_sensor_data(result, buf[0], buf[1]) != 0) {
        fprintf(stderr, "Invalid sensor data: %d, %d\n", result, buf[0]);
        return -1;
    }

    // Convert data to temperature and humidity
    *temperature = (float)((buf[1] << 8) | buf[0]) / 100.0;
    *humidity = (float)((buf[3] << 8) | buf[2]) / 100.0;

    return 0;
}

// Validates the sensor data
int validate_sensor_data(int status, float temperature, float humidity) {
    if (status != 0) {
        fprintf(stderr, "Sensor not present or error: %d\n", status);
        return -1;
    }

    // Check humidity range
    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", humidity);
        return -1;
    }

    // Check temperature range
    if (temperature < -40.0 || temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1;
    }

    return 0;
}

// Logs the data to a file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    float temperature, humidity;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            // Validate sensor data
            if (validate_sensor_data(temperature, humidity) == 0) {
                // Log the data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

