    if (validate_sensor_data(result, buf[0], buf[1]) != 0) {
        fprintf(stderr, "Invalid sensor data: %d, %d\n", result, buf[0]);
        return -1;
    }

    // Convert data to temperature and humidity
    *temperature = (float)((buf[1] << 8) | buf[0]) / 100.0;
    *humidity = (float)((buf[3] << 8) | buf[2]) / 100.0;

    return 0;
}

// Validates the sensor data
int validate_sensor_data(int status, float temperature, float humidity) {
    if (status != 0) {
        fprintf(stderr, "Sensor not present or error: %d\n", status);
        return -1;
    }

    // Check humidity range
    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", humidity);
        return -1;
    }

    // Check temperature range
    if (temperature < -40.0 || temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1;
    }

    return 0;
}

// Logs the data to a file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    float temperature, humidity;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            // Validate sensor data
            if (validate_sensor_data(temperature, humidity) == 0) {
                // Log the data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

