#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
void print_buffer();
void flush_buffer();
void signal_handler(int signal);
void cleanup();

// Circular buffer initialization
CircularBuffer temp_buffer = {0};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            print_buffer();
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping this sample.\n");
        }
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    // Read temperature register (0x00)
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 16.0;

    return 0;
}

// Add temperature to the circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("Temperature Buffer:\n");
    for (int i = 0; i < temp_buffer.count; i++) {
        float temp = temp_buffer.buffer[i];
        printf("%.2f\n", temp);
    }
}

// Flush the contents of the circular buffer to the log file
void flush_buffer() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    int bytes_written = fwrite(temp_buffer.buffer, sizeof(float), temp_buffer.count, fp);
    if (bytes_written != temp_buffer.count) {
        fprintf(stderr, "Failed to write all data to log file\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

