#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define VDD_PIN 1
#define VSS_PIN 2
#define SDA_PIN 3
#define SCL_PIN 4
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define CRC_VALUE 0x31
#define SAMPLE_INTERVAL 5 // seconds
#define MAX_SAMPLE_INTERVAL 60 // seconds
#define MAX_SAMPLE_COUNT 1000 // Number of samples to take

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_shtc3(int handle, float *temperature, float *humidity);
int validate_data(float temperature, float humidity);
void log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);
int cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHTC3 sensor
int read_shtc3(int handle, float *temperature, float *humidity) {
    char cmd[2] = {MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF};
    char data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 12.4 ms)
    gpioDelay(12400);

    // Read 6 bytes of data
    result = i2cReadDevice(handle, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC check
    uint16_t crc_temp = (data[0] << 8) | data[1];
    uint16_t crc_humidity = (data[2] << 8) | data[3];

    uint16_t temp_crc = (data[4] << 8) | data[5];

    if (crc_temp != crc_humidity) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return -1;
    }

    if (crc_temp != temp_crc) {
        fprintf(stderr, "CRC check failed for humidity\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int32_t raw_temp = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_humidity = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    *temperature = -45.0 + (175.0 * raw_temp / 65535.0);
    *humidity = 100.0 * raw_humidity / 65535.0;

    return 0;
}

// Validate temperature and humidity data
int validate_data(float temperature, float humidity) {
    if (temperature < -40.0 || temperature > 125.0 || humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Invalid temperature or humidity: %.2f, %.2f\n", temperature, humidity);
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    fflush(fp);
}

// Cleanup resources
int cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

