int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads raw data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, MEASUREMENT_CMD, buf, 2);
        if (result == 2) {
            // Success!
            data->speed = convert_to_speed(buf[0]);
            data->temperature = convert_to_temperature(buf[1]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retrying
        }
    }

    // Failure after all retries
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    data->speed = -1.0; // Indicate error
    data->temperature = -1.0; // Indicate error
    return -1; // Failure
}

