        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (program_running) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d ms...\n", SAMPLE_INTERVAL_MS);
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before retrying
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay between samples
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

