#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADPD105 I2C address
#define ADPD105_ADDR 0x39

// ADPD105 register addresses
#define ADPD105_REG_ID 0x00
#define ADPD105_REG_STATUS 0x01
#define ADPD105_REG_CONFIG 0x02
#define ADPD105_REG_DATA_L 0x04
#define ADPD105_REG_DATA_H 0x05
#define ADPD105_REG_RESULT 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    uint16_t data_l;
    uint16_t data_h;
} sensor_data_t;

// Function prototypes
int adpd105_init();
int adpd105_read_data(sensor_data_t *data);
float adpd105_compute_cct(sensor_data_t data);
int log_cct(float cct);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADPD105 sensor
int adpd105_init() {
    // Check the sensor ID
    int id = i2cReadByteData(i2c_handle, ADPD105_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, ADPD105_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read data from the ADPD105 sensor
int adpd105_read_data(sensor_data_t *data) {
    char buf[2];
    int result;

    // Read data L
    result = i2cReadI2CBlockData(i2c_handle, ADPD105_REG_DATA_L, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data L: %s\n", strerror(errno));
        return -1;
    }
    data->data_l = (buf[0] << 8) | buf[1];

    // Read data H
    result = i2cReadI2CBlockData(i2c_handle, ADPD105_REG_DATA_H, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data H: %s\n", strerror(errno));
        return -1;
    }
    data->data_h = (buf[0] << 8) | buf[1];

    return 0;
}

// Compute the correlated color temperature
float adpd105_compute_cct(sensor_data_t data) {
    // Placeholder implementation, replace with actual ADPD105 calculation
    // This is a simplified example, refer to the ADPD105 datasheet for the correct formula
    // and register addresses.
    // This example assumes a linear relationship between data_l and data_h.
    // In a real application, you would need to calibrate the sensor and
    // apply a proper color correction algorithm.

    // Example: Assuming data_l and data_h are linearly related
    float cct = (float)data.data_l / 256.0f; // Example scaling
    return cct;
}

// Log the average CCT to a CSV file
int log_cct(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, cct);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADPD105_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the ADPD105 sensor
    if (adpd105_init() < 0) {
        fprintf(stderr, "ADPD105 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (adpd105_read_data(&sensor_data) == 0) {
            // Compute the correlated color temperature
            float cct = adpd105_compute_cct(sensor_data);

            // Log the average CCT
            if (log_cct(cct) != 0) {
                fprintf(stderr, "Error logging CCT\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

