#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
SensorData read_sensor_data();
void log_data(SensorData data);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MLX90824
SensorData read_sensor_data() {
    SensorData data;
    uint16_t raw_pressure, raw_temperature;
    int result;

    // Read pressure data
    result = i2cReadWordData(i2c_handle, PRESSURE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        data.pressure = -1.0; // Indicate error
    } else {
        raw_pressure = (uint16_t)result;
        data.pressure = (float)raw_pressure / 10.0; // Convert to Pascals
    }

    // Read temperature data
    result = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        data.temperature = -1.0; // Indicate error
    } else {
        raw_temperature = (uint16_t)result;
        data.temperature = (float)raw_temperature / 10.0; // Convert to Celsius
    }

    return data;
}

// Log data to file
void log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData data = read_sensor_data();
        if (data.pressure != -1.0 && data.temperature != -1.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }
        gpioDelay(READ_INTERVAL_SEC * 1000); // Delay for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

