#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define NUM_SAMPLES 60
#define HYSTERESIS_THRESHOLD 28.0
#define FAN_ON_TIME_MS 1000
#define FAN_OFF_TIME_MS 1000
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[NUM_SAMPLES];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_lm75b(int handle, float *temperature);
float calculate_average(float *buffer, int head, int count);
void control_fan(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Circular buffer initialization
CircularBuffer temperature_buffer;

int main() {
    // Initialize circular buffer
    temperature_buffer.head = 0;
    temperature_buffer.count = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        float temperature;
        int retries = 0;

        // Read temperature from LM75B
        while (retries < I2C_RETRY_COUNT) {
            if (read_lm75b(i2c_handle, &temperature) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d), retrying...\n", retries + 1);
                retries++;
                gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == I2C_RETRY_COUNT) {
            fprintf(stderr, "I2C read failed after multiple retries\n");
            temperature = -999.0; // Indicate error
        } else {
            temperature = calculate_average(temperature_buffer.buffer, temperature_buffer.head, temperature_buffer.count);
        }

        // Control fan based on temperature
        control_fan(temperature);

        // Log temperature
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
        printf("%s - Temperature: %.2f °C\n", buf, temperature);

        // Store temperature in circular buffer
        temperature_buffer.buffer[temperature_buffer.head] = temperature;
        temperature_buffer.head = (temperature_buffer.head + 1) % NUM_SAMPLES;
        if (temperature_buffer.count < NUM_SAMPLES) {
            temperature_buffer.count++;
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from LM75B
int read_lm75b(int handle, float *temperature) {
    char buf[2];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (i2cReadDevice(handle, buf, 2) == 2) {
            // Check status bit (bit 7 of the first byte)
            if (buf[0] & 0x80) {
                fprintf(stderr, "LM75B status error: %d\n", buf[0]);
                return -1;
            }

            // Convert to Celsius (refer to LM75B datasheet)
            *temperature = (float)((buf[0] << 8) | buf[1]) / 16.0;
            return 0;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d), retrying...\n", retries + 1);
            retries++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1;
}

// Calculate the average of the temperature readings in the circular buffer
float calculate_average(float *buffer, int head, int count) {
    if (count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += buffer[head + i];
    }
    return sum / count;
}

// Control the cooling fan
void control_fan(float average_temperature) {
    if (average_temperature > HYSTERESIS_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        gpioDelay(FAN_ON_TIME_MS * 1000); // Wait for fan to turn on
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        gpioDelay(FAN_OFF_TIME_MS * 1000); // Wait for fan to turn off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

