#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define MEASURE_DURATION_US 50000 // 50ms
#define SAMPLE_INTERVAL_US 1000000 // 1 second
#define LOG_FILE "airflow.log"
#define CRC_POLYNOMIAL 0x31
#define CRC_VALUE 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int read_sdp810(int i2c_handle, float *pressure, float *temperature);
int validate_crc(const uint8_t *data, int len);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 implementation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(MEASURE_DURATION_US);

    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Validate CRC
    if (!validate_crc(data, 9)) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    // Convert data to float
    *pressure = (float)data[0] * 256.0 + (float)data[1];
    *temperature = (float)data[3] * 256.0 + (float)data[4];

    return 0;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[len - 1];
}

// Function to log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float pressure, temperature;
    SensorData sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            // Validate CRC
            if (validate_crc(data.pressure, 9) && validate_crc(data.temperature, 9)) {
                // Log data
                if (log_data(log_file, pressure, temperature) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }

                // Print data to console
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
            } else {
                fprintf(stderr, "CRC mismatch\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

