    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
char* get_timestamp();
int log_data(const char *timestamp, float temperature, float humidity);
