    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the HDC1080 sensor
int configure_sensor() {
    // Set config register to 0x0F (continuous conversion, temperature and humidity oversampling x1, normal mode)
    char config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x0F; // 0b00111111

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the two bytes for temperature and humidity
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    int16_t raw_humidity = (buffer[3] << 8) | buffer[4];

    // Convert raw data to Celsius and percentage
    data->temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    data->humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

