#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS40_ADDR 0x70
#define LOG_FILE "temperature_log.txt"
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10

// CRC8 Polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int open_i2c_device(int bus, int addr);
int read_sts40_data(int handle, uint8_t *data, int len);
int verify_crc8(const uint8_t *data, int len);
int log_temperature(const uint8_t *data, int len);
void signal_handler(int signal);
void cleanup();

// Function to open the I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read data from the STS40 sensor
int read_sts40_data(int handle, uint8_t *data, int len) {
    int retries = I2C_RETRIES;
    while (retries > 0) {
        int result = i2cReadI2CBlockData(handle, 0x00, (char *)data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s, retrying (%d/%d)\n", strerror(errno), retries, I2C_RETRIES);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to verify the CRC8 checksum
int verify_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == 0;
}

// Function to log the temperature reading to a file
int log_temperature(const uint8_t *data, int len) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,0x%02X,%d\n", timestamp, data[0], data[1]);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, STS40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[3];
    int retries = I2C_RETRIES;
    int i;

    // Main loop
    while (!terminate) {
        // Wait for the sensor to be ready (at least 10ms)
        while (i2cReadI2CBlockData(i2c_handle, 0x00, data, 3) == 3) {
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            if (retries == 0) {
                fprintf(stderr, "I2C read timeout, retrying...\n");
                break;
            }
        }
        if (retries == 0) {
            fprintf(stderr, "I2C read failed after multiple retries.\n");
            break;
        }

        // Read data from the sensor
        if (read_sts40_data(i2c_handle, data, 3) == 0) {
            // Verify CRC8 checksum
            if (verify_crc8(data, 3) == 1) {
                // Log the temperature reading
                log_temperature(data, 3);
            } else {
                fprintf(stderr, "CRC8 checksum failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read data from sensor.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

