        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, STS40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
