#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define CSV_FILE_PATH "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_PATH "/var/log/scd40_error.log"
#define BUFFER_CAPACITY 100
#define MEASUREMENT_INTERVAL 5 // seconds
#define ERROR_RETRY_COUNT 3
#define ERROR_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Circular buffer structure
typedef struct {
    float co2[BUFFER_CAPACITY];
    float temperature[BUFFER_CAPACITY];
    float humidity[BUFFER_CAPACITY];
    int head;
    int tail;
    pthread_mutex_t mutex;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_scd40(float *co2, float *temperature, float *humidity);
int validate_crc8(unsigned char crc, unsigned char data);
int write_to_csv(float co2[], float temperature[], float humidity[]);
void *logging_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Circular buffer initialization
CircularBuffer scd40_buffer = {0};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    scd40_buffer.head = 0;
    scd40_buffer.tail = 0;
    pthread_mutex_init(&scd40_buffer.mutex, NULL);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        perror("Failed to create logging thread");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        float co2[BUFFER_CAPACITY];
        float temperature[BUFFER_CAPACITY];
        float humidity[BUFFER_CAPACITY];

        // Read SCD40 data
        if (read_scd40(co2, temperature, humidity) == 0) {
            // Validate CRC8
            if (validate_crc8(co2[0], co2[1]) && validate_crc8(temperature[0], temperature[1]) && validate_crc8(humidity[0], humidity[1])) {
                // Write to CSV
                if (write_to_csv(co2, temperature, humidity) == 0) {
                    // Log errors
                    if (write_to_csv(co2, temperature, humidity) != 0) {
                        fprintf(stderr, "Failed to write to CSV\n");
                    }
                } else {
                    fprintf(stderr, "Failed to write to CSV\n");
                }
            } else {
                fprintf(stderr, "CRC8 validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read SCD40 data\n");
        }

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    pthread_join(logging_thread_id, NULL);
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read SCD40 data
int read_scd40(float *co2, float *temperature, float *humidity) {
    char buf[6];
    int bytes_read;
    int crc;
    int i;

    // Start periodic measurement
    char cmd[2] = {0x36, 0x00}; // Start periodic measurement command
    bytes_read = i2cWriteDevice(i2c_handle, cmd, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", bytes_read);
        return -1;
    }

    gpioDelay(10); // Wait for measurement to start (adjust as needed)

    // Read 6 bytes of data
    for (i = 0; i < 6; i++) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 1);
        if (bytes_read != 1) {
            fprintf(stderr, "Failed to read data: %d\n", bytes_read);
            return -1;
        }
        buf[i] = (char)buf[i] | 0x80; // Mark the start bit
    }

    // Validate CRC8
    crc = buf[0] + buf[1] + buf[2] + buf[3];
    if (crc != buf[4] + buf[5]) {
        fprintf(stderr, "CRC8 validation failed\n");
        return -1;
    }

    // Convert data
    *co2 = (float)((buf[0] << 8) | buf[1]) / 10.0;
    *temperature = (float)((buf[2] << 8) | buf[3]) / 10.0;
    *humidity = (float)((buf[4] << 8) | buf[5]) / 10.0;

    return 0;
}

// Validate CRC8
int validate_crc8(unsigned char crc, unsigned char data) {
    unsigned char crc_data[2] = {crc, data};
    unsigned char crc_calculated[2];
    crc_calculated[0] = crc_data[0] ^ 0x8C;
    crc_calculated[1] = crc_data[1] ^ 0x8C;

    for (int i = 0; i < 2; i++) {
        crc_calculated[i] = crc_calculated[i] ^ crc_data[i];
    }

    return crc_calculated[0] == crc_data[1];
}

// Write to CSV file
int write_to_csv(float co2[], float temperature[], float humidity[]) {
    FILE *fp = fopen(CSV_FILE_PATH, "a");
    if (fp == NULL) {
        perror("Failed to open CSV file");
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%)\n");
    }

    // Write data
    for (int i = 0; i < BUFFER_CAPACITY; i++) {
        fprintf(fp, "%ld,%f,%f,%f\n", (long)time(NULL), co2[i], temperature[i], humidity[i]);
    }

    fclose(fp);
    return 0;
}

// Logging thread function
void *logging_thread(void *arg) {
    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        pthread_mutex_lock(&scd40_buffer.mutex);
        for (int i = 0; i < BUFFER_CAPACITY; i++) {
            float co2 = scd40_buffer.co2[i];
            float temperature = scd40_buffer.temperature[i];
            float humidity = scd40_buffer.humidity[i];
            pthread_mutex_unlock(&scd40_buffer.mutex);

            if (write_to_csv(co2, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to write to CSV for timestamp: %s\n", timestamp);
            }
        }
        pthread_mutex_unlock(&scd40_buffer.mutex);

        gpioDelay(60000); // Sleep for 60 seconds
    }
    pthread_exit(NULL);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    pthread_mutex_destroy(&scd40_buffer.mutex);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (logging_thread_id != 0) {
        pthread_join(logging_thread_id, NULL);
    }
    pthread_mutex_destroy(&scd40_buffer.mutex);
    pthread_mutex_destroy(&scd40_buffer.mutex);
    pthread_mutex_destroy(&scd40_buffer.mutex);
}

