// CRC-8 implementation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < CRC_SIZE; j++) {
            crc = (crc >> 8) ^ (crc & 0x80 ? 0x31 : 0x30);
        }
    }
    return crc;
}

