        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Extract data
    data->differential_pressure = (float)((buf[0] << 8) | buf[1]) / 10.0;
    data->temperature = (float)((buf[2] << 8) | buf[3]) / 10.0;
    data->scale_factor = (uint8_t)((buf[4] << 8) | buf[5]);

    // CRC validation
    if (!validate_crc(crc8(buf + 0, 2), buf[2]) ||
        !validate_crc(crc8(buf + 3, 2), buf[5]) ||
        !validate_crc(crc8(buf + 6, 2), buf[8])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Function to validate CRC-8
int validate_crc(uint8_t crc, uint8_t data) {
    return crc8(data, CRC_SIZE) == crc;
