#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ICP10110_ADDR 0x69
#define MEASUREMENT_CMD 0x36
#define TEMP_REG 0x00
#define PRESS_REG 0x01
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL 5 // seconds
#define SAMPLE_DURATION 10 // milliseconds

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, MEASUREMENT_CMD, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10 ms

    // Read pressure data
    result = i2cReadI2CBlockData(i2c_handle, PRESS_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    // Combine pressure and temperature data
    data->pressure = (float)((uint16_t)buf[0] << 8 | (uint16_t)buf[1]);
    data->temperature = (float)((uint16_t)buf[2] << 8 | (uint16_t)buf[3]);

    return 0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(data_file); // Ensure data is written to file immediately
}

// Function to cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open data file
    data_file = fopen("environmental_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping this iteration\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

