#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x33
#define FAN_GPIO 18
#define TEMP_THRESHOLD 30.0
#define LOG_FILE "temperature_log.txt"
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_temperature(float *object_temp, float *ambient_temp);
void control_fan(float object_temp);
void log_temperature(float object_temp, float ambient_temp);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads temperature from the MLX90614 sensor
int read_temperature(float *object_temp, float *ambient_temp) {
    char buf[6];
    int result;

    // Send start measurement command (high repeatability)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Start measurement command
    if (result < 0) {
        fprintf(stderr, "Failed to write start measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10);

    // Read 6 bytes of data (temperature and ambient temperature)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (see MLX90614 datasheet)
    int raw_object_temp = (buf[0] << 8) | buf[1];
    int raw_ambient_temp = (buf[3] << 8) | buf[4];

    *object_temp = (float)raw_object_temp / 100.0;
    *ambient_temp = (float)raw_ambient_temp / 100.0;

    return 0;
}

// Controls the cooling fan based on object temperature
void control_fan(float object_temp) {
    if (object_temp > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Logs the temperature readings to a file
void log_temperature(float object_temp, float ambient_temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Object Temp: %.2f °C, Ambient Temp: %.2f °C\n", timestamp, object_temp, ambient_temp);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    float object_temp, ambient_temp;

    // Main loop
    while (program_running) {
        // Read temperature
        if (read_temperature(&object_temp, &ambient_temp) == 0) {
            // Control fan
            control_fan(object_temp);

            // Log temperature
            log_temperature(object_temp, ambient_temp);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

