#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define MEASUREMENT_CMD 0x36
#define CSV_FILENAME "temperature_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold temperature data
typedef struct {
    float temperature;
    int status;
} TemperatureData;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP102
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASUREMENT_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (datasheet specifies at least 10ms)
    gpioDelay(10);

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 100.0;

    return 0;
}

// Function to log temperature to CSV file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s,%.2f", timestamp, temperature);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", log_entry);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float temperature;
    int retry_count;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CSV_FILENAME);
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        retry_count = 0;
        while (retry_count < RETRY_COUNT) {
            if (read_temperature(&temperature) == 0) {
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature.\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading temperature, retrying...\n");
                retry_count++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry_count == RETRY_COUNT) {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

