#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x00
#define TEMP_MSB 0x01
#define TEMP_LSB 0x02
#define HUMID_MSB 0x03
#define HUMID_LSB 0x04
#define MEASUREMENT_DONE 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to initialize the HDC2010 sensor
int hdc2010_init(int i2c_handle)
{
    // Set MEASUREMENT_CONFIG to 0x00 (continuous measurement)
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC2010 sensor
int hdc2010_read_data(int i2c_handle, int16_t *temperature, int16_t *humidity)
{
    char buf[6];
    int result;

    // Read 6 bytes of data (TEMP_MSB, TEMP_LSB, HUMID_MSB, HUMID_LSB, MEASUREMENT_DONE, NAK)
    result = i2cReadI2CBlockData(i2c_handle, MEASUREMENT_CONFIG, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data from HDC2010: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB for temperature and humidity
    *temperature = (int16_t)((buf[0] << 8) | buf[1]);
    *humidity = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Function to convert raw temperature data to Celsius
float hdc2010_convert_temperature(int16_t raw_temp)
{
    return (float)raw_temp / 16384.0 * 165.0 - 40.0;
}

// Function to convert raw humidity data to relative humidity
float hdc2010_convert_humidity(int16_t raw_humidity)
{
    return (float)raw_humidity / 8192.0 * 100.0;
}

int main()
{
    int16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (hdc2010_init(i2c_handle) != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature and humidity data
        if (hdc2010_read_data(i2c_handle, &raw_temperature, &raw_humidity) == 0) {
            // Convert raw data to Celsius and relative humidity
            temperature = hdc2010_convert_temperature(raw_temperature);
            humidity = hdc2010_convert_humidity(raw_humidity);

            // Print the temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

