        return -1;
    }

    // Combine MSB and LSB for temperature and humidity
    *temperature = (int16_t)((buf[0] << 8) | buf[1]);
    *humidity = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Function to convert raw temperature data to Celsius
float hdc2010_convert_temperature(int16_t raw_temp)
{
    return (float)raw_temp / 16384.0 * 165.0 - 40.0;
}

// Function to convert raw humidity data to relative humidity
float hdc2010_convert_humidity(int16_t raw_humidity)
{
    return (float)raw_humidity / 8192.0 * 100.0;
}

