    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (hdc2010_init(i2c_handle) != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature and humidity data
        if (hdc2010_read_data(i2c_handle, &raw_temperature, &raw_humidity) == 0) {
            // Convert raw data to Celsius and relative humidity
            temperature = hdc2010_convert_temperature(raw_temperature);
            humidity = hdc2010_convert_humidity(raw_humidity);

