#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SDP800_I2C_ADDR 0x21
#define MEASURE_CMD 0x36
#define READ_CMD 0x2C
#define READ_SIZE 6
#define WAIT_MS 45
#define LOG_INTERVAL_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_checksum(const uint8_t *data, int len);
void log_data(sensor_data_t data);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[READ_SIZE];
    int result;

    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete

    result = i2cReadI2CBlockData(i2c_handle, READ_CMD, buf, READ_SIZE);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Validate checksum
    if (validate_checksum(buf, READ_SIZE) != 0) {
        fprintf(stderr, "Checksum validation failed\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

// Validate checksum
int validate_checksum(const uint8_t *data, int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Log data to console
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Pressure: %d Pa, Temperature: %d °C\n", timestamp, data.pressure, data.temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(LOG_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

