#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_FREQUENCY 1000000 // 1 MHz
#define GPIO_SSR 17
#define PID_KP 1.0
#define PID_KI 0.1
#define PID_KD 0.01
#define TARGET_TEMP_HIGH 50.0
#define TARGET_TEMP_LOW 45.0
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_TEMPERATURE_HIGH 100.0
#define MAX_TEMPERATURE_LOW 90.0
#define MAX_TEMPERATURE_HIGH_SCALE (MAX_TEMPERATURE_HIGH - TARGET_TEMP_HIGH) / (MAX_TEMPERATURE_HIGH - TARGET_TEMPERATURE_LOW)
#define MAX_TEMPERATURE_LOW_SCALE (MAX_TEMPERATURE_LOW - TARGET_TEMPERATURE_LOW) / (MAX_TEMPERATURE_HIGH - TARGET_TEMPERATURE_LOW)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float duty_cycle;
} SensorData;

// Function prototypes
int read_max6675(int spi_handle, float *temperature);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *derivative);
void control_ssr(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    char tx_buffer[4];
    char rx_buffer[4];
    int16_t raw_temperature;
    int retries = 3;

    while (retries > 0) {
        // Send start bit (0x01)
        tx_buffer[0] = 0x01;
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 4) != 4) {
            fprintf(stderr, "SPI read/write error (start bit)\n");
            retries--;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        // Read 16 bits of temperature data
        raw_temperature = ((rx_buffer[1] << 8) | rx_buffer[2]) >> 4;
        *temperature = (float)raw_temperature * 0.25; // Convert to Celsius

        // Check for sensor absent
        if (*temperature < -50.0) {
            fprintf(stderr, "Sensor absent detected\n");
            return -1; // Indicate sensor absence
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Indicate failure
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *derivative) {
    float error = setpoint - actual_temperature;
    *integral += error;
    *derivative = error - *integral;

    float output = KP * error + KI * (*integral) + KD * (*derivative);
    return output;
}

// Function to control SSR
void control_ssr(float duty_cycle) {
    gpioWrite(GPIO_SSR, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(GPIO_SSR, 0); // Turn off SSR
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    float temperature, target_temperature, integral, derivative;
    float duty_cycle;
    int spi_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_SSR, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_FREQUENCY, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Reflow oven control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature from MAX6675
        spi_result = read_max6675(spi_handle, &temperature);
        if (spi_result == 0) {
            // Calculate PID output
            integral = 0.0;
            derivative = 0.0;
            float pid_output = calculate_pid(TARGET_TEMP_HIGH, temperature, &integral, &derivative);

            // Control SSR
            control_ssr(pid_output);

            // Log data
            log_data(temperature, pid_output);

            // Print data to console
            printf("Temperature: %.2f C, PID Output: %.2f, Duty Cycle: %.2f\n", temperature, pid_output, pid_output);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Convert seconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

