#include <syslog.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <time.h>

// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D command to start measurement
#define HTU21D_MEASURE_CMD 0x2C

// HTU21D command to stop measurement
#define HTU21D_STOP_MEASURE_CMD 0x0F

// Global variables
int i2c_handle;
int running = 1;

// Function prototypes
int init_i2c();
int read_humidity(float *humidity);
int send_data_to_server(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Read humidity from HTU21D sensor
int read_humidity(float *humidity) {
    char cmd[1] = {HTU21D_MEASURE_CMD};
    char data[2];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write measurement command: %d", result);
        return -1;
    }

    // Wait for measurement to complete (datasheet specifies at least 20ms)
    gpioDelay(20);

    // Read two bytes of humidity data
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1;
    }

    // Convert humidity data to float
    int humidity_raw = (data[0] << 8) | data[1];
    *humidity = (float)humidity_raw / 1024.0;

    return 0;
}

// Send data to server via HTTP POST
int send_data_to_server(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];
    int len;
    float humidity_raw;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Configure server address
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Convert humidity to string
    snprintf(buffer, sizeof(buffer), "{\"humidity\": %.2f}", humidity);

    // Send data
    len = strlen(buffer);
    if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Failed to send data: %d", len);
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    float humidity;
    int result;

    // Initialize syslog
    openlog("humidity_server", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        // Read humidity
        result = read_humidity(&humidity);
        if (result == 0) {
            // Send data to server
            if (send_data_to_server(humidity) != 0) {
                syslog(LOG_ERR, "Failed to send data to server");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

