int i2c_write_byte_data(int i2c_handle, uint8_t reg, uint8_t data);

// Function to read a single byte from the I2C bus
int i2c_read_byte_data(int i2c_handle, uint8_t reg, uint8_t *data) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading byte from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (uint8_t)result;
    return 0;
}

// Function to write a single byte to the I2C bus
int i2c_write_byte_data(int i2c_handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(i2c_handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing byte to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from the I2C bus
int i2c_read_word_data(int i2c_handle, uint8_t reg, uint16_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, reg, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading word from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a word (2 bytes) to the I2C bus
int i2c_write_word_data(int i2c_handle, uint8_t reg, uint16_t data) {
    int result = i2cWriteI2CBlockData(i2c_handle, reg, (char *)&data, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing word to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the BMP280 sensor
int bmp280_init(int i2c_handle) {
    // Check the chip ID
    uint8_t chip_id = i2c_read_byte_data(i2c_handle, BMP280_REG_CONFIG, &chip_id);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2c_write_byte_data(i2c_handle, BMP280_REG_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Set oversampling and power mode
    if (i2c_write_byte_data(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing to ctrl_meas register\n");
        return -1;
    }

