#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x5A
#define PIR_GPIO 17
#define I2C_BUS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE_FORMAT "Timestamp,Temperature(C),Humidity(%),MotionDetected"

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_tmp117(int i2c_handle);
int read_aht20(int i2c_handle);
int read_pir_sensor(int gpio_pin);
char* get_timestamp();
int log_data(const char *timestamp, float temperature, float humidity, int motion_detected);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from TMP117
int read_tmp117(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading TMP117: %d\n", result);
        return -1;
    }

    int raw_temp = (buf[0] << 8) | buf[1];
    return raw_temp;
}

// Function to read humidity from AHT20
int read_aht20(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading AHT20: %d\n", result);
        return -1;
    }

    int raw_humidity = (buf[0] << 8) | buf[1];
    return raw_humidity;
}

// Function to read motion detection from PIR sensor
int read_pir_sensor(int gpio_pin) {
    int result;
    int motion_detected = 0;

    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP);

    result = gpioRead(gpio_pin);
    if (result == 1) {
        motion_detected = 1;
    }

    return motion_detected;
}

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log data to CSV file
int log_data(const char *timestamp, float temperature, float humidity, int motion_detected) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle_tmp117 = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Error opening TMP117 I2C device: %d\n", i2c_handle_tmp117);
        gpioTerminate();
        return 1;
    }

    i2c_handle_aht20 = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Error opening AHT20 I2C device: %d\n", i2c_handle_aht20);
        i2cClose(i2c_handle_tmp117);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for PIR sensor as input
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen("sensor_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle_tmp117);
        i2cClose(i2c_handle_aht20);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor data logger...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int temp_tmp117 = read_tmp117(i2c_handle_tmp117);
        int humidity_aht20 = read_aht20(i2c_handle_aht20);
        int motion_detected = read_pir_sensor(PIR_GPIO);

        // Validate sensor readings
        if (temp_tmp117 == -1 || humidity_aht20 == -1 || motion_detected == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log data
        if (log_data(timestamp, temp_tmp117, humidity_aht20, motion_detected) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

