#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define color gradient
#define RED_COLOR   0
#define GREEN_COLOR 50
#define BLUE_COLOR 100

// Define PWM range
#define PWM_RANGE   255

// Define PWM duty cycle range
#define PWM_DUTY_RANGE PWM_RANGE

// Global variable for PWM handle
int pwm_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int gpio, int frequency) {
    if (gpioSetPWMfrequency(gpio, frequency) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to map CPU load to color gradient
void map_cpu_load_to_color(int cpu_load, int *red_color, int *green_color, int *blue_color) {
    if (cpu_load < 0) {
        *red_color = 0;
        *green_color = 0;
        *blue_color = 0;
    } else if (cpu_load < 50) {
        *red_color = RED_COLOR;
        *green_color = GREEN_COLOR;
        *blue_color = BLUE_COLOR;
    } else if (cpu_load < 100) {
        *red_color = RED_COLOR;
        *green_color = GREEN_COLOR;
        *blue_color = BLUE_COLOR;
    } else {
        *red_color = RED_COLOR;
        *green_color = GREEN_COLOR;
        *blue_color = BLUE_COLOR;
    }
}

// Function to read CPU load from /proc/stat
int read_cpu_load() {
    FILE *fp;
    char line[256];
    int load;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open /proc/stat\n");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Failed to read from /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    load = atoi(line + 1);
    return load;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set PWM frequency
    if (set_pwm_frequency(RED_PIN, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    if (set_pwm_range(RED_PIN, PWM_RANGE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle range
    if (set_pwm_duty_cycle(RED_PIN, PWM_DUTY_RANGE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read CPU load
        int cpu_load = read_cpu_load();

        if (cpu_load < 0) {
            fprintf(stderr, "Failed to read CPU load, retrying in 500ms...\n");
            gpioDelay(500000); // 500ms
            continue;
        }

        // Map CPU load to color gradient
        map_cpu_load_to_color(cpu_load, RED_COLOR, GREEN_COLOR, BLUE_COLOR);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(RED_PIN, cpu_load) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for RED_PIN\n");
        }

        // Delay for 500ms
        gpioDelay(500000);
    }

    // Cleanup (should not reach here due to signal handler)
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();

    return 0;
}

