#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CALIB_00 0x88

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int bmp280_init(int i2c_handle);
int bmp280_read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
int bmp280_read_calibration_data(int i2c_handle, bmp280_calib_data *calib);
int bmp280_read_compensated_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
void format_data_to_json(int32_t temperature, int32_t pressure, char *json_string);
int send_udp_data(const char *json_string);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// BMP280 initialization function
int bmp280_init(int i2c_handle) {
    // Set oversampling and mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set the sensor to forced mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// BMP280 read raw data function
int bmp280_read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    char data[6];
    int32_t raw_temperature, raw_pressure;

    // Read 6 bytes of data (temperature MSB, temperature LSB, pressure MSB, pressure LSB, calibration data, and temperature calibration data)
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESSURE_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    // Combine the bytes to form the raw values
    raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    // Convert to signed integers
    *pressure = (int32_t)raw_pressure;
    *temperature = (int32_t)raw_temperature;

    return 0;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data(int i2c_handle, bmp280_calib_data *calib) {
    calib->dig_T1 = (uint16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00);
    calib->dig_T2 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 2);
    calib->dig_T3 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 4);
    calib->dig_P1 = (uint16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 6);
    calib->dig_P2 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 8);
    calib->dig_P3 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 10);
    calib->dig_P4 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 12);
    calib->dig_P5 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 14);
    calib->dig_P6 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 16);
    calib->dig_P7 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 18);
    calib->dig_P8 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 20);
    calib->dig_P9 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 22);

    return 0;
}

// BMP280 read compensated data function
int bmp280_read_compensated_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    int32_t var1, var2, T, p;
    var1 = ((((int32_t)raw_temperature) - (int32_t)calib->dig_T1) * (int32_t)calib->dig_T2) >> 12;
    var2 = ((((int32_t)raw_temperature) - (int32_t)calib->dig_T1) * (int32_t)calib->dig_T3) >> 12;
