    if (*temperature < 0) *temperature = 0;
    if (*temperature > 419430400) *temperature = 419430400;
    *temperature = (*temperature * (1 - (int32_t)calib->dig_T6)) >> (16 - (int32_t)calib->dig_T7);

    var1 = (int32_t)(((int32_t)raw_pressure) - (int32_t)calib->dig_P1);
    var2 = var1 * var1 * (int32_t)calib->dig_P2;
    var2 = var2 << (12 - (int32_t)calib->dig_P3);
    var2 = var2 + ((int32_t)calib->dig_P4) * var1;
    var1 = (((int32_t)calib->dig_P5) * var1 * var1 + (int32_t)calib->dig_P6) >> (16 - (int32_t)calib->dig_P7);
