    char data[6];
    int32_t raw_temperature, raw_pressure;

    // Read 6 bytes of data (temperature MSB, temperature LSB, pressure MSB, pressure LSB, calibration data, and temperature calibration data)
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESSURE_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    // Combine the bytes to form the raw values
    raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    // Convert to signed integers
    *pressure = (int32_t)raw_pressure;
    *temperature = (int32_t)raw_temperature;

    return 0;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data(int i2c_handle, bmp280_calib_data *calib) {
    calib->dig_T1 = (uint16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00);
    calib->dig_T2 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 2);
    calib->dig_T3 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 4);
    calib->dig_P1 = (uint16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 6);
    calib->dig_P2 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 8);
    calib->dig_P3 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 10);
    calib->dig_P4 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 12);
    calib->dig_P5 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 14);
    calib->dig_P6 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 16);
    calib->dig_P7 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 18);
    calib->dig_P8 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 20);
    calib->dig_P9 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 22);

    return 0;
}

// BMP280 read compensated data function
int bmp280_read_compensated_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    int32_t var1, var2, T, p;
    var1 = ((((int32_t)raw_temperature) - (int32_t)calib->dig_T1) * (int32_t)calib->dig_T2) >> 12;
    var2 = ((((int32_t)raw_temperature) - (int32_t)calib->dig_T1) * (int32_t)calib->dig_T3) >> 12;
    *temperature = (var1 * var1 * 5 + var2 * var2 * 4) >> 12;
    *temperature = (*temperature * (1 - (int32_t)calib->dig_T4)) >> (16 - (int32_t)calib->dig_T5);
    if (*temperature < 0) *temperature = 0;
    if (*temperature > 419430400) *temperature = 419430400;
    *temperature = (*temperature * (1 - (int32_t)calib->dig_T6)) >> (16 - (int32_t)calib->dig_T7);

    var1 = (int32_t)(((int32_t)raw_pressure) - (int32_t)calib->dig_P1);
    var2 = var1 * var1 * (int32_t)calib->dig_P2;
    var2 = var2 << (12 - (int32_t)calib->dig_P3);
    var2 = var2 + ((int32_t)calib->dig_P4) * var1;
    var1 = (((int32_t)calib->dig_P5) * var1 * var1 + (int32_t)calib->dig_P6) >> (16 - (int32_t)calib->dig_P7);
    if (var1 == 0)
    {
        *pressure = 0;
    } else {
        p = 1048576 - (int32_t)raw_pressure;
        p = (p - (var2 >> 12)) * (p - (var2 >> 12));
        var1 = (((int32_t)calib->dig_P8) * p + ((int32_t)calib->dig_P9)) >> (16 - (int32_t)calib->dig_P10);
        p = (((((int32_t)calib->dig_P10) + (p >> (32 - (int32_t)calib->dig_P11))) << (32 - (int32_t)calib->dig_P12)) + (var1 + (var1 >> 31));
        *pressure = (int32_t)(p / (1 << (16 - (int32_t)calib->dig_P13)));
    }
    return 0;
}

// Format data to JSON string function
void format_data_to_json(int32_t temperature, int32_t pressure, char *json_string) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(json_string, 256, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    snprintf(json_string + strlen(json_string), 256 - strlen(json_string), ",{\"temperature\":%d,\"pressure\":%d}", temperature, pressure);
}

// Send UDP data function
int send_udp_data(const char *json_string) {
    int sockfd;
    struct sockaddr_in servaddr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Configure server address
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Send data
    if (sendto(sockfd, json_string, strlen(json_string), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_handle) < 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data(i2c_handle, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read temperature and pressure data
        int32_t raw_temperature, raw_pressure;
        if (bmp280_read_compensated_data(i2c_handle, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read compensated data\n");
            continue; // Skip to the next iteration
        }

        // Format data to JSON string
        char json_string[256];
        format_data_to_json(raw_temperature, raw_pressure, json_string);

        // Send UDP data
        if (send_udp_data(json_string) < 0) {
            fprintf(stderr, "Failed to send UDP data\n");
        }

        // Wait for 5 seconds
        time_sleep(5.0);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

