#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define TEMPERATURE_THRESHOLD 25.0
#define TEMPERATURE_RANGE 40.0
#define PWM_RANGE 255
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_PERIOD 1000000 // 1 ms
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
int spi_channel;
int spi_speed;
int fan_gpio;
int temperature_buffer[BUFFER_SIZE];
int temperature_buffer_index = 0;
int pwm_duty_cycle = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_duty_cycle(float temperature);
void set_fan_duty_cycle(int duty_cycle);
void store_data(float temperature, int duty_cycle);
void print_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    unsigned char buffer[4];
    int result;

    // Read 4 bytes from the MAX31855
    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from MAX31855: %d\n", result);
        return -1;
    }

    // Extract temperature data
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    *temperature = (float)raw_temperature / 16384.0 * 100.0;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < TEMPERATURE_THRESHOLD) {
        return 0;
    } else if (temperature >= TEMPERATURE_THRESHOLD && temperature <= TEMPERATURE_RANGE) {
        float temperature_range = TEMPERATURE_RANGE - TEMPERATURE_THRESHOLD;
        float temperature_linear = temperature - TEMPERATURE_THRESHOLD;
        float duty_cycle = (temperature_linear / temperature_range) * PWM_RANGE;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
        return (int)duty_cycle;
    } else if (temperature > TEMPERATURE_RANGE + TEMPERATURE_THRESHOLD) {
        float temperature_linear = temperature - TEMPERATURE_RANGE - TEMPERATURE_THRESHOLD;
        float duty_cycle = (temperature_linear / (TEMPERATURE_RANGE + TEMPERATURE_THRESHOLD)) * PWM_RANGE;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
        return (int)duty_cycle;
    } else {
        return PWM_RANGE;
    }
}

// Function to set the fan duty cycle
void set_fan_duty_cycle(int duty_cycle) {
    gpioPWM(fan_gpio, duty_cycle);
}

// Function to store data in the circular buffer
void store_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    temperature_buffer[temperature_buffer_index] = temperature;
    temperature_buffer_index = (temperature_buffer_index + 1) % BUFFER_SIZE;
    pwm_duty_cycle = duty_cycle;

    printf("Timestamp: %s, Temperature: %.2f, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
}

// Function to print the data from the circular buffer
void print_data(float temperature, int duty_cycle) {
    printf("Timestamp: %s, Temperature: %.2f, Duty Cycle: %d\n", temperature_buffer[temperature_buffer_index], temperature, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_fan_duty_cycle(0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read temperature
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan duty cycle
            set_fan_duty_cycle(duty_cycle);

            // Store data
            store_data(temperature, duty_cycle);

            // Print data
            print_data(temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    return 0;
}

