#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// OSS (OverSampling Setting)
#define OSS_3 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 2

// I2C handle
int i2c_handle;

// Log file name
#define LOG_FILE "altitude_log.txt"

// Function prototypes
int read_bmp180(int i2c_handle, float *temperature, float *pressure);
int write_bmp180(int i2c_handle, int oss, float temperature, float pressure);
int read_calibration_data(int i2c_handle, uint16_t *x1, uint16_t *x2, uint16_t *x3, uint16_t *b1, uint16_t *b2, uint16_t *b3, uint16_t *m1, uint16_t *m2, uint16_t *m3);
int read_raw_data(int i2c_handle, int oss, uint16_t *x1, uint16_t *x2, uint16_t *x3, uint16_t *b1, uint16_t *b2, uint16_t *b3, uint16_t *m1, uint16_t *m2, uint16_t *m3, uint16_t *r1, uint16_t *r2, uint16_t *r3);
int read_temperature(int i2c_handle, float *temperature);
int read_pressure(int i2c_handle, float *pressure);
int log_data(float temperature, float pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);

// Global variable for log file pointer
FILE *log_file = NULL;

// Function to read a register from the BMP180
int read_register(int i2c_handle, uint8_t reg, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, reg, (char *)data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the BMP180
int write_register(int i2c_handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(i2c_handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, uint16_t *x1, uint16_t *x2, uint16_t *x3, uint16_t *b1, uint16_t *b2, uint16_t *b3, uint16_t *m1, uint16_t *m2, uint16_t *m3) {
    uint8_t buffer[22];
    if (read_register(i2c_handle, 0xAA, buffer) != 0) return -1;
    if (read_register(i2c_handle, 0xAC, buffer + 1) != 0) return -1;
    if (read_register(i2c_handle, 0xAE, buffer + 2) != 0) return -1;
    if (read_register(i2c_handle, 0xB0, buffer + 3) != 0) return -1;
    if (read_register(i2c_handle, 0xB2, buffer + 4) != 0) return -1;
    if (read_register(i2c_handle, 0xB4, buffer + 5) != 0) return -1;
    if (read_register(i2c_handle, 0xB6, buffer + 6) != 0) return -1;
    if (read_register(i2c_handle, 0xBC, buffer + 7) != 0) return -1;
    if (read_register(i2c_handle, 0xFE, buffer + 8) != 0) return -1;

    *x1 = (uint16_t)((buffer[0] << 8) | buffer[1]);
    *x2 = (uint16_t)((buffer[2] << 8) | buffer[3]);
    *x3 = (uint16_t)((buffer[4] << 8) | buffer[5]);
    *b1 = (uint16_t)((buffer[6] << 8) | buffer[7]);
    *b2 = (uint16_t)((buffer[8] << 8) | buffer[9]);
    *b3 = (uint16_t)((buffer[10] << 8) | buffer[11]);
    *m1 = (uint16_t)((buffer[12] << 8) | buffer[13]);
    *m2 = (uint16_t)((buffer[14] << 8) | buffer[15]);
    *m3 = (uint16_t)((buffer[16] << 8) | buffer[17]);

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_data(int i2c_handle, int oss, uint16_t *x1, uint16_t *x2, uint16_t *x3, uint16_t *b1, uint16_t *b2, uint16_t *b3, uint16_t *m1, uint16_t *m2, uint16_t *m3, uint16_t *r1, uint16_t *r2, uint16_t *r3) {
    uint8_t buffer[8];

    if (read_register(i2c_handle, BMP180_REG_CONTROL, buffer) != 0) return -1;

    // Set OSS to 3
    if (write_register(i2c_handle, BMP180_REG_CONTROL, 0x27) != 0) return -1;

    gpioDelay(5000); // Wait 4.5ms

    if (read_register(i2c_handle, BMP180_REG_MSB, buffer) != 0) return -1;
    if (read_register(i2c_handle, BMP180_REG_LSB, buffer + 1) != 0) return -1;
    if (read_register(i2c_handle, BMP180_REG_XLSB, buffer + 2) != 0) return -1;

    *r1 = (uint16_t)((buffer[0] << 8) | buffer[1]);
    *r2 = (uint16_t)((buffer[2] << 8) | buffer[3]);
    *r3 = (uint16_t)((buffer[4] << 8) | buffer[5]);

    *x1 = (uint16_t)((buffer[6] << 8) | buffer[7]);
    *x2 = (uint16_t)((buffer[8] << 8) | buffer[9]);
    *x3 = (uint16_t)((buffer[10] << 8) | buffer[11]);
    *b1 = (uint16_t)((buffer[12] << 8) | buffer[13]);
    *b2 = (uint16_t)((buffer[14] << 8) | buffer[15]);
    *b3 = (uint16_t)((buffer[16] << 8) | buffer[17]);
    *m1 = (uint16_t)((buffer[18] << 8) | buffer[19]);
    *m2 = (uint16_t)((buffer[20] << 8) | buffer[21]);

    return 0;
