#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 Registers
#define BMP180_ADDR 0x77
#define BMP180_CONTROL 0xF4
#define BMP180_MSB 0xF6
#define BMP180_LSB 0xF7
#define BMP180_XLSB 0xF8

// BMP180 Commands
#define BMP180_CALIB_START 0xAA
#define BMP180_CALIB_END 0xBA

// Oversampling Setting
#define OSS 0 // Ultra low power

// Calibration Data Structure
typedef struct {
    uint16_t ac1;
    uint16_t ac2;
    uint16_t ac3;
    int16_t ac4;
    int16_t ac5;
    int16_t ac6;
    uint16_t b1;
    uint16_t b2;
    uint16_t mb;
    uint16_t mc;
    uint16_t md;
} bmp180_calib_data_t;

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration Data
bmp180_calib_data_t calib_data;

// Function Prototypes
int read_calibration_data(int i2c_handle, bmp180_calib_data_t *calib);
int read_raw_temperature(int i2c_handle, int32_t *raw_temperature);
int read_raw_pressure(int i2c_handle, int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temperature, int32_t *calib);
double calculate_pressure(int32_t raw_pressure, int32_t *calib, double temperature);
int write_calibration_data(int i2c_handle, const bmp180_calib_data_t *calib);
int read_bmp180_data(int i2c_handle, int32_t *raw_temperature, int32_t *raw_pressure);
void timer_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calib_data_t *calib) {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_CALIB_START, data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    calib->ac1 = (data[1] << 8) | data[0];
    calib->ac2 = (data[3] << 8) | data[2];
    calib->ac3 = (data[5] << 8) | data[4];
    calib->ac4 = (data[7] << 8) | data[6];
    calib->ac5 = (data[9] << 8) | data[8];
    calib->ac6 = (data[11] << 8) | data[10];
    calib->b1 = (data[13] << 8) | data[12];
    calib->b2 = (data[15] << 8) | data[14];
    calib->mb = (data[17] << 8) | data[16];
    calib->mc = (data[19] << 8) | data[18];
    calib->md = (data[21] << 8) | data[20];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle, int32_t *raw_temperature) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle, int32_t *raw_pressure) {
    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = (data[0] << 16 | data[1] << 8 | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temperature, int32_t *calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature / 16384.0) - ((double)calib->ac6) / 16.0) * ((double)calib->ac5);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib->ac3) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib->ac3) / 8192.0)) * ((double)calib->ac2);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to calculate pressure in pascals
double calculate_pressure(int32_t raw_pressure, int32_t *calib, double temperature) {
    double var1, var2, p;
    var1 = ((double)temperature / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib->b2) / 32768.0;
    var2 = var2 + var1 * ((double)calib->b1) * 2.0;
    var1 = (((double)calib->mc) + var2) / 16.0;
    var2 = ((double)calib->b6) * var1 * var1 / 524288.0;
    var2 = var2 + ((double)calib->b5) * var1 / 524288.0;
    double t_fine = var1 + var2;
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (t_fine / 2.0)) * 6250.0 / t_fine;
    var1 = ((double)calib->b4) * p * p / 2147483648.0;
    var2 = p * ((double)calib->b3) / 32768.0;
    p = p + (var1 + var2 + ((double)calib->b2)) / 16.0;
    return p;
}

// Function to write calibration data to the BMP180
int write_calibration_data(int i2c_handle, const bmp180_calib_data_t *calib) {
    char data[26];
    data[0] = (char)(calib->ac1 >> 8);
    data[1] = (char)(calib->ac1 & 0xFF);
    data[2] = (char)(calib->ac2 >> 8);
    data[3] = (char)(calib->ac2 & 0xFF);
    data[4] = (char)(calib->ac3 >> 8);
    data[5] = (char)(calib->ac3 & 0xFF);
    data[6] = (char)(calib->ac4 >> 8);
    data[7] = (char)(calib->ac4 & 0xFF);
    data[8] = (char)(calib->ac5 >> 8);
    data[9] = (char)(calib->ac5 & 0xFF);
    data[10] = (char)(calib->ac6 >> 8);
    data[11] = (char)(calib->ac6 & 0xFF);
    data[12] = (char)(calib->b1 >> 8);
    data[13] = (char)(calib->b1 & 0xFF);
    data[14] = (char)(calib->b2 >> 8);
    data[15] = (char)(calib->b2 & 0xFF);
    data[16] = (char)(calib->mb >> 8);
    data[17] = (char)(calib->mb & 0xFF);
    data[18] = (char)(calib->mc >> 8);
    data[19] = (char)(calib->mc & 0xFF);
    data[20] = (char)(calib->md >> 8);
    data[21] = (char)(calib->md & 0xFF);
    data[22] = (char)(calib->b6 >> 8);
    data[23] = (char)(calib->b6 & 0xFF);
    data[24] = (char)(calib->b5 >> 8);
    data[25] = (char)(calib->b5 & 0xFF);

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_CONTROL, data, 26) != 26) {
        fprintf(stderr, "Error writing calibration data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read BMP180 data
int read_bmp180_data(int i2c_handle, int32_t *raw_temperature, int32_t *raw_pressure) {
    char data[6];
