#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "fan_log.txt"
#define MAX_TEMP 70.0
#define MIN_TEMP 40.0
#define MAX_PWM 255
#define MIN_PWM 0

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_cpu_temp();
float map_temperature(float temp);
int set_pwm(int duty_cycle);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    int temp_micro;
    int temp_milli_raw;
    int temp_micro_raw;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening CPU temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp_milli) != 1 || fscanf(fp, "%d", &temp_micro) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return (temp_milli * 1000) + (temp_micro / 1000);
}

// Function to map temperature to duty cycle
float map_temperature(float temp) {
    if (temp < MIN_TEMP) {
        return MIN_PWM;
    }
    if (temp > MAX_TEMP) {
        return MAX_PWM;
    }
    return (float)temp / (MAX_TEMP - MIN_TEMP) * MAX_PWM;
}

// Function to set PWM duty cycle
int set_pwm(int duty_cycle) {
    if (duty_cycle < MIN_PWM) {
        duty_cycle = MIN_PWM;
    } else if (duty_cycle > MAX_PWM) {
        duty_cycle = MAX_PWM;
    }
    gpioPWM(PWM_GPIO, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int temp_milli, temp_micro;
    float temp_celsius, duty_cycle;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature-controlled fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading CPU temperature, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Map temperature to duty cycle
        temp_celsius = (float)temp_milli / 1000.0;
        duty_cycle = map_temperature(temp_celsius);

        // Set PWM duty cycle
        result = set_pwm(duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Log data
        result = log_data(temp_celsius, duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Error logging data, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_pwm(0); // Stop the fan
    fclose(log_file);
    gpioTerminate();

    return 0;
}

