#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define ALERT_LED_GPIO 18
#define ALERT_THRESHOLD 28.0
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 1000
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Mutex structure
typedef struct {
    pthread_mutex_t mutex;
} Mutex;

// Function prototypes
int initialize_i2c();
int read_temperature(float *temperature);
float calculate_average(float *buffer, int size);
void control_led(float temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Circular buffer initialization
CircularBuffer temperature_buffer;

Mutex temperature_mutex;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&temperature_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    temperature_buffer.head = 0;
    temperature_buffer.count = 0;

    // Set GPIO18 as output
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_LED_GPIO, 0); // Initially off

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            float average = calculate_average(temperature_buffer.buffer, BUFFER_SIZE);
            control_led(average);
            log_temperature(average);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from LM75 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to Celsius
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 16.0;

    return 0;
}

// Calculate the average of the temperature readings in the buffer
float calculate_average(float *buffer, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

// Control the LED based on the temperature
void control_led(float temperature) {
    if (temperature > ALERT_THRESHOLD) {
        gpioWrite(ALERT_LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(ALERT_LED_GPIO, 0); // Turn LED off
    }
}

// Log the temperature to a file
void log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f °C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);

    fclose(fp);
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Close I2C file descriptor
    i2cClose(i2c_handle);

    // Release GPIO line
    gpioWrite(ALERT_LED_GPIO, 0); // Turn off LED

    // Destroy mutex
    pthread_mutex_destroy(&temperature_mutex);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

