#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// BMP180 Registers
#define BMP180_ADDR 0x77
#define BMP180_CONTROL 0xF4
#define BMP180_DATA_MSB 0xF6
#define BMP180_DATA_LSB 0xF7
#define BMP180_DATA_XLSB 0xF8

// BMP180 Calibration Data Registers
#define BMP180_CAL_AC1 0xAA
#define BMP180_CAL_AC2 0xAC
#define BMP180_CAL_AC3 0xAE
#define BMP180_CAL_AC4 0xB0
#define BMP180_CAL_AC5 0xB2
#define BMP180_CAL_AC6 0xB4
#define BMP180_CAL_B1 0xB6
#define BMP180_CAL_B2 0xB8
#define BMP180_CAL_MB 0xBA
#define BMP180_CAL_MC 0xBC
#define BMP180_CAL_MD 0xBE

// BMP180 Commands
#define BMP180_TEMP_CMD 0x2E
#define BMP180_PRESSURE_CMD 0x34

// Oversampling Setting
#define BMP180_OVERSAMPLING_SETTING 3 // x8

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Calibration Data
static int ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned int ac4, ac5, ac6;

// Function Prototypes
int read_calibration_data(int i2c_handle, int *ac1, int *ac2, int *ac3, int *b1, int *b2, int *mb, int *mc, int *md);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle);
float calculate_temperature(int raw_temperature, int ac1, int ac2, int ac3, int b1, int b2, int mb, int mc, int md);
float calculate_pressure(int raw_pressure, int ac1, int ac2, int ac3, int b1, int b2, int mb, int mc, int md);
int write_to_log(float temperature, float pressure);
void signal_handler(int signal);
int i2c_read_reg(int i2c_handle, uint8_t reg);
int i2c_write_reg(int i2c_handle, uint8_t reg, uint8_t value);

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// I2C Read Function
int i2c_read_reg(int i2c_handle, uint8_t reg) {
    char buf[1];
    int result = i2cReadI2CBlockData(i2c_handle, reg, buf, 1);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// I2C Write Function
int i2c_write_reg(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteI2CBlockData(i2c_handle, reg, buf, 2);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read Calibration Data
int read_calibration_data(int i2c_handle, int *ac1, int *ac2, int *ac3, int *b1, int *b2, int *mb, int *mc, int *md) {
    uint8_t data[22];
    if (i2c_read_reg(i2c_handle, BMP180_CAL_AC1) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_AC2) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_AC3) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_AC4) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_AC5) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_AC6) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_B1) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_B2) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_MB) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_MC) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_CAL_MD) < 0) return -1;

    *ac1 = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_AC1);
    *ac2 = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_AC2);
    *ac3 = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_AC3);
    *b1 = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_B1);
    *b2 = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_B2);
    *mb = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_MB);
    *mc = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_MC);
    *md = (uint16_t)i2c_read_reg(i2c_handle, BMP180_CAL_MD);

    return 0;
}

// Read Raw Temperature
int read_raw_temperature(int i2c_handle) {
    uint8_t data[2];
    if (i2c_read_reg(i2c_handle, BMP180_TEMP_CMD) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_DATA_MSB) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_DATA_LSB) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_DATA_XLSB) < 0) return -1;
    return (data[0] << 8) | data[1];
}

// Read Raw Pressure
int read_raw_pressure(int i2c_handle) {
    uint8_t data[2];
    if (i2c_read_reg(i2c_handle, BMP180_PRESSURE_CMD) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_DATA_MSB) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_DATA_LSB) < 0) return -1;
    if (i2c_read_reg(i2c_handle, BMP180_DATA_XLSB) < 0) return -1;
    return (data[0] << 8) | data[1];
}

// Calculate Temperature
float calculate_temperature(int raw_temperature, int ac1, int ac2, int ac3, int b1, int b2, int mb, int mc, int md) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)ac1) / 1024.0) * ((double)ac2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)ac1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)ac1) / 8192.0)) * ((double)ac3);
    double b5 = var1 + var2;
    T = (b5 + 8) / 16.0;
    var1 = b1 * ((double)T / 32768.0) + ((double)ac2 * (((double)T / 32768.0) * ((double)T / 32768.0)) / 524288.0);
    var2 = ((double)ac3 * ((double)T / 32768.0)) / 524288.0;
    T = (b5 + 8) / 16.0;
    T = (T * (T * 5 + 2)) / 2147483648.0;
    var1 = (var1 + var2) / 4.0;
    T = T - 8000;
    if (T < 0) {
        T = 0;
    }
    return (float)T;
}

// Calculate Pressure
float calculate_pressure(int raw_pressure, int ac1, int ac2, int ac3, int b1, int b2, int mb, int mc, int md) {
    double var1, var2, p;
    var1 = (((double)raw_pressure) / 16384.0 - ((double)ac1) / 1024.0) * ((double)ac2);
    var2 = ((((double)raw_pressure) / 131072.0 - ((double)ac1) / 8192.0) * (((double)raw_pressure) / 131072.0 - ((double)ac1) / 8192.0)) * ((double)ac3);
    double b5 = var1 + var2;
    p = b5 + 2.35;
    var1 = ((double)b2) * ((double)p / 524288.0) + ((double)ac6) * ((double)p / 524288.0) * ((double)p / 524288.0);
    var2 = ((double)ac5) * ((double)p) / 524288.0;
    p = p + (var1 + var2 + ((double)ac4) * ((double)p / 524288.0));
    return (float)p;
}

// Write to Log File
int write_to_log(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int i2c_handle;
    int ac1, ac2, ac3, b1, b2, mb, mc, md;
    int raw_temperature, raw_pressure;
    float temperature, pressure;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &ac1, &ac2, &ac3, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        raw_temperature = read_raw_temperature(i2c_handle);
        raw_pressure = read_raw_pressure(i2c_handle);

        if (raw_temperature < 0 || raw_pressure < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue; // Skip to the next iteration
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temperature, ac1, ac2, ac3, b1, b2, mb, mc, md);
        pressure = calculate_pressure(raw_pressure, ac1, ac2, ac3, b1, b2, mb, mc, md);

        // Write to log file
        if (write_to_log(temperature, pressure) < 0) {
            fprintf(stderr, "Error writing to log file\n");
        }

        // Print to console
        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

