    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL); // Timer 0, callback function, 500ms

    // Main loop
    while (running) {
        // Wait for the timer to fire
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

