#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://your_server.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define MAX_RETRIES 3

// DHT22 Commands
#define DHT22_MEASURE_HIGH 0xAA
#define DHT22_MEASURE_LOW 0x80

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global variables
static volatile int running = 1;
static int last_gpio_state = 0; // Last GPIO state read
static int last_gpio_value = 0; // Last GPIO value read
static int last_gpio_time = 0; // Last time read
static int last_gpio_retries = 0; // Last retries
static int last_gpio_error = 0; // Last error code
static volatile int last_gpio_error_time = 0; // Last error time

// Function prototypes
int read_dht22(int gpio, SensorData *data);
int validate_checksum(const unsigned char *data, int length);
int post_data(const char *json_data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(DHT22_GPIO, last_gpio_state); // Set GPIO to 0 to release resources
    gpioTerminate();
    printf("pigpio terminated.\n");
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, SensorData *data) {
    unsigned char data_buf[5];
    unsigned char checksum;
    int retries = 0;
    int result;

    // Send start signal
    gpioWrite(gpio, last_gpio_state);
    gpioDelay(1); // Small delay after setting GPIO high
    gpioWrite(gpio, 0);
    gpioDelay(1); // Small delay after setting GPIO low

    // Wait for the sensor to respond (at least 1 ms)
    int timeout = 0;
    while (timeout < 1000) {
        gpioRead(gpio);
        if (gpioRead(gpio) == last_gpio_value) {
            break;
        }
        gpioDelay(1);
        timeout++;
        if (timeout > MAX_RETRIES) {
            fprintf(stderr, "Error: DHT22 timeout waiting for response.\n");
            return -1; // Timeout
        }
    }

    if (timeout > MAX_RETRIES) {
        fprintf(stderr, "Error: DHT22 timeout waiting for response.\n");
        return -1; // Timeout
    }

    // Read data
    gpioWrite(gpio, 0);
    gpioDelay(1); // Small delay after setting GPIO low
    gpioWrite(gpio, 1);
    gpioDelay(1); // Small delay after setting GPIO high
    gpioRead(gpio);
    gpioDelay(1); // Small delay after reading

    // Validate checksum
    if (validate_checksum(data_buf, 5) != 0) {
        fprintf(stderr, "Error: DHT22 checksum validation failed.\n");
        return -1; // Checksum error
    }

    // Extract temperature and humidity
    data_buf[0] = data_buf[0] | (data_buf[1] << 8);
    data_buf[1] = data_buf[1] | (data_buf[2] << 8);
    data_buf[2] = data_buf[2] | (data_buf[3] << 8);
    data_buf[3] = data_buf[3] | (data_buf[4] << 8);

    data_buf[4] = data_buf[4] | (data_buf[5] << 8);
    data_buf[5] = data_buf[5] | (data_buf[6] << 8);

    data_buf[4] = data_buf[4] | (data_buf[7] << 8);
    data_buf[7] = data_buf[7] | (data_buf[8] << 8);
    data_buf[8] = data_buf[8] | (data_buf[9] << 8);
    data_buf[9] = data_buf[9] | (data_buf[10] << 8);
    data_buf[10] = data_buf[10] | (data_buf[11] << 8);
    data_buf[11] = data_buf[11] | (data_buf[12] << 8);
    data_buf[12] = data_buf[12] | (data_buf[13] << 8);
    data_buf[13] = data_buf[13] | (data_buf[14] << 8);
    data_buf[14] = data_buf[14] | (data_buf[15] << 8);

    // Convert data to temperature and humidity
    data_buf[0] = data_buf[0] & 0x7F; // Mask out the high bit
    data_buf[1] = (data_buf[1] << 7) | (data_buf[2] >> 7);
    data_buf[2] = (data_buf[2] << 7) | (data_buf[3] >> 7);
    data_buf[3] = (data_buf[3] << 7) | (data_buf[4] >> 7);
    data_buf[4] = (data_buf[4] << 7) | (data_buf[5] >> 7);
    data_buf[5] = (data_buf[5] << 7) | (data_buf[6] >> 7);

    data_buf[0] = data_buf[0] & 0x7F; // Mask out the high bit
    data_buf[1] = (data_buf[1] << 7) | (data_buf[2] >> 7);
    data_buf[2] = (data_buf[2] << 7) | (data_buf[3] >> 7);
    data_buf[3] = (data_buf[3] << 7) | (data_buf[4] >> 7);
    data_buf[4] = (data_buf[4] << 7) | (data_buf[5] >> 7);
    data_buf[5] = (data_buf[5] << 7) | (data_buf[6] >> 7);
    data_buf[6] = data_buf[6] | (data_buf[7] >> 7);
    data_buf[7] = data_buf[7] | (data_buf[8] >> 7);
    data_buf[8] = data_buf[8] | (data_buf[9] >> 7);
    data_buf[9] = data_buf[9] | (data_buf[10] >> 7);
    data_buf[10] = data_buf[10] | (data_buf[11] >> 7);
    data_buf[11] = data_buf[11] | (data_buf[12] >> 7);
    data_buf[12] = data_buf[12] | (data_buf[13] >> 7);
    data_buf[13] = data_buf[13] | (data_buf[14] >> 7);
    data_buf[14] = data_buf[14] | (data_buf[15] >> 7);

    // Calculate checksum
    checksum = 0;
    for (int i = 0; i < 5; i++) {
        checksum += data_buf[i];
    }

    // Validate checksum
    if (checksum != data_buf[5]) {
        fprintf(stderr, "Error: DHT22 checksum validation failed.\n");
        return -1; // Checksum error
    }

    // Store data
    *data = (SensorData){
        .temperature = (float)data_buf[0] / 10.0,
        .humidity = (float)data_buf[1] / 10.0,
    };

    return 0; // Success
}

// Function to validate checksum
int validate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 0; i < length; i++) {
        checksum += data[i];
    }

    return (checksum == data[length - 1]) ? 0 : 1; // Return 1 if checksum is correct, 0 otherwise
}

// Function to post data to server
int post_data(const char *json_data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = system(SERVER_URL " -d " + json_data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: HTTP POST failed (attempt %d/%d). Error code: %d\n", retries + 1, MAX_RETRIES, result);
            retries++;
            sleep(RETRY_DELAY_MS); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: HTTP POST failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure after all retries
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set GPIO mode for DHT22
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0); // Set GPIO low initially

    // Set up retries for DHT22
    last_gpio_state = 0;
    last_gpio_value = 0;
    last_gpio_time = 0;
    last_gpio_retries = 0;
    last_gpio_error = 0;
    last_gpio_error_time = 0;

    // Main loop
    while (running) {
        SensorData sensor_data;
        int retries = 0;
        int result;

        // Read DHT22 sensor
        while (retries < MAX_RETRIES) {
            result = read_dht22(DHT22_GPIO, &sensor_data);
            if (result == 0) {
                break; // Success
            } else {
                fprintf(stderr, "Error: DHT22 read failed (attempt %d/%d). Error code: %d\n", retries + 1, MAX_RETRIES, result);
                retries++;
                gpioDelay(RETRY_DELAY_MS); // Wait before retrying
            }
        }

        if (result == 0) {
            // Validate checksum
            if (validate_checksum(sensor_data.data, 5) != 0) {
                fprintf(stderr, "Error: DHT22 checksum validation failed.\n");
                post_data(""); // Send empty JSON payload
                continue; // Skip to the next iteration
            }

            // Post data to server
            if (post_data(sensor_data.data) != 0) {
                fprintf(stderr, "Error: Failed to post data to server.\n");
            } else {
                printf("Data posted successfully.\n");
            }
        } else {
            fprintf(stderr, "Error: DHT22 read failed after %d retries.\n", MAX_RETRIES);
        }

        // Wait before next reading
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup
    cleanup();

    return 0;
}

