            // Post data to server
            if (post_data(sensor_data.data) != 0) {
                fprintf(stderr, "Error: Failed to post data to server.\n");
            } else {
                printf("Data posted successfully.\n");
            }
        } else {
            fprintf(stderr, "Error: DHT22 read failed after %d retries.\n", MAX_RETRIES);
        }

        // Wait before next reading
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup
    cleanup();

    return 0;
