        fprintf(stderr, "Error reading b5\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, 0xF9, (char *)&b6, 1) != 1) {
        fprintf(stderr, "Error reading b6\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, 0xFA, (char *)&b7, 1) != 1) {
        fprintf(stderr, "Error reading b7\n");
        return -1;
    }

    // Set calibration data
    *x1 = (uint16_t)((buffer[1] << 8) | buffer[0]);
    *x2 = (uint16_t)((buffer[3] << 8) | buffer[2]);
