    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buffer, 3) != 3) {
        fprintf(stderr, "Error reading temperature\n");
        return -1;
    }

    raw_temp = (buffer[0] << 12) | (buffer[1] << 4) | (buffer[2] >> 4);
    *temperature = (175.0 * raw_temp / 65536.0) - 46.0;

    return 0;
}

// Function to calculate the temperature in degrees Celsius
float calculate_temperature(int32_t raw_temp) {
    return (175.0 * raw_temp) / 65536.0;
}

// Function to calculate the pressure in hPa
float calculate_pressure(int32_t raw_pressure) {
    return (175.0 * raw_pressure) / 65536.0;
}

// Function to log the data to a file
void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    if (level == FALLING_EDGE) {
        // Debounce
        if (gpioGetCurrentTime() - program_running_time > 200000) {
            program_running = 0;
            printf("Logging disabled\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    int i2c_handle;
    float temperature, pressure;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
