        gpioTerminate();
        return 1;
    }

    // Initialize BMP180 sensor
    if (bmp180_init(i2c_handle) != 0) {
        fprintf(stderr, "BMP180 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    gpioSetISRFuncEx(GPIO_4, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Main loop
    while (program_running) {
        // Read temperature and pressure
        ret = bmp180_read_compression(i2c_handle, &temperature, &pressure, NULL);
        if (ret != 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            // Log the data
            log_data(temperature, pressure);
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds = 2000000 microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

