#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Define constants
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_TEMP_VALUE 10000 // Maximum temperature value
#define MAX_FAN_STATE_VALUE 3 // Maximum fan state value
#define MAX_FAN_SPEED_VALUE 3 // Maximum fan speed value
#define MAX_TEMP_VALUE_DOUBLE (MAX_TEMP_VALUE * 1000.0) // Convert to millidegrees
#define MAX_FAN_SPEED_VALUE_DOUBLE (MAX_FAN_SPEED_VALUE * 1000.0) // Convert to millidegrees
#define TEMP_STEP 0.1
#define FAN_STEP 0.1
#define LOG_INTERVAL 5 // Seconds

// Global variables
int running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_cpu_temp();
int read_fan_state();
int map_temperature(int temp);
int map_fan_state(int fan_state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening CPU temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        perror("Error reading CPU temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read fan state from file
int read_fan_state() {
    FILE *fp;
    int fan_state;

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1;
    }

    if (fscanf(fp, "%d", &fan_state) != 1) {
        perror("Error reading fan state");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return fan_state;
}

// Function to map temperature to fan state
int map_temperature(int temp) {
    if (temp < 45) {
        return 0;
    } else if (temp < 55) {
        return 1;
    } else if (temp < 65) {
        return 2;
    } else {
        return 3;
    }
}

// Function to map fan state to temperature
int map_fan_state(int fan_state) {
    if (fan_state == 0) {
        return 45;
    } else if (fan_state == 1) {
        return 55;
    } else if (fan_state == 2) {
        return 65;
    } else {
        return MAX_TEMP_VALUE;
    }
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        perror("Error writing to log file");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int cpu_temp, fan_state;
    int temp_value, fan_speed_value;
    int temp_value_double, fan_speed_value_double;
    int temp_int, fan_state_int;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CPU temperature
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            log_event("Error reading CPU temperature");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read fan state
        fan_state = read_fan_state();
        if (fan_state == -1) {
            log_event("Error reading fan state");
            sleep(1); // Wait before retrying
            continue;
        }

        // Map temperature to fan state
        fan_state_int = map_fan_state(fan_state);

        // Map fan state to temperature
        temp_value = map_temperature(fan_state_int);

        // Map fan speed to temperature
        fan_speed_value = map_fan_state(fan_state_int);

        // Calculate temperature in millidegrees
        temp_value_double = (float)temp_value * 1000.0;

        // Calculate fan speed in millidegrees
        fan_speed_value_double = (float)fan_speed_value * 1000.0;

        // Validate fan state
        if (fan_state_int != fan_state) {
            log_event("Fan state changed");
            gpioWrite(FAN_STATE_FILE, fan_state);
            log_event("Fan state changed");
        }

        // Log events
        log_event("CPU Temperature: " + std::to_string(cpu_temp) + " °C");
        log_event("Fan State: " + std::to_string(fan_state_int) + "");
        log_event("Temperature: " + std::to_string(temp_value) + " °C");
        log_event("Fan Speed: " + std::to_string(fan_speed_value) + "");

        // Wait for the next cycle
        sleep(LOG_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

