    } else if (temp < 55) {
        return 1;
    } else if (temp < 65) {
        return 2;
    } else {
        return 3;
    }
}

// Function to map fan state to temperature
int map_fan_state(int fan_state) {
    if (fan_state == 0) {
        return 45;
    } else if (fan_state == 1) {
        return 55;
    } else if (fan_state == 2) {
        return 65;
    } else {
        return MAX_TEMP_VALUE;
    }
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        perror("Error writing to log file");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int cpu_temp, fan_state;
    int temp_value, fan_speed_value;
    int temp_value_double, fan_speed_value_double;
    int temp_int, fan_state_int;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CPU temperature
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            log_event("Error reading CPU temperature");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read fan state
        fan_state = read_fan_state();
        if (fan_state == -1) {
            log_event("Error reading fan state");
            sleep(1); // Wait before retrying
            continue;
        }

        // Map temperature to fan state
        fan_state_int = map_fan_state(fan_state);

        // Map fan state to temperature
        temp_value = map_temperature(fan_state_int);

        // Map fan speed to temperature
        fan_speed_value = map_fan_state(fan_state_int);

        // Calculate temperature in millidegrees
        temp_value_double = (float)temp_value * 1000.0;

        // Calculate fan speed in millidegrees
        fan_speed_value_double = (float)fan_speed_value * 1000.0;

        // Validate fan state
        if (fan_state_int != fan_state) {
            log_event("Fan state changed");
            gpioWrite(FAN_STATE_FILE, fan_state);
            log_event("Fan state changed");
        }

        // Log events
        log_event("CPU Temperature: " + std::to_string(cpu_temp) + " °C");
        log_event("Fan State: " + std::to_string(fan_state_int) + "");
        log_event("Temperature: " + std::to_string(temp_value) + " °C");
        log_event("Fan Speed: " + std::to_string(fan_speed_value) + "");

        // Wait for the next cycle
        sleep(LOG_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

