#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 100
#define PID_KP 1.0
#define PID_KI 0.1
#define PID_KD 0.01
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define MAX_ERROR_THRESHOLD 5.0
#define MAX_ERROR_COUNT 5
#define MAX_ERROR_TIME_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID parameters
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDParams;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
float calculate_pid(float setpoint, float actual_temperature, PIDParams pid_params);
void set_pwm(int gpio, int duty_cycle);
void log_data(float temperature, int duty_cycle, PIDParams pid_params);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    unsigned char buffer[4];
    int result;

    // Read 4 bytes from SPI
    result = spiRead(spi_handle, (char *)buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from SPI: %d\n", result);
        return -1;
    }

    // Extract temperature data
    int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    *temperature = (float)raw_temperature / 16384.0 * 100.0;

    return 0;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, PIDParams pid_params) {
    float error = setpoint - actual_temperature;
    float pid_output = pid_params.Kp * error + pid_params.Ki * error + pid_params.Kd * (error - pid_params.Kd * error);
    return pid_output;
}

// Function to set PWM duty cycle
void set_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log data to file
