    printf("Cleaning up...\n");
    set_pwm(HEATER_GPIO, 0); // Turn off heater
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    spiClose(spi_handle);
}

