    PIDParams pid_params = {PID_KP, PID_KI, PID_KD};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as PWM output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate PID output
            pid_output = calculate_pid(MAX_TEMPERATURE, temperature, pid_params);

            // Set PWM duty cycle
            set_pwm(HEATER_GPIO, (int)pid_output);

            // Log data
            log_data(temperature, (int)pid_output, pid_params);

            printf("Temperature: %.2f °C, PID Output: %.2f%%\n", temperature, pid_output);
        } else {
            fprintf(stderr, "Error reading temperature, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

