// Define GPIO pins
#define FAN_PIN 18
#define TEMP_PIN 4

// Define PWM frequency and duty cycle range
#define PWM_FREQUENCY 25000
#define MIN_PWM_FREQUENCY 1000
#define MAX_PWM_FREQUENCY 200000
#define MIN_PWM_DUTY 0
#define MAX_PWM_DUTY 100

// Define PWM range
#define PWM_RANGE (MAX_PWM_DUTY - MIN_PWM_DUTY)

// Define PWM duty cycle range
#define PWM_DUTY_RANGE (MAX_PWM_DUTY - MIN_PWM_DUTY)

// Define temperature range
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0

// Define PWM duty cycle percentage range
#define PWM_DUTY_RANGE (MAX_PWM_DUTY - MIN_PWM_DUTY)

// Global variables
volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_fan_speed(int duty_cycle);
int read_cpu_temperature();
float map_temperature_to_duty_cycle(float temperature);
int log_data(float temperature, int duty_cycle);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetMode(TEMP_PIN, PI_INPUT);

    return 0;
}

// Function to set fan speed
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    gpioPWM(FAN_PIN, duty_cycle);
    return 0;
}

// Function to read CPU temperature
int read_cpu_temperature() {
    int raw_temp;
    raw_temp = gpioRead(TEMP_PIN);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading CPU temperature\n");
        return -1;
    }
    return raw_temp;
}

// Function to map temperature to duty cycle
float map_temperature_to_duty_cycle(float temperature) {
    if (temperature < TEMP_MIN) {
        return MIN_PWM_DUTY;
    } else if (temperature > TEMP_MAX) {
        return MAX_PWM_DUTY;
    } else {
        return (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * PWM_DUTY_RANGE + MIN_PWM_DUTY;
    }
}

// Function to log data to file
int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

