    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (°C),PWM Duty Cycle (%%)\n");
    }

    // Main loop
    while (running) {
        // Read CPU temperature
        int raw_temp = read_cpu_temperature();
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading CPU temperature, skipping this iteration\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Map temperature to duty cycle
        float temperature = (float)raw_temp / 1000.0; // Convert to Celsius
        int duty_cycle = map_temperature_to_duty_cycle(temperature);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, skipping this iteration\n");
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, skipping this iteration\n");
        }

        // Sleep for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

