    i2c_handle1 = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SLF3S_ADDRESS + 1, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        return -1;
    }

    return 0;
}

// Read sensor data from I2C
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buf[6];
    int bytes_read;

    // Read 6 bytes from the sensor (2 data bytes + CRC)
    bytes_read = i2cReadDevice(i2c_handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Validate checksum
    if (!validate_checksum(buf[2])) {
        fprintf(stderr, "Checksum validation failed for sensor data\n");
        return -1;
    }

    // Extract flow data
    data->flow1 = (int16_t)((buf[0] << 8) | buf[1]);
    data->flow2 = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

// Validate CRC-8 checksum
int validate_checksum(int data) {
    int checksum = (data >> 8) & 0xFF;
    int crc = data & 0xFF;

    if (crc != checksum) {
        fprintf(stderr, "Checksum mismatch for data: %d, %d\n", data, checksum);
        return 0; // Invalid checksum
    }
    return 1; // Valid checksum
}

// Log data to file
int log_data(const char *timestamp, int flow1, int flow2) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d\n", timestamp, flow1, flow2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor1_data, sensor2_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
            if (validate_checksum(sensor1_data.flow1) && validate_checksum(sensor1_data.flow2)) {
