#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define RED_REG 0x02
#define IR_REG 0x03
#define IR_THRESHOLD 2000
#define LED_GPIO 17
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_sensor_data(int *red, int *ir);
void log_data(int red, int ir);
void control_led(int ir_value);
void cleanup();
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int red;
    int ir;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&red, &ir) == 0) {
            // Log data
            log_data(red, ir);

            // Control LED
            control_led(ir);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *red, int *ir) {
    char buf[2];
    int result;

    // Read red channel
    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read red channel data: %d\n", result);
        return -1;
    }
    *red = (buf[0] << 8) | buf[1];

    // Read infrared channel
    result = i2cReadI2CBlockData(i2c_handle, IR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read infrared channel data: %d\n", result);
        return -1;
    }
    *ir = (buf[0] << 8) | buf[1];

    return 0;
}

// Log data to file
void log_data(int red, int ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on IR value
void control_led(int ir_value) {
    if (ir_value > IR_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

