#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 18
#define PULSES_PER_REVOLUTION 1
#define LOG_FILE "rpm_log.txt"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 12345
#define MAX_RETRIES 3
#define TIMEOUT_US 1000000 // 1 second

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_counter_mutex = PTHREAD_MUTEX_INITIALIZER;
static int running = 1;
static int server_socket = -1;
static int log_fd = -1;

// Function prototypes
void *interrupt_handler(void *arg);
double calculate_rpm(int pulses);
void log_rpm(double rpm);
void *tcp_client_thread(void *arg);
void signal_handler(int signal);
int initialize_gpio();
int initialize_log();
void cleanup();

// Interrupt handler function
void *interrupt_handler(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        int pulses = gpioRead(GPIO_PIN);
        if (pulses >= 0) {
            pthread_mutex_lock(&pulse_counter_mutex);
            pulse_count += pulses;
            pthread_mutex_unlock(&pulse_counter_mutex);
        } else {
            syslog(LOG_ERR, "Error reading GPIO pin: %s", strerror(errno));
        }
        gpioDelay(1000000); // 1 second delay
    }
    return NULL;
}

// RPM calculation function
double calculate_rpm(int pulses) {
    if (pulses == 0) {
        return 0.0;
    }
    return (double)pulses / (double)PULSES_PER_REVOLUTION;
}

// Logging function
void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fd != -1) {
        fprintf(log_fd, "%s, RPM: %.2f\n", timestamp, rpm);
        fflush(log_fd); // Ensure data is written to file immediately
    } else {
        syslog(LOG_ERR, "Error: Log file not opened.");
    }
}

// TCP client thread function
void *tcp_client_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    int sock = -1;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};
    int bytes_received;

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Error creating socket: %s", strerror(errno));
        return NULL;
    }

    // Configure server address
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sock);
        return NULL;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Error connecting to server: %s", strerror(errno));
        close(sock);
        return NULL;
    }

    // Receive data from server
    while (1) {
        bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            syslog(LOG_INFO, "Received: %s", buffer);
        } else if (bytes_received < 0) {
            syslog(LOG_ERR, "Error receiving data: %s", strerror(errno));
            break;
        } else {
            syslog(LOG_INFO, "No data received.");
        }
        if (bytes_received > 0) {
            // Parse data (example: "RPM: 1234.5")
            char *start = strstr(buffer, "RPM:");
            if (start != NULL) {
                char *end = strstr(start + strlen("RPM:"), "\n");
                if (end != NULL) {
                    double rpm = atof(start + strlen("RPM:") + 1);
                    log_rpm(rpm);
                }
            }
        }
        sleep(1); // Delay before next read
    }

    // Cleanup
    close(sock);
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// GPIO initialization function
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Log file opening function
int initialize_log() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Error opening log file: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (log_fd != -1) {
        close(log_fd);
    }
    gpioTerminate();
    if (server_socket != -1) {
        close(server_socket);
    }
    pthread_mutex_destroy(&pulse_counter_mutex);
    syslog(LOG_INFO, "Cleanup complete.");
}

int main() {
    // Initialize syslog
    openlog("rpm_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed.");
        return 1;
    }

    // Initialize log file
    if (initialize_log() != 0) {
        syslog(LOG_ERR, "Log file initialization failed.");
        cleanup();
        return 1;
    }

    // Create interrupt handler thread
    pthread_t interrupt_thread;
    if (pthread_create(&interrupt_thread, NULL, interrupt_handler, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create interrupt handler thread.");
        cleanup();
        return 1;
    }

    // Create TCP client thread
    pthread_t client_thread;
    if (pthread_create(&client_thread, NULL, tcp_client_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create TCP client thread.");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        pthread_mutex_lock(&pulse_counter_mutex);
        int pulses = pulse_count;
        pthread_mutex_unlock(&pulse_counter_mutex);

        if (pulses > 0) {
            double rpm = calculate_rpm(pulses);
