#include <pigpio.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x38
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t infrared;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_sensor_data(int fd, sensor_data_t *data);
void log_data(const sensor_data_t *data);
void control_led(int gpio, int state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    char buf[6];
    int bytes_read = read(fd, buf, sizeof(buf));
    if (bytes_read != sizeof(buf)) {
        perror("Error reading sensor data");
        return -1;
    }

    // Convert raw data to 16-bit integers
    data->red = (buf[0] << 8) | buf[1];
    data->infrared = (buf[3] << 8) | buf[4];

    return 0;
}

// Log data to file
void log_data(const sensor_data_t *data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data->red, data->infrared);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, ADPD144RI_ADDR);
    if (i2c_fd < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            log_data(&sensor_data);
            control_led(LED_GPIO, 1); // Turn on LED
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sample interval
            control_led(LED_GPIO, 0); // Turn off LED
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

