// Define the number of samples to collect for peak detection
#define NUM_SAMPLES 100

// Define the threshold for detecting rising edges
#define THRESHOLD 500

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to read the audio input
int read_audio_input() {
    int value = gpioRead(AUDIO_IN_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", AUDIO_IN_PIN);
        return -1;
    }
    return value;
}

// Function to detect rising edges
int detect_rising_edge(int pin, int threshold) {
    int count = 0;
    int value = read_audio_input();
    if (value < 0) {
        return -1;
    }
    if (value == 1) {
        count++;
    }
    if (count == NUM_SAMPLES) {
        if (value == 1 && value == value + 1) {
            return 1;
        }
    }
    return 0;
}

// Function to log the event to a file
int log_event(int level) {
    FILE *fp = fopen(AUDIO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", AUDIO_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s %d\n", timestamp, level);
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set GPIO modes
    if (set_gpio_mode(AUDIO_IN_PIN, PI_INPUT) != 0) {
        cleanup_gpio();
        return 1;
    }
    if (set_gpio_mode(GAIN_SELECT_PIN, PI_OUTPUT) != 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int level = detect_rising_edge(AUDIO_IN_PIN, THRESHOLD);
        if (level == 1) {
            if (log_event(level) != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }
        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Program terminated.\n");
    return 0;
}

