#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_1 17
#define TOUCH_SENSOR_2 18
#define TOUCH_SENSOR_3 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME_MS 100

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_touch_sensor(int gpio_pin);
void debounce_touch_sensor(int gpio_pin);
void print_alert(int gpio_pin);
void cleanup_handler(int signal);

// Signal handler for graceful shutdown
void cleanup_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioTerminate();
    exit(0);
}

// Function to read the touch sensor
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the touch sensor
void debounce_touch_sensor(int gpio_pin) {
    gpioDelay(DEBOUNCE_TIME_MS * 1000); // Delay for debounce time in microseconds
}

// Function to print an alert
void print_alert(int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ALERT: TOUCH DETECTED on GPIO %d\n", timestamp, gpio_pin);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TOUCH_SENSOR_1, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_2, PI_INPUT);
