#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// PWM frequency in Hz
#define PWM_FREQUENCY 100

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("Received signal, shutting down...\n");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    return 0;
}

// Read the flame sensor
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_GPIO);
    if (reading < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", reading);
        return -1; // Indicate error
    }
    return reading;
}

// Control the fan
void control_fan(int state) {
    gpioPWM(FAN_GPIO, state);
}

// Log events to file
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == -1) {
            fprintf(stderr, "Error reading flame sensor, retrying...\n");
            gpioDelay(DEBOUNCE_TIME * 1000); // Wait for debounce
            continue;
        }

        if (flame_detected == 0) {
            printf("Flame detected!\n");
            control_fan(1); // Turn on fan
            log_event("Flame detected");
            gpioDelay(PWM_FREQUENCY * 1000); // Wait for PWM period
            control_fan(0); // Turn off fan
            log_event("Flame ended");
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_fan(0); // Ensure fan is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

