#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int spi_speed;
    int gpio_ce;
    int gpio_data_ready;
    int start_frequency;
    int end_frequency;
    int chirps;
    int samples;
    int frame_size;
} radar_config_t;

// Global variables
radar_config_t config;
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_spi(int channel, int speed);
int read_radar_data(int spi_handle, uint8_t *data, int num_samples);
void process_radar_data(uint8_t *data, int num_samples, int *range, int *doppler);
void log_data(int range, int doppler);
void handle_interrupt(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int init_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, spi_handle);
        return -1;
    }
    return 0;
}

// Function to read radar data from the sensor
int read_radar_data(int spi_handle, uint8_t *data, int num_samples) {
    char tx_buf[num_samples * config.frame_size];
    char rx_buf[num_samples * config.frame_size];

    // Fill transmit buffer with chirps
    for (int i = 0; i < num_samples; i++) {
        tx_buf[i] = (uint8_t)(config.start_frequency + (i % config.chirps) * (config.end_frequency - config.start_frequency));
    }

    // Read data from SPI
    int result = spiXfer(spi_handle, tx_buf, rx_buf, num_samples * config.frame_size);
    if (result != num_samples * config.frame_size) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1;
    }

    // Convert data to range-Doppler heatmap format
    for (int i = 0; i < num_samples; i++) {
        data[i] = (uint8_t)(rx_buf[i] << 8); // Combine high and low bytes
    }

    return 0;
}

// Function to process radar data
void process_radar_data(uint8_t *data, int num_samples, int *range, int *doppler) {
    // Placeholder for data processing (replace with actual TI SDK calls)
    *range = (int)(data[0] * 100); // Example range calculation
    *doppler = (int)(data[1] * 100); // Example Doppler calculation
}

// Function to log data to a binary file
void log_data(int range, int doppler) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, range, doppler);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        uint8_t *data = (uint8_t *)malloc(config.frame_size);
        if (data == NULL) {
            fprintf(stderr, "Error allocating memory for data\n");
            return;
        }

        if (read_radar_data(spi_handle, data, config.frame_size) == 0) {
            process_radar_data(data, config.frame_size, range, doppler);
            log_data(range, doppler);
        } else {
            fprintf(stderr, "Error reading radar data during interrupt\n");
        }

        free(data);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.gpio_ce, PI_OUTPUT);
    gpioSetMode(config.gpio_data_ready, PI_INPUT);

    // Initialize SPI
    if (init_spi(config.spi_channel, config.spi_speed) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(config.gpio_data_ready, RISING_EDGE, 0, handle_interrupt, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

