// Define constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x00
#define CONVERSION_REG 0x01
#define LIGHT_DATA_FILE "light_data.txt"
#define RETRY_COUNT 3
#define SLEEP_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    uint8_t config_value;
} opt3001_config_t;

// Function prototypes
int opt3001_init(int i2c_handle);
int opt3001_read_data(int i2c_handle, uint16_t *lux);
int log_data(FILE *fp, uint16_t lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the OPT3001 sensor
int opt3001_init(int i2c_handle) {
    // Configure the sensor for continuous conversion mode
    uint8_t config_data[2] = {0x00, 0x01}; // Enable continuous conversion, set FS range
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to config register.\n");
        return -1;
    }
    return 0;
}

// Read data from the OPT3001 sensor
int opt3001_read_data(int i2c_handle, uint16_t *lux) {
    char buf[2];
    int result;

    // Read the conversion register
    result = i2cWriteDevice(i2c_handle, CONVERSION_REG, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to conversion register.\n");
        return -1;
    }

    // Read the lux value
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from conversion register.\n");
        return -1;
    }

    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

// Log data to a file
int log_data(FILE *fp, uint16_t lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Write data to file
    if (fprintf(fp, "%s, %u\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3001 sensor
    if (opt3001_init(i2c_handle) != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LIGHT_DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        uint16_t lux;

        // Read data from sensor
        if (opt3001_read_data(i2c_handle, &lux) == 0) {
            // Log data to file
            if (log_data(log_file, lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 100ms
        gpioDelay(SLEEP_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

