    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s Flame Detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
    fclose(fp);
    return 0;
}

