        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Flame detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting\n");
            break;
