    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", TILT_GPIO_PIN, value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TILT_GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_GPIO_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl-C to exit.\n");

    while (program_running) {
        int tilt_state = read_tilt_sensor();
        if (tilt_state < 0) {
            fprintf(stderr, "Error reading tilt sensor, exiting.\n");
            break;
        }

        time_t now = time(NULL);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        if (tilt_state == 0) {
            printf("%s Tilted\n", timestamp);
        } else {
            printf("%s Not Tilted\n", timestamp);
        }

        gpioDelay(100); // Delay for 100ms
    }

    gpioTerminate();
    return 0;
}

