#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_CONFIG 0x24
#define REG_UV_CONFIG 0x25

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int uv_index;
    int als_visible;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int read_si1145_register(int reg_addr, uint8_t *data);
int write_si1145_register(int reg_addr, uint8_t data);
int initialize_si1145();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_si1145() {
    // Reset the sensor
    if (write_si1145_register(REG_ALS_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error resetting Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (write_si1145_register(REG_ALS_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error configuring Si1145\n");
        return -1;
    }

    if (write_si1145_register(REG_UV_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error configuring Si1145\n");
        return -1;
    }

    return 0;
}

// Function to read data from a Si1145 register
int read_si1145_register(int reg_addr, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, reg_addr, (char *)data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg_addr, result);
        return -1;
    }
    return 0;
}

// Function to write data to a Si1145 register
int write_si1145_register(int reg_addr, uint8_t data) {
    int result = i2cWriteByteData(i2c_handle, reg_addr, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg_addr, result);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1145 sensor
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    if (initialize_si1145() != 0) {
        fprintf(stderr, "Error initializing Si1145\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t als_vis_data[2];
    if (read_si1145_register(REG_ALS_VIS_DATA0, als_vis_data) != 0) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    data->uv_index = als_vis_data[0];
    data->als_visible = als_vis_data[1];

    return 0;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to the log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,Visible Light\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

