#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_LOG_FILE "flow_log.txt"
#define START_COMMAND_LENGTH 2
#define FLOW_RATE_THRESHOLD 0.5
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_flow_rate(int i2c_handle, float *flow_rate);
float validate_flow_rate(float flow_rate, int crc);
void log_flow_rate(float flow_rate1, float flow_rate2);
void set_alarm(int gpio, int state);
void cleanup();
void signal_handler(int signal);

// CRC Polynomial and Initial Value
const uint8_t crc_poly[] = {0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f};
const uint8_t crc_init_value[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read flow rate from a sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    char buf[2];
    int bytes_read;
    int16_t raw_flow;

    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading flow rate: %d\n", bytes_read);
        return -1;
    }

    raw_flow = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw_flow / 60.0; // Convert to ml/min

    return 0;
}

// Function to validate flow rate with CRC
int validate_flow_rate(float flow_rate, int crc) {
    if (crc != crc_poly[crc_init_value[0]]) {
        fprintf(stderr, "CRC check failed for flow rate: %.2f\n", flow_rate);
        return -1;
    }
    return 0;
}

// Function to log flow rate to a file
void log_flow_rate(float flow_rate1, float flow_rate2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
