#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27

// Define circular buffer size
#define BUFFER_SIZE 100

// Define threshold for obstacle detection
#define OBSTACLE_THRESHOLD 500

// Define alert message
#define ALERT_MESSAGE "Obstacle detected!"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int value;
    time_t timestamp;
} sensor_data_t;

// Circular buffer
sensor_data_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio(int gpio);
int read_sensor(int gpio);
void add_to_buffer(int gpio, int value);
void print_buffer();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(SENSOR_1_GPIO) != 0 ||
        initialize_gpio(SENSOR_2_GPIO) != 0 ||
        initialize_gpio(SENSOR_3_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        int sensor3_value = read_sensor(SENSOR_3_GPIO);

        // Add sensor data to the buffer
        add_to_buffer(SENSOR_1_GPIO, sensor1_value);
        add_to_buffer(SENSOR_2_GPIO, sensor2_value);
        add_to_buffer(SENSOR_3_GPIO, sensor3_value);

        // Print the buffer
        print_buffer();

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize a GPIO pin
int initialize_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio);
        return 1;
    }
    if (gpioSetPullUpDown(gpio, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to enable pull-up resistor on GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Function to read the sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to add sensor data to the circular buffer
void add_to_buffer(int gpio, int value) {
    sensor_data_t data;
    data.gpio = gpio;
    data.value = value;
    data.timestamp = time(NULL);

    // Overwrite the oldest entry in the buffer
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Check if the buffer is full
    if (buffer_index == 0) {
        printf("Buffer is full. No new data.\n");
    } else {
        printf("GPIO: %d, Value: %d, Timestamp: %ld\n", gpio, value, data.timestamp);
    }
}

// Function to print the contents of the buffer
void print_buffer() {
    printf("Sensor Data:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer_index == i) {
            printf("  GPIO: %d, Value: %d, Timestamp: %ld\n", buffer_buffer[i].gpio, buffer_buffer[i].value, buffer_buffer[i].timestamp);
        }
    }
    printf("\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

