#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x68

// TMAG5170 register addresses
#define TMAG5170_REG_X_MSB 0x00
#define TMAG5170_REG_X_LSB 0x01
#define TMAG5170_REG_Y_MSB 0x02
#define TMAG5170_REG_Y_LSB 0x03
#define TMAG5170_REG_Z_MSB 0x04
#define TMAG5170_REG_Z_LSB 0x05
#define TMAG5170_REG_CONFIG 0x0E
#define TMAG5170_REG_STATUS 0x0F

// Configuration values
#define TMAG5170_CONFIG_MODE 0x01
#define TMAG5170_CONFIG_RANGE 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tmag5170_init(int i2c_handle);
int tmag5170_read_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the TMAG5170 sensor
int tmag5170_init(int i2c_handle) {
    // Configure the sensor for continuous conversion mode
    if (i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_MODE) < 0) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }

    // Configure the sensor for 50mT range
    if (i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_RANGE) < 0) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read data from the TMAG5170 sensor
int tmag5170_read_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;

    // Read X, Y, and Z data in a single read
    result = i2cReadI2CBlockData(i2c_handle, TMAG5170_REG_X_MSB, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two MSBs to form a 16-bit value
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Log data to a CSV file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Write the data to the CSV file
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately
}

int main() {
    int16_t x, y, z;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tmag5170_init(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (tmag5170_read_data(i2c_handle, &x, &y, &z) == 0) {
            // Log the data
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Wait 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

