#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 7
#define PULSE_DURATION_US 100000 // 100ms
#define RPM_LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
volatile int pulse_start_time = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the pulse count from the GPIO pin
int read_pulse_count() {
    return pulse_count;
}

// Function to calculate the RPM from the pulse count
double calculate_rpm(int pulse_count) {
    if (pulse_count == 0) {
        return 0.0;
    }

    double time_diff_us = (double)(pulse_count - pulse_start_time) / 1000000.0;
    double rpm = 60.0 / time_diff_us; // RPM = 60 / time_diff_us

    return rpm;
}

// Function to log the RPM to a file
int log_rpm(double rpm) {
    FILE *fp = fopen(RPM_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", RPM_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, rpm);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int pulse_count = read_pulse_count();
        if (pulse_count > 0) {
            pulse_start_time = gpioTick();
            pulse_count++;
        } else {
            // Handle the case where the sensor is absent or not rotating
            double rpm = 0.0;
            if (log_rpm(rpm) != 0) {
                fprintf(stderr, "Error logging RPM\n");
            }
        }

        gpioDelay(1000000); // 1 second delay
    }

    return 0;
}

