    fprintf(fp, "%s,%.2f\n", timestamp, rpm);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int pulse_count = read_pulse_count();
        if (pulse_count > 0) {
            pulse_start_time = gpioTick();
            pulse_count++;
        } else {
            // Handle the case where the sensor is absent or not rotating
            double rpm = 0.0;
            if (log_rpm(rpm) != 0) {
                fprintf(stderr, "Error logging RPM\n");
            }
        }

        gpioDelay(1000000); // 1 second delay
    }

    return 0;
}

