    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting.");
        closelog();
        return 1;
    }

    log_event("Touch sensor monitoring started.");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            log_event("Touch detected!");
            control_led(1); // Turn on LED
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
            if (read_sensor() == 1) {
                log_event("Touch released.");
                control_led(0); // Turn off LED
            }
        } else {
            log_event("No touch detected.");
