        gpioDelay(50); // Check every 50ms
    }

    // Cleanup (should not reach here if signal handler works)
    control_led(0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog

    return 0;
}

