#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Define circular buffer size
#define BUFFER_SIZE 100

// Define overflow counter
#define OVERFLOW_COUNT 0

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Define log buffer
static char *log_buffer = NULL;
static int log_buffer_size = 0;
static int log_buffer_index = 0;

// Global variables
static volatile int running = 1;

// Function prototypes
void cleanup();
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int read_sensor(int pin);
void set_led(int pin, int state);
void log_event(int sensor_pin, int state);
void circular_buffer_init(int *buffer, int size);
void circular_buffer_add(int *buffer, int index, int value);
int circular_buffer_get(int *buffer, int index);
int circular_buffer_is_full(int *buffer, int size);
int circular_buffer_is_empty(int *buffer, int size);
int circular_buffer_get_size(int *buffer, int *size);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED1_PIN, 0);
    gpioWrite(LED2_PIN, 0);
    gpioTerminate();
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to set LED state
void set_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log event
void log_event(int sensor_pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_buffer != NULL) {
        circular_buffer_add(log_buffer, log_buffer_index, state);
        log_buffer_index = (log_buffer_index + 1) % BUFFER_SIZE;
        if (circular_buffer_is_full(log_buffer, BUFFER_SIZE)) {
            log_buffer_size = circular_buffer_get_size(log_buffer, &log_buffer_size);
            if (log_buffer_size == 0) {
                log_buffer_index = 0;
            }
        }
    } else {
        log_buffer_index = 0;
    }

    circular_buffer_add(log_buffer, log_buffer_index, state);
    log_buffer_index = (log_buffer_index + 1) % BUFFER_SIZE;
    if (circular_buffer_is_empty(log_buffer, BUFFER_SIZE)) {
        log_buffer_size = circular_buffer_get_size(log_buffer, &log_buffer_size);
        if (log_buffer_size == 0) {
            log_buffer_index = 0;
        }
    }
}

// Function to initialize circular buffer
void circular_buffer_init(int *buffer, int size) {
    if (size > BUFFER_SIZE) {
        fprintf(stderr, "Circular buffer size is too small\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        buffer[i] = -1; // Initialize to -1 to indicate an empty buffer
    }
}

// Function to add an element to the circular buffer
void circular_buffer_add(int *buffer, int index, int value) {
    buffer[index] = value;
}

// Function to get an element from the circular buffer
int circular_buffer_get(int *buffer, int index) {
    if (index < 0 || index >= BUFFER_SIZE) {
        fprintf(stderr, "Index out of bounds\n");
        return -1;
    }
    return buffer[index];
}

// Function to check if the circular buffer is full
int circular_buffer_is_full(int *buffer, int size) {
    return (buffer[0] == -1) ? 1 : 0;
}

// Function to check if the circular buffer is empty
int circular_buffer_is_empty(int *buffer, int size) {
    return (buffer[0] == -1) ? 1 : 0;
}

// Function to get the size of the circular buffer
int circular_buffer_get_size(int *buffer, int *size) {
    return (buffer[0] == -1) ? 0 : *size;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_init(log_buffer, BUFFER_SIZE);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up signal handler for cleanup
    signal(SIGTERM, cleanup);

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check for touch events
        if (sensor1_value == 1 && sensor2_value == 1) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY);

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            log_event(SENSOR1_PIN, sensor1_value);
            log_event(SENSOR2_PIN, sensor2_value);

            // Set LED state
            set_led(LED1_PIN, 1);
            set_led(LED2_PIN, 1);

            // Wait for a short period
            gpioDelay(50);

            // Turn off LEDs
            set_led(LED1_PIN, 0);
            set_led(LED2_PIN, 0);
        } else if (sensor1_value == 0 && sensor2_value == 0) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY);

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            log_event(SENSOR1_PIN, sensor1_value);
            log_event(SENSOR2_PIN, sensor2_value);

            // Set LED state
            set_led(LED1_PIN, 1);
            set_led(LED2_PIN, 1);

            // Wait for a short period
            gpioDelay(50);

            // Turn off LEDs
            set_led(LED1_PIN, 0);
            set_led(LED2_PIN, 0);
        } else {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY);
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

