#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 5

// Global variables
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int debounce_sensor(int gpio_pin, int *debounced_state);
int calculate_rpm(int sensor1_state, int sensor2_state);
void log_data(int rpm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initializes the pigpio library and sets the GPIO pins as inputs.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    return 0;
}

// Reads the state of the specified GPIO pin.
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Debounces the sensor state based on the debounce delay.
int debounce_sensor(int gpio_pin, int *debounced_state) {
    int current_state = gpioRead(gpio_pin);
    int delay_ms = DEBOUNCE_DELAY;

    gpioDelay(delay_ms * 1000); // Convert ms to microseconds

    if (current_state != debounced_state) {
        *debounced_state = current_state;
        return 1; // State changed
    } else {
        return 0; // State unchanged
    }
}

// Calculates the RPM based on the sensor states.
int calculate_rpm(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        return 0; // No rotation
    }

    // Assuming one rotation per second
    int rpm = (sensor1_state + sensor2_state) / 2;

    // Limit RPM to a reasonable range
    if (rpm > 1000) {
        rpm = 1000;
    } else if (rpm < 0) {
        rpm = 0;
    }

    return rpm;
}

// Logs the RPM and sensor states to a CSV file.
void log_data(int rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Monitoring RPM... Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_debounced = debounce_sensor(SENSOR1_PIN, &sensor1_state);
        int sensor2_debounced = debounce_sensor(SENSOR2_PIN, &sensor2_state);

        // Calculate RPM
        int rpm = calculate_rpm(sensor1_state, sensor2_state);

        // Log data
        log_data(rpm);

        // Print RPM to console
        printf("RPM: %d\n", rpm);

        // Delay to control the loop rate
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

