#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27

// Define constants
#define SENSOR_THRESHOLD_HIGH 2  // Seconds
#define SENSOR_THRESHOLD_LOW 0  // Seconds
#define ALARM_DURATION_HIGH 2    // Seconds
#define ALARM_DURATION_LOW 0     // Seconds

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, const char *timestamp);
void alarm_activate(int duration_secs);
void alarm_deactivate();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Log event to file
int log_event(const char *event_type, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s - %s - %s\n", timestamp, event_type, timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Activate alarm
void alarm_activate(int duration_secs) {
    gpioWrite(ALARM_PIN, 1); // Activate alarm
    gpioDelay(duration_secs * 1000000); // Delay for duration_secs
    alarm_deactivate();
}

// Deactivate alarm
void alarm_deactivate() {
    gpioWrite(ALARM_PIN, 0); // Deactivate alarm
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Log events
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (sensor1_value == 1) {
            log_event("Sensor1_Start", timestamp);
        } else if (sensor1_value == 0) {
            log_event("Sensor1_End", timestamp);
        }

        if (sensor2_value == 1) {
            log_event("Sensor2_Start", timestamp);
        } else if (sensor2_value == 0) {
            log_event("Sensor2_End", timestamp);
        }

        // Check for tilt events
        if (sensor1_value == 1 && sensor2_value == 1) {
            if (sensor1_value == 1 && sensor2_value == 1) {
                if (sensor1_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            } else if (sensor1_value == 1 && sensor2_value == 0) {
                if (sensor1_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            } else if (sensor1_value == 0 && sensor2_value == 1) {
                if (sensor1_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            } else if (sensor1_value == 0 && sensor2_value == 0) {
                if (sensor1_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    alarm_deactivate();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

