volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, const char *timestamp);
void alarm_activate(int duration_secs);
void alarm_deactivate();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Log event to file
int log_event(const char *event_type, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s - %s - %s\n", timestamp, event_type, timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Activate alarm
void alarm_activate(int duration_secs) {
    gpioWrite(ALARM_PIN, 1); // Activate alarm
    gpioDelay(duration_secs * 1000000); // Delay for duration_secs
    alarm_deactivate();
}

// Deactivate alarm
void alarm_deactivate() {
    gpioWrite(ALARM_PIN, 0); // Deactivate alarm
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

