            log_event("Sensor1_Start", timestamp);
        } else if (sensor1_value == 0) {
            log_event("Sensor1_End", timestamp);
        }

        if (sensor2_value == 1) {
            log_event("Sensor2_Start", timestamp);
        } else if (sensor2_value == 0) {
            log_event("Sensor2_End", timestamp);
        }

        // Check for tilt events
        if (sensor1_value == 1 && sensor2_value == 1) {
            if (sensor1_value == 1 && sensor2_value == 1) {
                if (sensor1_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            } else if (sensor1_value == 1 && sensor2_value == 0) {
                if (sensor1_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            } else if (sensor1_value == 0 && sensor2_value == 1) {
                if (sensor1_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 1) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            } else if (sensor1_value == 0 && sensor2_value == 0) {
                if (sensor1_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                } else if (sensor2_value == 0) {
                    alarm_activate(ALARM_DURATION_HIGH);
                }
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    alarm_deactivate();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

