// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int debounce_read(int pin);
int log_event(const char *sensor_id, int pin);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);
    gpioSetMode(SENSOR5_PIN, PI_INPUT);

    return 0;
}

// Function to read the digital value from a sensor pin
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to perform a debounce read
int debounce_read(int pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Wait for debounce delay
    return gpioRead(pin);
}

// Function to log an event to the log file
int log_event(const char *sensor_id, int pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor: %s, Pin: %d\n", timestamp, sensor_id, pin);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        syslog(LOG_ERR, "Log file not opened");
        return -1;
    }
}

