void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (sensor_ids != NULL) {
        free(sensor_ids);
    }
    syslog(LOG_INFO, "Cleanup complete");
}

