        // Log events
        if (sensor1_value != sensor1_debounced) {
            if (log_event("Sensor1", SENSOR1_PIN) != 0) {
                syslog(LOG_ERR, "Failed to log event for Sensor1");
            }
        }
        if (sensor2_value != sensor2_debounced) {
            if (log_event("Sensor2", SENSOR2_PIN) != 0) {
                syslog(LOG_ERR, "Failed to log event for Sensor2");
            }
        }
        if (sensor3_value != sensor3_debounced) {
            if (log_event("Sensor3", SENSOR3_PIN) != 0) {
                syslog(LOG_ERR, "Failed to log event for Sensor3");
