#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensors
#define SENSOR_1_PIN 5
#define SENSOR_2_PIN 6
#define SENSOR_3_PIN 13
#define SENSOR_4_PIN 19
#define SENSOR_5_PIN 26
#define SENSOR_6_PIN 12
#define SENSOR_7_PIN 16
#define SENSOR_8_PIN 20

// Define the number of sensors
#define NUM_SENSORS 8

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track the last touch state for each sensor
static int last_touch_states[NUM_SENSORS] = {0, 0, 0, 0, 0, 0, 0, 0};

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpioSetMode(SENSOR_1_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_1_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_2_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_2_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_3_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_3_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_4_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_4_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_5_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_5_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_6_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_6_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_7_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_7_PIN + i, PI_PUD_UP);
        gpioSetMode(SENSOR_8_PIN + i, PI_INPUT);
        gpioSetPullUpDown(SENSOR_8_PIN + i, PI_PUD_UP);
    }

    return 0; // Indicate success
}

// Function to read the state of a single touch sensor
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the sensor index and touch state
void log_touch_state(int sensor_index, int gpio_pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor %d (GPIO %d): %s\n", timestamp, sensor_index, gpio_pin, state ? "Touched" : "Released");
}

// Function to handle touch sensor events
void handle_touch_event(int sensor_index, int gpio_pin, int state) {
    if (state == 1) {
        last_touch_states[sensor_index] = gpio_pin;
        printf("Touch detected on sensor %d (GPIO %d)\n", sensor_index, gpio_pin);
    } else if (state == 0) {
        last_touch_states[sensor_index] = 0; // Reset state on release
        printf("Touch released on sensor %d (GPIO %d)\n", sensor_index, gpio_pin);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to read and log touch states
    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int gpio_pin = SENSOR_1_PIN + i;
            int current_state = read_touch_sensor(gpio_pin);

            if (current_state != last_touch_states[i]) {
                handle_touch_event(i, gpio_pin, current_state);
                last_touch_states[i] = current_state;
            }
        }

        gpioDelay(50); // Delay for 50ms
    }

    return 0;
}

