#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"
#define MAX_LUX_VALUE 2000
#define MAX_BRIGHTNESS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_veml7700(int i2c_handle, float *lux);
int map_lux_to_brightness(float lux);
int set_led_brightness(int gpio, int brightness);
int log_data(FILE *fp, float lux, int brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700 sensor
int read_veml7700(int i2c_handle, float *lux) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit lux value
    *lux = (float)((buf[0] << 8) | buf[1]) / 10.0; // Convert to lux

    return 0;
}

// Map lux value to brightness level
int map_lux_to_brightness(float lux) {
    if (lux < 0) {
        lux = 0;
    }
    if (lux > MAX_LUX_VALUE) {
        lux = MAX_LUX_VALUE;
    }
    return (int)((lux / MAX_LUX_VALUE) * MAX_BRIGHTNESS);
}

// Set LED brightness using PWM
int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(FILE *fp, float lux, int brightness) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, brightness) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    float lux;
    int brightness;
    int error_code;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_veml7700(i2c_handle, &lux) == 0) {
            // Map lux value to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            if (set_led_brightness(GPIO_LED, brightness) != 0) {
                fprintf(stderr, "Failed to set LED brightness\n");
            }

            // Log data
            if (log_data(log_file, lux, brightness) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1 second = 1000 milliseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

