#include <string.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_PIN_GPIO 17
#define LOG_FILE "fire_events.log"

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s - Flame detected!\n", timestamp);
    fclose(fp);
}

// Function to set the alert pin HIGH for 1 second
void set_alert_pin(int gpio) {
    gpioWrite(gpio, 1); // Set GPIO HIGH
    gpioDelay(1000000); // Wait for 1 second
    gpioWrite(gpio, 0); // Set GPIO LOW
}

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to handle the signal (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(ALERT_PIN_GPIO, 0); // Set alert pin LOW
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALERT_PIN_GPIO, PI_OUTPUT);

    // Set alert pin to LOW initially
    gpioWrite(ALERT_PIN_GPIO, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the flame sensor
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);

        // Get the timestamp
        char* timestamp = get_timestamp();

        // Log the event
        log_event(timestamp);

        // Check for flame detection
        if (flame_detected == 0) {
            // Set the alert pin HIGH
            set_alert_pin(ALERT_PIN_GPIO);

            // Wait for 1 second
            gpioDelay(1000000);

            // Set the alert pin LOW
            gpioWrite(ALERT_PIN_GPIO, 0);
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(500000); // 0.5 seconds
    }

    return 0;
}

