#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define LEFT_SENSOR_GPIO 17
#define MIDDLE_SENSOR_GPIO 27
#define RIGHT_SENSOR_GPIO 22

#define SAMPLE_INTERVAL_MS 50
#define CSV_FILE_NAME "path_log.csv"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int open_gpio(int gpio) {
    int chip = i2cOpen(1, 0x50, 0); // I2C bus 1, address 0x50, no flags
    if (chip < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", chip);
        return -1;
    }
    return chip;
}

int read_sensor(int gpio) {
    int value = i2cReadByteData(gpio, 0);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor from GPIO %d: %d\n", gpio, value);
        return -1;
    }
    return value;
}

int write_sensor(int gpio, int value) {
    int result = i2cWriteByteData(gpio, 0, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to sensor on GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

int log_data(FILE *fp, int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    FILE *fp = NULL;
    int left_value, middle_value, right_value;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    int chip = open_gpio(LEFT_SENSOR_GPIO);
    if (chip < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(chip);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,left,middle,right\n");
    }

    // Main loop
    while (program_running) {
        left_value = read_sensor(LEFT_SENSOR_GPIO);
        middle_value = read_sensor(MIDDLE_SENSOR_GPIO);
        right_value = read_sensor(RIGHT_SENSOR_GPIO);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensors, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        if (write_sensor(LEFT_SENSOR_GPIO, left_value) != 0) {
            fprintf(stderr, "Error writing to left sensor\n");
        }
        if (write_sensor(MIDDLE_SENSOR_GPIO, middle_value) != 0) {
            fprintf(stderr, "Error writing to middle sensor\n");
        }
        if (write_sensor(RIGHT_SENSOR_GPIO, right_value) != 0) {
            fprintf(stderr, "Error writing to right sensor\n");
        }

        if (log_data(fp, left_value, middle_value, right_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Wait for the next sample
    }

    // Cleanup
    fclose(fp);
    i2cClose(chip);
    gpioTerminate();

    return 0;
