#include <pigpio.h>

// Constants
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "touch_log.txt"
#define TIMEOUT_MS 1000
#define GPIO_CHIP "/dev/gpiochip4"

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_touch_sensor();
int toggle_led(int state);
int log_event(int state);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    int fd;
    struct spi_ioc_transfer tr;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    tr.tx_buf = (unsigned long)SPI_MODE_0;
    tr.rx_buf = NULL;
    tr.len = 0;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &tr.mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &tr.bits_per_word) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI mode and bits per word
    if (ioctl(fd, SPI_IOC_WR_MODE, &tr.mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &tr.bits_per_word) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return 0;
}

// Function to read touch sensor
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to toggle LED
int toggle_led(int state) {
    gpioWrite(LED_PIN, state);
    return state;
}

// Function to log event
int log_event(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - %s\n", timestamp, state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to cleanup resources
void cleanup() {
    running = 0;
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor, retrying in %dms...\n", TIMEOUT_MS);
            sleep(TIMEOUT_MS);
            continue;
        }

        if (touch_state == 1) {
            printf("Touch detected!\n");
            if (toggle_led(1) < 0) {
                fprintf(stderr, "Error toggling LED, retrying in %dms...\n", TIMEOUT_MS);
                sleep(TIMEOUT_MS);
                continue;
            }
            if (log_event(1) < 0) {
                fprintf(stderr, "Error logging event, retrying in %dms...\n", TIMEOUT_MS);
                sleep(TIMEOUT_MS);
                continue;
            }
            gpioDelay(TIMEOUT_MS); // Debounce
        } else if (touch_state == 0) {
            printf("No touch detected.\n");
        }

        gpioDelay(TIMEOUT_MS); // Short delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

