#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define BUZZER_DURATION_MS 2000
#define ALERT_LOG_FILE "alert_log.txt"
#define SOCKET_PORT 12345
#define SOCKET_IP "127.0.0.1"
#define SOCKET_IP_PORT 12345

// Global variables
static volatile int running = 1;
static int socket_fd = -1;

// Function prototypes
int initialize_gpio();
int initialize_socket();
int read_flame_sensor();
void activate_buzzer(int duration_ms);
void log_alert(const char *message);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    return 0;
}

// Initialize socket
int initialize_socket() {
    struct sockaddr_in server_addr;
    int sockfd;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SOCKET_PORT);
    if (inet_pton(AF_INET, SOCKET_IP, &server_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect failed");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Read flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate buzzer for a specified duration
void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Log alert to file
void log_alert(const char *message) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open alert log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio
    if (socket_fd != -1) {
        close(socket_fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize socket
    socket_fd = initialize_socket();
    if (socket_fd == -1) {
        cleanup();
        return 1;
    }

