    signal(SIGTERM, signal_handler);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Log sensor data
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        } else {
            log_sensor_data(1, sensor1_value);
            log_sensor_data(2, sensor2_value);
            log_sensor_data(3, sensor3_value);
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

