#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define HEART_RATE_REG 0x24
#define CONFIG_REG 0x2A
#define CONFIG_VALUE 0x01 // Example configuration value
#define NUM_SAMPLES 5
#define BPM_MIN 30
#define BPM_MAX 220
#define BPM_STEP 5
#define LOG_FILE "heart_rate.csv"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int bpm_min;
    int bpm_max;
    int bpm_step;
} sensor_config_t;

// Function prototypes
int init_i2c();
int read_heart_rate(int *heart_rate);
int apply_moving_average(int raw_heart_rate, int *filtered_heart_rate);
int validate_bpm(int filtered_heart_rate);
int write_config(int i2c_handle, int config_value);
int read_config(int i2c_handle, int *part_id, int *hw_rev);
int log_data(int heart_rate);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read heart rate from the sensor
int read_heart_rate(int *heart_rate) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading heart rate: %d\n", result);
        return -1;
    }

    *heart_rate = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to apply a moving average filter to the raw heart rate
int apply_moving_average(int raw_heart_rate, int *filtered_heart_rate) {
    int sum = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        sum += raw_heart_rate;
        raw_heart_rate += BPM_STEP;
        if (raw_heart_rate < BPM_MIN) raw_heart_rate = BPM_MIN;
        if (raw_heart_rate > BPM_MAX) raw_heart_rate = BPM_MAX;
    }
    *filtered_heart_rate = sum / NUM_SAMPLES;
    return 0;
}

// Function to validate the filtered heart rate
int validate_bpm(int filtered_heart_rate) {
    return (filtered_heart_rate >= BPM_MIN && filtered_heart_rate <= BPM_MAX);
}

// Function to write a configuration value to the sensor
int write_config(int i2c_handle, int config_value) {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = config_value;
    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing config value: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the PART_ID and HW_REV registers from the sensor
int read_config(int i2c_handle, int *part_id, int *hw_rev) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x2A, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading config: %d\n", result);
        return -1;
    }

    *part_id = (buf[0] << 8) | buf[1];
    *hw_rev = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to log the heart rate data to a file
int log_data(int heart_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, heart_rate);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int heart_rate;
    int filtered_heart_rate;
    int part_id;
    int hw_rev;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read heart rate
        if (read_heart_rate(&heart_rate) == 0) {
            // Apply moving average filter
            if (apply_moving_average(heart_rate, &filtered_heart_rate) == 0) {
                // Validate BPM
                if (validate_bpm(filtered_heart_rate)) {
                    // Write configuration
                    if (write_config(i2c_handle, CONFIG_VALUE) != 0) {
                        fprintf(stderr, "Error writing config value\n");
                    }

                    // Read config
                    if (read_config(i2c_handle, &part_id, &hw_rev) != 0) {
                        fprintf(stderr, "Error reading config\n");
                    }

                    // Log data
                    if (log_data(filtered_heart_rate) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }

                    printf("Heart rate: %d BPM, Part ID: %d, HW Rev: %d\n", filtered_heart_rate, part_id, hw_rev);
                } else {
                    fprintf(stderr, "Invalid BPM reading\n");
                }
            } else {
                fprintf(stderr, "Invalid heart rate reading\n");
            }
        } else {
            fprintf(stderr, "Error reading heart rate\n");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

