#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_handle;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpio_handle = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", FLAME_SENSOR_GPIO, gpio_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the GPIO value
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        // Check for falling edge
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Check for duplicate alerts
            if (strcmp(timestamp, log_file->f_name) != 0) {
                // Print message to console
                printf("%s FLAME DETECTED\n", timestamp);

                // Append timestamped message to log file
                fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
                fflush(log_file); // Ensure immediate write

                // Wait for 100ms
                gpioDelay(100000); // 100ms = 100000 microseconds
            }
        }

        // Delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

