#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_1 5
#define TOUCH_SENSOR_2 6
#define TOUCH_SENSOR_3 7
#define TOUCH_SENSOR_4 8
#define TOUCH_SENSOR_5 9
#define TOUCH_SENSOR_6 10
#define TOUCH_SENSOR_7 11
#define TOUCH_SENSOR_8 12

#define COUNTER_GPIO 17
#define COUNTER_BITS 8

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

#define LOG_FILE "touch_log.txt"

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static int counter_value = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_touch_sensor(int gpio_pin);
int initialize_counter();
void update_counter(int counter_value);
void log_event(int channel, int counter_value);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_1, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_2, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_3, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_4, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_5, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_6, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_7, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_8, PI_INPUT);

    gpioSetMode(COUNTER_GPIO, PI_OUTPUT);
    gpioWrite(COUNTER_GPIO, 0); // Ensure counter is initially 0

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", SPI_DEVICE);
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", SPI_DEVICE);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read touch sensor
int read_touch_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

// Initialize counter
int initialize_counter() {
    gpioSetMode(COUNTER_GPIO, PI_OUTPUT);
    gpioWrite(COUNTER_GPIO, 0); // Ensure counter is initially 0
    return 0;
}

// Update counter value
void update_counter(int counter_value) {
    gpioWrite(COUNTER_GPIO, 1); // Set the counter pin high
    counter_value = counter_value ^ 0x80; // Toggle the counter pin
    gpioWrite(COUNTER_GPIO, 0); // Set the counter pin low
    gpioDelay(1); // Small delay to allow the counter to update
}

// Log event to file
void log_event(int channel, int counter_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s | Channel: %d | Counter: %d\n", timestamp, channel, counter_value);
    fclose(fp);
}

// Cleanup resources
void cleanup() {
    gpioWrite(COUNTER_GPIO, 0); // Ensure counter is 0
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Touch sensor counter program started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_value = read_touch_sensor(TOUCH_SENSOR_1);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor 1\n");
            continue; // Skip to the next sensor
        }

        int touch_value_2 = read_touch_sensor(TOUCH_SENSOR_2);
        int touch_value_3 = read_touch_sensor(TOUCH_SENSOR_3);
        int touch_value_4 = read_touch_sensor(TOUCH_SENSOR_4);
        int touch_value_5 = read_touch_sensor(TOUCH_SENSOR_5);
        int touch_value_6 = read_touch_sensor(TOUCH_SENSOR_6);
        int touch_value_7 = read_touch_sensor(TOUCH_SENSOR_7);
        int touch_value_8 = read_touch_sensor(TOUCH_SENSOR_8);

        if (touch_value_1 < 0 || touch_value_2 < 0 || touch_value_3 < 0 || touch_value_4 < 0 ||
            touch_value_5 < 0 || touch_value_6 < 0 || touch_value_7 < 0 || touch_value_8 < 0) {
            fprintf(stderr, "Error reading touch sensor, skipping this iteration\n");
            continue;
        }

        update_counter(touch_value_1);
        update_counter(touch_value_2);
        update_counter(touch_value_3);
        update_counter(touch_value_4);
        update_counter(touch_value_5);
        update_counter(touch_value_6);
        update_counter(touch_value_7);
        update_counter(touch_value_8);

        log_event(1, counter_value);
        log_event(2, counter_value);
        log_event(3, counter_value);
        log_event(4, counter_value);
        log_event(5, counter_value);
        log_event(6, counter_value);
        log_event(7, counter_value);
        log_event(8, counter_value);

        gpioDelay(100); // Delay for 100ms
    }

    cleanup();
    return 0;
}

