#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_WINDOW 50

// Global variables
static volatile int sensor1_state = 1; // Initialize to 1 (inactive)
static volatile int sensor2_state = 1;
static volatile int debounce_count = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor(int gpio);
void log_event(int sensor_number, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the sensor state
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the event to the log file
void log_event(int sensor_number, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up/down resistors
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Debounce logic
        if (sensor1_value == 1 && sensor1_state == 0) {
            debounce_count++;
            if (debounce_count >= DEBOUNCE_WINDOW) {
                sensor1_state = 1;
                debounce_count = 0;
                log_event(1, sensor1_state);
            }
        } else if (sensor1_value == 0 && sensor1_state == 1) {
            debounce_count = 0;
            sensor1_state = 0;
            log_event(1, sensor1_state);
        }

        if (sensor2_value == 1 && sensor2_state == 0) {
            debounce_count++;
            if (debounce_count >= DEBOUNCE_WINDOW) {
                sensor2_state = 1;
                debounce_count = 0;
                log_event(2, sensor2_state);
            }
        } else if (sensor2_value == 0 && sensor2_state == 1) {
            debounce_count = 0;
            sensor2_state = 0;
            log_event(2, sensor2_state);
        }

        gpioDelay(100); // Delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    fclose(log_file);
    return 0;
}

