// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_states(int left_state, int center_state, int right_state);
void cleanup(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Register the cleanup function to be called on exit
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop to read sensor states
    while (program_running) {
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int center_state = read_sensor(CENTER_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        log_sensor_states(left_state, center_state, right_state);

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    cleanup(0);
    return 0;
}

// Function to read the sensor state
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor states to the console
void log_sensor_states(int left_state, int center_state, int right_state) {
    printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);
}

// Cleanup function to be called on exit
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    program_running = 0; // Set the flag to exit the main loop
    gpioTerminate(); // Terminate the pigpio library
    exit(0);
}

