#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 2
#define MIDDLE_SENSOR_PIN 3
#define RIGHT_SENSOR_PIN 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl-C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    return 0;
}

// Function to read the digital value from a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor values to stdout
void log_sensor_values(int left_sensor_value, int middle_sensor_value, int right_sensor_value) {
    printf("L:%d M:%d R:%d\n", left_sensor_value, middle_sensor_value, right_sensor_value);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Sensor monitoring started. Press Ctrl-C to exit.\n");

    // Main loop to read and log sensor values
    while (program_running) {
        int left_sensor_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_sensor_value == -1 || middle_sensor_value == -1 || right_sensor_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break; // Exit the loop if any sensor reading fails
        }

        log_sensor_values(left_sensor_value, middle_sensor_value, right_sensor_value);

        gpioDelay(100); // Wait 100 milliseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

