#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensors
#define TOUCH_SENSOR_1_PIN 5
#define TOUCH_SENSOR_2_PIN 6
#define TOUCH_SENSOR_3_PIN 13
#define TOUCH_SENSOR_4_PIN 19
#define TOUCH_SENSOR_5_PIN 26
#define TOUCH_SENSOR_6_PIN 12
#define TOUCH_SENSOR_7_PIN 16
#define TOUCH_SENSOR_8_PIN 20

// Global variable to track the last timestamp
time_t last_timestamp = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read the touch sensor state
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to get the current timestamp
void get_timestamp(time_t *timestamp) {
    struct tm *timeinfo;
    timeinfo = localtime(timestamp);
    if (timeinfo == NULL) {
        perror("localtime");
        exit(1);
    }
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    *timestamp = time(NULL);
}

// Function to format the output string
char* format_output(int touch_state1, int touch_state2, int touch_state3, int touch_state4, int touch_state5, int touch_state6, int touch_state7, int touch_state8) {
    char *output = (char*)malloc(256 * sizeof(char));
    if (output == NULL) {
        perror("malloc");
        exit(1);
    }
    snprintf(output, 256, "[%lds] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
             last_timestamp, touch_state1, touch_state2, touch_state3, touch_state4, touch_state5, touch_state6, touch_state7, touch_state8);
    return output;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TOUCH_SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_4_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_5_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_6_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_7_PIN, PI_INPUT);
    gpioSetMode(TOUCH_SENSOR_8_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor polling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor states
        int touch_state1 = read_touch_sensor(TOUCH_SENSOR_1_PIN);
        int touch_state2 = read_touch_sensor(TOUCH_SENSOR_2_PIN);
        int touch_state3 = read_touch_sensor(TOUCH_SENSOR_3_PIN);
        int touch_state4 = read_touch_sensor(TOUCH_SENSOR_4_PIN);
        int touch_state5 = read_touch_sensor(TOUCH_SENSOR_5_PIN);
        int touch_state6 = read_touch_sensor(TOUCH_SENSOR_6_PIN);
        int touch_state7 = read_touch_sensor(TOUCH_SENSOR_7_PIN);
        int touch_state8 = read_touch_sensor(TOUCH_SENSOR_8_PIN);

        // Get the current timestamp
        get_timestamp(&last_timestamp);

        // Format the output string
        char *output = format_output(touch_state1, touch_state2, touch_state3, touch_state4, touch_state5, touch_state6, touch_state7, touch_state8);

        // Print the output to the console
        printf("%s\n", output);

        // Wait for 200 milliseconds
        gpioDelay(200);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    gpioTerminate();
    return 0;
}

