#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define PON_REG 0x01
#define AEN_REG 0x02
#define RGBC_REG 0x03
#define INT_TIME_MS 154
#define RED_THRESHOLD 200
#define GREEN_THRESHOLD 200
#define BLUE_THRESHOLD 200
#define LED_GPIO 17
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int configure_tcs34725();
int read_tcs34725(float *red, float *green, float *blue, float *clear);
void control_led(float red, float green, float blue, float clear);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Configures the TCS34725 sensor
int configure_tcs34725() {
    // Power on the sensor
    if (i2cWriteByteData(i2c_fd, PON_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing PON register\n");
        return -1;
    }

    // Enable RGBC mode
    if (i2cWriteByteData(i2c_fd, AEN_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing AEN register\n");
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_fd, RGBC_REG, (0x01 << 4) | (INT_TIME_MS << 2) | 0x01) < 0) {
        fprintf(stderr, "Error writing RGBC register\n");
        return -1;
    }

    return 0;
}

// Reads calibrated red, green, blue and clear values from the TCS34725
int read_tcs34725(float *red, float *green, float *blue, float *clear) {
    unsigned char data[6];
    int16_t red_raw, green_raw, blue_raw, clear_raw;
    int32_t red_calibrated, green_calibrated, blue_calibrated, clear_calibrated;

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_fd, RGBC_REG, (char *)data, 6) < 0) {
        fprintf(stderr, "Error reading RGBC data\n");
        return -1;
    }

    // Combine the bytes to form the raw values
    red_raw = (data[0] << 8) | data[1];
    green_raw = (data[2] << 8) | data[3];
    blue_raw = (data[4] << 8) | data[5];
    clear_raw = (data[6] << 8) | data[7];

    // Convert raw values to calibrated values
    red_calibrated = (int32_t)red_raw;
    green_calibrated = (int32_t)green_raw;
    blue_calibrated = (int32_t)blue_raw;
    clear_calibrated = (int32_t)clear_raw;

    // Calculate calibrated values
    *red = (float)red_calibrated / 16383.0f;
    *green = (float)green_calibrated / 16383.0f;
    *blue = (float)blue_calibrated / 16383.0f;
    *clear = (float)clear_calibrated / 16383.0f;

    return 0;
}

// Controls the LED based on the calibrated values
void control_led(float red, float green, float blue, float clear) {
    if (red > RED_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Configure TCS34725
    if (configure_tcs34725() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float red, green, blue, clear;
    float red_threshold, green_threshold, blue_threshold, clear_threshold;

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_tcs34725(&red, &green, &blue, &clear) == 0) {
            // Control LED
            control_led(red, green, blue, clear);

            // Print sensor values
            printf("Red: %.2f, Green: %.2f, Blue: %.2f, Clear: %.2f\n", red, green, blue, clear);

            // Calculate thresholds
            red_threshold = RED_THRESHOLD;
            green_threshold = GREEN_THRESHOLD;
            blue_threshold = BLUE_THRESHOLD;
            clear_threshold = CLEAR_THRESHOLD;

            // Check sensor values against thresholds
            if (red > red_threshold) {
                printf("Red threshold exceeded!\n");
            }
            if (green > green_threshold) {
                printf("Green threshold exceeded!\n");
            }
            if (blue > blue_threshold) {
                printf("Blue threshold exceeded!\n");
            }
            if (clear > clear_threshold) {
                printf("Clear threshold exceeded!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor values\n");
        }

        // Wait for 200ms
        gpioDelay(200);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

