#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_COMMAND 0x10
#define WS2812B_PIN 18
#define PWM_FREQUENCY 1000000 // 1 MHz
#define PWM_PERIOD 1000000 // 1 ms
#define LOG_BASE 10.0
#define LOG_SLOPE 0.1
#define LOG_INTERCEPT 0.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float lux;
    int error;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_bh1750(int *lux);
float calculate_logarithmic_brightness(int lux);
void set_ws2812b_timing(int pwm_frequency, int pwm_period);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(int *lux) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, BH1750_COMMAND, 0x10);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the lux value
    *lux = (buf[0] << 8) | buf[1];

    return 0;
}

// Calculate logarithmic brightness level
float calculate_logarithmic_brightness(int lux) {
    return LOG_BASE * pow(lux / LOG_BASE, LOG_SLOPE) + LOG_INTERCEPT;
}

// Set WS2812B PWM timing
void set_ws2812b_timing(int pwm_frequency, int pwm_period) {
    gpioSetPWMfrequency(WS2812B_PIN, pwm_frequency);
    gpioSetPWMperiod(WS2812B_PIN, pwm_period);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set WS2812B pin as output
    gpioSetMode(WS2812B_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int lux;
        if (read_bh1750(&lux) == 0) {
            // Calculate logarithmic brightness level
            float brightness = calculate_logarithmic_brightness(lux);

            // Set PWM timing
            set_ws2812b_timing(PWM_FREQUENCY, PWM_PERIOD);

            // Print lux value and brightness level
            printf("Lux: %d, Brightness: %.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 180ms
        gpioDelay(180000); // 180ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

