#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SPI_BUS "/dev/spidev0.0"
#define SPI_MODE SPI_MODE0
#define SPI_SPEED 1000000 // 1 MHz
#define APA102_LED_COUNT 32
#define LED_DATA_SIZE (APA102_LED_COUNT * 4) // Each LED frame is 4 bytes

// Global variables
int i2c_handle;
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold LED data
typedef struct {
    uint32_t zero_start;
    uint32_t led_frames[APA102_LED_COUNT];
} led_data_t;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(int i2c_handle, uint16_t *light_level);
int read_apb102_leds(int spi_handle, led_data_t *led_data);
void scale_led_data(led_data_t *led_data, uint32_t zero_start, uint32_t *led_frames);
void send_spi_data(uint32_t zero_start, uint32_t *led_frames, int led_count);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read light level from BH1750
int read_bh1750(int i2c_handle, uint16_t *light_level) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading BH1750: %s\n", strerror(errno));
        return -1;
    }

    *light_level = (buf[0] << 8) | buf[1];
    return 0;
}

// Read LED data from APA102
int read_apb102_leds(int spi_handle, led_data_t *led_data) {
    uint8_t frame[LED_DATA_SIZE];
    int result = spiRead(spi_handle, (char *)frame, LED_DATA_SIZE);
    if (result != LED_DATA_SIZE) {
        fprintf(stderr, "Error reading SPI data: %s\n", strerror(errno));
        return -1;
    }

    // Parse the frame data
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        led_data->led_frames[i] = (uint32_t)frame[i * 4];
    }

    return 0;
}

// Scale LED data
void scale_led_data(led_data_t *led_data, uint32_t zero_start, uint32_t *led_frames) {
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        led_data->led_frames[i] = (led_data->led_frames[i] - zero_start) / 255.0; // Scale to 0-1
    }
}

// Send SPI data to LED strip
void send_spi_data(uint32_t zero_start, uint32_t *led_frames, int led_count) {
    uint32_t frame[LED_DATA_SIZE];
    for (int i = 0; i < led_count; i++) {
        frame[i * 4] = led_frames[i];
    }

    // Send the frame
    if (spiWrite(spi_handle, (char *)frame, LED_DATA_SIZE) != LED_DATA_SIZE) {
        fprintf(stderr, "Error writing SPI data: %s\n", strerror(errno));
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t light_level;
        uint32_t led_frames[APA102_LED_COUNT];

        // Read light level
        if (read_bh1750(i2c_handle, &light_level) == 0) {
            // Read LED data
            if (read_apb102_leds(spi_handle, led_data_t) == 0) {
                // Scale LED data
                scale_led_data(led_data_t, light_level, led_frames);

                // Send SPI data
                send_spi_data(light_level, led_frames, APA102_LED_COUNT);
            } else {
                fprintf(stderr, "Error reading LED data\n");
            }
        } else {
            fprintf(stderr, "Error reading light level\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

