// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_DATA_MSB 0x00
#define VEML7700_ALS_DATA_LSB 0x01
#define VEML7700_ALS_DATA_XLSB 0x02

// WS2812B GPIO pin (BCM)
#define WS2812B_PIN 18

// Gamma correction factor (adjust as needed)
#define GAMMA 2.2

// I2C file descriptor
int i2c_fd;

// Flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a byte from the VEML7700
int read_veml7700_byte(int fd) {
    int data = wiringPiI2CReadReg8(fd, VEML7700_ALS_DATA_MSB);
    if (data < 0) {
        fprintf(stderr, "Error reading byte from I2C: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return data;
}

// Function to read a word (2 bytes) from the VEML7700
int read_veml7700_word(int fd) {
    int data = wiringPiI2CReadReg8(fd, VEML7700_ALS_DATA_MSB);
    if (data < 0) {
        fprintf(stderr, "Error reading word from I2C: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    data = wiringPiI2CReadReg8(fd, VEML7700_ALS_DATA_LSB);
    if (data < 0) {
        fprintf(stderr, "Error reading word from I2C: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    data = wiringPiI2CReadReg8(fd, VEML7700_ALS_DATA_XLSB);
    if (data < 0) {
        fprintf(stderr, "Error reading word from I2C: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return (data << 8) | (data >> 8); // Combine MSB and LSB
}

// Function to calculate the lux value from the raw data
float calculate_lux(int raw_data) {
    // Simple linear scaling (adjust as needed)
    float lux = (float)raw_data / 0.1; // Example scaling factor
    return lux;
}

// Function to convert raw data to brightness level (0-255)
int calculate_brightness(float lux) {
    // Gamma correction
    float brightness = (float)raw_data / 0.1; // Example scaling factor
    return (int)(brightness * GAMMA);
}

// Function to set the WS2812B LED strip
void set_led_strip(int pin, int brightness) {
    digitalWrite(pin, brightness);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(VEML7700_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Set WS2812B pin as output
    pinMode(WS2812B_PIN, OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VEML7700 and WS2812B LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read raw data from VEML7700
        int raw_data = read_veml7700_word(i2c_fd);
        if (raw_data == -1) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Calculate lux value
        float lux = calculate_lux(raw_data);

        // Calculate brightness level
        int brightness = calculate_brightness(lux);

        // Set LED strip
        set_led_strip(WS2812B_PIN, brightness);

        // Print lux and brightness value
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay for 200ms
        delay(200);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_led_strip(WS2812B_PIN, 0); // Turn off LED strip
    close(i2c_fd);

    return 0;
}

