void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to control the LED with buzzer
void control_led_with_buzzer(int state) {
    control_led(state);
    control_buzzer(state);
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s\n", timestamp, event);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistors (optional, but recommended)
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Flame sensor self-test started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Check for persistent LOW
        if (flame_detected == 0 && program_running) {
            printf("Flame detected!\n");
            log_event("Flame detected");
            control_led_with_buzzer(1); // Turn on LED and buzzer
            gpioDelay(500); // Wait 500ms
            control_led_with_buzzer(0); // Turn off LED and buzzer
            gpioDelay(500); // Wait 500ms
            log_event("Flame cleared");
        }

        // Read flame sensor again
        int new_flame_detected = read_flame_sensor();

        // Check for persistent LOW after initial read
        if (new_flame_detected == 0 && program_running) {
            printf("Flame detected!\n");
            log_event("Flame detected");
            control_led_with_buzzer(1); // Turn on LED and buzzer
            gpioDelay(500); // Wait 500ms
            control_led_with_buzzer(0); // Turn off LED and buzzer
            gpioDelay(500); // Wait 500ms
            log_event("Flame cleared");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup GPIO lines before exiting
    gpioTerminate();

    return 0;
}

