#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define LUX_THRESHOLD 1000
#define LUX_MAX_VALUE 2000
#define BUFFER_SIZE 60
#define LED_ON_DURATION_MS 500
#define LED_OFF_DURATION_MS 500
#define FREQUENCY_MIN_HZ 0.5
#define FREQUENCY_MAX_HZ 5.0
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_COUNT 60

// Global variables
static int i2c_fd = -1;
static int led_state = 0; // 0 = off, 1 = on
static int lux_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_bh1750(int fd);
float calculate_average_lux(int *buffer, int buffer_size);
void blink_led(int duration_ms);
void signal_handler(int signal);

// Function to read data from BH1750 sensor
int read_bh1750(int fd) {
    uint8_t cmd = 0x10; // High resolution mode, clock output pin tied to VCC
    uint8_t data[2];
    int result;

    result = i2c_smbus_write_byte_data(fd, 0x00, cmd);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait for measurement (at least 10ms)

    result = i2c_smbus_read_i2c_block_data(fd, 0x00, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to calculate the average lux from the circular buffer
float calculate_average_lux(int *buffer, int buffer_size) {
    if (buffer_size == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    return sum / buffer_size;
}

// Function to blink the LED
void blink_led(int duration_ms) {
    if (led_state == 0) {
        led_state = 1;
        gpioWrite(LED_GPIO, 1); // Turn LED on
        usleep(duration_ms * 1000); // Delay in microseconds
        led_state = 0;
        gpioWrite(LED_GPIO, 0); // Turn LED off
        usleep(duration_ms * 1000); // Delay in microseconds
    }
}

// Signal handler for Ctrl-C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int lux;
    float average_lux;
    int i;

    // Register signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
