#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define LED blink period
#define BLINK_PERIOD_MS 1000

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_init();
int gpio_set_output(int pin, int value);
int gpio_set_input(int pin, int pull_up);
int gpio_get_input(int pin);
int gpio_request_line(int pin, int pull_up);
int gpio_release_line(int pin);
int gpio_request_chip();
int gpio_release_chip();
void blink_led(int pin);
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Initialize GPIO
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Request LED line
    if (gpio_request_line(LED_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to request LED line\n");
        gpioTerminate();
        return 1;
    }

    // Request button line
    if (gpio_request_line(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to request button line\n");
        gpioTerminate();
        return 1;
    }

    // Request chip
    if (gpio_request_chip() != 0) {
        fprintf(stderr, "Failed to request chip\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Set GPIO pin output
int gpio_set_output(int pin, int value) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", pin);
        return 1;
    }
    gpioWrite(pin, value);
    return 0;
}

// Set GPIO pin input with pull-up resistor
int gpio_set_input(int pin, int pull_up) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", pin);
        return 1;
    }
    if (gpioSetPullUpDown(pin, pull_up) != 0) {
        fprintf(stderr, "Failed to set pull-up for pin %d\n", pin);
        return 1;
    }
    return 0;
}

// Get GPIO pin value
int gpio_get_input(int pin) {
    return gpioRead(pin);
}

// Request GPIO line for output
int gpio_request_line(int pin, int pull_up) {
    if (gpio_set_output(pin, 0) != 0) {
        fprintf(stderr, "Failed to set output for pin %d\n", pin);
        return 1;
    }
    return gpio_request_line(pin, pull_up);
}

// Release GPIO line
int gpio_release_line(int pin) {
    if (gpio_set_output(pin, 0) != 0) {
        fprintf(stderr, "Failed to set output for pin %d\n", pin);
        return 1;
    }
    return gpio_release_line(pin);
}

// Request GPIO chip
int gpio_request_chip() {
    if (gpio_request_line(0, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to request chip\n");
        return 1;
    }
    return 0;
}

// Release GPIO chip
int gpio_release_chip() {
    if (gpio_release_line(0) != 0) {
        fprintf(stderr, "Failed to release chip\n");
        return 1;
    }
    return 0;
}

// Blink LED
void blink_led(int pin) {
    int i;
    for (i = 0; i < 2; i++) {
        gpio_set_output(pin, 1);
        gpioDelay(BLINK_PERIOD_MS);
        gpio_set_output(pin, 0);
        gpioDelay(BLINK_PERIOD_MS);
    }
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (falling edge)
        printf("Button pressed!\n");
        blink_led(LED_PIN);
        gpioDelay(500); // Debounce delay
        gpio_set_input(BUTTON_PIN, PI_PUD_UP); // Reset pull-up
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        return 1;
    }

    // Set up callback for button press
    if (gpioSetAlertFuncEx(BUTTON_PIN, button_callback, 0) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup
    gpio_release_chip();
    gpioTerminate();

    return 0;
}

