// Function to turn the LED on
void led_on(int gpio) {
    gpioWrite(gpio, 1);
}

// Function to turn the LED off
void led_off(int gpio) {
    gpioWrite(gpio, 0);
}

// Function to blink the LED
void blink_led(int gpio, int on_time_ms, int off_time_ms) {
    gpioDelay(on_time_ms * 1000); // Convert ms to microseconds
    led_on(gpio);
    gpioDelay(off_time_ms * 1000); // Convert ms to microseconds
    led_off(gpio);
