#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1D

// LSM303DLHC registers
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact interrupt
#define GPIO_PIN 17

// Impact threshold (G-force)
#define IMPACT_THRESHOLD 2.0

// Impact log file
#define IMPACT_LOG_FILE "impact_log.txt"

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float compute_magnitude(int16_t x, int16_t y, int16_t z);
void handle_impact_interrupt();
void log_impact_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is initially LOW
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Compute magnitude of acceleration
float compute_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Handle impact interrupt
void handle_impact_interrupt() {
    gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
    gpioDelay(50000);       // Wait for 50ms
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    gpioDelay(50000);       // Wait for 50ms
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    gpioDelay(50000);       // Wait for 50ms
}

// Log impact data to file
void log_impact_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t impact_threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(IMPACT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    float magnitude;
    int16_t raw_x, raw_y, raw_z;

    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Compute magnitude
            magnitude = compute_magnitude(raw_x, raw_y, raw_z);

            // Check impact threshold
            if (magnitude > impact_threshold) {
                printf("Impact detected!\n");
                handle_impact_interrupt();
                log_impact_data(raw_x, raw_y, raw_z);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is LOW before exiting
    gpioTerminate();
    fclose(log_file);

    return 0;
}

