#define L3G4200D_CTRL_REG1 0x20
#define L3G4200D_OUT_X_L 0x28
#define L3G4200D_OUT_X_H 0x29
#define L3G4200D_OUT_Y_L 0x2A
#define L3G4200D_OUT_Y_H 0x2B
#define L3G4200D_OUT_Z_L 0x2C
#define L3G4200D_OUT_Z_H 0x2D

// Gyroscope Calibration Parameters
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0

// I2C Bus and Address
#define I2C_BUS 1
#define GYRO_ADDRESS 0x6B

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int initialize_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void apply_offsets(int16_t raw_data, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void check_gyro_absence();
void signal_handler(int signal);

// Function to initialize the gyroscope
int initialize_gyro() {
    // Initialize WHO_AM_I register
    if (i2cWriteByteData(i2c_handle, L3G4200D_WHO_AM_I, 0x00) < 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register\n");
        return -1;
    }

    // Set CTRL_REG1 to enable gyroscope and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, L3G4200D_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, L3G4200D_OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to apply gyroscope offsets
void apply_offsets(int16_t raw_data, float *x, float *y, float *z) {
    *x = raw_data - X_OFFSET;
    *y = raw_data - Y_OFFSET;
    *z = raw_data - Z_OFFSET;
}

