void check_gyro_absence() {
    int who_am_i = i2cReadByteData(i2c_handle, L3G4200D_WHO_AM_I);
    if (who_am_i != 0x00) {
        fprintf(stderr, "Gyroscope absence detected. WHO_AM_I: 0x%02X\n", who_am_i);
        program_running = 0; // Stop the program if gyroscope is absent
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

