// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// GPIO pin for LED
#define LED_PIN 17

// Acceleration threshold (g)
#define ACCELERATION_THRESHOLD 2.0

// I2C bus
#define I2C_BUS 1

// File to log data to
#define LOG_FILE "accel_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_adxl345();
int read_acceleration(accelerometer_data_t *data);
int verify_device_id();
int log_data(accelerometer_data_t data);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize ADXL345
int init_adxl345() {
    // Power on the ADXL345
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    return 0;
}

