#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define OUT_X_L_M 0x22
#define OUT_X_H_M 0x23
#define OUT_Y_L_M 0x24
#define OUT_Y_H_M 0x25
#define OUT_Z_L_M 0x26
#define OUT_Z_H_M 0x27
#define OUT_X_L_P 0x2E
#define OUT_X_H_P 0x2F
#define OUT_Y_L_P 0x30
#define OUT_Y_H_P 0x31
#define OUT_Z_L_P 0x32
#define OUT_Z_H_P 0x33

// LSM303DLHC configuration
#define ACCEL_FS_2G 0x08
#define MAG_FS_4T 0x08
#define ACCEL_DATA_FORMAT_LSM303DLHC 0x00
#define MAG_DATA_FORMAT_LSM303DLHC 0x00

// Tilt-compensated heading calculation
#define PI 3.14159265358979323846

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_accel();
int init_mag();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
int read_mag_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y, int16_t z);
int log_data(float heading, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return -1;
    }

    // Set accelerometer to +/- 2g range and enable full-scale measurement
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, ACCEL_FS_2G) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return -1;
    }

    // Set magnetometer to +/- 4t range and enable full-scale measurement
    if (i2cWriteByteData(i2c_handle_mag, CTRL_REG4_A, MAG_FS_4T) < 0) {
        fprintf(stderr, "Failed to write to magnetometer CTRL_REG4_A\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize accelerometer
int init_accel() {
    // Set accelerometer to continuous measurement mode
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, ACCEL_DATA_FORMAT_LSM303DLHC) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_mag() {
    // Set magnetometer to continuous measurement mode
    if (i2cWriteByteData(i2c_handle_mag, CTRL_REG4_A, MAG_DATA_FORMAT_LSM303DLHC) < 0) {
        fprintf(stderr, "Failed to write to magnetometer CTRL_REG4_A\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_M, buf, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Read magnetometer data
int read_mag_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_L_M, buf, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2(y, sqrt(x * x + z * z)) * 180 / PI;
    return heading;
}

// Log data to file
int log_data(float heading, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize accelerometer and magnetometer
    if (init_accel() < 0 || init_mag() < 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) < 0 ||
            read_mag_data(&mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(accel_x, accel_y, accel_z);

        // Log data
        if (log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Close I2C resources
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

