#define DISTANCE_REG 0x04
#define DISTANCE_THRESHOLD 100 // mm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl6180x();
int read_distance();
void log_distance(int distance);
void check_door_status(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL6180X sensor
int init_vl6180x() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // Reset command
        fprintf(stderr, "Error: Failed to reset VL6180X sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Set the sensor to continuous mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // Continuous mode command
        fprintf(stderr, "Error: Failed to set VL6180X to continuous mode.\n");
        return -1;
    }
    gpioDelay(10);

    // Set the sensor to high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // High-resolution command
        fprintf(stderr, "Error: Failed to set VL6180X to high-resolution mode.\n");
        return -1;
    }
    gpioDelay(10);

    // Set the sensor to continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // Continuous high-resolution command
        fprintf(stderr, "Error: Failed to set VL6180X to continuous high-resolution mode.\n");
        return -1;
    }
    gpioDelay(10);

    return 0;
}

// Read the distance from the VL6180X sensor
int read_distance() {
    char buf[2];
    int distance;

    // Read the distance register (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance from VL6180X.\n");
        return -1;
    }

    distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Log the distance to a file
void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
}

// Check the door status and log the distance if necessary
void check_door_status(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        log_distance(distance);
        printf("DOOR_OPEN\n");
    } else {
        printf("DOOR_CLOSED\n");
    }
}

