    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    if (init_vl6180x() != 0) {
        fprintf(stderr, "Error: VL6180X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            check_door_status(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

