#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_RATE_MS 10
#define LOG_FILE "audio_log.dat"
#define MAX_RETRIES 3

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    int sensor_id;
    int16_t *buffer;
    int buffer_size;
    int16_t *last_buffer;
    int last_buffer_size;
    int running;
} sensor_t;

// Global variables
sensor_t sensors[2];
int running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_sensor(sensor_t *sensor);
int read_sensor_data(sensor_t *sensor, int16_t *buffer, int buffer_size);
int process_sensor_data(sensor_t *sensor, int16_t *buffer, int16_t *last_buffer, int buffer_size, int16_t *last_buffer_data);
int calculate_tdoa(int16_t *buffer1, int16_t *buffer2, int16_t *last_buffer, int buffer_size, int16_t *last_buffer_data);
int log_data(sensor_t *sensor, int16_t *buffer, int16_t *last_buffer, int buffer_size, int16_t *last_buffer_data, int tdoa);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize a sensor
int initialize_sensor(sensor_t *sensor) {
    sensor->handle = i2cOpen(I2C_BUS, sensor->address, 0);
    if (sensor->handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", sensor->address, sensor->handle);
        return -1;
    }

    sensor->sensor_id = sensor->address;
    sensor->buffer = (int16_t *)malloc(sensor->buffer_size * sizeof(int16_t));
    if (sensor->buffer == NULL) {
        fprintf(stderr, "Error allocating memory for sensor buffer\n");
        i2cClose(sensor->handle);
        return -1;
    }

    sensor->last_buffer = (int16_t *)malloc(sensor->buffer_size * sizeof(int16_t));
    if (sensor->last_buffer == NULL) {
        fprintf(stderr, "Error allocating memory for last buffer\n");
        free(sensor->buffer);
        i2cClose(sensor->handle);
        return -1;
    }

    sensor->last_buffer_size = sensor->buffer_size;
    sensor->running = 1;

    return 0;
}

// Read data from a sensor
int read_sensor_data(sensor_t *sensor, int16_t *buffer, int buffer_size) {
    if (sensor->running) {
        char buf[sensor->buffer_size];
        int bytes_read = i2cReadI2CBlockData(sensor->handle, 0, buf, sensor->buffer_size);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
            return -1;
        }

        for (int i = 0; i < bytes_read; i++) {
            buffer[i] = (int16_t)buf[i];
        }
    } else {
        fprintf(stderr, "Sensor is not running.  Attempting to re-initialize.\n");
        i2cClose(sensor->handle);
        sensor->running = 1;
        if (initialize_sensor(sensor) != 0) {
            fprintf(stderr, "Failed to re-initialize sensor.\n");
            return -1;
        }
    }
    return 0;
}

// Process sensor data (convert to signed 16-bit integers)
int process_sensor_data(sensor_t *sensor, int16_t *buffer, int16_t *last_buffer, int buffer_size, int16_t *last_buffer_data) {
    for (int i = 0; i < buffer_size; i++) {
        buffer[i] = (int16_t)buffer[i];
    }
    for (int i = 0; i < buffer_size; i++) {
        last_buffer[i] = last_buffer_data[i];
    }
    return 0;
}

// Calculate TDOA
int calculate_tdoa(int16_t *buffer1, int16_t *buffer2, int16_t *last_buffer, int buffer_size, int16_t *last_buffer_data) {
    int16_t diff1 = 0, diff2 = 0;
    for (int i = 0; i < buffer_size; i++) {
        diff1 += buffer1[i] - last_buffer[i];
        diff2 += buffer2[i] - last_buffer[i];
    }
    int sum1 = diff1 / buffer_size;
    int sum2 = diff2 / buffer_size;
    int tdoa = (sum1 + sum2) / 2;
    return tdoa;
}

// Log data to file
int log_data(sensor_t *sensor, int16_t *buffer, int16_t *last_buffer, int buffer_size, int16_t *last_buffer_data, int tdoa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n",
            timestamp, sensor->sensor_id, buffer[0], buffer[1], buffer[2], buffer[3], tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize sensors
    sensors[0].sensor_id = SENSOR1_ADDR;
    sensors[0].address = SENSOR1_ADDR;
    sensors[0].running = 1;
    sensors[0].handle = i2cOpen(I2C_BUS, sensors[0].address, 0);
    if (sensors[0].handle < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1 at address 0x%02X: %d\n", sensors[0].address, sensors[0].handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    sensors[1].sensor_id = SENSOR2_ADDR;
    sensors[1].address = SENSOR2_ADDR;
    sensors[1].running = 1;
    sensors[1].handle = i2cOpen(I2C_BUS, sensors[1].address, 0);
    if (sensors[1].handle < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2 at address 0x%02X: %d\n", sensors[1].address, sensors[1].handle);
        i2cClose(sensors[0].handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(&sensors[0]) != 0 || initialize_sensor(&sensors[1]) != 0) {
        fprintf(stderr, "Failed to initialize one or more sensors.\n");
        i2cClose(sensors[0].handle);
        i2cClose(sensors[1].handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int16_t buffer1[16], buffer2[16];
        int16_t last_buffer1[16], last_buffer2[16];
        int16_t buffer1_data[16], buffer2_data[16];
        int16_t last_buffer1_data[16], last_buffer2_data[16];
        int buffer1_size, buffer2_size, last_buffer1_size, last_buffer2_size;
        int buffer1_index, buffer2_index, last_buffer1_index, last_buffer2_index;
        int tdoa;

        // Read sensor data
        if (read_sensor_data(&sensors[0], buffer1, 16) != 0 ||
            read_sensor_data(&sensors[1], buffer2, 16) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process sensor data
        if (process_sensor_data(&sensors[0], buffer1, buffer1_data, 16, &last_buffer1_data[0]) != 0 ||
            process_sensor_data(&sensors[1], buffer2, buffer2_data, 16, &last_buffer2_data[0]) != 0) {
            fprintf(stderr, "Error processing sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(buffer1_data, buffer2_data, last_buffer1_data, 16, &last_buffer1_data[0]);

        // Log data
        if (log_data(&sensors[0], buffer1, buffer1_data, 16, &last_buffer1_data[0], tdoa) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        if (log_data(&sensors[1], buffer2, buffer2_data, 16, &last_buffer2_data[0], tdoa) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(sensors[0].handle);
    i2cClose(sensors[1].handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

