#include <pigpio.h>

// ADIS16488A Register Map
#define ADIS16488A_REG_GYRO_X_OUT 0x00
#define ADIS16488A_REG_GYRO_Y_OUT 0x02
#define ADIS16488A_REG_GYRO_Z_OUT 0x04
#define ADIS16488A_REG_ACCEL_X_OUT 0x06
#define ADIS16488A_REG_ACCEL_Y_OUT 0x08
#define ADIS16488A_REG_ACCEL_Z_OUT 0x0A
#define ADIS16488A_REG_CTRL_REG1 0x0E
#define ADIS16488A_REG_CTRL_REG2 0x10
#define ADIS16488A_REG_CTRL_REG3 0x12
#define ADIS16488A_REG_CTRL_REG4 0x14
#define ADIS16488A_REG_CTRL_REG5 0x16
#define ADIS16488A_REG_CTRL_REG6 0x18
#define ADIS16488A_REG_CTRL_REG7 0x1A
#define ADIS16488A_REG_STATUS 0x20
#define ADIS16488A_REG_FIFO_DATA 0x22

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CS 8

// Gyroscope Sensitivity
#define GYRO_SENSITIVITY 0.005

// Accelerometer Sensitivity
#define ACCEL_SENSITIVITY 0.00025

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int read_gyro_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z);
int read_accel_data(int handle, float *accel_x, float *accel_y, float *accel_z);
void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int spi_handle);
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[0];
    return 0;
}

// Function to write a register to the ADIS16488A
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z) {
    uint16_t gyro_data;
    if (spi_read_register(handle, ADIS16488A_REG_GYRO_X_OUT, &gyro_data) != 0) {
        fprintf(stderr, "Failed to read gyro X data\n");
        return -1;
    }

    *gyro_x = (float)gyro_data * GYRO_SENSITIVITY;
    *gyro_y = (float)gyro_data * GYRO_SENSITIVITY;
    *gyro_z = (float)gyro_data * GYRO_SENSITIVITY;

    return 0;
}

