        fprintf(stderr, "Failed to read accel X data\n");
        return -1;
    }

    *accel_x = (float)accel_data * ACCEL_SENSITIVITY;
    *accel_y = (float)accel_data * ACCEL_SENSITIVITY;
    *accel_z = (float)accel_data * ACCEL_SENSITIVITY;

    return 0;
}

