    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Function to perform cleanup and close the SPI handle
void cleanup(int spi_handle) {
    printf("Cleaning up and closing SPI...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    fclose(fp);
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        cleanup(spi_handle);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    time_t last_read_time = 0;

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Read accelerometer data
            if (read_accel_data(spi_handle, &accel_x, &accel_y, &accel_z) == 0) {
                // Get current timestamp
                time_t current_time = time(NULL);

                // Check if enough time has passed since the last read
                if (difftime(current_time, last_read_time) >= 0.04) { // 40 µs
                    // Log the data
                    log_data(fp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
                    last_read_time = current_time;
                }
            } else {
                fprintf(stderr, "Failed to read accelerometer data\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup(spi_handle);
    return 0;
