int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the pigpio library and SPI
int initialize_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read a single register from the ADIS16448
int read_register(int reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = 0x80 | (reg_addr & 0x7F); // Single-register read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return (rx_buf[1] << 8) | rx_buf[0];
}

// Function to read gyroscope and accelerometer data
int read_gyro_accel_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    int16_t gyro_x_raw = read_register(ADIS16448_GYRO_X_OUT);
    int16_t gyro_y_raw = read_register(ADIS16448_GYRO_Y_OUT);
    int16_t gyro_z_raw = read_register(ADIS16448_GYRO_Z_OUT);
    int16_t accel_x_raw = read_register(ADIS16448_ACCEL_X_OUT);
    int16_t accel_y_raw = read_register(ADIS16448_ACCEL_Y_OUT);
    int16_t accel_z_raw = read_register(ADIS16448_ACCEL_Z_OUT);

    if (gyro_x_raw == -1 || gyro_y_raw == -1 || gyro_z_raw == -1 || accel_x_raw == -1 || accel_y_raw == -1 || accel_z_raw == -1) {
        return -1;
    }

    *gyro_x = (int16_t)((gyro_x_raw & 0x7FFF) >> 1); // Sign extend
    *gyro_y = (int16_t)((gyro_y_raw & 0x7FFF) >> 1);
    *gyro_z = (int16_t)((gyro_z_raw & 0x7FFF) >> 1);
    *accel_x = (int16_t)((accel_x_raw & 0x7FFF) >> 1);
    *accel_y = (int16_t)((accel_y_raw & 0x7FFF) >> 1);
    *accel_z = (int16_t)((accel_z_raw & 0x7FFF) >> 1);

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data * GYRO_SCALE;
}

// Function to convert raw data to g's
float convert_to_g(int16_t raw_data) {
    return (float)raw_data * ACCEL_SCALE;
}

// Function to log the data to the console
void log_data(float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    printf("Gyro X: %.2f, Gyro Y: %.2f, Gyro Z: %.2f, Accel X: %.2f, Accel Y: %.2f, Accel Z: %.2f\n",
           gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope and accelerometer data
        if (read_gyro_accel_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            // Convert raw data to degrees per second and g's
            float gyro_x_degrees_per_second = convert_to_degrees_per_second(gyro_x);
            float gyro_y_degrees_per_second = convert_to_degrees_per_second(gyro_y);
            float gyro_z_degrees_per_second = convert_to_degrees_per_second(gyro_z);
            float accel_x_g = convert_to_g(accel_x);
            float accel_y_g = convert_to_g(accel_y);
            float accel_z_g = convert_to_g(accel_z);

            // Log the data
            log_data(gyro_x_degrees_per_second, gyro_y_degrees_per_second, gyro_z_degrees_per_second, accel_x_g, accel_y_g, accel_z_g);
        } else {
            fprintf(stderr, "Failed to read gyro and accel data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close SPI device
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

