#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define MPU6886_REG_ACCEL_XOUT_H 0x3B
#define MPU6886_REG_GYRO_XOUT_H 0x43

// Scaling factors (adjust based on your sensor's configuration)
#define ACCEL_SCALE 16384.0f // 16384 LSB/g
#define GYRO_SCALE 131.0f   // 131 LSB/deg/s

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a 16-bit value from the MPU-6886
int read_mpu6886_register(int handle, int reg) {
    int value = i2cReadWordData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to read accelerometer data
int read_accelerometer_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    int16_t accel_x_raw, accel_y_raw, accel_z_raw;

    accel_x_raw = read_mpu6886_register(handle, MPU6886_REG_ACCEL_XOUT_H);
    if (accel_x_raw < 0) return -1;
    accel_x_raw = (accel_x_raw << 8) | (accel_x_raw >> 8); // Combine MSB and LSB

    accel_y_raw = read_mpu6886_register(handle, MPU6886_REG_ACCEL_XOUT_H + 1);
    if (accel_y_raw < 0) return -1;
    accel_y_raw = (accel_y_raw << 8) | (accel_y_raw >> 8);

    accel_z_raw = read_mpu6886_register(handle, MPU6886_REG_ACCEL_XOUT_H + 2);
    if (accel_z_raw < 0) return -1;
    accel_z_raw = (accel_z_raw << 8) | (accel_z_raw >> 8);

    *accel_x = (int16_t)(accel_x_raw >> 8);
    *accel_y = (int16_t)(accel_y_raw >> 8);
    *accel_z = (int16_t)(accel_z_raw >> 8);

    return 0;
}

// Function to read gyroscope data
int read_gyroscope_data(int handle, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    int gyro_x_raw, gyro_y_raw, gyro_z_raw;

    gyro_x_raw = read_mpu6886_register(handle, MPU6886_REG_GYRO_XOUT_H);
    if (gyro_x_raw < 0) return -1;
    gyro_x_raw = (gyro_x_raw << 8) | (gyro_x_raw >> 8); // Combine MSB and LSB

    gyro_y_raw = read_mpu6886_register(handle, MPU6886_REG_GYRO_XOUT_H + 1);
    if (gyro_y_raw < 0) return -1;
    gyro_y_raw = (gyro_y_raw << 8) | (gyro_y_raw >> 8);

    gyro_z_raw = read_mpu6886_register(handle, MPU6886_REG_GYRO_XOUT_H + 2);
    if (gyro_z_raw < 0) return -1;
    gyro_z_raw = (gyro_z_raw << 8) | (gyro_z_raw >> 8);

    *gyro_x = (int16_t)(gyro_x_raw >> 8);
    *gyro_y = (int16_t)(gyro_y_raw >> 8);
    *gyro_z = (int16_t)(gyro_z_raw >> 8);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read accelerometer data
        if (read_accelerometer_data(i2c_handle, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Accelerometer: X=%.2f g, Y=%.2f g, Z=%.2f g\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        // Read gyroscope data
        if (read_gyroscope_data(i2c_handle, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Gyroscope: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

