    accel_x_raw = read_mpu6886_register(handle, MPU6886_REG_ACCEL_XOUT_H);
    if (accel_x_raw < 0) return -1;
    accel_x_raw = (accel_x_raw << 8) | (accel_x_raw >> 8); // Combine MSB and LSB

