// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Interrupt pin
#define INT1_PIN 17

// GPIO pin for interrupt
#define INT1_GPIO_PIN 11

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.5

// File to log free-fall events
#define LOG_FILE "freefall_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int adxl345_init();
int read_register(int reg);
int write_register(int reg, int value);
int read_acceleration(float *x, float *y, float *z);
void handle_interrupt(int gpio, int level, uint32_t tick);
void log_event(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize the ADXL345
int adxl345_init() {
    // Set power control register to enable the sensor
    if (write_register(ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    // Set data format to full resolution
    if (write_register(ADXL345_REG_DATA_FORMAT, 0x08) != 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set data rate to 100 Hz
    if (write_register(ADXL345_REG_DATA_RATE, 0x08) != 0) {
        fprintf(stderr, "Error writing to DATA_RATE register\n");
        return -1;
    }

    return 0;
}

// Function to read a register from the ADXL345
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    return value;
}

// Function to write a register to the ADXL345
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X with value 0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = read_register(ADXL345_REG_DATAX0);
    x1 = read_register(ADXL345_REG_DATAX1);
    y0 = read_register(ADXL345_REG_DATAY0);
    y1 = read_register(ADXL345_REG_DATAY1);
    z0 = read_register(ADXL345_REG_DATAZ0);
    z1 = read_register(ADXL345_REG_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (float)((x1 << 8) | x0) / 16384.0f;
    *y = (float)((y1 << 8) | y0) / 16384.0f;
    *z = (float)((z1 << 8) | z0) / 16384.0f;

    return 0;
}

// Interrupt handler function
void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge interrupt
        uint32_t tick_diff = tick - gpio_read(INT1_GPIO_PIN);
        if (tick_diff > 0) {
            float x, y, z;
            if (read_acceleration(&x, &y, &z) == 0) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                log_event(x, y, z);
            }
        }
    }
}

// Function to log an event to the CSV file
void log_event(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(INT1_PIN, PI_INPUT);
    gpioSetPullUpDown(INT1_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    gpioSetAlertFuncEx(INT1_PIN, handle_interrupt, NULL);

    // Main loop
    while (program_running) {
        // Read acceleration data
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            // Free-fall detection
            if (fabs(x) > FREEFALL_THRESHOLD || fabs(y) > FREEFALL_THRESHOLD || fabs(z) > FREEFALL_THRESHOLD) {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log the event
                log_event(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

