#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR registers
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define OUTX_H_G 0x29
#define OUTX_H_XL 0x2A
#define OUTY_L_G 0x2B
#define OUTY_L_XL 0x2C
#define OUTY_H_G 0x2D
#define OUTY_H_XL 0x2E
#define OUTZ_L_G 0x2F
#define OUTZ_L_XL 0x30
#define OUTZ_H_G 0x31
#define OUTZ_H_XL 0x32

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE ±2.0
#define GYRO_RANGE ±250.0

// Fall detection parameters
#define FALL_THRESHOLD 0.2  // g
#define FALL_WINDOW 1.0    // s

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void fall_detection_state_machine(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the LSM6DSR sensor
int init_sensor() {
    // Set accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x70) < 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to ±250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x70) < 0) {
        fprintf(stderr, "Error setting gyroscope range\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[14];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buf, 14) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    raw_accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 14) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    raw_gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert raw data to g and dps
    data->accel_x = (float)raw_accel_x / ACCEL_RANGE;
    data->accel_y = (float)raw_accel_y / ACCEL_RANGE;
    data->accel_z = (float)raw_accel_z / ACCEL_RANGE;
    data->gyro_x = (float)raw_gyro_x / GYRO_RANGE;
    data->gyro_y = (float)raw_gyro_y / GYRO_RANGE;
    data->gyro_z = (float)raw_gyro_z / GYRO_RANGE;

    return 0;
}

// Log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

