// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the LSM6DSR sensor
int init_sensor() {
    // Set accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x70) < 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to ±250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x70) < 0) {
        fprintf(stderr, "Error setting gyroscope range\n");
        return -1;
    }

    return 0;
}

