int read_sensor_data(sensor_data_t *data) {
    char buf[14];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buf, 14) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    raw_accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 14) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
