    raw_gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert raw data to g and dps
    data->accel_x = (float)raw_accel_x / ACCEL_RANGE;
    data->accel_y = (float)raw_accel_y / ACCEL_RANGE;
    data->accel_z = (float)raw_accel_z / ACCEL_RANGE;
    data->gyro_x = (float)raw_gyro_x / GYRO_RANGE;
    data->gyro_y = (float)raw_gyro_y / GYRO_RANGE;
    data->gyro_z = (float)raw_gyro_z / GYRO_RANGE;

    return 0;
}

