#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define GYRO_ADDR 0x68
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x43
#define SENSITIVITY 114.285
#define SAMPLE_INTERVAL_MS 10
#define CSV_FILE "gyro_log.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int initialize_i2c();
int read_gyro_data(gyro_data_t *data);
void convert_to_degrees_per_second(int16_t raw_data, float *degrees_per_second);
void append_to_csv(const char *timestamp, float x, float y, float z);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_degrees_per_second(int16_t raw_data, float *degrees_per_second) {
    *degrees_per_second = (float)raw_data / SENSITIVITY;
}

// Append data to CSV file
void append_to_csv(const char *timestamp, float x, float y, float z) {
    fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

