#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to log the flame event to a file
int log_flame_event(int sensor_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s – Flame detected: %s\n", timestamp, (sensor_value == 0) ? "YES" : "NO");
    fclose(fp);
    return 0;
}

// Function to handle errors and exit
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    if (log_flame_event(-1) != 0) {
        fprintf(stderr, "Error logging flame event!\n");
    }
    gpioTerminate();
    exit(1);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        handle_error("GPIO initialization failed");
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) {
            printf("Flame detected!\n");
            if (log_flame_event(sensor_value) != 0) {
                handle_error("Failed to log flame event");
            }
        } else {
            printf("No flame detected.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Exiting gracefully.\n");
    return 0;
}

