#define Y_AXIS_REG 0x02

// Define the register address for the Z axis data
#define Z_AXIS_REG 0x04

// Define the number of axes (3)
#define NUM_AXES 3

// Define the number of samples to read (100ms)
#define SAMPLE_DURATION_MS 100

