        data.x = 0; // Set to 0 to avoid using uninitialized data
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine the two bytes for each axis into a 16-bit integer
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

