    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        sensor_data_t data = read_sensor_data();

        if (data.x != 0 || data.y != 0 || data.z != 0) {
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(SAMPLE_DURATION_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

