#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG2 0x21
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Scaling factors
#define SENSITIVITY 0.146  // mG/LSB
#define SCALE_FACTOR 0.1   // mG/LSB

// I2C bus
#define I2C_BUS 1

// File name for logging
#define LOG_FILE "magnetic_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_lis3mdl();
int read_lis3mdl_data(int16_t *x, int16_t *y, int16_t *z);
double convert_to_mG(int16_t raw_data);
void log_data(double x, double y, double z);
void metal_detector_alert(double magnitude);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    double x;
    double y;
    double z;
} sensor_data_t;

// Function to initialize the LIS3MDL sensor
int initialize_lis3mdl() {
    // Enable continuous measurement mode
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set data rate to 10 Hz
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    // Set measurement mode to continuous
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read data from the LIS3MDL sensor
int read_lis3mdl_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to convert raw data to mG
double convert_to_mG(int16_t raw_data) {
    return (double)raw_data * SCALE_FACTOR;
}

// Function to log data to a file
void log_data(double x, double y, double z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(log_file);
}

// Function to check for metal detector alert
void metal_detector_alert(double magnitude) {
    if (magnitude > 800.0) {
        fprintf(stderr, "Metal detected! Magnitude: %.3f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3MDL sensor
    if (initialize_lis3mdl() < 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    int16_t raw_x, raw_y, raw_z;
    double x, y, z;

    while (!terminate) {
        // Read sensor data
        if (read_lis3mdl_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert raw data to mG
            x = convert_to_mG(raw_x);
            y = convert_to_mG(raw_y);
            z = convert_to_mG(raw_z);

            // Log data
            log_data(x, y, z);

            // Check for metal detector alert
            metal_detector_alert(x + y + z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

