        log_sequence("Obstacle detected by sensor 1");
    }
    if (is_obstacle_detected(sensor2_value)) {
        log_sequence("Obstacle detected by sensor 2");
    }
    if (is_obstacle_detected(sensor3_value)) {
        log_sequence("Obstacle detected by sensor 3");
    }

    // Simulate routine completion
    log_sequence("Self-parking sequence completed");
}

