        return 1;
    }

    printf("Self-parking sequence started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        simulate_self_parking();
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

