#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR registers
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define OUTX_H_G 0x29
#define OUTX_H_XL 0x2A
#define OUTY_L_G 0x2B
#define OUTY_L_XL 0x2C
#define OUTY_H_G 0x2D
#define OUTY_H_XL 0x2E
#define OUTZ_L_G 0x2F
#define OUTZ_L_XL 0x30
#define OUTZ_H_G 0x31
#define OUTZ_H_XL 0x32

// Accelerometer and Gyroscope axes
#define ACCEL_X_AXIS 0
#define ACCEL_Y_AXIS 1
#define ACCEL_Z_AXIS 2
#define GYRO_X_AXIS 3
#define GYRO_Y_AXIS 4
#define GYRO_Z_AXIS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int initialize_lsm6dsr();
int read_register(int reg);
int write_register(int reg, int value);
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
int read_gyroscope_data(int16_t *x, int16_t *y, int16_t *z);
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void cleanup();
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize LSM6DSR
int initialize_lsm6dsr() {
    // Set CTRL1_XL to 100 Hz, enable accelerometer and gyroscope
    if (write_register(CTRL1_XL, 0x70) < 0) {
        fprintf(stderr, "Failed to set CTRL1_XL\n");
        return -1;
    }

    // Set CTRL2_G to +/- 2g, enable accelerometer and gyroscope
    if (write_register(CTRL2_G, 0x70) < 0) {
        fprintf(stderr, "Failed to set CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read a single register from the LSM6DSR
int read_register(int reg) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to write register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to read register 0x%02X\n", reg);
        return -1;
    }
    return buf[0];
}

// Write a single register to the LSM6DSR
int write_register(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to write register 0x%02X with value 0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    buf[0] = OUTX_L_G;
    buf[1] = OUTX_L_XL;
    buf[2] = OUTX_H_G;
    buf[3] = OUTX_H_XL;
    buf[4] = OUTY_L_G;
    buf[5] = OUTY_L_XL;

    if (i2cWriteDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Failed to write accelerometer data\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Read gyroscope data
int read_gyroscope_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    buf[0] = OUTX_L_G;
    buf[1] = OUTX_L_XL;
    buf[2] = OUTX_H_G;
    buf[3] = OUTX_H_XL;
    buf[4] = OUTY_L_G;
    buf[5] = OUTY_L_XL;

    if (i2cWriteDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Failed to write gyroscope data\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Print accelerometer and gyroscope data
void print_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    printf("Accel: X=%d, Y=%d, Z=%d, Gyro: X=%d, Y=%d, Z=%d\n",
           accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Initialize LSM6DSR
    if (initialize_lsm6dsr() < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (program_running) {
        if (read_accelerometer_data(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        } else if (read_gyroscope_data(&gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
        } else {
            print_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

