#define FXOS8700_REG_OUT_X_MSB 0x04
#define FXOS8700_REG_OUT_X_LSB 0x05
#define FXOS8700_REG_OUT_Y_MSB 0x06
#define FXOS8700_REG_OUT_Y_LSB 0x07
