#define FXOS8700_REG_OUT_Z_LSB 0x09
#define FXOS8700_REG_OUT_M_XL_MSB 0x0A
#define FXOS8700_REG_OUT_M_XL_LSB 0x0B
#define FXOS8700_REG_OUT_M_ZL_MSB 0x0C
#define FXOS8700_REG_OUT_M_ZL_LSB 0x0D
#define FXOS8700_REG_OUT_M_ZH_MSB 0x0E
#define FXOS8700_REG_OUT_M_ZH_LSB 0x0F

// Define the I2C bus and handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the FXOS8700
int16_t read_16bit_value(int i2c_handle, uint8_t reg) {
    int16_t value = i2cReadWordData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %d\n", reg, value);
        return 0; // Return 0 on error
    }
    return value;
}

// Function to read a 12-byte block from the FXOS8700
int read_12byte_block(int i2c_handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(i2c_handle, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading 12-byte block from register 0x%02X: %d\n", reg, result);
        return 0; // Return 0 on error
    }
    return result;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700(int i2c_handle) {
    // Check WHO_AM_I register
    int who_am_i = read_16bit_value(i2c_handle, FXOS8700_REG_WHO_AM_I);
    if (who_am_i != 0x60) {
        fprintf(stderr, "FXOS8700 not found: WHO_AM_I = 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer and magnetometer
    // Example configuration (refer to the datasheet for correct values)
    // This is a simplified example, adjust as needed
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x60) < 0) { // Enable accelerometer and set range
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00) < 0) { // Enable magnetometer
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

