    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the FXOS8700 sensor
    if (init_fxos8700(i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read 12-byte block
        uint8_t data[12];
        if (read_12byte_block(i2c_handle, FXOS8700_REG_OUT_X_MSB, data, 12) != 12) {
            fprintf(stderr, "Error reading 12-byte block\n");
            continue; // Continue to the next iteration
        }

        // Extract accelerometer and magnetometer data
        int16_t accel_x = read_16bit_value(i2c_handle, FXOS8700_REG_OUT_X_MSB);
        int16_t accel_y = read_16bit_value(i2c_handle, FXOS8700_REG_OUT_X_MSB + 2);
        int16_t accel_z = read_16bit_value(i2c_handle, FXOS8700_REG_OUT_X_MSB + 4);
        int16_t mag_x = read_16bit_value(i2c_handle, FXOS8700_REG_OUT_X_MSB + 6);
        int16_t mag_y = read_16bit_value(i2c_handle, FXOS8700_REG_OUT_X_MSB + 8);
        int16_t mag_z = read_16bit_value(i2c_handle, FXOS8700_REG_OUT_X_MSB + 10);

        // Print the data
        printf("Accel X: %d, Y: %d, Z: %d, Mag X: %d, Y: %d, Z: %d\n",
               accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (this part will not be reached in the current loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

