#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Tilt threshold
#define TILT_THRESHOLD 30.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt_angle(int16_t x, int16_t y);
void log_tilt_event(float tilt_angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int init_adxl345() {
    // Enable the accelerometer (ODR = 100 Hz)
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of data (X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine the two bytes for each axis
    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    // Convert to g-force units (assuming +/- 2g range)
    *x = (int16_t)((raw_x / 16384.0) * 2000.0); // +/- 2g range
    *y = (int16_t)((raw_y / 16384.0) * 2000.0);
    *z = (int16_t)((raw_z / 16384.0) * 2000.0);

    return 0;
}

// Calculate the tilt angle in degrees
float calculate_tilt_angle(int16_t x, int16_t y) {
    float x_g = (float)x / 2000.0;
    float y_g = (float)y / 2000.0;

    float angle = atan2(y_g, x_g) * 180 / M_PI;

    // Clamp the angle to the range [-90, 90]
    if (angle < -90.0) angle += 180.0;
    if (angle > 90.0) angle -= 180.0;

    return angle;
}

// Log the tilt event to a file
void log_tilt_event(float tilt_angle) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s Tilt angle: %.2f degrees\n", s, tilt_angle);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t x, y, z;

        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate tilt angle
            float tilt_angle = calculate_tilt_angle(x, y);

            // Log tilt event
            log_tilt_event(tilt_angle);

            // Check if tilt exceeds threshold
            if (tilt_angle > TILT_THRESHOLD) {
                printf("Tilt threshold exceeded! Tilt angle: %.2f degrees\n", tilt_angle);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

