#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define ALERT_THRESHOLD 5
#define SAMPLE_INTERVAL_MS 1000
#define SAMPLE_WINDOW_MS 5000
#define SAMPLE_WINDOW_COUNT (SAMPLE_WINDOW_MS / SAMPLE_INTERVAL_MS)
#define SAMPLE_WINDOW_SIZE (SAMPLE_WINDOW_COUNT * SAMPLE_INTERVAL_MS)

static volatile int running = 1;
static volatile int alert_count = 0;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default threshold: %d\n", ALERT_THRESHOLD);
            threshold = ALERT_THRESHOLD;
        }
    } else {
        threshold = ALERT_THRESHOLD;
    }

    printf("Monitoring sound sensor on GPIO %d with threshold: %d\n", GPIO_PIN, threshold);

    // Main loop
    while (running) {
        // Read the digital OUT line
        int reading = gpioRead(GPIO_PIN);

        // Check for errors during GPIO read
        if (reading < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            running = 0; // Exit loop if read fails
            continue;
        }

        // Count the number of high readings within the window
        int count = 0;
        for (i = 0; i < SAMPLE_WINDOW_COUNT; i++) {
            if (reading == 1) {
                count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS); // Delay to avoid busy-waiting
        }

        // Check if the count exceeds the threshold
        if (count > threshold) {
            printf("ALERT: %d high readings in window\n", count);
            alert_count++;
        } else {
            printf("Status: %d high readings in window\n", count);
        }

        // Wait for the next window
        gpioDelay(SAMPLE_WINDOW_MS);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

