#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC registers
#define CTRL_REG1 0x20
#define MAG_OUT_X_L 0x28
#define MAG_OUT_X_H 0x29
#define MAG_OUT_Y_L 0x2A
#define MAG_OUT_Y_H 0x2B
#define MAG_OUT_Z_L 0x2C
#define MAG_OUT_Z_H 0x2D

// GPIO pin for LED
#define LED_PIN 17

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_i2c_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_i2c_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int handle, int *x, int *y, int *z) {
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = read_i2c_register(handle, MAG_OUT_X_L);
    x_h = read_i2c_register(handle, MAG_OUT_X_H);
    y_l = read_i2c_register(handle, MAG_OUT_Y_L);
    y_h = read_i2c_register(handle, MAG_OUT_Y_H);
    z_l = read_i2c_register(handle, MAG_OUT_Z_L);
    z_h = read_i2c_register(handle, MAG_OUT_Z_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        return -1;
    }

    *x = (x_h << 8) | x_l;
    *y = (y_h << 8) | y_l;
    *z = (z_h << 8) | z_l;

    return 0;
}

// Function to calculate the Z-axis magnitude
float calculate_magnitude(int x, int y, int z) {
    return (float)sqrt(x * x + y * y + z * z);
}

// Function to set the LED brightness using PWM
void set_led_brightness(int gpio_pin, int brightness) {
    gpioPWM(gpio_pin, brightness);
}

// Function to log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen("error.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening error.log for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure magnetometer
    if (write_i2c_register(i2c_handle, CTRL_REG1, 0x00) < 0) {
        log_error("Failed to configure magnetometer");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LED_PIN, 255);

    // Set PWM mode (normal)
    gpioSetPWMmode(LED_PIN, PI_PWM_MODE_NORMAL);

    // Set initial LED brightness to 0
    set_led_brightness(LED_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int x, y, z;
        if (read_magnetometer_data(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            set_led_brightness(LED_PIN, (int)(magnitude * 255.0));
        } else {
            set_led_brightness(LED_PIN, 0); // Turn off LED if reading fails
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

