#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG 0x00
#define HMC5883L_MSB 0x01
#define HMC5883L_LSB 0x02
#define HMC5883L_X_MSB 0x03
#define HMC5883L_X_LSB 0x04
#define HMC5883L_Y_MSB 0x05
#define HMC5883L_Y_LSB 0x06
#define HMC5883L_Z_MSB 0x07
#define HMC5883L_Z_LSB 0x08
#define HMC5883L_STATUS 0x09
#define HMC5883L_CONTROL 0x0A
#define HMC5883L_DATA_X_MSB 0x11
#define HMC5883L_DATA_X_LSB 0x12
#define HMC5883L_DATA_Y_MSB 0x13
#define HMC5883L_DATA_Y_LSB 0x14
#define HMC5883L_DATA_Z_MSB 0x15
#define HMC5883L_DATA_Z_LSB 0x16

// Configuration values
#define HMC5883L_CONFIG_MODE_NORMAL 0x00
#define HMC5883L_CONFIG_RES_125 0x40
#define HMC5883L_CONFIG_RES_100 0x00
#define HMC5883L_CONFIG_RES_25 0x00
#define HMC5883L_CONFIG_MODE_NORMAL 0x00

// Magnetometer data structure
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Global variables
int i2c_handle;
magnetometer_data_t magnetometer_data;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetometer_data(magnetometer_data_t *data);
int process_magnetometer_data(magnetometer_data_t *data, magnetometer_data_t *offset);
void print_magnetometer_data(magnetometer_data_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, HMC5883L_MSB, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Process magnetometer data and apply offsets
int process_magnetometer_data(magnetometer_data_t *data, magnetometer_data_t *offset) {
    // Calculate the running average of the last 100 samples
    int sum = 0;
    for (int i = 0; i < 100; i++) {
        sum += data->x;
    }
    int average = (int)(sum / 100);

    // Apply the offsets
    data->x -= average;
    data->y -= average;
    data->z -= average;

    return 0;
}

// Print magnetometer data
void print_magnetometer_data(magnetometer_data_t *data) {
    printf("X: %d, Y: %d, Z: %d\n", data->x, data->y, data->z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        magnetometer_data.x = 0;
        magnetometer_data.y = 0;
        magnetometer_data.z = 0;

        if (read_magnetometer_data(&magnetometer_data) == 0) {
            if (process_magnetometer_data(&magnetometer_data, &magnetometer_data) != 0) {
                fprintf(stderr, "Error processing magnetometer data\n");
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        print_magnetometer_data(&magnetometer_data);

        gpioDelay(500); // 500ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

