void set_solenoid_active(int pin);
void set_solenoid_inactive(int pin);
void cleanup();
void signal_handler(int signal);

// Global variable to track the current solenoid state
int current_solenoid_state = 0;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set the GPIO pins to output mode
    gpioSetMode(SOLENOID1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID2_PIN, PI_OUTPUT);

    // Main loop
    while (1) {
        // Set the active solenoid pin
        set_solenoid_active(SOLENOID1_PIN);
        set_solenoid_inactive(SOLENOID2_PIN);

        // Wait for 500ms
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 500000}, NULL);

        // Set the inactive solenoid pin
        set_solenoid_inactive(SOLENOID1_PIN);
        set_solenoid_inactive(SOLENOID2_PIN);
    }

    return 0;
}

