#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Constants
#define UART_PORT_1 "/dev/serial0"
#define UART_PORT_2 "/dev/serial1"
#define BAUD_RATE 9600
#define TIMEOUT_US 50000 // 5 seconds
#define LOCK_DURATION_US 20000 // 2 seconds
#define LOCK_GPIO 17
#define UNLOCK_GPIO 27
#define EXPECTED_CODE "123456"
#define MAX_RETRIES 3
#define MAX_RETRY_DELAY_US 10000 // 10 seconds

// Global variables
int uart_fd_1 = -1;
int uart_fd_2 = -1;
int lock_gpio_1 = -1;
int lock_gpio_2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart(const char *port, int baud_rate);
int read_uart(int fd, char *buffer, int max_len);
int validate_code(const char *code, const char *expected_code);
int lock_door(int gpio_pin, int duration_us);
int unlock_door(int gpio_pin, int duration_us);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize UART
int initialize_uart(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_cflag &= ~(CSIZE | CSTOPB | PARENB);
    tty.c_cflag &= ~(CS8 | CLOCAL | CREAD);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG | ISTRIP | IXON);
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    }
    return bytes_read;
}

// Validate code
int validate_code(const char *code, const char *expected_code) {
    if (strcmp(code, expected_code) != 0) {
        fprintf(stderr, "Error: Code mismatch: %s != %s\n", code, expected_code);
        return 0; // Indicate failure
    }
    return 1; // Indicate success
}

// Lock door
int lock_door(int gpio_pin, int duration_us) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    gpioDelay(duration_us);
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
    gpioDelay(duration_us);
    return 0;
}

// Unlock door
int unlock_door(int gpio_pin, int duration_us) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    gpioDelay(duration_us);
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
    gpioDelay(duration_us);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_fd_1 != -1) {
        close(uart_fd_1);
    }
    if (uart_fd_2 != -1) {
        close(uart_fd_2);
    }
    if (lock_gpio_1 != -1) {
        gpioWrite(lock_gpio_1, 0); // Ensure lock is LOW
    }
    if (lock_gpio_2 != -1) {
        gpioWrite(lock_gpio_2, 0); // Ensure lock is LOW
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART ports
    uart_fd_1 = initialize_uart(UART_PORT_1, BAUD_RATE);
    uart_fd_2 = initialize_uart(UART_PORT_2, BAUD_RATE);

    if (uart_fd_1 == -1 || uart_fd_2 == -1) {
        cleanup();
        return 1;
    }

    // Set GPIO pins as output
    lock_gpio_1 = gpioSetMode(LOCK_GPIO, PI_OUTPUT);
    if (lock_gpio_1 < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LOCK_GPIO);
        cleanup();
        return 1;
    }
    lock_gpio_2 = gpioSetMode(LOCK_GPIO, PI_OUTPUT);
    if (lock_gpio_2 < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LOCK_GPIO);
        cleanup();
        return 1;
    }

    // Main loop
    char buffer1[256], buffer2[256];
    int bytes_read1, bytes_read2;
    time_t start_time1, end_time1, start_time2, end_time2;
    struct tm *time_info1, *time_info2;
    char code1[10], code2[10];
    int valid_code1 = 0, valid_code2 = 0;
    int retries = 0;

    while (program_running) {
        // Read data from UART 1
        bytes_read1 = read_uart(uart_fd_1, buffer1, sizeof(buffer1));
        if (bytes_read1 == -1) {
            fprintf(stderr, "Error reading from UART 1, retrying...\n");
            retries++;
            if (retries > MAX_RETRY_DELAY_US) {
                fprintf(stderr, "Max retries reached for UART 1, exiting.\n");
                cleanup();
                return 1;
            }
            sleep(1); // Wait before retrying
            continue;
        }

        // Read data from UART 2
        bytes_read2 = read_uart(uart_fd_2, buffer2, sizeof(buffer2));
        if (bytes_read2 == -1) {
            fprintf(stderr, "Error reading from UART 2, retrying...\n");
            retries++;
            if (retries > MAX_RETRY_DELAY_US) {
                fprintf(stderr, "Max retries reached for UART 2, exiting.\n");
                cleanup();
                return 1;
            }
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate codes
        if (validate_code(buffer1, EXPECTED_CODE) == 0) {
            valid_code1 = 1;
        }
        if (validate_code(buffer2, EXPECTED_CODE) == 0) {
            valid_code2 = 1;
        }

        // Check for timeout
        if (bytes_read1 == 0 || bytes_read2 == 0) {
            time(&start_time1);
            time(&end_time1);
            time_diff(&start_time1, &end_time1);
            time_diff(&start_time1, &time(NULL));
            time_diff(&end_time1, &time(NULL));
            start_time1 = 0; // Reset start time
            end_time1 = 0; // Reset end time

            time(&start_time2);
            time(&end_time2);
            time_diff(&start_time2, &end_time2);
            time_diff(&start_time2, &time(NULL));
            time_diff(&end_time2, &time(NULL));
            start_time2 = 0; // Reset start time
            end_time2 = 0; // Reset end time

            if (valid_code1 && valid_code2) {
                // Check for code match
                if (strcmp(buffer1, code1) == 0 && strcmp(buffer2, code2) == 0) {
                    printf("Code match: %s\n", code1);
                    lock_door(LOCK_GPIO, LOCK_DURATION_US);
                    unlock_door(LOCK_GPIO, LOCK_DURATION_US);
                    gpioDelay(LOCK_DURATION_US);
                    printf("Door unlocked\n");
                } else {
                    fprintf(stderr, "Code mismatch: %s != %s\n", code1, code2);
                }
            } else {
                fprintf(stderr, "Code mismatch: %s != %s\n", code1, code2);
            }
        }

        // Check for lock failure
        if (lock_gpio_1 == -1 || lock_gpio_2 == -1) {
            fprintf(stderr, "Error: Lock GPIOs not initialized\n");
            cleanup();
            return 1;
        }
        if (lock_gpio_1 == -1 || lock_gpio_2 == -1) {
            fprintf(stderr, "Error: Lock GPIOs not initialized\n");
            cleanup();
            return 1;
        }
        if (lock_gpio_1 == -1 || lock_gpio_2 == -1) {
            fprintf(stderr, "Error: Lock GPIOs not initialized\n");
            cleanup();
            return 1;
        }

        // Delay to avoid busy-waiting
        sleep(1);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

