volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_door_strike();
int deactivate_door_strike();
int log_event(const char *event);
int log_failsafe_event();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, shutting down gracefully.", signal);
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(DOOR_STRIKE_PIN, PI_OUTPUT);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate door strike relay
int activate_door_strike() {
    gpioWrite(DOOR_STRIKE_PIN, 1); // Set GPIO HIGH
    gpioDelay(1000000);           // Wait for 1 second
    gpioWrite(DOOR_STRIKE_PIN, 0); // Set GPIO LOW
    return 0;
}

// Deactivate door strike relay
int deactivate_door_strike() {
    gpioWrite(DOOR_STRIKE_PIN, 0); // Set GPIO LOW
    return 0;
}

// Log event to syslog
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, event);
    return 0;
}

