int log_failsafe_event() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_ERR, "%s: Failsafe event detected. De-energizing relay.", timestamp);
    return 0;
}

// Cleanup GPIO pins
void cleanup() {
    gpioWrite(DOOR_STRIKE_PIN, 0); // Ensure relay is de-energized
    gpioTerminate();
    closelog();
    exit(0);
}

