    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        return 1;
    }

    // Main loop
    while (program_running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected!");
            log_event("Motion detected!");
            activate_door_strike();
            log_failsafe_event();
            sleep(1); // Debounce
            deactivate_door_strike();
            log_event("Motion stopped.");
        } else {
            syslog(LOG_INFO, "No motion detected.");
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

