#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <math.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B

// Accelerometer sensitivity (mg/LSB)
#define ACCEL_SENSITIVITY 16384.0f

// Buffer size
#define BUFFER_SIZE 100

// Global variables
static int i2c_fd;
static int buffer_fd;
static volatile sig_atomic_t running = 1;

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

// Circular buffer structure
typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Function prototypes
int init_i2c(int addr);
int init_buffer(circular_buffer_t *buffer);
int read_accel_data(int fd, accel_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, accel_data_t data);
accel_data_t get_latest_data(circular_buffer_t *buffer);
void cleanup_resources();
void signal_handler(int sig);

// Initialize I2C
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize the circular buffer
int init_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;

    return 0;
}

// Read acceleration data from MPU6050
int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read accelerometer data
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw data to g-force units
    data->x = (float)raw_x / ACCEL_SENSITIVITY;
    data->y = (float)raw_y / ACCEL_SENSITIVITY;
    data->z = (float)raw_z / ACCEL_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, accel_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest data from the circular buffer
accel_data_t get_latest_data(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return (accel_data_t){0.0f, 0.0f, 0.0f}; // Return dummy data if buffer is empty
    }

    accel_data_t latest_data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->count = 0;
    }

    return latest_data;
}

// Cleanup resources
void cleanup_resources() {
    printf("Cleaning up resources...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (buffer_fd >= 0) {
        munmap(buffer_fd, BUFFER_SIZE * sizeof(circular_buffer_t));
    }
    printf("Cleanup complete.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize buffer
    circular_buffer_t buffer;
    if (init_buffer(&buffer) != 0) {
        fprintf(stderr, "Failed to initialize buffer. Exiting.\n");
        cleanup_resources();
        return 1;
    }

    // Main loop
    while (running) {
        accel_data_t latest_data = get_latest_data(&buffer);
        printf("Latest data: X=%.2f, Y=%.2f, Z=%.2f\n", latest_data.x, latest_data.y, latest_data.z);

        // Wait for 100ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000000; // 100ms * 1000000ns/ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup resources before exiting
    cleanup_resources();

    return 0;
}

