#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define SOUND_SENSOR_DEBOUNCE_MS 100
#define RELAY_ACTIVATION_DURATION_MS 3000
#define LOG_FILE "alarm_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void deactivate_relay();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    gpioDelay(RELAY_ACTIVATION_DURATION_MS);
    deactivate_relay();
}

// Function to deactivate the relay
void deactivate_relay() {
    gpioWrite(RELAY_PIN, 0); // Turn relay off
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle signals (SIGINT and SIGTERM)
void cleanup() {
    printf("Cleaning up and exiting...\n");
    deactivate_relay();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 0) { // No sound detected (LOW signal)
            log_event("No sound detected");
            activate_relay();
            gpioDelay(SOUND_SENSOR_DEBOUNCE_MS * 1000); // Debounce
        } else if (sound_detected == 1) { // Sound detected (HIGH signal)
            log_event("Sound detected");
            deactivate_relay();
            gpioDelay(RELAY_ACTIVATION_DURATION_MS * 1000); // Cooldown
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

