#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG 0x00
#define HMC5883L_DATA_X_MSB 0x07
#define HMC5883L_DATA_X_LSB 0x08
#define HMC5883L_DATA_Y_MSB 0x09
#define HMC5883L_DATA_Y_LSB 0x0A
#define HMC5883L_DATA_Z_MSB 0x0B
#define HMC5883L_DATA_Z_LSB 0x0C

// GPIO pin for LED
#define LED_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Circular buffer structure
typedef struct {
    magnetometer_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
