#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD 50
#define LUX_THRESHOLD_HIGH 150
#define LUX_THRESHOLD_LOW 300
#define I2C_BUS 1
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float calculate_lux(int raw_value);
void control_relays(int lux_value);
void log_data(float lux_value, int red_relay_state, int green_relay_state, int blue_relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read data from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int raw_value;

    // Send measurement command (high resolution mode)
    if (i2cWriteByte(i2c_handle, 0x10) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 2 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Combine the two bytes to get the raw value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Function to calculate lux value from raw sensor value
float calculate_lux(int raw_value) {
    // Formula from BH1750 datasheet
    return (float)raw_value / 1.2;
}

// Function to control the relays based on lux value
void control_relays(int lux_value) {
    int red_relay_state = 0;
    int green_relay_state = 0;
    int blue_relay_state = 0;

    if (lux_value < LUX_THRESHOLD) {
        red_relay_state = 1;
    } else if (lux_value >= LUX_THRESHOLD_HIGH && lux_value < LUX_THRESHOLD_HIGH + LUX_THRESHOLD) {
        green_relay_state = 1;
    } else if (lux_value >= LUX_THRESHOLD_HIGH + LUX_THRESHOLD + LUX_THRESHOLD_HIGH + LUX_THRESHOLD) {
        blue_relay_state = 1;
    } else {
        red_relay_state = 0;
        green_relay_state = 0;
        blue_relay_state = 0;
    }

    gpioWrite(RED_GPIO, red_relay_state);
    gpioWrite(GREEN_GPIO, green_relay_state);
    gpioWrite(BLUE_GPIO, blue_relay_state);
}

// Function to log data to file
void log_data(float lux_value, int red_relay_state, int green_relay_state, int blue_relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Red: %s, Green: %s, Blue: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            lux_value, red_relay_state ? "ON" : "OFF", green_relay_state ? "ON" : "OFF", blue_relay_state ? "ON" : "OFF");

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Light sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor value
        int raw_value = read_bh1750(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor value, retrying in 1 second...\n");
            gpioDelay(1000000); // 1 second
            continue;
        }

        // Calculate lux value
        float lux_value = calculate_lux(raw_value);

        // Control relays
        control_relays(lux_value);

        // Log data
        log_data(lux_value, gpioRead(RED_GPIO), gpioRead(GREEN_GPIO), gpioRead(BLUE_GPIO));

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Light sensor monitoring stopped.\n");

    return 0;
}

