#include <pigpio.h>
#include <unistd.h>

// Define GPIO pin and log file paths
#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"

// Define the number of events to check for an earthquake
#define EARTHQUAKE_THRESHOLD 3

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int check_earthquake_threshold(int sensor_value);
int log_event(int sensor_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to check if the sensor value meets the earthquake threshold
int check_earthquake_threshold(int sensor_value) {
    return (sensor_value == 1) ? EARTHQUAKE_THRESHOLD : 0;
}

// Function to log the event to the log file
int log_event(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d\n", timestamp, sensor_value);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = 1000;

    // Parse command-line arguments
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Error: Invalid poll timeout value. Using default: %d ms\n", poll_timeout_ms);
            poll_timeout_ms = 1000;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring vibration sensor for earthquakes...\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            int earthquake_count = 0;
            int last_earthquake_value = 0;

            // Check for earthquake threshold
            if (check_earthquake_threshold(sensor_value) == EARTHQUAKE_THRESHOLD) {
                earthquake_count++;
                last_earthquake_value = sensor_value;
            }

            // Check if three consecutive earthquakes have occurred
            if (earthquake_count >= EARTHQUAKE_THRESHOLD) {
                printf("EARTHQUAKE ALERT: %d consecutive earthquakes detected!\n", earthquake_count);
                log_event(sensor_value);
                earthquake_count = 0; // Reset the count
            }

            // Check if the last event was an earthquake
            if (sensor_value == last_earthquake_value) {
                earthquake_count++;
            }

            // Check if the last event was the last one
            if (earthquake_count >= EARTHQUAKE_THRESHOLD) {
                printf("EARTHQUAKE ALERT: %d consecutive earthquakes detected!\n", earthquake_count);
                log_event(sensor_value);
                earthquake_count = 0; // Reset the count
            }
        }

        gpioDelay(poll_timeout_ms * 1000); // Delay for the specified timeout
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

