#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// Hard-Iron Calibration Offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Heading Calibration
#define HEIGHT_OFFSET 0

// Compass Direction Constants
#define N 0
#define NE 1
#define E 2
#define SE 3
#define S 4
#define SW 5
#define W 6
#define NW 7

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
magnetometer_data_t read_magnetometer_data();
void calibrate_magnetometer(magnetometer_data_t *data);
void map_heading_to_compass_direction(int heading);
void log_data(magnetometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read magnetometer data from LSM303DLHC
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data (X_L_A, X_H_A, Y_L_A, Y_H_A, Z_L_A, Z_H_A)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0;
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calibrate magnetometer data
void calibrate_magnetometer(magnetometer_data_t *data) {
    // Hard-Iron Calibration
    data->x = (int16_t)((data->x - HEIGHT_OFFSET) * X_OFFSET);
    data->y = (int16_t)((data->y - HEIGHT_OFFSET) * Y_OFFSET);
    data->z = (int16_t)((data->z - HEIGHT_OFFSET) * Z_OFFSET);
}

// Map heading to compass direction
void map_heading_to_compass_direction(int heading) {
    switch (heading) {
        case 0:
            printf("N");
            break;
        case 1:
            printf("NE");
            break;
        case 2:
            printf("E");
            break;
        case 3:
            printf("SE");
            break;
        case 4:
            printf("S");
            break;
        case 5:
            printf("SW");
            break;
        case 6:
            printf("W");
            break;
        case 7:
            printf("NW");
            break;
        default:
            printf("Unknown");
            break;
    }
}

// Log data to CSV file
void log_data(magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d\n", timestamp, data.x, data.y, data.z, data.x + data.y + data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        magnetometer_data_t data = read_magnetometer_data();
        calibrate_magnetometer(&data);
        map_heading_to_compass_direction(data.x);
        log_data(data);
        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

