#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 200

// Global variables
static volatile int touch_state = 0; // 0 = no touch, 1 = touch
static volatile int last_touch_time = 0; // Last touch time
static volatile int relay_state = 0; // Relay state
static FILE *log_file = NULL;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void touch_callback(int gpio, int level, uint32_t tick, void *user);
void log_relay_state(int relay_state);
void cleanup(int signal);

// Callback function for touch sensor
void touch_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge (touch detected)
        touch_state = 1;
        last_touch_time = tick;
        log_relay_state(relay_state);
    }
}

// Function to log relay state to a file
void log_relay_state(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}", timestamp, relay_state == 1 ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to cleanup GPIO and log file
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    running = 0; // Stop the main loop

    // Set relay to OFF
    gpioWrite(RELAY_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Set up interrupt handler for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIME_MS, touch_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Wait for a short period to avoid busy-waiting
        gpioDelay(100); // 100 milliseconds

        // Check if the relay state has changed
        if (relay_state != relay_state_prev) {
            relay_state_prev = relay_state;
            if (relay_state == 1) {
                gpioWrite(RELAY_PIN, 1); // Turn relay ON
                log_relay_state(relay_state);
            } else {
                gpioWrite(RELAY_PIN, 0); // Turn relay OFF
                log_relay_state(relay_state);
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10); // 10 milliseconds
    }

    return 0;
}

