#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 register addresses
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48

// Scaling factors (adjust based on your sensor)
#define GYRO_SCALE_FACTOR 0.02  // Degrees/second per LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read a 16-bit value from the MPU-6050
int16_t read_mpu6050_register(int reg) {
    int16_t value = 0;
    int i;

    for (i = 0; i < 2; i++) {
        value |= (i2cReadByteData(i2c_handle, reg) & 0x7F) << (7 - i);
    }
    return value;
}

// Function to read the X, Y, and Z angular velocities from the MPU-6050
void read_mpu6050_data(int16_t *x, int16_t *y, int16_t *z) {
    *x = read_mpu6050_register(MPU6050_GYRO_XOUT_H);
    *y = read_mpu6050_register(MPU6050_GYRO_YOUT_H);
    *z = read_mpu6050_register(MPU6050_GYRO_ZOUT_H);
}

// Function to log the data to a file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int16_t x, y, z;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // Bus 1, address 0x68, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        read_mpu6050_data(&x, &y, &z);

        // Log the data
        log_data(x, y, z);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10 milliseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

