#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000 // 50ms

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_distance() {
    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_GPIO, 0);

    int start_tick = gpioTick();
    int timeout = 0;

    while (gpioRead(ECHO_GPIO) == 0 && timeout < TIMEOUT_US) {
        start_tick = gpioTick();
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        return -1; // Timeout
    }

    int end_tick = gpioTick();
    int pulse_duration = end_tick - start_tick;

    return pulse_duration;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = read_distance();

        if (distance >= 0) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

            fprintf(log_file, "%s, Distance: %d\n", buf, distance);
            fflush(log_file);

            printf("%s, Distance: %d\n", buf, distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping measurement.\n");
        }

        gpioDelay(60000); // Wait for 1 second
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

