#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering cycle duration in seconds
#define WATERING_DURATION 86400

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variable to track the last watering cycle time
time_t last_watering_time = 0;

// Function prototypes
int initialize_gpio();
int set_relay_state(int pin, int state);
int activate_relay(int pin);
int deactivate_relay(int pin);
int log_watering_cycle(time_t cycle_start_time);
int check_gpio_chip_initialization();
int check_gpio_chip_version();
int check_gpio_chip_interface();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);
    gpioTerminate();
    exit(0);
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for relay 1\n");
        return -1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for relay 2\n");
        return -1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for relay 3\n");
        return -1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for relay 4\n");
        return -1;
    }

    // Set initial relay states to HIGH
    if (set_relay_state(RELAY1_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set relay 1 state\n");
        return -1;
    }
    if (set_relay_state(RELAY2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set relay 2 state\n");
        return -1;
    }
    if (set_relay_state(RELAY3_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set relay 3 state\n");
        return -1;
    }
    if (set_relay_state(RELAY4_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set relay 4 state\n");
        return -1;
    }

    return 0;
}

// Function to set the state of a relay
int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to relay %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to activate a relay for 5 seconds
int activate_relay(int pin) {
    if (set_relay_state(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate relay %d\n", pin);
        return -1;
    }
    gpioDelay(5000000); // 5 seconds
    if (set_relay_state(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int pin) {
    if (set_relay_state(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to log the start time of a watering cycle
int log_watering_cycle(time_t cycle_start_time) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    struct tm *timeinfo = localtime(&cycle_start_time);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s - Watering cycle started\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to check if the GPIO chip initialization failed
int check_gpio_chip_initialization() {
    int result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to check if the GPIO chip version is compatible
int check_gpio_chip_version() {
    int version = gpioVersion();
    if (version < 0) {
        fprintf(stderr, "pigpio version check failed\n");
        return -1;
    }
    printf("pigpio version: %d\n", version);
    return 0;
}

// Function to check if the GPIO chip interface is supported
int check_gpio_chip_interface() {
    int interface = gpioGetInterface();
    if (interface < 0) {
        fprintf(stderr, "pigpio interface check failed\n");
        return -1;
    }
    printf("pigpio interface: %d\n", interface);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Check GPIO chip initialization
    if (check_gpio_chip_initialization() != 0) {
        gpioTerminate();
        return 1;
    }

    // Check GPIO chip version
    if (check_gpio_chip_version() != 0) {
        gpioTerminate();
        return 1;
    }

    // Check GPIO chip interface
    if (check_gpio_chip_interface() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to water the plants
    while (1) {
        // Get the current time
        time(&last_watering_time);

        // Check if the watering cycle has elapsed
        if (difftime(time(NULL), last_watering_time) >= WATERING_DURATION) {
            // Activate all four relays in sequence
            if (activate_relay(RELAY1_PIN) != 0) {
                fprintf(stderr, "Failed to activate relay 1\n");
            }
            if (activate_relay(RELAY2_PIN) != 0) {
                fprintf(stderr, "Failed to activate relay 2\n");
            }
            if (activate_relay(RELAY3_PIN) != 0) {
                fprintf(stderr, "Failed to activate relay 3\n");
            }
            if (activate_relay(RELAY4_PIN) != 0) {
                fprintf(stderr, "Failed to activate relay 4\n");
            }

            // Log the watering cycle
            if (log_watering_cycle(last_watering_time) != 0) {
                fprintf(stderr, "Failed to log watering cycle\n");
            }

            // Wait for the next watering cycle
            time_t next_cycle_time = last_watering_time + WATERING_DURATION;
            if (log_watering_cycle(next_cycle_time) != 0) {
                fprintf(stderr, "Failed to log next watering cycle\n");
            }
            sleep(86400); // Wait for 86,400 seconds (24 hours)
        } else {
            // Check if the watering cycle has been interrupted by a signal
            if (signal(SIGINT, NULL) == SIG_ERR) {
                fprintf(stderr, "Failed to set signal handler for SIGINT\n");
            }
            if (signal(SIGTERM, NULL) == SIG_ERR) {
                fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
            }

            // Deactivate all relays
            if (deactivate_relay(RELAY1_PIN) != 0) {
                fprintf(stderr, "Failed to deactivate relay 1\n");
            }
            if (deactivate_relay(RELAY2_PIN) != 0) {
                fprintf(stderr, "Failed to deactivate relay 2\n");
            }
            if (deactivate_relay(RELAY3_PIN) != 0) {
                fprintf(stderr, "Failed to deactivate relay 3\n");
            }
            if (deactivate_relay(RELAY4_PIN) != 0) {
                fprintf(stderr, "Failed to deactivate relay 4\n");
            }

            // Log the interruption
            if (log_watering_cycle(0) != 0) {
                fprintf(stderr, "Failed to log interruption\n");
            }

            // Wait for the next watering cycle
            time_t next_cycle_time = last_watering_time + WATERING_DURATION;
            if (log_watering_cycle(next_cycle_time) != 0) {
                fprintf(stderr, "Failed to log next watering cycle\n");
            }
            sleep(86400); // Wait for 86,400 seconds (24 hours)
        }
    }

    return 0;
}

