#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int read_gyro_data(gyro_data_t *data);
void store_gyro_data(gyro_data_t data);
void print_gyro_data(gyro_data_t data);
void check_gyro_threshold(gyro_data_t data);
void cleanup();
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to store gyroscope data in the buffer
void store_gyro_data(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print gyroscope data
void print_gyro_data(gyro_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

// Function to check gyroscope threshold
void check_gyro_threshold(gyro_data_t data) {
    int16_t x = data.x;
    int16_t y = data.y;
    int16_t z = data.z;

    if (x > 250 || y > 250 || z > 250) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Store gyroscope data
            store_gyro_data(gyro_data);

            // Check gyroscope threshold
            check_gyro_threshold(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        // Delay for 50 ms (20 Hz sampling rate)
        gpioDelay(50);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

