#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define PWR_MGMT_2 0x6A
#define INT_ENABLE 0x19
#define INT_SOURCE 0x1C
#define INT_DATA_SRC 0x1B
#define INT_PIN 17
#define LED_PIN 11

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3906250 // 3.9 MHz
#define SPI_MODE 0

// Circular Buffer Parameters
#define BUFFER_SIZE 64

// Gyroscope Data Structure
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    time_t timestamp;
} gyro_data_t;

// Global Variables
int spi_handle;
gyro_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
int running = 1;

// Function Prototypes
int initialize_spi();
int read_gyro_data(gyro_data_t *data);
int store_gyro_data(gyro_data_t data);
int check_gyro_threshold(gyro_data_t data);
void blink_warning_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char tx_buf[6];
    char rx_buf[6];

    // Read raw gyroscope data
    if (spiXfer(spi_handle, tx_buf, rx_buf, 6) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((rx_buf[1] << 8) | rx_buf[0]);
    int16_t y = (int16_t)((rx_buf[3] << 8) | rx_buf[2]);
    int16_t z = (int16_t)((rx_buf[5] << 8) | rx_buf[4]);

    // Combine high and low bytes for timestamp
    data->timestamp = (time_t)((rx_buf[3] << 24) | (rx_buf[2] << 16) | (rx_buf[1] << 8) | rx_buf[0]);

    return 0;
}

// Function to store gyroscope data in the circular buffer
int store_gyro_data(gyro_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    return 0;
}

// Function to check if the gyroscope data exceeds the threshold
