#define INT_SOURCE 0x1C
#define INT_DATA_SRC 0x1B
#define INT_PIN 17
#define LED_PIN 11

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3906250 // 3.9 MHz
#define SPI_MODE 0

// Circular Buffer Parameters
#define BUFFER_SIZE 64

// Gyroscope Data Structure
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    time_t timestamp;
} gyro_data_t;

// Global Variables
