    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(&circular_buffer[buffer_index]) == 0) {
            // Store gyroscope data
            store_gyro_data(circular_buffer[buffer_index]);

