#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define alert duration (seconds)
#define ALERT_DURATION 2

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Define log file name
#define LOG_FILE "seismic_events.txt"

// Global variables
static volatile int alert_active = 0;
static volatile int alert_duration_start = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void alert_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_event(const char *timestamp);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        if (alert_active) {
            alert_duration_start = tick;
            alert_active = 0;
        }
    } else if (level == 0) {
        if (alert_duration_start == 0) {
            alert_duration_start = tick;
        }
    }
}

// Log event to file
void log_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup function
void cleanup() {
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register callbacks
    gpioSetAlertFuncEx(SENSOR1_PIN, alert_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_PIN, alert_callback, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check for seismic events
        if (sensor1_value == 1 && sensor2_value == 1) {
            if (alert_active) {
                // Check if alert duration is met
                if (alert_duration_start == 0) {
                    alert_duration_start = 0; // Reset duration if it's the first event
                } else if (alert_duration_start > ALERT_DURATION) {
                    // Trigger alert
                    gpioWrite(ALERT_PIN, 1);
                    gpioDelay(ALERT_DURATION * 1000); // 2 seconds
                    gpioWrite(ALERT_PIN, 0);
                    alert_active = 0;
                    alert_duration_start = 0; // Reset duration
                }
            }
        } else if (alert_active) {
            // Check if alert duration is over
            if (alert_duration_start > 0) {
                alert_duration_start = 0; // Reset duration
            }
        }

        gpioDelay(100); // Delay to avoid busy-waiting
    }

    return 0;
}

