// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CE_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define LED_PIN 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define GYRO_REG_ADDR 0x00 // Example register address
#define GYRO_REG_DATA_LEN 2 // Example data length

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float rate;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_gyro_data(gyro_data_t *data);
float convert_to_degrees_per_second(int16_t raw_data);
void add_to_buffer(gyro_data_t data);
void check_threshold(float rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CE_PIN, PI_OUTPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetPullUpDown(CE_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyro data
int read_gyro_data(gyro_data_t *data) {
    char tx_buf[2];
    char rx_buf[GYRO_REG_DATA_LEN];
    int result;

    // Set CE low to enable the gyro
    gpioWrite(CE_PIN, 0);

    // Construct the SPI transfer command
    tx_buf[0] = GYRO_REG_ADDR | 0x80; // MSB = 1 for read
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, GYRO_REG_DATA_LEN);
    if (result != GPIOD_SUCCESS) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract the raw data
    int16_t raw_data = ((int16_t)rx_buf[0] << 8) | rx_buf[1];

    // Convert to degrees per second
    data->rate = convert_to_degrees_per_second(raw_data);

    // Set CE high to enable the gyro
    gpioWrite(CE_PIN, 1);

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    // This is a placeholder.  A real implementation would calibrate
    // the gyroscope and convert the raw data to degrees per second.
    // For demonstration purposes, we'll just return a random value.
    return (float)raw_data * 0.1; // Example: 10 degrees/second
}

// Function to add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the threshold and turn the LED on/off
void check_threshold(float rate) {
    if (rate > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close SPI and turn off the LED
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyro data
        if (read_gyro_data(&gyro_buffer[0]) != 0) {
            fprintf(stderr, "Failed to read gyro data\n");
        } else {
            // Add data to the buffer
            add_to_buffer(gyro_buffer[0]);

            // Check threshold and turn LED on/off
            check_threshold(gyro_buffer[0].rate);

            // Get current timestamp
            time_t current_time = time(NULL);

            // Store timestamp and rate in the buffer
            gyro_data_t data = {current_time, gyro_buffer[0].rate};
            add_to_buffer(data);

            // Print data to console
            printf("Timestamp: %ld, Rate: %.2f deg/s\n", current_time, gyro_buffer[0].rate);
        }

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

