    gpioWrite(LAMP1_PIN, 0);
    gpioWrite(LAMP2_PIN, 0);
    gpioWrite(LAMP3_PIN, 0);
    gpioSetPWMfrequency(LAMP1_PIN, 0);
    gpioSetPWMfrequency(LAMP2_PIN, 0);
    gpioSetPWMfrequency(LAMP3_PIN, 0);
    gpioSetPWMrange(LAMP1_PIN, 0);
    gpioSetPWMrange(LAMP2_PIN, 0);
    gpioSetPWMrange(LAMP3_PIN, 0);
    gpioTerminate();
}

