    int duration;

    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    duration = atoi(argv[1]);

    // Validate duration
    if (duration < 1 || duration > SUNSET_DURATION) {
        fprintf(stderr, "Invalid duration. Duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Setup signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        return 1;
    }

    // Fade the lamps
    sunset_sequence(duration);

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

