// Define GPIO pins for the relays
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

// Global variable to track the current state of the relays
int relay_states[4] = {0, 0, 0, 0}; // Initialize all relays to OFF

// Function to set the state of a relay
void set_relay_state(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to get the current state of a relay
int get_relay_state(int pin) {
    return gpioRead(pin);
}

// Function to initialize the pigpio library and set the GPIO pins to output mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as output
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    return 0;
}

// Function to cleanly release the GPIO pins
void cleanup_gpio() {
    gpioWrite(RED_PIN, 0);
    gpioWrite(YELLOW_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
}

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to simulate the traffic light sequence
void simulate_traffic_light() {
    // Red for 10 seconds
    set_relay_state(RED_PIN, 1);
    set_relay_state(YELLOW_PIN, 0);
    set_relay_state(GREEN_PIN, 0);
    set_relay_state(BLUE_PIN, 0);
    gpioDelay(10000); // 10 seconds

    // Red + Yellow for 2 seconds
    set_relay_state(RED_PIN, 1);
    set_relay_state(YELLOW_PIN, 1);
    set_relay_state(GREEN_PIN, 0);
    set_relay_state(BLUE_PIN, 0);
    gpioDelay(2000); // 2 seconds

    // Green for 10 seconds
    set_relay_state(RED_PIN, 0);
    set_relay_state(YELLOW_PIN, 0);
    set_relay_state(GREEN_PIN, 1);
    set_relay_state(BLUE_PIN, 0);
    gpioDelay(10000); // 10 seconds

    // Yellow for 3 seconds
    set_relay_state(RED_PIN, 0);
    set_relay_state(YELLOW_PIN, 1);
    set_relay_state(GREEN_PIN, 0);
    set_relay_state(BLUE_PIN, 0);
    gpioDelay(3000); // 3 seconds
}

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and set GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Simulate the traffic light sequence
    simulate_traffic_light();

    // Clean up and exit
    cleanup_gpio();
    return 0;
}

