#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 17
#define FLAME_SENSOR_2 22
#define FLAME_SENSOR_3 27
#define BUZZER 18
#define LED 23

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor(int gpio);
int is_flame_detected(int sensor_number);
void log_flame_event(int sensor_number);
void activate_buzzer(int gpio);
void deactivate_buzzer(int gpio);
void activate_led(int gpio);
void deactivate_led(int gpio);
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to check if flame is detected
int is_flame_detected(int sensor_number) {
    return read_flame_sensor(sensor_number) == 0;
}

// Function to log the flame event
void log_flame_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame Detected on GPIO %d\n", timestamp, sensor_number);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer
void activate_buzzer(int gpio) {
    gpioWrite(gpio, 1); // Turn buzzer on
}

// Function to deactivate the buzzer
void deactivate_buzzer(int gpio) {
    gpioWrite(gpio, 0); // Turn buzzer off
}

// Function to activate the LED
void activate_led(int gpio) {
    gpioWrite(gpio, 1); // Turn LED on
}

// Function to deactivate the LED
void deactivate_led(int gpio) {
    gpioWrite(gpio, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensors
        int sensor1_value = read_flame_sensor(FLAME_SENSOR_1);
        int sensor2_value = read_flame_sensor(FLAME_SENSOR_2);
        int sensor3_value = read_flame_sensor(FLAME_SENSOR_3);

        // Check for flame detection
        if (sensor1_value == 0 && sensor2_value == 0 && sensor3_value == 0) {
            // Flame detected
            log_flame_event(1);
            activate_buzzer(BUZZER);
            activate_led(LED);
            gpioDelay(500000); // Debounce delay (500ms)
            deactivate_buzzer(BUZZER);
            deactivate_led(LED);
            log_flame_event(2);
        } else if (sensor1_value == 0 && sensor2_value == 0 && sensor3_value == 1) {
            // Flame detected and cleared
            log_flame_event(3);
            deactivate_buzzer(BUZZER);
            deactivate_led(LED);
            gpioDelay(500000); // Debounce delay (500ms)
            activate_buzzer(BUZZER);
            activate_led(LED);
            log_flame_event(4);
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    deactivate_buzzer(BUZZER);
    deactivate_led(LED);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

