    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensors
        int sensor1_value = read_flame_sensor(FLAME_SENSOR_1);
        int sensor2_value = read_flame_sensor(FLAME_SENSOR_2);
        int sensor3_value = read_flame_sensor(FLAME_SENSOR_3);

