        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
        return 1;
    }
    return 0;
}

// Dispense solenoid
int dispense_solenoid(int pin, int duration_ms) {
    int pwm_value = (int)((float)duration_ms / 1000.0 * MAX_PWM_VALUE);
    if (set_solenoid_pin(pin, 1) != 0) return 1;
    gpioPWM(pin, pwm_value);
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (set_solenoid_pin(pin, 0) != 0) return 1;
    return 0;
}

