    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (dispense_solenoid(SOLENOID1_PIN, DISPENSE_INTERVAL_MS) != 0) {
            fprintf(stderr, "Error dispending solenoid 1\n");
