        if (dispense_solenoid(SOLENOID2_PIN, DISPENSE_INTERVAL_MS) != 0) {
            fprintf(stderr, "Error dispending solenoid 2\n");
        }
        gpioDelay(DISPENSE_DURATION_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

