// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define RELAY_ACTIVE_HIGH 1

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_relay(int state);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially inactive
    gpioWrite(RELAY_PIN, RELAY_ACTIVE_HIGH);

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control relay state
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up and exiting...\n");
    gpioWrite(RELAY_PIN, RELAY_ACTIVE_HIGH); // Ensure relay is off
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 0) { // Assuming touch sensor outputs HIGH when touched
            printf("Touch detected!\n");
            control_relay(1); // Activate relay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            control_relay(0); // Deactivate relay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    return 0;
}

