#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Configuration
#define ALSA_DEVICE "default"
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define SAMPLE_SIZE (SAMPLE_RATE * PERIOD_SIZE)
#define SENSITIVITY 1.0
#define GATE_THRESHOLD 0.5
#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 255

// Global variables
static int alsa_fd = -1;
static int running = 1;

// Function prototypes
int alsa_open(const char *device);
int alsa_prepare(int fd, int format, int channels, int period_size, int rate);
int alsa_capture(int fd, short *buffer, int buffer_size);
int alsa_close(int fd);
float calculate_rms(short *buffer, int buffer_size);
void map_rms_to_color(float rms, int *red, int *green, int *blue);
void set_gpio_pwm(int gpio, int period, int duty_cycle);
void signal_handler(int signal);

// ALSA open function
int alsa_open(const char *device) {
    alsa_fd = alsa_open(device, 0); // Open device in non-blocking mode
    if (alsa_fd < 0) {
        fprintf(stderr, "Error opening ALSA device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return 0;
}

// ALSA prepare function
int alsa_prepare(int fd, int format, int channels, int period_size, int rate) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    snd_pcm_hw_params_alloca(&hw_params);

    err = snd_pcm_hw_params_any(alsa_fd, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error allocating hw params: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params_set_access(alsa_fd, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params_set_format(alsa_fd, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(alsa_fd, hw_params, channels);
    if (err < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params_set_period_size(alsa_fd, hw_params, period_size);
    if (err < 0) {
        fprintf(stderr, "Error setting period size: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params_set_rate(alsa_fd, hw_params, rate, 0); // Set rate to default
    if (err < 0) {
        fprintf(stderr, "Error setting rate: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params(alsa_fd, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting hw params: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// ALSA capture function
int alsa_capture(int fd, short *buffer, int buffer_size) {
    int err;
    snd_pcm_t *pcm;
    snd_pcm_hw_params_t *hw_params;
    int i;

    pcm = snd_pcm_open_w_api(alsa_fd, SND_PCM_STREAM_CAPTURE, SND_PCM_FORMAT_S16_LE, SND_PCM_ACCESS_RW_INTERLEAVED, -1);
    if (pcm == NULL) {
        fprintf(stderr, "Error opening PCM device: %s\n", strerror(errno));
        return -1;
    }

    err = snd_pcm_hw_params_alloca(&hw_params);
    if (err < 0) {
        fprintf(stderr, "Error allocating hw params: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_access(pcm, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_format(pcm, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(pcm, hw_params, 1);
    if (err < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params_set_period_size(pcm, hw_params, PERIOD_SIZE);
    if (err < 0) {
        fprintf(stderr, "Error setting period size: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_hw_params(pcm, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting hw params: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    err = snd_pcm_prepare(pcm, hw_params);
    if (err < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", strerror(errno));
        snd_pcm_close(pcm);
        return -1;
    }

    for (i = 0; i < buffer_size; i++) {
        short sample = snd_pcm_readi(pcm, buffer + i, 1);
        if (sample < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", strerror(errno));
            snd_pcm_prepare(pcm, hw_params);
            err = snd_pcm_prepare(pcm, hw_params);
            if (err < 0) {
                fprintf(stderr, "Error preparing PCM device: %s\n", strerror(errno));
                break;
            }
        }
    }

    snd_pcm_drain(pcm);
    snd_pcm_close(pcm);

    return 0;
}

// ALSA close function
int alsa_close(int fd) {
    if (alsa_fd != -1) {
        snd_pcm_close(alsa_fd);
        snd_pcm_unprepare(alsa_fd, NULL, NULL);
        snd_pcm_close(alsa_fd);
        alsa_fd = -1;
    }
    return 0;
}

// Calculate RMS amplitude
float calculate_rms(short *buffer, int buffer_size) {
    float sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (float)buffer[i] * buffer[i];
    }
    return sqrt(sum_of_squares / buffer_size);
}

// Map RMS amplitude to color
void map_rms_to_color(float rms, int *red, int *green, int *blue) {
    if (rms > GATE_THRESHOLD) {
        *red = 255;
        *green = 0;
        *blue = 0;
    } else {
        *red = (int)((float)rms * PWM_RANGE / GATE_THRESHOLD);
        *green = (int)((float)rms * PWM_RANGE / GATE_THRESHOLD);
        *blue = (int)((float)rms * PWM_RANGE / GATE_THRESHOLD);
    }
}

// Set GPIO PWM duty cycle
void set_gpio_pwm(int gpio, int period, int duty_cycle) {
    gpioSetPWMfrequency(gpio, PWM_FREQUENCY);
    gpioPWM(gpio, duty_cycle);
