#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 11
#define RELAY2_PIN 13
#define RELAY3_PIN 15
#define RELAY4_PIN 17

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHT_DURATION 14400

// Define the duty cycle range for PWM
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variable to track the current phase
int current_phase = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    // Turn off all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to set the duty cycle of a relay
void set_relay_duty_cycle(int relay_pin, int duty_cycle) {
    gpioWrite(relay_pin, duty_cycle);
}

// Function to simulate sunrise
void sunrise() {
    printf("Sunrise: Sunrise phase complete.\n");
    current_phase = 1;
    set_relay_duty_cycle(RELAY1_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY2_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY3_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY4_PIN, MIN_DUTY_CYCLE);
}

// Function to simulate sunset
void sunset() {
    printf("Sunset: Sunset phase complete.\n");
    current_phase = 2;
    set_relay_duty_cycle(RELAY1_PIN, MAX_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY2_PIN, MAX_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY3_PIN, MAX_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY4_PIN, MAX_DUTY_CYCLE);
}

// Function to simulate daytime
void daytime() {
    printf("Daytime: Daytime phase complete.\n");
    current_phase = 3;
    set_relay_duty_cycle(RELAY1_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY2_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY3_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY4_PIN, MIN_DUTY_CYCLE);
}

// Function to simulate nighttime
void nighttime() {
    printf("Nighttime: Nighttime phase complete.\n");
    current_phase = 4;
    set_relay_duty_cycle(RELAY1_PIN, MAX_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY2_PIN, MAX_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY3_PIN, MAX_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY4_PIN, MAX_DUTY_CYCLE);
}

// Function to simulate the sunrise cycle
void sunrise_cycle() {
    sunrise();
    gpioDelay(SUNRISE_DURATION * 1000); // Convert seconds to milliseconds
    set_relay_duty_cycle(RELAY1_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY2_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY3_PIN, MIN_DUTY_CYCLE);
    set_relay_duty_cycle(RELAY4_PIN, MIN_DUTY_CYCLE);
