    set_relay_duty_cycle(RELAY4_PIN, MIN_DUTY_CYCLE);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial duty cycle to 0
    set_relay_duty_cycle(RELAY1_PIN, 0);
    set_relay_duty_cycle(RELAY2_PIN, 0);
    set_relay_duty_cycle(RELAY3_PIN, 0);
    set_relay_duty_cycle(RELAY4_PIN, 0);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Cycle through the phases
        switch (current_phase) {
            case 0:
                sunrise_cycle();
                break;
            case 1:
                sunrise_cycle();
                break;
            case 2:
                sunset_cycle();
                break;
            case 3:
                sunset_cycle();
                break;
            case 4:
                sunrise_cycle();
                break;
            default:
                fprintf(stderr, "Invalid phase: %d\n", current_phase);
                break;
        }
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    gpioTerminate();
    return 0;
}

