#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN_1 17
#define SENSOR_PIN_2 18
#define SENSOR_PIN_3 27

// Debounce interval in milliseconds
#define DEBOUNCE_INTERVAL 200

// Video capture command
#define VIDEO_CAPTURE_COMMAND "raspivid -t 0 -o /home/pi/videos/YYYYMMDD_HHMMSS.h264 -vf -f h264 -qscale 0 -c:v h264 -c:a copy"

// Log file path
#define LOG_FILE "/home/pi/logs/motion_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void trigger_video_capture();
void log_motion_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);
    gpioSetMode(SENSOR_PIN_3, PI_INPUT);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Trigger video capture
void trigger_video_capture() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    char command[256];
    snprintf(command, sizeof(command), VIDEO_CAPTURE_COMMAND);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing command: %s\n", command);
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Video capture failed with exit status: %d\n", WEXITSTATUS(status));
    }
}

// Log motion event
void log_motion_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Motion detected\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_PIN_1);
        int sensor2_value = read_sensor(SENSOR_PIN_2);
        int sensor3_value = read_sensor(SENSOR_PIN_3);

        // Debounce sensor readings
        int sensor1_debounced = 0;
        int sensor2_debounced = 0;
        int sensor3_debounced = 0;

        for (int i = 0; i < 5; i++) {
            if (read_sensor(SENSOR_PIN_1) == 1) {
                sensor1_debounced++;
            }
            gpioDelay(DEBOUNCE_INTERVAL);
        }

        for (int i = 0; i < 5; i++) {
            if (read_sensor(SENSOR_PIN_2) == 1) {
                sensor2_debounced++;
            }
            gpioDelay(DEBOUNCE_INTERVAL);
        }

        for (int i = 0; i < 5; i++) {
            if (read_sensor(SENSOR_PIN_3) == 1) {
                sensor3_debounced++;
            }
            gpioDelay(DEBOUNCE_INTERVAL);
        }

        // Check for motion events
        if (sensor1_debounced > 0 && sensor2_debounced > 0 && sensor3_debounced > 0) {
            trigger_video_capture();
            log_motion_event();
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

