#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to read the moisture sensor value
int read_moisture_sensor() {
    int moisture_value = gpioRead(RELAY_1_PIN);
    if (moisture_value < 0) {
        fprintf(stderr, "Error reading moisture sensor\n");
        return -1; // Indicate an error
    }
    return moisture_value;
}

// Function to log the sensor reading, relay state, and timestamp to a file
int log_data(int moisture_value, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Moisture: %d, Relay: %s\n", timestamp, moisture_value, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

// Function to deactivate all relays
void deactivate_relays() {
    set_relay_state(RELAY_1_PIN, 0);
    set_relay_state(RELAY_2_PIN, 0);
    set_relay_state(RELAY_3_PIN, 0);
    set_relay_state(RELAY_4_PIN, 0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set the GPIO pins as output
    gpioSetMode(RELAY_1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY_4_PIN, PI_OUTPUT);

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the moisture sensor value
        int moisture_value = read_moisture_sensor();
        if (moisture_value < 0) {
            fprintf(stderr, "Error reading moisture sensor, exiting...\n");
            break;
        }

        // Determine the relay state based on the moisture value
        int relay_state = (moisture_value < MOISTURE_THRESHOLD) ? 1 : 0; // 1 = ON, 0 = OFF

        // Log the data
        if (log_data(moisture_value, relay_state) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Activate/deactivate the relays
        if (moisture_value < MOISTURE_THRESHOLD) {
            set_relay_state(RELAY_1_PIN, 1);
            set_relay_state(RELAY_2_PIN, 1);
            set_relay_state(RELAY_3_PIN, 1);
            set_relay_state(RELAY_4_PIN, 1);
        } else {
            set_relay_state(RELAY_1_PIN, 0);
            set_relay_state(RELAY_2_PIN, 0);
            set_relay_state(RELAY_3_PIN, 0);
            set_relay_state(RELAY_4_PIN, 0);
        }

        // Delay for 5 seconds
        gpioDelay(5000); // 5 seconds = 5000 milliseconds
    }

    // Deactivate all relays before exiting
    deactivate_relays();

    // Close the log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

