#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 register addresses
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAZ0 0x36

// Free-fall threshold
#define FREEFALL_THRESHOLD 0.2f

// GPIO pin for alarm
#define ALARM_GPIO 27

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the ADXL345
int init_adxl345() {
    // Enable the accelerometer (ODR = 100 Hz)
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    // Set free-fall detection to active mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to detect free-fall
int detect_freefall(int16_t x, int16_t y, int16_t z) {
    return (fabs(x) < FREEFALL_THRESHOLD || fabs(y) < FREEFALL_THRESHOLD || fabs(z) < FREEFALL_THRESHOLD);
}

// Function to log a free-fall event
void log_freefall(int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to set the alarm GPIO high
void set_alarm_high() {
    gpioWrite(ALARM_GPIO, 1);
}

// Function to set the alarm GPIO low
void set_alarm_low() {
    gpioWrite(ALARM_GPIO, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                log_freefall(x, y, z);
                set_alarm_high();
                gpioDelay(500000); // 5 seconds
                set_alarm_low();
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    set_alarm_low();
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

