#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIG_PULSE_DURATION 10 // us
#define TIMEOUT_ERROR_THRESHOLD 23000 // us
#define TIMEOUT_TIMEOUT_DURATION 200 // ms
#define TIMEOUT_TIMEOUT_COUNT 3

// Define mutex
#define MUTEX_NAME "distance_log_mutex"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Mutex
int distance_log_mutex = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *userdata);
void timeout_callback(int gpio, int level, uint32_t tick, void *userdata);
void log_distance(int distance_cm);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt callback function for rising edge of echo
void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    if (level == 1) {
        uint32_t pulse_start = tick;
        uint32_t pulse_end = tick;

        // Get current timestamp with nanosecond precision
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Get current tick count
        uint32_t current_tick = gpioTick();

        // Calculate pulse duration in nanoseconds
        uint32_t pulse_duration = (pulse_end - pulse_start) * 1000000;

        // Check for timeout
        if (pulse_duration > TIMEOUT_TIMEOUT_DURATION) {
            fprintf(stderr, "Timeout detected: Echo pulse duration exceeds timeout threshold.\n");
            log_distance(0); // Log timeout error
            return;
        }

        // Log distance
        log_distance(pulse_duration);
    }
}

// Interrupt callback function for falling edge of echo
void timeout_callback(int gpio, int level, uint32_t tick, void *userdata) {
    if (level == 0) {
        uint32_t pulse_start = tick;
        uint32_t pulse_end = tick;

        // Get current timestamp with nanosecond precision
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Get current tick count
        uint32_t current_tick = gpioTick();

        // Calculate pulse duration in nanoseconds
        uint32_t pulse_duration = (pulse_end - pulse_start) * 1000000;

        // Check for timeout
        if (pulse_duration > TIMEOUT_TIMEOUT_DURATION) {
            fprintf(stderr, "Timeout detected: Echo pulse duration exceeds timeout threshold.\n");
            log_distance(0); // Log timeout error
            return;
        }

        // Log timeout error
        log_distance(0); // Log timeout error
    }
}

// Function to log distance to file
void log_distance(int distance_cm) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance_cm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Disable interrupts
    gpioSetISRFuncEx(TRIG_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    if (distance_log_mutex != 0) {
        gpioSetMutex(distance_log_mutex);
        gpioDelay(1000000); // Wait for mutex to be released
        gpioSetMutex(distance_log_mutex);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (gpioInitialiseMutex(distance_log_mutex) < 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupts
    gpioSetISRFuncEx(TRIG_PIN, RISING_EDGE, 0, echo_callback, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, timeout_callback, NULL);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100000); // Sleep for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(TRIG_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioSetMutex(distance_log_mutex);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

