#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG2 0x21
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Buzzer GPIO pin
#define BUZZER_PIN 17

// Free-fall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Impact threshold (g)
#define IMPACT_THRESHOLD 1.5

// Global variables
static int i2c_fd;
static int freefall_detected = 0;
static int impact_detected = 0;
static int buzzer_on = 0;
static int override_freefall = 0;
static int override_impact = 0;
static int i2c_address = LIS3DH_ADDR;
static int i2c_bus = -1;

// Function prototypes
int lis3dh_init(int i2c_bus, int i2c_address);
int lis3dh_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
int lis3dh_check_freefall(int fd, int16_t x, int16_t y, int16_t z);
int lis3dh_check_impact(int fd, int16_t x, int16_t y, int16_t z);
void buzzer_on(int pin);
void buzzer_off(int pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (buzzer_on) {
        buzzer_off(BUZZER_PIN);
    }
    exit(0);
}

// Initialize the LIS3DH sensor
int lis3dh_init(int i2c_bus, int i2c_address) {
    int fd;

    // Open I2C device
    fd = wiringPiI2CSetup(i2c_address);
    if (fd == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Configure the sensor (example configuration)
    // Refer to the LIS3DH datasheet for the correct register settings
    // For example, to enable free-fall detection:
    if (wiringPiI2CWriteReg8(fd, LIS3DH_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Configure free-fall detection (example)
    if (wiringPiI2CWriteReg8(fd, LIS3DH_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

// Read acceleration data from the LIS3DH sensor
int lis3dh_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int16_t x_l, x_h, y_l, y_h, z_l, z_h;

    // Read X, Y, and Z axes data
    x_l = wiringPiI2CReadReg8(fd, LIS3DH_OUT_X_L);
    x_h = wiringPiI2CReadReg8(fd, LIS3DH_OUT_X_H);
    y_l = wiringPiI2CReadReg8(fd, LIS3DH_OUT_Y_L);
    y_h = wiringPiI2CReadReg8(fd, LIS3DH_OUT_Y_H);
    z_l = wiringPiI2CReadReg8(fd, LIS3DH_OUT_Z_L);
    z_h = wiringPiI2CReadReg8(fd, LIS3DH_OUT_Z_H);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Check if free-fall is detected
int lis3dh_check_freefall(int fd, int16_t x, int16_t y, int16_t z) {
    int16_t magnitude = (x * x + y * y + z * z);

    // Check if the magnitude is below the free-fall threshold
    if (magnitude < FREEFALL_THRESHOLD) {
        freefall_detected = 1;
        return 1; // Free-fall detected
    } else {
        freefall_detected = 0;
        return 0; // Free-fall not detected
    }
}

// Check if impact is detected
int lis3dh_check_impact(int fd, int16_t x, int16_t y, int16_t z) {
    int16_t magnitude = (x * x + y * y + z * z);

    // Check if the magnitude is above the impact threshold
    if (magnitude > IMPACT_THRESHOLD) {
        impact_detected = 1;
        return 1; // Impact detected
    } else {
        impact_detected = 0;
        return 0; // Impact not detected
    }
}

// Activate the buzzer
void buzzer_on(int pin) {
    digitalWrite(pin, HIGH);
    printf("Buzzer ON\n");
}

// Deactivate the buzzer
void buzzer_off(int pin) {
    digitalWrite(pin, LOW);
    printf("Buzzer OFF\n");
}

// Initialize the LIS3DH sensor
int lis3dh_init(int i2c_bus, int i2c_address) {
    int fd;

    // Open I2C device
    fd = wiringPiI2CSetup(i2c_address);
    if (fd == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Configure the sensor (example configuration)
    // For example, to enable free-fall detection:
    if (wiringPiI2CWriteReg8(fd, LIS3DH_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Configure free-fall detection (example)
    if (wiringPiI2CWriteReg8(fd, LIS3DH_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

int main(int argc, char *argv[]) {
    int opt;
    int override_freefall_arg = 0;
    int override_impact_arg = 0;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "f:i:b:")) != -1) {
        switch (opt) {
            case 'f':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                i2c_bus = atoi(optarg);
                break;
            case 'b':
                buzzer_on = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f i2c_address] [-i i2c_bus] [-b buzzer_on]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(i2c_address);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the LIS3DH sensor
    if (lis3dh_init(i2c_bus, i2c_address) == -1) {
        fprintf(stderr, "Error initializing LIS3DH sensor.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read acceleration data
        if (lis3dh_read_acceleration(i2c_fd, &x, &y, &z) == -1) {
            fprintf(stderr, "Error reading acceleration data.\n");
            continue; // Skip to the next iteration
        }

        // Check for free-fall and impact
        if (lis3dh_check_freefall(i2c_fd, x, y, z) == 1) {
