#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define THRESHOLD 2.0f
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "/var/log/high_acceleration.log"

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int read_accelerometer(accelerometer_data_t *data);
float process_accelerometer_data(accelerometer_data_t data);
void log_acceleration(float x, float y, float z);
void send_data_to_server(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(accelerometer_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g's (assuming +/- 2g range)
    data->x = (float)raw_x / 16384.0f; // 12-bit resolution
    data->y = (float)raw_y / 16384.0f;
    data->z = (float)raw_z / 16384.0f;

    return 0;
}

// Process accelerometer data
float process_accelerometer_data(accelerometer_data_t data) {
    float x = data.x;
    float y = data.y;
    float z = data.z;

    // Apply threshold check
    if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
        return 0.0f; // Return 0 if any axis exceeds threshold
    }

    return x + y + z;
}

// Log acceleration data to file
void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", s, x, y, z);
    fclose(fp);
}

// Send data to server
void send_data_to_server(float x, float y, float z) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%.2f,%.2f,%.2f", x, y, z);

    if (sendto(sockfd, buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                LIS3DH_ADDR = strtol(optarg, NULL, 16);
                break;
            case 't':
                THRESHOLD = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set CTRL_REG1 to enable accelerometer and set range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x10) != 0) { // Enable accelerometer, +/- 2g
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        cleanup();
        return 1;
    }

    // Set CTRL_REG4 to enable high-resolution 12-bit data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) != 0) { // Enable high-resolution mode
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        cleanup();
        return 1;
    }

    // Set CTRL_REG1 to start continuous data acquisition
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) != 0) { // Start continuous data acquisition
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        cleanup();
        return 1;
    }

    // Set CTRL_REG4 to set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) != 0) { // Set data rate to 100 Hz
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        cleanup();
        return 1;
    }

    // Set CTRL_REG1 to enable high-resolution 12-bit data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) != 0) { // Enable high-resolution mode
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        cleanup();
        return 1;
    }

    // Set threshold
    if (set_threshold(THRESHOLD) != 0) {
        fprintf(stderr, "Error setting threshold\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data;
        if (read_accelerometer(&data) == 0) {
            float x = process_accelerometer_data(data);
            float y = process_accelerometer_data(data);
            float z = process_accelerometer_data(data);

            log_acceleration(x, y, z);
            send_data_to_server(x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        gpioDelay(100); // 100 Hz data rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

