#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define REG_MAG_X 0x00
#define REG_MAG_Y 0x02
#define REG_MAG_Z 0x04
#define REG_CONFIG 0x06
#define THRESHOLD 5.0f
#define RELAY_GPIO 17
#define I2C_RETRY_COUNT 50
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnetic_field(int16_t x, int16_t y, int16_t z);
void control_relay(int state);
void log_event(const char *event_type, float magnetic_field);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from Si7210
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, REG_MAG_X, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate magnetic field strength
float calculate_magnetic_field(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Control relay state
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log event to file
void log_event(const char *event_type, float magnetic_field) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - %s - %.2f mT\n", s, event_type, magnetic_field);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set relay to initial state (HIGH)
    control_relay(1); // Activate relay

    // Register signal handler
    signal(SIGINT, signal_handler);

    int retry_count = 0;
    int i2c_retry_count = 0;
    int i2c_retry_delay = I2C_RETRY_DELAY_MS;

    // Main loop
    while (program_running) {
        int16_t x, y, z;
        float magnetic_field;

        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate magnetic field
            magnetic_field = calculate_magnetic_field(x, y, z);

            // Check for timeout
            if (i2c_retry_count == I2C_RETRY_COUNT) {
                fprintf(stderr, "Timeout: Failed to read sensor data after %d retries.\n", I2C_RETRY_COUNT);
                i2c_retry_count = 0; // Reset retry count
                i2c_retry_delay = I2C_RETRY_DELAY_MS; // Retry delay
            } else {
                i2c_retry_count++;
            }

            // Check threshold
            if (magnetic_field > THRESHOLD) {
                // Control relay
                control_relay(1); // Activate relay
                log_event("Relay activated", magnetic_field);
                i2c_retry_delay = I2C_RETRY_DELAY_MS; // Retry delay
            } else {
                control_relay(0); // Deactivate relay
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            i2c_retry_count = 0; // Reset retry count
            i2c_retry_delay = I2C_RETRY_DELAY_MS; // Retry delay
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

