#include <pigpio.h>
#include <time.h>

#define RELAY_GPIO 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"

// Structure to hold relay state
typedef struct {
    int state;
    int last_state;
} RelayState;

RelayState relay_state = {0, 0};

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, relay_state.last_state); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to initialize the relay GPIO
int initialize_relay() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, relay_state.last_state); // Set initial state
    return 0;
}

// Function to read the relay state from a file
int read_relay_state() {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (fscanf(fp, "%d", &relay_state.state) != 1) {
        fprintf(stderr, "Error reading relay state from log file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to write the relay state to a file
int write_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Error opening log file for writing");
        return -1;
    }

    fprintf(fp, "%d", state);
    fclose(fp);
    return 0;
}

// Function to send a command to the server
int send_command(const char *command) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(PORT);

    // Convert IP address and port number to string
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return -1;
    }

    // Send command
    if (send(sockfd, command, strlen(command), 0) < 0) {
        perror("Send failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Function to read the relay state from the server
int read_relay_state_from_server() {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];
    int state;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(PORT);

    // Convert IP address and port number to string
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        return -1;
    }

    // Read relay state
    if (read(sockfd, buffer, sizeof(buffer)) < 0) {
        perror("Read failed");
        close(sockfd);
        return -1;
    }

    state = atoi(buffer);

    close(sockfd);
    return state;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_relay() != 0) {
        return 1;
    }

    // Read relay state from file
    if (read_relay_state() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read relay state from server
        int new_state = read_relay_state_from_server();
        if (new_state != relay_state.state) {
            relay_state.state = new_state;
            if (write_relay_state(new_state) != 0) {
                fprintf(stderr, "Failed to write new relay state\n");
            }
        }

        // Send command to server
        if (send_command("ON") != 0) {
            fprintf(stderr, "Failed to send ON command\n");
        }
        if (send_command("OFF") != 0) {
            fprintf(stderr, "Failed to send OFF command\n");
        }

        // Delay to avoid overwhelming the server
        sleep(1);
    }

    return 0;
}

