#define SENSOR2_ADDR 0x71

// Define GPIO pin for relay
#define RELAY_PIN 18

// Define I2C bus
#define I2C_BUS 1

// Define flow rate threshold (ml/min)
#define FLOW_THRESHOLD 5.0

// Define I2C handle
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_sensor(int i2c_handle, int address);
int validate_crc8(uint8_t data[], int data_len);
int control_relay(int gpio_pin, int state);
int log_flow_rate(int i2c_handle, int address, int flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 != -1) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 != -1) {
        i2cClose(i2c_handle2);
    }
    gpioWrite(RELAY_PIN, 0); // De-energize relay
    gpioTerminate();
    exit(0);
}

// Function to read data from the sensor
int read_sensor(int i2c_handle, int address) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from sensor at address 0x%02X: %d\n", address, bytes_read);
        return -1;
    }

    uint8_t data[2];
    memcpy(data, buf, 2);

    // Validate CRC-8
    if (!validate_crc8(data, 2)) {
        fprintf(stderr, "CRC-8 check failed for sensor at address 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Function to validate CRC-8
int validate_crc8(uint8_t data[], int data_len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[0]);
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to log flow rate to file
int log_flow_rate(int i2c_handle, int address, int flow_rate) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening flow_log.txt\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Sensor 1: %d, Sensor 2: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow_rate, flow_rate);

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin for relay as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1 at address 0x%02X: %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2 at address 0x%02X: %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read flow rates from both sensors
        int flow_rate1 = read_sensor(i2c_handle1, SENSOR1_ADDR);
        int flow_rate2 = read_sensor(i2c_handle2, SENSOR2_ADDR);

        if (flow_rate1 == -1 || flow_rate2 == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate flow rates
        if (flow_rate1 < 0 || flow_rate2 < 0) {
            fprintf(stderr, "Error: Invalid flow rate from sensor. Skipping.\n");
            continue;
        }

        // Check if both sensors are below the threshold
        if (flow_rate1 < FLOW_THRESHOLD && flow_rate2 < FLOW_THRESHOLD) {
            // Control the relay
            if (control_relay(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Error controlling relay.\n");
            }
        } else {
            // De-energize the relay if both sensors are above the threshold
            if (control_relay(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Error controlling relay.\n");
            }
        }

        // Log the flow rates
        if (log_flow_rate(i2c_handle1, SENSOR1_ADDR, flow_rate1) != 0) {
            fprintf(stderr, "Error logging flow rate.\n");
        }
        if (log_flow_rate(i2c_handle2, SENSOR2_ADDR, flow_rate2) != 0) {
            fprintf(stderr, "Error logging flow rate.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is de-energized
    gpioTerminate();
    return 0;
}

