#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define RAIN_THRESHOLD 500  // Example threshold
#define MOTOR_DURATION 5    // Motor duration in seconds
#define LOG_FILE "/var/log/rain_window.log"

// Global variables
static volatile int rain_detected = 0;
static volatile int motor_running = 0;
static volatile int rain_detected_count = 0;
static volatile int rain_detected_last_poll = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int direction) {
    if (direction == 1) {
        gpioWrite(MOTOR_ENA_PIN, 1); // ENA high
        gpioWrite(MOTOR_IN1_PIN, 1);  // IN1 high
        gpioWrite(MOTOR_IN2_PIN, 0); // IN2 low
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0); // ENA low
        gpioWrite(MOTOR_IN1_PIN, 0);  // IN1 low
        gpioWrite(MOTOR_IN2_PIN, 1); // IN2 high
    }
}

// Function to log events with syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    motor_running = 0; // Stop the motor
    gpioWrite(MOTOR_ENA_PIN, 0); // Ensure ENA is low
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Rain window system started");

    // Main loop
    while (1) {
        // Read rain sensor
        int rain_detected_now = read_rain_sensor();

        // Check if rain is detected
        if (rain_detected_now == 0) {
            if (rain_detected_count == 0) {
                // Start the motor
                control_motor(1);
                rain_detected_count = 1;
                rain_detected_last_poll = gpioTick();
            } else {
                // Wait for the sensor to dry
                while (rain_detected_now == 0 && rain_detected_count > 0) {
                    gpioDelay(100); // Check every 100ms
                    rain_detected_now = read_rain_sensor();
                    if (rain_detected_now == 0) {
                        rain_detected_count--;
                    }
                }
                if (rain_detected_now == 0) {
                    // Stop the motor
                    control_motor(0);
                    rain_detected_count = 0;
                    rain_detected_last_poll = 0;
                    log_event("Rain detected, starting motor");
                }
            }
        } else {
            // Stop the motor
            control_motor(0);
            rain_detected_count = 0;
            rain_detected_last_poll = 0;
            log_event("Rain detected, stopping motor");
        }

        // Wait for the next poll
        gpioDelay(200); // 200ms
    }

    return 0;
}

