#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_MS 2000
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_bh1750(int i2c_handle);
float calculate_lux(int raw_value);
void control_grow_light(int lux_value);
void log_data(float lux_value);
void signal_handler(int signal);
int initialize_i2c(int bus, int addr);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read data from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int raw_value;

    // Trigger continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 10ms)
    gpioDelay(10);

    // Read 2 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Function to calculate lux value
float calculate_lux(int raw_value) {
    // BH1750 datasheet formula: lux = (raw_value / 1.2) * 1000
    return (float)raw_value / 1.2 * 1000.0;
}

// Function to control the grow light relay
void control_grow_light(int lux_value) {
    if (lux_value < 150) {
        gpioWrite(RELAY_PIN, 1); // Activate relay
    } else {
        gpioWrite(RELAY_PIN, 0); // Deactivate relay
    }
}

// Function to log data to file
void log_data(float lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(1, BH1750_ADDR);
    if (i2c_handle < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_bh1750(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        float lux_value = calculate_lux(raw_value);
        log_data(lux_value);
        control_grow_light(lux_value);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

