#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <unistd.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_RECONNECT_INTERVAL 5
#define GPIO_PIN 17
#define RELAY_ON "ON"
#define RELAY_OFF "OFF"
#define RELAY_STATE_FILE "/sys/class/gpio/gpio17/state"
#define RELAY_STATE_FILE_LOCK "relay_state_lock"

// Global variables
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function prototypes
int initialize_gpio();
int initialize_mqtt();
void cleanup_gpio();
void cleanup_mqtt();
void signal_handler(int signal);
int connect_mqtt();
void subscribe_mqtt();
void publish_mqtt(const char *payload);
void cleanup_mqtt_client();
void cleanup_gpio();
void log_message(int severity, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set GPIO17 to LOW initially
    return 0;
}

// Function to initialize MQTT
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioWrite(GPIO_PIN, 0); // Set GPIO17 to LOW
    gpioTerminate();
}

// Function to cleanup MQTT
void cleanup_mqtt() {
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

// Function to log messages
void log_message(int severity, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(severity, "%s - %s", timestamp, message);
}

// Function to connect to MQTT broker
int connect_mqtt() {
    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Function to subscribe to MQTT topic
void subscribe_mqtt() {
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
        return;
    }
}

// Function to publish payload to MQTT broker
void publish_mqtt(const char *payload) {
    int rc = mosquitto_publish(mosq, NULL, RELAY_STATE_FILE, strlen(payload), (const unsigned char *)payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to publish payload to MQTT broker: %s", mosquitto_strerror(rc));
        return;
    }
}

// Function to cleanup MQTT client
void cleanup_mqtt_client() {
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioWrite(GPIO_PIN, 0); // Set GPIO17 to LOW
    gpioTerminate();
}

int main() {
    // Initialize syslog
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        log_message(LOG_ERR, "MQTT initialization failed, exiting");
        cleanup_gpio();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        // Connect to MQTT broker
        if (connect_mqtt() != 0) {
            log_message(LOG_ERR, "Failed to connect to MQTT broker, retrying...");
            sleep(5);
            continue;
        }

        // Subscribe to MQTT topic
        subscribe_mqtt();

        // Main loop
        while (running) {
            // Get current relay state
            char payload[100];
            FILE *fp = fopen(RELAY_STATE_FILE, "r");
            if (fp == NULL) {
                log_message(LOG_ERR, "Failed to open relay state file, using default state");
                fclose(fp);
                sleep(5);
                continue;
            }

            if (fgets(payload, sizeof(payload), fp) != NULL) {
                fclose(fp);
                char *state = strtok(payload, "\n");
                if (state != NULL) {
                    if (strcmp(state, RELAY_ON) == 0) {
                        // Set GPIO17 HIGH
                        gpioWrite(GPIO_PIN, 1);
                        log_message(LOG_INFO, "Relay ON");
                    } else if (strcmp(state, RELAY_OFF) == 0) {
                        // Set GPIO17 LOW
                        gpioWrite(GPIO_PIN, 0);
                        log_message(LOG_INFO, "Relay OFF");
                    } else {
                        log_message(LOG_ERR, "Invalid relay state: %s", state);
                    }
                } else {
                    log_message(LOG_ERR, "Failed to read relay state file");
                }
            } else {
                log_message(LOG_ERR, "Failed to read relay state file, using default state");
            }

            // Publish payload to MQTT broker
            publish_mqtt(payload);

            // Sleep for 5 seconds
            sleep(5);
        }

        // Cleanup MQTT client
        cleanup_mqtt_client();

        // Cleanup GPIO
        cleanup_gpio();

        // Log cleanup messages
        log_message(LOG_INFO, "Relay controller stopped");
        closelog();
        return 0;
    }

    // Cleanup resources before exiting
    cleanup_mqtt_client();
    cleanup_gpio();
    return 0;
}

