// Define GPIO pins
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23
#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

// Define constants
#define TICKS_PER_REVOLUTION 64
#define PWM_FREQUENCY 100000 // Hz
#define MAX_PWM_VALUE 255
#define MAX_PWM_DUTY_CYCLE_PER_REVOLUTION (TICKS_PER_REVOLUTION / TICKS_PER_REVOLUTION / PWM_FREQUENCY)
#define STALL_THRESHOLD_SEC 2.0 // Seconds
#define STALL_THRESHOLD_COUNT_HIGH_COUNT 100
#define STALL_THRESHOLD_COUNT_LOW_COUNT 50

// Define motor parameters
#define MOTOR_A_SPEED_RPM 50
#define MOTOR_B_SPEED_RPM 50

// Define PI controller parameters
#define PI_GAIN 0.1
#define PI_DELAY 0.1 // 100ms

// Define SPI channel
#define SPI_CHANNEL 0

// Global variables
volatile bool motor_a_running = false;
volatile bool motor_b_running = false;
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int stall_count_a = 0;
volatile int stall_count_b = 0;

