void stop_motors();
void signal_handler(int signal);
void cleanup();

// Encoder phase detection
int detect_encoder_edge(int pin) {
    int edge = 0;
    int count = 0;
    int i;

    for (i = 0; i < 4; i++) {
        if (digitalRead(pin) == HIGH) {
            count++;
        }
        delayMicroseconds(1); // Small delay to avoid busy-waiting
        if (count == 4) {
            edge = 1;
            break;
        }
    }

    return edge;
}

// PID controller
void calculate_pid(int *encoder_a_ticks, int *encoder_b_ticks, int *stall_count_a, int *stall_count_b, int *pi_error, int *pi_output) {
    double error = 0.0;
    double integral = 0.0;
    double derivative = 0.0;

    integral += error;
    derivative = error - *pi_error;

    *pi_error = error;
    *pi_output = PI_GAIN * derivative + PI_DELAY;

    double output = *pi_output;

