    if (output < 0) output = 0;
    if (output > MAX_PWM_VALUE) output = MAX_PWM_VALUE;

    // Windup prevention
    if (output > MAX_PWM_DUTY_CYCLE_PER_REVOLUTION) {
        output = MAX_PWM_DUTY_CYCLE_PER_REVOLUTION;
    } else if (output < 0) {
        output = 0;
    }

