    if (output > MAX_PWM_VALUE) output = MAX_PWM_VALUE;
    if (output < 0) output = 0;

    // Update encoder ticks
    encoder_a_ticks += output;
    encoder_b_ticks += output;

    // Check for stall
    if (encoder_a_ticks == 0) {
        stall_count_a++;
