    encoder_a_ticks -= output;
    encoder_b_ticks -= output;

    // Limit PWM duty cycle to 0-255
    if (encoder_a_ticks < 0) encoder_a_ticks = 0;
    if (encoder_a_ticks > MAX_PWM_VALUE) encoder_a_ticks = MAX_PWM_VALUE;
    if (encoder_b_ticks < 0) encoder_b_ticks = 0;
    if (encoder_b_ticks > MAX_PWM_VALUE) encoder_b_ticks = MAX_PWM_VALUE;

    // Update motor speeds
    set_motor_speed(MOTOR_A_PWM, MOTOR_B_PWM, MOTOR_A_DIR, MOTOR_B_DIR);
}

