#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define LED_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define DARK_THRESHOLD 50
#define LIGHT_THRESHOLD 200
#define I2C_BUS 1
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_bh1750(int i2c_handle);
int control_led(int gpio_pin, int state);
int log_data(int lux, int relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes to get the lux value
    int lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Control the LED strip
int control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Log data to file
int log_data(int lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Lux: %d, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int lux = read_bh1750(i2c_handle);
        if (lux >= 0) {
            printf("Lux: %d\n", lux);

            if (lux < DARK_THRESHOLD && relay_state == 0) {
                printf("Dusk detected, turning relay ON\n");
                control_led(LED_PIN, 1);
                gpioDelay(500000); // 500ms
                control_led(LED_PIN, 0);
                gpioDelay(500000); // 500ms
                relay_state = 1;
            } else if (lux > LIGHT_THRESHOLD && relay_state == 1) {
                printf("Dawn detected, turning relay OFF\n");
                control_led(LED_PIN, 0);
                gpioDelay(500000); // 500ms
                relay_state = 0;
            }

            if (relay_state == 1) {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

