// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Define relay state
#define RELAY_OFF 0
#define RELAY_ON 1

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_touch_sensor(int gpio_pin);
int control_relay(int gpio_pin, int state);
int log_relay_state(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        control_relay(RELAY_PIN, RELAY_OFF); // Turn off the relay
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log the relay state
int log_relay_state(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Relay state: %s\n", timestamp, (relay_state == RELAY_ON) ? "ON" : "OFF");
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, depends on sensor)
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Touch-toggled relay program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor(TOUCH_SENSOR_PIN);

        if (touch_detected == RELAY_ON) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
            if (read_touch_sensor(TOUCH_SENSOR_PIN) == RELAY_OFF) {
                control_relay(RELAY_PIN, RELAY_ON);
                log_relay_state(RELAY_ON);
                printf("Touch detected, relay toggled ON\n");
            }
        } else if (touch_detected == RELAY_OFF) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
            if (read_touch_sensor(TOUCH_SENSOR_PIN) == RELAY_ON) {
                control_relay(RELAY_PIN, RELAY_ON);
                log_relay_state(RELAY_ON);
                printf("Touch detected, relay toggled OFF\n");
            }
        }

        gpioDelay(10 * 1000); // Sleep for 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(RELAY_PIN, RELAY_OFF); // Turn off the relay
    gpioTerminate(); // Release pigpio resources

    return 0;
}

