#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define FLOW_SENSOR_DEBOUNCE_TIME_MS 100
#define SOLENOID_OPEN_THRESHOLD_LPM 5.0
#define SOLENOID_CLOSED_THRESHOLD_LPM 4.5
#define LOG_FILE_NAME "water_flow.log"

// Global variables
static volatile int flow_count = 0;
static volatile int solenoid_state = 0; // 0 = closed, 1 = open
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int initialize_gpio();
int read_flow_sensor();
int control_solenoid(int state);
int log_data(int flow_lpm, int solenoid_state);
void *flow_sensor_isr(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set pull-up/down resistor on flow sensor pin (optional, depends on sensor)
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the flow sensor
int read_flow_sensor() {
    int pulse_count = gpioRead(FLOW_SENSOR_PIN);
    if (pulse_count < 0) {
        fprintf(stderr, "Error reading flow sensor\n");
        return -1;
    }
    return pulse_count;
}

// Function to control the solenoid valve
int control_solenoid(int state) {
    if (gpioWrite(SOLENOID_PIN, state) != 0) {
        fprintf(stderr, "Error writing to solenoid\n");
        return -1;
    }
    solenoid_state = state;
    return 0;
}

// Function to log data to the log file
int log_data(int flow_lpm, int solenoid_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    pthread_mutex_lock(&log_mutex);
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow: %d LPM, Solenoid: %d\n", timestamp, flow_lpm, solenoid_state);
    fflush(log_file); // Ensure data is written to disk immediately

    pthread_mutex_unlock(&log_mutex);
    return 0;
}

// Interrupt service routine (ISR) for the flow sensor
void *flow_sensor_isr(void *arg) {
    pthread_mutex_lock(&log_mutex);
    flow_count++;
    pthread_mutex_unlock(&log_mutex);

    gpioDelay(FLOW_SENSOR_DEBOUNCE_TIME_MS * 1000); // Debounce

    if (flow_count > 0) {
        flow_count = 0;
        if (read_flow_sensor() == 0) {
            if (solenoid_state == 0) {
                if (log_data(flow_lpm, solenoid_state) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                control_solenoid(0); // Close solenoid
            } else {
                if (log_data(flow_lpm, solenoid_state) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                control_solenoid(1); // Open solenoid
            }
        }
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&log_mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Create mutex
    if (pthread_mutex_init(&log_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up ISR for flow sensor
    if (pthread_create(&flow_sensor_thread, NULL, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error creating ISR thread\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

