#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default configuration values
#define DEFAULT_CONFIG_FILE "config.ini"

// Default TCP port
#define DEFAULT_TCP_PORT 12345

// Default TCP address
#define DEFAULT_TCP_ADDRESS "127.0.0.1"

// Default logging file
#define DEFAULT_LOG_FILE "dispensing_log.json"

// HX711 calibration factor
#define HX711_CALIBRATION_FACTOR 1.0

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24

// Servo PWM frequency
#define SERVO_FREQUENCY 50

// API call endpoint
#define API_ENDPOINT "http://localhost:12345/api/dispense"

// Global variables
static volatile int running = 1;
static int tcp_socket = -1;
static FILE *log_file = NULL;
static int log_fd = -1;

// Calibration factor
static float calibration_factor = HX711_CALIBRATION_FACTOR;

// Structure to hold configuration data
typedef struct {
    char *config_file;
    int tcp_port;
    char *tcp_address;
    char *log_file;
} Config;

// Function prototypes
int load_config(const char *filename, Config *config);
float read_hx711(int data_pin, int sck_pin);
float calibrate_weight(float raw_weight, float calibration_factor);
int send_api_request(const char *target_weight, float *actual_weight);
int log_event(const char *event_type, float target_weight, float actual_weight);
void signal_handler(int signal);
void cleanup();

// Function to load configuration from file
int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "config_file") == 0) {
                config->config_file = strdup(value);
            } else if (strcmp(key, "tcp_port") == 0) {
                config->tcp_port = atoi(value);
            } else if (strcmp(key, "tcp_address") == 0) {
                config->tcp_address = strdup(value);
            } else if (strcmp(key, "log_file") == 0) {
                config->log_file = strdup(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to read raw weight from HX711
float read_hx711(int data_pin, int sck_pin) {
    int i;
    int count = 0;
    int data = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    gpioWrite(sck_pin, 0);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 data pin not ready after %d attempts\n", 1000);
        return -1.0; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Convert to signed 24-bit integer
    int32_t raw_value = (int32_t)data;

    // Apply gain and offset
    raw_value = raw_value - 4; // Adjust gain and offset as needed

    // Scale to grams
    float weight = (float)raw_value / 1024.0 * calibration_factor;

    return weight;
}

// Function to calibrate weight using a known weight and calibration factor
float calibrate_weight(float raw_weight, float calibration_factor) {
    return raw_weight / calibration_factor;
}

// Function to send API request to the server
int send_api_request(const char *target_weight, float *actual_weight) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];
    int bytes_sent;
    char response[256];

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(TCP_PORT);
    if (inet_pton(AF_INET, TCP_ADDRESS, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error connecting to server");
        close(sockfd);
        return -1;
    }

    // Prepare request
    snprintf(buffer, sizeof(buffer), "{\"target_weight\": \"%s\", \"actual_weight\": %f}", target_weight, actual_weight);

    // Send request
    bytes_sent = send(sockfd, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        perror("Error sending request");
        close(sockfd);
        return -1;
    }

    // Receive response
    if (recv(sockfd, response, sizeof(response), 0) < 0) {
        perror("Error receiving response");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Function to log events to a JSON file
int log_event(const char *event_type, float target_weight, float actual_weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"event_type\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f}\n",
            timestamp, event_type, target_weight, actual_weight);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (tcp_socket != -1) {
        close(tcp_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config;
    float target_weight, actual_weight;
    float calibrated_weight;
    int i;

    // Load configuration
    if (load_config(config.config_file, &config) != 0) {
        fprintf(stderr, "Using default configuration: %s\n", config.config_file);
        config.tcp_port = DEFAULT_TCP_PORT;
        config.tcp_address = DEFAULT_TCP_ADDRESS;
        config.log_file = DEFAULT_LOG_FILE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HX711_FREQUENCY, SERVO_FREQUENCY);

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open socket
    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket < 0) {
        perror("Error creating socket");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read raw weight
        float raw_weight = read_hx711(HX711_DATA_PIN, HX711_SCK_PIN);
        if (raw_weight < 0) {
            fprintf(stderr, "Error reading HX711, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calibrate weight
        calibrated_weight = calibrate_weight(raw_weight, config.calibration_factor);

        // Send API request
        if (send_api_request(target_weight, &actual_weight) != 0) {
            fprintf(stderr, "Error sending API request\n");
        }

        // Log event
        if (log_event("dispensing", calibrated_weight, actual_weight) != 0) {
            fprintf(stderr, "Error logging event\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

