#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_MS 50
#define RELAY_ON_DURATION_MS 500
#define RELAY_OFF_DURATION_MS 1000
#define LOG_FILE "relay_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_init(int pin);
int read_touch_sensor();
int toggle_relay(int pin, int state);
int log_relay_state(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// GPIO initialization function
int gpio_init(int pin) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(pin, INPUT);
    pullUpDnControl(pin, PUD_UP); // Enable pull-up resistor
    return 0;
}

// Reads the touch sensor value
int read_touch_sensor() {
    return digitalRead(TOUCH_SENSOR_PIN);
}

// Toggles the relay state
int toggle_relay(int pin, int state) {
    digitalWrite(pin, state);
    return 0;
}

// Logs the relay state change to a file
int log_relay_state(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
