#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD 20 // us

// Define servo angles
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define servo pulse width range
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variables
static volatile int running = 1;
static int angle = 90; // Initial angle

// Function prototypes
int read_key();
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a key from the keyboard
int read_key() {
    int key = getchar();
    if (key == '\r') {
        return '\r'; // Ignore Enter key
    }
    return key;
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range: %d\n", angle);
        return;
    }

    // Calculate pulse width
    int pulse_width = (int)((angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    // Set PWM pulse width
    gpioPWM(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM period
    gpioSetPWMperiod(SERVO_PIN, PWM_PERIOD);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Servo control program. Press Enter to exit.\n");

    // Main loop
    while (running) {
        int key = read_key();

        if (key == 'q' || key == 'Q') {
            printf("Exiting...\n");
            break;
        }

        if (key == '+') {
            angle += 10;
            if (angle > 180) {
                angle = 180;
            }
        } else if (key == '-') {
            angle -= 10;
            if (angle < 0) {
                angle = 0;
            }
        }

        set_servo_angle(angle);

        printf("Angle: %d, Pulse Width: %d\n", angle, pulse_width);

        gpioDelay(100); // Delay for 100ms
    }

    // Stop PWM pulses
    gpioPWM(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

