#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_WINDOW_MS 2
#define RPM_LOG_FILE "motor_rpm.log"

volatile unsigned int pulse_count = 0;
volatile unsigned int last_pulse_time = 0;
volatile int debounce_flag = 1;

FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the RPM to a file
int log_rpm(const char *timestamp, float rpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to calculate RPM from pulse count
float calculate_rpm(unsigned int pulse_count) {
    return (float)pulse_count / (float)DEBOUNCE_WINDOW_MS * 60.0;
}

// Function to handle signals (e.g., SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen(RPM_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", RPM_LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring RPM on GPIO %d...\n", GPIO_PIN);

    // Main loop
    while (1) {
        // Read pulse count
        unsigned int current_pulse_count = pulse_count;

        // Debounce the pulse count
        if (current_pulse_count > last_pulse_time && debounce_flag) {
            pulse_count = current_pulse_count;
            debounce_flag = 0;
        } else {
            debounce_flag = 1;
        }

        // Calculate RPM
        float rpm = calculate_rpm(pulse_count);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log RPM
        if (log_rpm(timestamp, rpm) != 0) {
            fprintf(stderr, "Error logging RPM.\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

