// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_GPIO 24
#define PWM_FREQUENCY 1000 // Hz

// Define constants
#define FLOW_RATE_SCALE 0.1 // L/min to PWM duty cycle (0-255)
#define PWM_RANGE 255
#define PWM_PERIOD 1 // us
#define PWM_FREQUENCY_SCALE 100 // Hz
#define PWM_PERIOD_SCALE 100 // us
#define FLOW_SENSOR_INTERRUPT_RANGE 1024
#define FLOW_SENSOR_INTERRUPT_PERIOD_RANGE (FLOW_SENSOR_INTERRUPT_RANGE / PWM_FREQUENCY)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int initialize_pigpio();
int initialize_flow_sensor();
int initialize_pwm();
void cleanup_gpio();
void cleanup_pigpio();
int initialize_flow_sensor_interrupt();
int read_flow_sensor();
float calculate_flow_rate(int pulse_count);
void set_pwm_duty_cycle(float flow_rate);
