// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);
    gpioSetPWMrange(VALVE_ENABLE_PIN, PWM_RANGE);

    return 0;
}

