#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RFID tag structure
typedef struct {
    unsigned char tag[10];
} rfid_tag_t;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_rfid_tag(rfid_tag_t *tag);
int check_rfid_tag(const rfid_tag_t *tag);
int check_button_press();
int engage_locks();
int disengage_locks();
int log_access_attempt(const rfid_tag_t *tag);
void signal_handler(int signal);

// Global variables
int spi_handle;
FILE *log_file;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read RFID tag data
int read_rfid_tag(rfid_tag_t *tag) {
    char tx_buf[1] = {0x01}; // Example: Start bit
    char rx_buf[1] = {0x00}; // Example: End bit

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 1);
    if (result != 1) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    // Extract 10 bytes from the received data
    for (int i = 0; i < 10; i++) {
        tag->tag[i] = rx_buf[i];
    }

    return 0;
}

// Function to check RFID tag
int check_rfid_tag(const rfid_tag_t *tag) {
    if (memcmp(tag->tag, "1234567890", 10) != 0) {
        fprintf(stderr, "Invalid tag: %s\n", tag->tag);
        return -1;
    }
    return 0;
}

// Function to check button press
int check_button_press() {
    int button_value = gpioRead(BUTTON_PIN);
    if (button_value == 0) {
        return 1; // Button is pressed
    } else {
        return 0; // Button is not pressed
    }
}

// Function to engage locks
int engage_locks() {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    gpioDelay(5000000); // 5 seconds
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    return 0;
}

// Function to disengage locks
int disengage_locks() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    return 0;
}

// Function to log access attempt
int log_access_attempt(const rfid_tag_t *tag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - RFID Tag: %s, Button Press: %s\n", timestamp, tag->tag, check_button_press() ? "Yes" : "No");
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_access_attempt(NULL); // Log the event
    disengage_locks();
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (1) {
        rfid_tag_t tag;
        if (read_rfid_tag(&tag) == 0) {
            if (check_rfid_tag(&tag) == 0) {
                printf("Access granted!\n");
                log_access_attempt(&tag);
                if (check_button_press() == 1) {
                    printf("Button pressed! Engaging locks...\n");
                    engage_locks();
                    log_access_attempt(&tag);
                }
            } else {
                printf("Invalid tag! Engaging locks...\n");
                engage_locks();
                log_access_attempt(&tag);
            }
        } else {
            fprintf(stderr, "Error reading RFID tag!\n");
            log_access_attempt(NULL); // Log the error
        }

        gpioDelay(100000); // Check every 100ms
    }

    return 0;
}

