#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the solenoid valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Define the water distribution schedule
#define WATER_DISTRIBUTION_SCHEDULE "1,500ms,5s,1,1000ms,10s"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log an event to the log file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Activate valve
    gpioDelay(duration_ms); // Wait for specified duration
    gpioWrite(gpio_pin, 0); // Deactivate valve
}

// Function to log a message to the log file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Set GPIO pins as HIGH initially
    gpioWrite(VALVE1_GPIO, 1);
    gpioWrite(VALVE2_GPIO, 1);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Get the water distribution schedule
        char *schedule = strtok(WATER_DISTRIBUTION_SCHEDULE, ",");
        char *endptr;
        int duration_ms = 0;

        // Parse the schedule string
