#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define rate limiting parameters
#define UNLOCK_DURATION 500
#define RATE_LIMIT_DURATION 2000
#define RATE_LIMIT_INTERVAL 1000 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int state);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, event_type);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            printf("Motion detected!\n");
            log_event("Motion");

            // Activate relay for 500ms
            control_relay(1);
            gpioDelay(UNLOCK_DURATION * 1000); // Convert milliseconds to microseconds
            control_relay(0);

            // Rate limiting
            gpioDelay(RATE_LIMIT_INTERVAL * 1000); // Convert milliseconds to microseconds
        } else if (pir_value == 0) {
            printf("No motion detected.\n");
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

