    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            printf("Motion detected!\n");
            log_event("Motion");

            // Activate relay for 500ms
            control_relay(1);
            gpioDelay(UNLOCK_DURATION * 1000); // Convert milliseconds to microseconds
