#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define HX711_SCALE_FACTOR 1.0  // Example scale factor
#define HX711_OFFSET 0.0       // Example offset
#define SOLENOID_GPIO 27
#define READ_TIMEOUT 0.5       // Seconds
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_FILE "calibration.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Calibration data structure
typedef struct {
    float scale_factor;
    float offset;
} CalibrationData;

// Calibration data structure
CalibrationData calibration_data = {HX711_SCALE_FACTOR, HX711_OFFSET};

// Function prototypes
int initialize_gpio();
int read_hx711(int data_pin, int clock_pin, float *weight);
float calculate_weight(float raw_value, float scale_factor, float offset);
void control_solenoid(int gpio_pin, int state);
void log_reading(float weight);
void load_calibration_data(const char *filename, CalibrationData *calibration);
void save_calibration_data(const char *filename, const CalibrationData *calibration);
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);
    gpioSetMode(HX711_SCALE_FACTOR, PI_INPUT);
    gpioSetMode(HX711_OFFSET, PI_INPUT);

    return 0;
}

// Function to read data from HX711
int read_hx711(int data_pin, int clock_pin, float *weight) {
    int i;
    int count = 0;
    int data = 0;
    int bit = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for HX711 to be ready (adjust as needed)
    gpioDelay(1); // Small delay

    // Read clock pulses
    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    // Apply gain and offset
    data = data - calibration_data.offset;
    data = data * calibration_data.scale_factor;

    // Convert to float
    *weight = (float)data;

    return 0;
}

// Function to calculate weight
float calculate_weight(float raw_value, float scale_factor, float offset) {
    return raw_value + offset;
}

// Function to control the solenoid lock
void control_solenoid(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log reading to file
void log_reading(float weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
void load_calibration_data(const char *filename, CalibrationData *calibration) {
    if (fopen(filename, "r") == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s\n", filename);
        return;
    }

    fscanf(calibration_file, "%f,%f", &calibration->scale_factor, &calibration->offset);
    fclose(calibration_file);
}

// Function to save calibration data to file
void save_calibration_data(const char *filename, const CalibrationData *calibration) {
    fprintf(calibration_file, "%.2f,%f\n", calibration->scale_factor, calibration->offset);
    fclose(calibration_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    float weight;
    int retry_count = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration data
    load_calibration_data(CALIBRATION_FILE, &calibration_data);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Open calibration file
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s\n", CALIBRATION_FILE);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read HX711 sensor
        if (read_hx711(HX711_SCALE_FACTOR, HX711_OFFSET, &weight) != 0) {
            fprintf(stderr, "Error reading HX711\n");
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Maximum retry limit reached. Exiting.\n");
                running = 0; // Exit loop if maximum retry limit reached
            }
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate weight
        weight = calculate_weight(weight, calibration_data.scale_factor, calibration_data.offset);

        // Control solenoid
        control_solenoid(SOLENOID_GPIO, 1); // Activate solenoid
        gpioDelay(100); // Delay for solenoid activation
        control_solenoid(SOLENOID_GPIO, 0); // Deactivate solenoid

        // Log reading
        log_reading(weight);

        // Wait for read timeout
        if (retry_count > 0) {
            retry_count = 0; // Reset retry count
            gpioDelay(READ_TIMEOUT * 1000); // Wait for read timeout
        }
    }

    // Cleanup
    fclose(log_file);
    fclose(calibration_file);
    gpioTerminate();

    return 0;
}

