#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_ENABLE_PIN 27

// Define constants
#define RAIN_THRESHOLD 3
#define RAIN_DURATION 5
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define LOG_FILE "/var/log/window_control.log"

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_sensor(int sensor_value);
int control_motor(int motor_pin, int enable_pin, int direction, int pwm_duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the sensor
int debounce_sensor(int sensor_value) {
    // Debounce logic: Wait for a short period
    gpioDelay(50); // 50ms

    // Read the sensor again
    int new_value = gpioRead(RAIN_SENSOR_PIN);

    // Check if the sensor value has changed
    if (new_value != sensor_value) {
        return new_value; // Return the new value
    }

    return sensor_value; // Return the initial value
}

// Function to control the motor
int control_motor(int motor_pin, int enable_pin, int direction, int pwm_duty_cycle) {
    gpioWrite(enable_pin, 1); // Enable the motor
    gpioPWM(motor_pin, pwm_duty_cycle); // Set the PWM duty cycle
    gpioDelay(1000); // Wait for 1 second
    gpioWrite(enable_pin, 0); // Disable the motor
    gpioPWM(motor_pin, 0); // Set PWM to 0 to stop the motor
    return 0;
}

// Function to log events to syslog
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Program terminated by signal.");
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT);

    // Set PWM range for PWM enable pin
    gpioSetPWMrange(MOTOR_ENABLE_PIN, 255);

    // Set PWM frequency
