#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration factor threshold
#define CALIBRATION_THRESHOLD 5.0

// Define weight threshold
#define WEIGHT_THRESHOLD 5.0

// Define timeout duration (in microseconds)
#define TIMEOUT_DURATION 100000 // 100ms

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_hx711(int data_pin, int clock_pin, int *raw_value);
float calibrate_weight(int raw_value);
float calculate_weight(float raw_value, float calibration_factor);
void control_solenoid(int solenoid_pin, int duration_seconds);
void log_data(float weight, int raw_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Read data from HX711
int read_hx711(int data_pin, int clock_pin, int *raw_value) {
    int i;
    int bit_value = 0;

    gpioWrite(clock_pin, 0); // Ensure clock is low initially

    for (i = 0; i < 24; i++) {
        gpioWrite(data_pin, 1);
        gpioDelay(1); // Small delay to allow clock to rise
        bit_value = bit_value << 1;
        if (gpioRead(clock_pin)) {
            bit_value++;
        }
        gpioWrite(data_pin, 0);
        gpioDelay(1); // Small delay to allow clock to fall
    }

    *raw_value = bit_value;
    return 0;
}

// Calibrate weight from raw value
float calibrate_weight(int raw_value) {
    float calibration_factor = 1.0; // Default calibration factor
    int num_samples = 100; // Number of samples to average
    float sum = 0.0;
    int i;

    printf("Calibrating weight... Please place a known weight on the sensor.\n");
    for (i = 0; i < num_samples; i++) {
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return -1.0; // Indicate calibration error
        }
        sum += raw_value;
