#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// GPIO pin for the valve
#define VALVE_GPIO 18

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// Watering duration in seconds
#define WATERING_DURATION 3600

// Global variables
static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int valve_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_config_file(const char *filename, int *duration);
int write_config_file(const char *filename, int duration);
int read_watering_duration(int gpio_pin);
int set_valve_state(int gpio_pin, int state);
int read_valve_state(int gpio_pin);
void signal_handler(int signal);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);

// Function to read watering duration from configuration file
int read_config_file(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Check for duration=<seconds> line
        if (strncmp(line, "duration=", 8) == 0) {
            char *endptr;
            *duration = strtol(line + 8, &endptr, 10);
            if (*endptr != '\0' || *duration < 1 || *duration > 3600) {
                fprintf(stderr, "Error: Invalid watering duration: %d\n", *duration);
                fclose(fp);
                return -1;
            }
            break;
        }
    }

    fclose(fp);
    return 0;
}

// Function to write watering duration to configuration file
int write_config_file(const char *filename, int duration) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening config file for writing");
        return -1;
    }

    fprintf(fp, "duration=%d\n", duration);
    fclose(fp);
    return 0;
}

// Function to read watering duration from GPIO pin
int read_watering_duration(int gpio_pin) {
    int duration = 0;
    int fd;

    fd = open("/sys/class/gpio/gpio18/value", O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    char value_str[2];
    if (read(fd, value_str, 1) != 1) {
        perror("Error reading GPIO value");
        close(fd);
        return -1;
    }

    close(fd);

    if (value_str[0] == '1') {
        duration = WATERING_DURATION;
    } else {
        duration = 0;
    }

    return duration;
}

// Function to set the valve state
int set_valve_state(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to read the valve state
int read_valve_state(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    return value;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from SPI device
