// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PIN 22
#define RIGHT_MOTOR_PIN 23
#define PWM_PIN_LEFT 22
#define PWM_PIN_RIGHT 23
#define PWM_PIN_MIDDLE 24

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define motor speeds
#define MOTOR_SPEED_LEFT 150
#define MOTOR_SPEED_RIGHT 150

// Define control law parameters
#define SENSOR_THRESHOLD 0.5
#define MAX_SPEED_PWM 500
#define MIN_SPEED_PWM 500

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int calculate_speed(int sensor_value, int motor_pin);
void set_motor_speed(int motor_pin, int speed);
void log_data(int sensor_value, int motor_pin, int left_speed, int right_speed);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sensor pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Set motor pins as outputs
    gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN_LEFT, PI_OUTPUT);
    gpioSetMode(PWM_PIN_RIGHT, PI_OUTPUT);
    gpioSetMode(PWM_PIN_MIDDLE, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_LEFT, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_RIGHT, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_MIDDLE, PWM_FREQUENCY);

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Calculate motor speed based on sensor value
int calculate_speed(int sensor_value, int motor_pin) {
    if (sensor_value == 0) {
        return MOTOR_SPEED_LEFT;
    } else if (sensor_value == 1) {
        return MOTOR_SPEED_RIGHT;
    } else {
        return 0;
    }
}

// Set motor speed
void set_motor_speed(int motor_pin, int speed) {
    if (speed > MAX_SPEED_PWM) {
        speed = MAX_SPEED_PWM;
    } else if (speed < MIN_SPEED_PWM) {
        speed = MIN_SPEED_PWM;
    }

    gpioPWM(motor_pin, speed);
}

// Log data to file
void log_data(int sensor_value, int motor_pin, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, sensor_value, motor_pin, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Robot control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor_value = read_sensor(RIGHT_SENSOR_PIN);

        // Calculate motor speeds
        int left_speed = calculate_speed(left_sensor_value, LEFT_MOTOR_PIN);
        int right_speed = calculate_speed(right_sensor_value, RIGHT_MOTOR_PIN);

        // Set motor speeds
        set_motor_speed(LEFT_MOTOR_PIN, left_speed);
        set_motor_speed(RIGHT_MOTOR_PIN, right_speed);

        // Log data
        log_data(left_sensor_value, LEFT_MOTOR_PIN, left_speed, right_speed);

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

