#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
int log_data(int lux_value, int relay_state);
void control_relay(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char buf[2];
    int lux_value;

    // Send measurement command (high repeatability, clock stretching disabled)
    if (i2cWriteByte(i2c_handle, 0x10) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10);

    // Read two bytes of data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the lux value
    lux_value = (buf[0] << 8) | buf[1];

    return lux_value;
}

// Function to log data to file
int log_data(int lux_value, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, Lux: %d, Relay: %s\n", timestamp, lux_value, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    int lux_value, relay_state;
    int i2c_result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        lux_value = read_bh1750(i2c_handle);
        if (lux_value < 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d ms...\n", DELAY_MS);
            gpioDelay(DELAY_MS);
            continue;
        }

        relay_state = gpioRead(RELAY_GPIO);

        if (log_data(lux_value, relay_state) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        control_relay(RELAY_GPIO, relay_state);

        gpioDelay(DELAY_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(RELAY_GPIO, 0); // Turn off relay
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

