    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, Lux: %d, Relay: %s\n", timestamp, lux_value, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    int lux_value, relay_state;
    int i2c_result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        lux_value = read_bh1750(i2c_handle);
        if (lux_value < 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d ms...\n", DELAY_MS);
            gpioDelay(DELAY_MS);
            continue;
        }

        relay_state = gpioRead(RELAY_GPIO);

        if (log_data(lux_value, relay_state) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        control_relay(RELAY_GPIO, relay_state);

        gpioDelay(DELAY_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(RELAY_GPIO, 0); // Turn off relay
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

