#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo pulse width range
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_button(int gpio_pin);
int write_servo(int pulse_width);
void lock_door();
void unlock_door();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as output
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-up resistor on lock button pin
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    // Set pull-down resistor on unlock button pin
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_DOWN);

    return 0; // Indicate success
}

// Function to read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to write servo pulse width
int write_servo(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return 1; // Indicate failure
    }

    // Convert pulse width to microseconds
    int microseconds = (int)(pulse_width * 1000.0);

    // Set servo pulse width
    gpioServo(SERVO_PIN, microseconds);

    return 0; // Indicate success
}

// Function to lock the door
void lock_door() {
    if (write_servo(1000) != 0) {
        fprintf(stderr, "Failed to lock door\n");
    }
}

// Function to unlock the door
void unlock_door() {
    if (write_servo(2000) != 0) {
        fprintf(stderr, "Failed to unlock door\n");
    }
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_pressed = read_button(LOCK_BUTTON_PIN);
        int unlock_pressed = read_button(UNLOCK_BUTTON_PIN);

        // Debounce button presses
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

        if (lock_pressed) {
            lock_door();
        } else if (unlock_pressed) {
            unlock_door();
        }

        gpioDelay(100 * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

