    gpio_initialized = 1;
    return 0;
}

// Function to initialize MQTT
int initialize_mqtt() {
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return -1;
    }
    mosquitto_connect_callback_set(mqtt_client, network_loop);
    mosquitto_message_callback_set(mqtt_client, alert_callback);
    return 0;
}

