        syslog(LOG_ERR, "Invalid NEC checksum: checksum=0x%08X", frame->checksum);
        return -1;
    }
    return 0;
}

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick, void *userdata) {
    syslog(LOG_INFO, "Alert received on GPIO %d", gpio);
}

// Network loop function
void network_loop(void *userdata) {
    while (!terminate) {
        gpioDelay(100); // Check every 100ms
        if (gpioRead(GPIO_PIN) == 0) { // Rising edge
            // Decode NEC frame
            if (decode_nec_frame(&frame) == 0) {
                // Validate NEC frame
                if (validate_nec_frame(&frame) == 0) {
                    // Validate checksum
                    if (validate_checksum(&frame) == 0) {
