                        char command_str[32];
                        snprintf(command_str, sizeof(command_str), "{\"address\": 0x%08X, \"command\": 0x%08X}", frame.address, frame.command);
                        int rc = mosquitto_publish(mqtt_client, MQTT_TOPIC, strlen(command_str), (const uint8_t *)command_str, 0, false);
                        if (rc != MOSQ_ERR_SUCCESS) {
                            syslog(LOG_ERR, "Failed to publish command to MQTT: %s", mosquitto_strerror(rc));
                        } else {
                            syslog(LOG_INFO, "Published command: %s", command_str);
                        }
                    } else {
                        syslog(LOG_ERR, "Failed to validate checksum");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to validate NEC frame");
                }
            } else {
                syslog(LOG_ERR, "Failed to decode NEC frame");
            }
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
    }
    if (gpioInitialise()) {
        gpioTerminate();
    }
    syslog(LOG_INFO, "Cleanup complete");
}

int main() {
    // Open syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize NEC decoder
    if (initialize_nec_decoder() != 0) {
        syslog(LOG_ERR, "NEC decoder initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Set up alert callback
    gpioSetAlertFuncEx(GPIO_PIN, alert_callback, NULL);

    // Create network loop thread
    pthread_t network_thread;
    if (pthread_create(&network_thread, NULL, network_loop, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create network thread");
        cleanup();
        return 1;
    }

    // Wait for termination signal
    while (!terminate) {
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    pthread_join(network_thread, NULL);

    return 0;
}

