#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <time.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/mman.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_COUNT 4
#define UDP_SOCKET_PORT 5005
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define MAX_SENSORS 4
#define MAX_I2C_ADDR 0x10
#define I2C_ADDR_REG 0x00
#define DATA_REG 0x06
#define CONVERSION_COMMAND 0x10
#define RETRY_COUNT 3

// Global variables
int i2c_fd;
int udp_socket;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor(int fd, int sensor_id);
float convert_lux(int raw_value);
void broadcast_udp_packet(const sensor_data_t *data, int num_sensors);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from a single sensor
int read_sensor(int fd, int sensor_id) {
    int raw_value = read(fd, DATA_REG, 1);
    if (raw_value < 0) {
        perror("Failed to read sensor data");
        return -1;
    }
    return raw_value;
}

// Convert raw lux value to lux
