#include <pigpio.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x40
#define FLOW_REG 0x00
#define FLOW_RATE_REG 0x01
#define FLOW_RATE_MIN 0x0000
#define FLOW_RATE_MAX 0xFFFF
#define FLOW_RATE_SCALE 0.01 // SLPM/LSB
#define LOG_FILE "airflow_log.txt"

int i2c_handle;
FILE *log_file;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SENSOR_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a zero-length I2C write
int write_zero_length_i2c(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read two bytes from the I2C bus
int read_two_bytes(int handle, int reg, int *low, int *high) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)high, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    *high = (high[0] << 8) | high[1];
    *low = (low[0] << 8) | low[1];
    return 0;
}

// Function to convert raw flow data to SLPM
float convert_flow_to_slpm(int raw_flow) {
    return (float)raw_flow * FLOW_RATE_SCALE;
}

// Function to log data to a file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_flow_low, raw_flow_high;
    float flow_rate;

    // Main loop
    while (1) {
        // Write zero-length I2C write
        if (write_zero_length_i2c(i2c_handle, FLOW_REG, 0) != 0) {
            fprintf(stderr, "Failed to write to I2C. Retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Read two bytes from I2C
        if (read_two_bytes(i2c_handle, FLOW_REG, &raw_flow_low, &raw_flow_high) != 0) {
            fprintf(stderr, "Failed to read from I2C. Retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert raw flow to SLPM
        flow_rate = convert_flow_to_slpm(raw_flow_high << 8 | raw_flow_low);

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Failed to log data. Retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

