#define CSV_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILE "seismic_error.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *csv_file;
FILE *error_log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SENSOR_ADDRESS, 0); // Bus 1, address 0x0A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        log_error("Error opening I2C");
        return -1;
    }
    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadDevice(i2c_handle, buffer, 6) == 6) {
            data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
            data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
            data.z = (int16_t)((buffer[4] << 8) | buffer[5]);
            return data;
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, i2c_handle);
            log_error("I2C read error");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    log_error("Failed to read sensor data after retries");
    return sensor_data_t{0, 0, 0}; // Return default values on failure
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written to file immediately

    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                SENSOR_ADDRESS = strtol(optarg, NULL, 0);
                break;
            case 'i':
                SAMPLE_INTERVAL = strtol(optarg, NULL, 0);
                break;
            case 'f':
                CSV_FILENAME = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILENAME);
        cleanup();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", ERROR_LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        sensor_data_t data = read_sensor_data();

        if (data.x != 0 || data.y != 0 || data.z != 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

