#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_MULTICAST_PORT 5000
#define TTL 1
#define RETRY_DELAY_MS 1000

int i2c_fd;
int udp_socket;

// Function to handle signals (SIGINT and SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the BH1750 sensor value
int read_bh1750(int fd) {
    unsigned char buf[2];
    int raw_value;

    // Send measurement command (high repeatability, clock stretching disabled)
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    usleep(10000);

    // Read two bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Function to convert raw value to lux
float convert_to_lux(int raw_value) {
    // Formula from BH1750 datasheet
    return (float)raw_value / 1.2;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *address, int port, float lux) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(address);
    addr.sin_port = htons(port);

    if (sendto(udp_socket, (const char *)&lux, sizeof(float), 0, (const struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP packet");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set TTL to 1
    if (setsockopt(udp_socket, IPPROTO_IP, IP_TTL, &TTL, sizeof(TTL)) < 0) {
        perror("Failed to set TTL");
        close(i2c_fd);
        close(udp_socket);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int raw_value = read_bh1750(i2c_fd);
        if (raw_value >= 0) {
            float lux = convert_to_lux(raw_value);
            if (send_udp_multicast(UDP_MULTICAST_ADDR, UDP_MULTICAST_PORT, lux) != 0) {
                fprintf(stderr, "Failed to send UDP packet\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor\n");
        }

        usleep(100000); // Wait 100ms
    }

    // Cleanup (should not reach here in normal execution due to signal handler)
    close(i2c_fd);
    close(udp_socket);
    gpioTerminate();

    return 0;
}

