#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define BUFFER_SIZE 1024
#define MAGIC_WORD_SIZE 8
#define MAX_OBJECTS 100
#define MAX_BUFFER_SIZE (MAX_OBJECTS * MAGIC_WORD_SIZE)
#define CSV_FILE "radar_data.csv"

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int handle, char *buffer, int max_len);
int parse_magic_word(const char *buffer, int buffer_len, int *magic_word_size);
int parse_tlv(const char *buffer, int buffer_len, int *tlv_type, float *range, float *velocity);
int validate_tlv(const char *buffer, int buffer_len, int tlv_type, float *range, float *velocity);
int append_to_csv(FILE *file, RadarData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the UART interface
int initialize_uart(const char *device, int baud_rate) {
    uart_handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Reads data from the UART interface
int read_uart_data(int handle, char *buffer, int max_len) {
    int bytes_read = serRead(handle, buffer, max_len);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Parses the magic word from the UART data
int parse_magic_word(const char *buffer, int buffer_len, int *magic_word_size) {
    if (buffer_len < MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error: Not enough data to parse magic word\n");
        return -1;
    }

    *magic_word_size = MAGIC_WORD_SIZE;
    if (memcmp(buffer, "RADAR_MAGIC_WORD", MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Error: Invalid magic word\n");
        return -1;
    }

    return 0;
}

// Parses the TLV data from the UART data
int parse_tlv(const char *buffer, int buffer_len, int *tlv_type, float *range, float *velocity) {
    if (buffer_len < (MAGIC_WORD_SIZE + 4)) {
        fprintf(stderr, "Error: Not enough data to parse TLV\n");
        return -1;
    }

    // Extract range and velocity from TLV data
    memcpy(range, buffer, sizeof(float));
    memcpy(range + sizeof(float), buffer + MAGIC_WORD_SIZE + 4, sizeof(float));

    memcpy(velocity, buffer + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + 8, sizeof(float));
    memcpy(velocity + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + 8 + sizeof(float), buffer + MAGIC_WORD_SIZE + MAGIC_WORD_SIZE + 16, sizeof(float));

    *tlv_type = buffer[MAGIC_WORD_SIZE + 4];

    return 0;
}

// Validates the TLV data
int validate_tlv(const char *buffer, int buffer_len, int tlv_type, float *range, float *velocity) {
    if (buffer_len < (MAGIC_WORD_SIZE + 4 + sizeof(float) + sizeof(float))) {
        fprintf(stderr, "Error: Not enough data to validate TLV\n");
        return -1;
    }

    // Validate range and velocity
    if (validate_range(range) != 0) {
        fprintf(stderr, "Error: Invalid range\n");
        return -1;
    }
    if (validate_velocity(velocity) != 0) {
        fprintf(stderr, "Error: Invalid velocity\n");
        return -1;
    }

    return 0;
}

// Validates the range
int validate_range(float *range) {
    if (*range < 0.0 || *range > 100.0) {
        fprintf(stderr, "Error: Range out of range: %f\n", *range);
        return -1;
    }
    return 0;
}

// Validates the velocity
int validate_velocity(float *velocity) {
    if (*velocity < -10.0 || *velocity > 10.0) {
        fprintf(stderr, "Error: Velocity out of range: %f\n", *velocity);
        return -1;
    }
    return 0;
}

// Appends data to the CSV file
int append_to_csv(FILE *file, RadarData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(file, "%s,%d,%f,%f\n", timestamp, data.object_index, data.range_m, data.velocity_mps);
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function to close the UART and CSV file
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART
    if (initialize_uart(UART_DEVICE, BAUD_RATE) != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    char buffer[BUFFER_SIZE];
    int bytes_read;
    RadarData data;
    int magic_word_size;
    float range, velocity;

    while (!terminate) {
        bytes_read = read_uart_data(uart_handle, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            // Parse magic word
            if (parse_magic_word(buffer, bytes_read, &magic_word_size) == 0) {
                // Parse TLV data
                if (parse_tlv(buffer, bytes_read, &data.tlv_type, &data.range, &data.velocity) == 0) {
                    // Validate TLV data
                    if (validate_tlv(buffer, bytes_read, data.tlv_type, &data.range, &data.velocity) == 0) {
                        // Append data to CSV file
                        append_to_csv(csv_file, data);
                    } else {
                        fprintf(stderr, "Error: TLV validation failed\n");
                    }
                } else {
                    fprintf(stderr, "Error: TLV parsing failed\n");
                }
            } else {
                fprintf(stderr, "Error: Magic word parsing failed\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART\n");
        }

        usleep(10000); // Delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

