#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device
#define UART_DEVICE "/dev/ttyAMA0"

// Define API call
#define API_CALL_COMMAND "EMERGENCY STOP!\n"

// Global variables
int uart_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_sensor_states(int left_sensor_state, int middle_sensor_state, int right_sensor_state);
void send_data_to_uart();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Log sensor states
void log_sensor_states(int left_sensor_state, int middle_sensor_state, int right_sensor_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left_sensor_state, middle_sensor_state, right_sensor_state);
}

// Send data to UART
void send_data_to_uart() {
    int result = gpioWrite(UART_HANDLE, 1); // Send 1 to UART
    if (result != 0) {
        fprintf(stderr, "Error writing to UART: %d\n", result);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open UART device
    uart_handle = serOpen(UART_DEVICE, 115200, 0); // 0 for no flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring sensor inputs. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int left_sensor_state = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor_state = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor_state = read_sensor(RIGHT_SENSOR_PIN);

        log_sensor_states(left_sensor_state, middle_sensor_state, right_sensor_state);

        if (left_sensor_state == 0 && middle_sensor_state == 0 && right_sensor_state == 0) {
            send_data_to_uart();
        }

        gpioDelay(100); // Delay for 100ms (10Hz)
    }

    // Close UART device
    serClose(uart_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

